from math import sqrt


def is_prime(n):
    for i in range(2, int(sqrt(n))+1):
        if n % i == 0:
            return False

    return True


def make_divisors(a, b):
    lower_divisors = []
    upper_divisors = []

    i = 1
    n = min(a, b)
    m = max(a, b)

    while i*i <= n:
        if n % i == 0 and m % i == 0:
            if is_prime(i):
                lower_divisors.append(i)

            if i != n // i:
                if m % (n // i) == 0:
                    if is_prime(n//i):
                        upper_divisors.append(n//i)
        i += 1

    return lower_divisors + upper_divisors[::-1]


def main():
    A, B = [int(x) for x in input().split()]
    divisors = make_divisors(A, B)
    print(len(divisors))


if __name__ == '__main__':
    main()

from fractions import gcd

def create_primeNum(N):
    if N == 1:
        return 1
    primeNum=1
    for k in range(2, N + 1):
        # 2以外の偶数は素数ではないので無視する
        if k % 2 == 0 and k != 2:
            continue
        if pow(2, k - 1, k) == 1:
            primeNum += 1
    return primeNum

if __name__ == "__main__":
    a,b = map(int,input().split())
    N = gcd(a, b)
    print(create_primeNum(N))

