    """
    初期値
    cost = 0
    still_closed = [1]*N
    d = 0
    """
    if d == M:
        if sum(still_closed) == 0:
            return cost
        else:
            return - 1
    still_closed1 = copy.copy(still_closed)
    still_closed2 = copy.copy(still_closed)
