def main():
    Q = int(input())
    lr = [list(map(int, input().split())) for i in range(Q)]

    MAX = int(1e5)
    MAX_PRIME = MAX
    primes = []
    is_prime = [True] * (MAX_PRIME+1)
    for i in range(2, MAX_PRIME+1):
        if is_prime[i]:
            primes.append(i)
            for j in range(2*i, MAX_PRIME+1, i):
                is_prime[j] = False
    count = [0] * (MAX+1)
    for p in primes:
        if p&1:
            tmp = (p + 1) // 2
            if is_prime[tmp]:
                count[p] = 1
    for i in range(1, MAX+1):
        count[i] += count[i-1]

    # print(count[:10])
    for i in range(Q):
        l, r = lr[i]
        print(count[r] - count[l-1])




