def max_happiness(n, data, dp, a, b, c):
  if dp[n] is not None:
    return dp[n]
  if n == 0:
    if a and b:
      return max(data[n][0], data[n][1])
    elif b and c:
      return max(data[n][1], data[n][2])
    elif c and a:
      return max(data[n][2], data[n][0])

  max_a = -1
  max_b = -1
  max_c = -1

  if a:
    max_a = data[n][0] + max_happiness(n-1, data, dp, a=False, b=True, c=True)
  if b:
    max_b = data[n][1] + max_happiness(n-1, data, dp, a=True, b=False, c=True)
  if c:
    max_c = data[n][2] + max_happiness(n-1, data, dp, a=True, b=True, c=False)

  dp[n] = max(max_a, max_b, max_c)
  return dp[n]

