def count_four(lst):
    counter = 0
    for i in lst:
        if i%4 == 0:
            counter += 1
    return counter

def count_two(lst):
    counter = 0
    for i in lst:
        if i%2 == 0:
            counter += 1
    return counter

n = int()
lst = list(map(int,input().split()))

def solve(lst):
    four = count_four(lst)
    two = count_two(lst) - four
    sonota = len(lst) - four - two

    if sonota < four + 1:
        return "Yes"
    elif ((four + 1 - sonota) == 0) and (two == 0):
        return "Yes"
    else:
        return "No"

print(solve(lst))

