def chk2(S1,S2):
    T1=chk(S1,S)
    Sm=(S1+S2)//2
    Tm=chk(Sm,S)
    if (Sm-S1+1)%2!=0:
        if T1==Tm:
            chk2(Sm+1,S2)
        else:
            chk2(S1,Sm-1)
    elif (Sm-S1+1)%2==0:
        if T1==Tm:
            chk2(S1,Sm-1)
        else:
            chk2(Sm+1,S2)

