def main():
    l = {}
    lR = {}
    l = input()
    lR = l[::-1]
    givenLen = len(l)

    if l == lR:
        return 0

    temp = {}
    temp[0] = 0
    for i, e in enumerate(l):
        temp[i+1] = e
    l = dict(temp)
    temp = {}
    temp[0] = 0
    for i, e in enumerate(lR):
        temp[i+1] = e
    lR = dict(temp)

    LCStable = [[0 for _ in range(givenLen+1)]]*(givenLen+1)

    for i in l:
        for j in lR:
            if i == 0 or j == 0:
                LCStable[i][j] = 0
            elif l[i] == lR[j]:
                LCStable[i][j] = LCStable[i-1][j-1]+1
            else:
                LCStable[i][j] = max(LCStable[i][j-1], LCStable[i-1][j])
    return givenLen-LCStable[-1][-1]


