        int a; cin >> a;
        v.push_back(a);
    }
    vector<int> v2 = v;
    vector<int> ans;
    bool f = true;
    bool update = true;
    while(v2.size()!=0){
        update = false;
        for(int i=v2.size()-1; i>=0; --i){
            for(int j=v2.size(); j>=1; --j){
                if(v2[i] == j && i+1 == j){
                    ans.push_back(v2[i]);
                    v2.erase(v2.begin()+i);
                    update = true;
                    break;
                }
                if(i == 0 && j==1){
                    f = false;
                }
            }
            if(update) break;
        }
        if(!f) break;
    }
    reverse(ans.begin(), ans.end());
    if(f){
        for(auto e: ans) cout << e << endl;
    }else{
        cout << -1 << endl;
    }
	return 0;
}

