for i in range(l):
  # n[:i] 0 {1..9}*k 0*(l-i-1-k)
  count += 9 ** k * comb(l-i-1, k)
  # n[:i] {1..(n[i]-1)} {1..9}*(k-1) 0*(l-i-1-k)
  if k >= 1 and n[i] > 1:
    count += 9 ** (k-1) * comb(l-i-1, k-1) * (n[i]-1)
  # Next is n[:i+1] {1..9}*(k-1) 0*(l-i-k)
  if n[i] > 0:
    k -= 1
  if k < 0:
    break
print(count)

