def cut_cake(H, W, K, s):
    a = [['.' for _ in range(W)] for _ in range(H)]
    piece = 1
    for i in range(H):
        for j in range(W):
            if s[i][j] == '#':
                a[i][j] = str(piece)
                piece += 1
                # Extend the piece to the right
                for k in range(j + 1, W):
                    if s[i][k] == '#':
                        break
                    a[i][k] = str(piece - 1)
                # Extend the piece downwards
                for k in range(i + 1, H):
                    if s[k][j] == '#':
                        break
                    a[k][j] = str(piece - 1)
    for i in range(H):
        print(' '.join(a[i]))

