def solve():
    n, m = map(int, input().split())
    p = list(map(int, input().split()))
    edges = [tuple(map(int, input().split())) for _ in range(m)]

    # Create a graph representing the swaps
    graph = [[] for _ in range(n + 1)]
    for x, y in edges:
        graph[x].append(y)
        graph[y].append(x)

    # Perform depth-first search to find connected components
    visited = [False] * (n + 1)
    components = []
    for i in range(1, n + 1):
        if not visited[i]:
            component = []
            dfs(i, graph, visited, component)
            components.append(component)

    # Count the number of fixed points in each component
    fixed_points = 0
    for component in components:
        fixed_points += count_fixed_points(component, p)

    return fixed_points


def dfs(node, graph, visited, component):
    visited[node] = True
    component.append(node)
    for neighbor in graph[node]:
        if not visited[neighbor]:
            dfs(neighbor, graph, visited, component)


def count_fixed_points(component, p):
    fixed_points = 0
    for node in component:
        if p[node - 1] == node:
            fixed_points += 1
    return fixed_points


print(solve())

