    s = str(n)
    for i in range(len(s) - 1):
        if abs(int(s[i]) - int(s[i + 1])) > 1:
            return False
    return True


def kth_lunlun(k):
    count = 0
    n = 1
    while count < k:
        if is_lunlun(n):
            count += 1
        n += 1
    return n - 1


