def solve(n, m, s):
    dp = [float('inf')] * (n + 1)
    dp[0] = 0
    for i in range(n + 1):
        if s[i] == '1':
            continue
        for j in range(1, m + 1):
            if i + j <= n and dp[i] + 1 < dp[i + j]:
                dp[i + j] = dp[i] + 1
    if dp[n] == float('inf'):
        return -1
    else:
        ans = []
        cur = n
        while cur > 0:
            for j in range(1, m + 1):
                if cur - j >= 0 and dp[cur - j] == dp[cur] - 1:
                    ans.append(j)
                    cur -= j
                    break
        return ' '.join(map(str, ans[::-1]))

