def gcd(a, b):
  while b:
    a, b = b, a % b
  return a

def solve(n, k, a):
  if k >= n - 1:
    return max(a)
  else:
    g = a[0]
    for i in range(1, n):
      g = gcd(g, a[i])
    if k > 0:
      return g + (k // (n - 1))
    else:
      return g

