def solve(n, s):
    left = 0
    right = 0
    for i in range(n):
        if s[i] == '(':
            left += 1
        else:
            right += 1
    ans = ''
    for i in range(left):
        ans += '('
    for i in range(n):
        ans += s[i]
    for i in range(right - left):
        ans += ')'
    return ans


