from collections import defaultdict

def kenkenpa(N, M, edges, S, T):
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)

    queue = [(S, 0)]
    visited = set()
    while queue:
        node, steps = queue.pop(0)
        if node == T:
            return steps
        if node in visited:
            continue
        visited.add(node)
        if steps % 3 == 0:
            for neighbor in graph[node]:
                queue.append((neighbor, steps + 1))
    return -1

