    for _ in range(N):
        a, b, c = list(map(int, input().split(' ')))
        A.append(a)
        B.append(b)
        C.append(c)
    dp = [[INF for _ in range(8001)] for _ in range(N + 1)]
    dp[0][0] = 0
    for n in range(1, N + 1):
        a, b, c = A[n - 1], B[n - 1], C[n - 1]
        for v in range(8001):
            if dp[n - 1][v] != INF:
                dp[n][v] = min(dp[n][v], dp[n - 1][v])
                dp[n][v + (MB * a - MA * b)] = min(dp[n][v + (MB * a - MA * b)], dp[n - 1][v] + c)
    ans = dp[N][0]
    if ans >= INF:
        ans = -1
    print(ans)


