def solve(n, k, r, s, p, t):
    dp = [0] * (n + 1)
    for i in range(1, n + 1):
        dp[i] = max(dp[i], dp[i - 1])
        if i >= k:
            if t[i - 1] == 'r' and t[i - k - 1] != 'p':
                dp[i] = max(dp[i], dp[i - k] + p)
            if t[i - 1] == 'p' and t[i - k - 1] != 's':
                dp[i] = max(dp[i], dp[i - k] + s)
            if t[i - 1] == 's' and t[i - k - 1] != 'r':
                dp[i] = max(dp[i], dp[i - k] + r)
    return dp[n]

