/**
   _____                       _        _    _                      
  / ____|                     | |      | |  | |                     
 | (___   __ _ _ __ ___  _ __ | | ___  | |  | |___  __ _  __ _  ___ 
  \___ \ / _` | '_ ` _ \| '_ \| |/ _ \ | |  | / __|/ _` |/ _` |/ _ \
  ____) | (_| | | | | | | |_) | |  __/ | |__| \__ \ (_| | (_| |  __/
 |_____/ \__,_|_| |_| |_| .__/|_|\___|  \____/|___/\__,_|\__, |\___|
                        | |                               __/ |     
                        |_|                              |___/      
 */
public class MainActivity extends AppCompatActivity {

    private static final String TAG = MainActivity.class.getSimpleName();
    private static final String SAMPLE_ALIAS = "MYALIAS";

    @BindView (R.id.toolbar)
    Toolbar toolbar;

    @BindView (R.id.ed_text_to_encrypt)
    EditText edTextToEncrypt;

    @BindView (R.id.tv_encrypted_text)
    TextView tvEncryptedText;

    @BindView (R.id.tv_decrypted_text)
    TextView tvDecryptedText;

    private EnCryptor encryptor;
    private DeCryptor decryptor;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);
        ButterKnife.bind(this);
        setSupportActionBar(toolbar);

        encryptor = new EnCryptor();

        try {
            decryptor = new DeCryptor();
        } catch (CertificateException | NoSuchAlgorithmException | KeyStoreException |
                IOException e) {
            e.printStackTrace();
        }
    }

    @OnClick ({R.id.btn_encrypt, R.id.btn_decrypt})
    public void onClick(final View view) {

        final int id = view.getId();

        switch (id) {
            case R.id.btn_encrypt:
                encryptText();
                break;
            case R.id.btn_decrypt:
                decryptText();
                break;
        }
    }

    private void decryptText() {
        try {
            tvDecryptedText.setText(decryptor
                    .decryptData(SAMPLE_ALIAS, encryptor.getEncryption(), encryptor.getIv()));
        } catch (UnrecoverableEntryException | NoSuchAlgorithmException |
                KeyStoreException | NoSuchPaddingException | NoSuchProviderException |
                IOException | InvalidKeyException e) {
            Log.e(TAG, "decryptData() called with: " + e.getMessage(), e);
        } catch (IllegalBlockSizeException | BadPaddingException | InvalidAlgorithmParameterException e) {
            e.printStackTrace();
        }
    }

    private void encryptText() {

        try {
            final byte[] encryptedText = encryptor
                    .encryptText(SAMPLE_ALIAS, edTextToEncrypt.getText().toString());
            tvEncryptedText.setText(Base64.encodeToString(encryptedText, Base64.DEFAULT));
        } catch (UnrecoverableEntryException | NoSuchAlgorithmException | NoSuchProviderException |
                KeyStoreException | IOException | NoSuchPaddingException | InvalidKeyException e) {
            Log.e(TAG, "onClick() called with: " + e.getMessage(), e);
        } catch (InvalidAlgorithmParameterException | SignatureException |
                IllegalBlockSizeException | BadPaddingException e) {
            e.printStackTrace();
        }
    }
}

package ch_10;


public class Exercise10_26 {
    public static void main(String[] args) {

        StringBuilder str = new StringBuilder();

        for (String arg : args) {
            str.append(arg);
        }

        String str2 = str.toString().replaceAll(" ", "");

        str2 = str2.replaceAll("[+]", "%+%");
        str2 = str2.replaceAll("[-]", "%-%");
        str2 = str2.replaceAll("[.]", "%.%");
        str2 = str2.replaceAll("[/]", "%/%");


        args = str2.split("%");

        int result = 0;

        switch (args[1].charAt(0)) {

            case '+':
                result = Integer.parseInt(args[0]) + Integer.parseInt(args[2]);
                break;

            case '-':
                result = Integer.parseInt(args[0]) - Integer.parseInt(args[2]);
                break;

            case '.':
                result = Integer.parseInt(args[0]) * Integer.parseInt(args[2]);
                break;

            case '/':
                result = Integer.parseInt(args[0]) / Integer.parseInt(args[2]);
                break;

        }
        System.out.println(args[0] + ' ' + args[1] + ' ' + args[2] + " = " + result);
    }

}

package ch_08;

import java.util.*;


public class Exercise08_09 {
    private static final String USER_X_ID = "X";
    private static final String USER_O_ID = "O";
    static final String IN_PROMPT_ROW = "Enter a row (0, 1, or 2) for player";
    static final String IN_PROMPT_COLUMN = "Enter a column (0, 1, or 2) for player";
    static String[][] boxes;
    static String nextMove;
    static String currentMove;
    static boolean blank;
    static final String verticalLine = "——————-——————\r\n";
    static String status;
    static String winner;
    static int totalMoves = 9;

    static {
        boxes = new String[][]{{"", "", ""},
                {"", "", ""},
                {"", "", ""}}; //Tic tac toe board empty
        nextMove = USER_X_ID;
        status = "continue";
        blank = true;

    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int row = 0, col = 0;
        System.out.print("Welcome to Tic Tac Toe!\n");
        while (status.equals("continue")) {
            if (blank) {
                printBlankBoard();
                blank = false;
            } else {
                printGameBoard();
            }
            System.out.print(IN_PROMPT_ROW + " " + nextMove + ":");
            row = in.nextInt();
            System.out.print(IN_PROMPT_COLUMN + " " + nextMove + ":");
            col = in.nextInt();
            if ((col == 0 || col == 1 || col == 2) && (row == 0 || row == 1 || row == 2)) {
                addMove(row, col);
            } else {
                System.out.println("You entered an invalid character player " + nextMove + " enter a 0, 1, or 2 next time...");
            }
        }
        if (status.equals("win")) {
            //WIN
            printGameBoard();
            System.out.print("\nPlayer " + winner + " won!");
        } else {
            //DRAW
            System.out.println("The match is a draw!!");
        }

    }

    //Add players move to the boxes array and test win condition
    static void addMove(int markRow, int markCol) {
        if (boxes[markRow][markCol].equals("")) {
            boxes[markRow][markCol] = nextMove;
            totalMoves--;
        } else {
            System.out.println("Nice try, you can only enter your mark in an empty box...");
        }

        if (checkWinner()) {
            status = "win";
        } else if (totalMoves < 1) {
            status = "draw";
        }
    }

    private static void printGameBoard() {

        for (int i = 0; i < 3; i++) {
            System.out.print(verticalLine);
            for (int j = 0; j < 3; j++) {
                if (boxes[i][j].equals("")) {
                    System.out.print("|   ");
                } else {
                    System.out.print("| ");
                    System.out.print(boxes[i][j]);
                    System.out.print(" ");
                }
            }
            System.out.print("|\r\n"); // Last piece of bottom right box
        }
        System.out.println(verticalLine);//Bottom line t-t-t board

        nextMove = nextMove.equals(USER_X_ID) ? USER_O_ID : USER_X_ID;
    }

    //Runs first iteration of main while loop
    static void printBlankBoard() {
        for (int i = 0; i < 3; i++) {
            System.out.print(verticalLine);
            for (int j = 0; j < 3; j++) {
                System.out.print("|   ");
            }
            System.out.print("|\r\n");
        }
        System.out.println(verticalLine);//Bottom line t-t-t board
    }

    //Iterate boxes array's and determine which player, if any, is the winner
    static boolean checkWinner() {
        boolean won = false;
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                if (!(boxes[i][j].equals(""))) {
                    if (boxes[i][j].equals("X")) {
                        if (boxes[0][0].equals("X") && boxes[0][1].equals("X") && boxes[0][2].equals("X") ||
                                boxes[1][0].equals("X") && boxes[1][1].equals("X") && boxes[1][2].equals("X") ||
                                boxes[2][0].equals("X") && boxes[2][1].equals("X") && boxes[2][2].equals("X") ||
                                boxes[0][0].equals("X") && boxes[1][0].equals("X") && boxes[2][0].equals("X") ||
                                boxes[0][1].equals("X") && boxes[1][1].equals("X") && boxes[2][1].equals("X") ||
                                boxes[0][2].equals("X") && boxes[1][2].equals("X") && boxes[2][2].equals("X") ||
                                boxes[0][0].equals("X") && boxes[1][1].equals("X") && boxes[2][2].equals("X") ||
                                boxes[0][2].equals("X") && boxes[1][1].equals("X") && boxes[2][0].equals("X")) {
                            winner = "X";
                            won = true;
                        }

                    } else {
                        if (boxes[0][0].equals("O") && boxes[0][1].equals("O") && boxes[0][2].equals("O") ||
                                boxes[1][0].equals("O") && boxes[1][1].equals("O") && boxes[1][2].equals("O") ||
                                boxes[2][0].equals("O") && boxes[2][1].equals("O") && boxes[2][2].equals("O") ||
                                boxes[0][0].equals("O") && boxes[1][0].equals("O") && boxes[2][0].equals("O") ||
                                boxes[0][1].equals("O") && boxes[1][1].equals("O") && boxes[2][1].equals("O") ||
                                boxes[0][2].equals("O") && boxes[1][2].equals("O") && boxes[2][2].equals("O") ||
                                boxes[0][0].equals("O") && boxes[1][1].equals("O") && boxes[2][2].equals("O") ||
                                boxes[0][2].equals("O") && boxes[1][1].equals("O") && boxes[2][0].equals("O")) {
                            winner = "O";
                            won = true;
                        }


                    }


                }

            }
        }

        return won;

    }

}

package ch_17.exercise17_11;

import javafx.application.Application;
import javafx.geometry.Insets;
import javafx.geometry.Pos;
import javafx.scene.Scene;
import javafx.scene.control.Alert;
import javafx.scene.control.Button;
import javafx.scene.control.TextField;
import javafx.scene.layout.HBox;
import javafx.scene.layout.Priority;
import javafx.scene.layout.VBox;
import javafx.scene.text.Text;
import javafx.scene.text.TextAlignment;
import javafx.stage.Stage;

import java.io.BufferedOutputStream;
import java.io.File;
import java.io.FileOutputStream;
import java.nio.file.Files;


public class Exercise17_11 extends Application {
    public static void main(String[] args) {
        Application.launch(args);
    }

    @Override
    public void start(Stage primaryStage) throws Exception {
        VBox mainBox = new VBox();
        HBox topHBox = new HBox();
        Text text = new Text("If you split a file named temp.txt into 3 smaller files,\nthe three smaller files are:" +
                " temp.txt.1, temp.txt.2, and temp.txt.3.");
        topHBox.getChildren().add(text);

        HBox.setHgrow(text, Priority.ALWAYS);
        HBox.setMargin(text, new Insets(5, 5, 5, 5));

        HBox middleHBox = new HBox(5);
        TextField fileField = new TextField();
        Text filePrompt = new Text("Enter a file: ");
        filePrompt.setTextAlignment(TextAlignment.LEFT);
        HBox.setMargin(fileField, new Insets(0, 10, 0, 258));
        fileField.setMinWidth(200);
        middleHBox.getChildren().add(filePrompt);
        middleHBox.getChildren().add(fileField);

        HBox lowMiddleHBox = new HBox(5);
        Text numPiecesPrompt = new Text("Specify the number of smaller files: ");
        numPiecesPrompt.setTextAlignment(TextAlignment.LEFT);
        lowMiddleHBox.getChildren().add(numPiecesPrompt);
        TextField numPiecesField = new TextField();
        numPiecesField.setPromptText("Example: 3");
        numPiecesField.setMinWidth(200);
        lowMiddleHBox.getChildren().add(numPiecesField);
        HBox.setHgrow(numPiecesPrompt, Priority.ALWAYS);
        HBox.setMargin(numPiecesField, new Insets(0, 10, 0, 100));

        HBox buttonBox = new HBox();
        Button startButton = new Button("Start");
        buttonBox.setAlignment(Pos.CENTER);
        buttonBox.getChildren().add(startButton);

        startButton.setOnAction(e -> {
            String fileInput = fileField.getText();
            if (fileInput.isEmpty()) {
                Alert alert = new Alert(Alert.AlertType.ERROR);
                alert.setContentText("Please enter a value for file name before pressing start button.");
                alert.show();

            } else if (numPiecesField.getText().isEmpty()) {
                Alert alert = new Alert(Alert.AlertType.ERROR);
                alert.setContentText("Please enter a value for number of files to output...");
                alert.show();
            } else {
                int numOutFiles = Integer.parseInt(numPiecesField.getText());
                File sourceFile = new File("ch_17/exercise17_11", fileInput);
                try {
                    splitFiles(sourceFile, numOutFiles);
                    Alert alert = new Alert(Alert.AlertType.CONFIRMATION);
                    alert.setContentText("Success!");
                    alert.show();

                } catch (Exception ex) {
                    Alert alert = new Alert(Alert.AlertType.ERROR);
                    alert.setContentText(ex.getMessage());
                    alert.show();

                    ex.printStackTrace();
                }

            }
        });
        mainBox.getChildren().addAll(topHBox, middleHBox, lowMiddleHBox, buttonBox);
        VBox.setVgrow(topHBox, Priority.ALWAYS);
        VBox.setVgrow(middleHBox, Priority.ALWAYS);
        VBox.setVgrow(lowMiddleHBox, Priority.ALWAYS);
        VBox.setVgrow(buttonBox, Priority.ALWAYS);

        Scene scene = new Scene(mainBox, 550, 150);
        primaryStage.setTitle(getClass().getName());
        primaryStage.setScene(scene);
        primaryStage.setResizable(false);
        primaryStage.show();
    }

    private static void splitFiles(File sourceFile, int numberOfPieces) throws Exception {

        File outDirectory = new File(sourceFile.getParent(), "Results_Directory");
        if (!outDirectory.exists()) {
            outDirectory.mkdir();
        }

        File[] outFiles = new File[numberOfPieces];
        for (int i = 0; i < outFiles.length; i++) {
            outFiles[i] = new File(outDirectory, sourceFile.getName() + "." + (i + 1));

        }

        byte[] bytes = Files.readAllBytes(sourceFile.toPath());
        int bytePerFile = bytes.length / numberOfPieces;
        int masterByteArrayIndex = 0;
        for (File file : outFiles) {
            BufferedOutputStream outputStream = new BufferedOutputStream(new FileOutputStream(file));
            for (int i = 0; i < bytePerFile; i++) {
                outputStream.write(bytes[masterByteArrayIndex]);
                masterByteArrayIndex++;
            }
            outputStream.flush();
            outputStream.close();
        }

    }

}

