public class ApiAuthenticator implements OkAuthenticator {

  AccountManager accountManager;
  Application application;

  @Inject
  public ApiAuthenticator(Application application, AccountManager accountManager) {
    this.application = application;
    this.accountManager = accountManager;
  }

  @Override
  public Credential authenticate(Proxy proxy, URL url, List<Challenge> challenges)
      throws IOException {
    // Do not try to authenticate oauth related endpoints
    if (url.getPath().startsWith("/oauth")) return null;

    for (Challenge challenge : challenges) {
      if (challenge.getScheme().equals("Bearer")) {
        Account[] accounts = accountManager.getAccountsByType(AuthConstants.ACCOUNT_TYPE);
        if (accounts.length != 0) {
          String oldToken = accountManager.peekAuthToken(accounts[0],
              AuthConstants.AUTHTOKEN_TYPE);
          if (oldToken != null) {
            Timber.d("invalidating auth token");
            accountManager.invalidateAuthToken(AuthConstants.ACCOUNT_TYPE, oldToken);
          }
          try {
            Timber.d("calling accountManager.blockingGetAuthToken");
            String token = accountManager.blockingGetAuthToken(accounts[0],
                AuthConstants.AUTHTOKEN_TYPE, false);

            if(token==null) {
              accountManager.removeAccount(accounts[0], null, null);
            }

            // Do not retry certain URLs
            //if (url.getPath().startsWith("/donotretry")) {
            //  return null;
            //} else if (token != null) {
            if (token != null) {
              return token(token);
            }
          } catch (OperationCanceledException e) {
            e.printStackTrace();
          } catch (AuthenticatorException e) {
            e.printStackTrace();
          }
        }
      }
    }
    return null;
  }

  private Credential token(String token) {
    try {
      // TODO: when there is support for different types of Credentials, stop using reflection
      Constructor<?> constructor = Credential.class.getDeclaredConstructor(String.class);
      Assert.assertTrue(Modifier  .isPrivate(constructor.getModifiers()));
      constructor.setAccessible(true);
      return (Credential) constructor.newInstance("Bearer " + token);
    } catch (InstantiationException e) {
      e.printStackTrace();
    } catch (IllegalAccessException e) {
      e.printStackTrace();
    } catch (NoSuchMethodException e) {
      e.printStackTrace();
    } catch (InvocationTargetException e) {
      e.printStackTrace();
    }
    return null;
  }

  @Override
  public Credential authenticateProxy(Proxy proxy, URL
      url, List<Challenge> challenges) throws IOException {
    return null;
  }
}

package ch_03;

import java.util.Scanner;


public class Exercise03_13 {

	public static void main(String[] args) {

		Scanner input = new Scanner(System.in);
		System.out.print("(0-single filer, 1-married jointly or "
				+ "qualifying widow(er), 2-married separately, 3-head of " + "household) Enter the filing status: ");
		int status = input.nextInt();
		// Prompt the user to enter taxable income
		System.out.print("Enter the taxable income: ");
		double income = input.nextDouble();

		double tax = 0; //Initialize var for computed tax amount
		//Initialize var's for upper bounds
		int upBound10 = 0, upBound15 = 0, upBound25 = 0, upBound28 = 0, upBound33 = 0;

		if (status == 0) { // Compute tax for single filers
			upBound10 = 8350;
			upBound15 = 33950;
			upBound25 = 82250;
			upBound28 = 171550;
			upBound33 = 372950;

		} else if (status == 1) { // Married Filing Jointly or Qualifying Widow(er)
			upBound10 = 16700;
			upBound15 = 67900;
			upBound25 = 137050;
			upBound28 = 208850;
			upBound33 = 372950;

		} else if (status == 2) { // Compute tax for married separately
			upBound10 = 8350;
			upBound15 = 33950;
			upBound25 = 68525;
			upBound28 = 104425;
			upBound33 = 186475;

		} else if (status == 3) { // Compute tax for head of household
			upBound10 = 11950;
			upBound15 = 45500;
			upBound25 = 117450;
			upBound28 = 190200;
			upBound33 = 372950;
		} else {
			System.out.println("Error: invalid status");
			System.exit(1);
		}

		if (income <= upBound10)
			tax = income * 0.10;
		else if (income <= upBound15)
			tax = upBound10 * 0.10 + (income - upBound10) * 0.15;
		else if (income <= upBound25)
			tax = upBound10 * 0.10 + (upBound15 - upBound10) * 0.15 + (income - upBound15) * 0.25;
		else if (income <= upBound28)
			tax = upBound10 * 0.10 + (upBound15 - upBound10) * 0.15 + (upBound25 - upBound15) * 0.25
					+ (income - upBound25) * 0.28;
		else if (income <= upBound33)
			tax = upBound10 * 0.10 + (upBound15 - upBound10) * 0.15 + (upBound25 - upBound15) * 0.25
					+ (upBound28 - upBound25) * 0.28 + (income - upBound28) * 0.33;
		else
			tax = upBound10 * 0.10 + (upBound15 - upBound10) * 0.15 + (upBound25 - upBound15) * 0.25
					+ (upBound28 - upBound25) * 0.28 + (upBound33 - upBound28) * 0.33 + (income - upBound33) * 0.35;

		input.close();

		System.out.println("Tax is " + (int) (tax * 100) / 100.0);
	}
}

