                {"West Virginia", "Charleston"}, {"Wisconsin", "Madison"},
                {"Wyoming", "Cheyenne"}
        };

        Map<String, String> stateCapitalsMap = new HashMap<>();
        for (String[] pair : statesAndCaptials) {
            stateCapitalsMap.putIfAbsent(pair[0], pair[1]);
        }

        Scanner in = new Scanner(System.in);
        System.out.print("Enter a state: ");
        String userInput = in.nextLine().trim();

        if (stateCapitalsMap.containsKey(userInput)) {
            System.out.println("The capital of " + userInput + " is " + stateCapitalsMap.get(userInput));
        } else {
            System.out.println("We could not find a capital for the state: " + userInput);
        }

        in.close();
    }

}

package ch_10;

import java.math.BigDecimal;
import java.math.BigInteger;


public class Exercise10_21 {
    public static void main(String[] args) {
        BigInteger testNumber = BigInteger.valueOf(Long.MAX_VALUE);
        BigInteger FIVE = BigInteger.valueOf(5L);
        BigInteger SIX = BigInteger.valueOf(6L);

        int count = 0;
        while (count < 10) {
            testNumber = testNumber.add(BigInteger.ONE);

            BigInteger remainder = testNumber.remainder(FIVE);
            if (remainder.intValue() == 0) {
                System.out.print("\n" + testNumber.toString());
                System.out.print(" divided by 5 = ");
                BigInteger res = testNumber.divide(FIVE);
                System.out.print(res.toString());
                count++;
            }

            BigInteger remainder6 = testNumber.remainder(SIX);
            if (remainder6.intValue() == 0) {
                System.out.print("\n" + testNumber.toString());
                System.out.print(" divided by 6 = ");
                BigInteger res = testNumber.divide(SIX);
                System.out.print(res.toString());
                count++;
            }

        }
    }
}

package ch_05;

import java.util.*;


public class Exercise05_42 {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        double comish = 0;
        double bal = 0;
        double sales = 0;

        System.out.println("Enter the commission desired: ");
        double potentialComish = in.nextDouble();

        for (sales = 0.01; comish < potentialComish; sales += 0.01) {
            bal = comish = 0.0;

            if (sales >= 10000.01)
                comish += (bal = sales - 10000) * 0.12;
            if (sales >= 5000.01)
                comish += (bal -= bal - 5000) * 0.10;

            if (sales >= 0.01)
                comish += bal * 0.08;
        }

        System.out.printf(
                "Sales must be $%.0f to earn commission of $%.0f\n", potentialComish, sales);
    }
}

