package ch_22;

import java.util.Scanner;


public class Exercise22_05 {
    private void findSubsequence(String[] tokens) {
        int longest = 0;
        int longestStartIndex = 0;
        int count = 1;
        int value = 0;
        int startIndex = 0;

        for (int i = 0; i < tokens.length - 1; i++) {
            int curr = Integer.parseInt(tokens[i]);
            int next = Integer.parseInt(tokens[i + 1]);
            if (next == 0) break;
            if (curr == next) {
                count++;
                longest = Math.max(longest, count);
                if (count == longest) {
                    value = curr;
                    longestStartIndex = startIndex;
                }
            } else {
                startIndex = i + 1;
                count = 1;
            }

        }
        System.out.println("The longest same number sequence starts at index " + longestStartIndex +
                " with " + longest + " values " + "of " + value);

    }

    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        System.out.println("Enter a series of numbers ending with 0:");
        String[] tokens = input.nextLine().split("\\s+");
        new Exercise22_05().findSubsequence(tokens);

        input.close();

    }
}

package ch_14;

import javafx.application.Application;
import javafx.scene.Scene;
import javafx.scene.layout.Pane;
import javafx.scene.paint.Color;
import javafx.scene.shape.Circle;
import javafx.scene.shape.Line;
import javafx.stage.Stage;


public class Exercise14_25 extends Application {
    private final double RADIUS = 80;
    private final double WIDTH = 200;
    private final double HEIGHT = 200;

    @Override
    public void start(Stage primaryStage) throws Exception {
        double[][] pointsInCircle = new double[5][2];
        Circle circle = new Circle(100,100, RADIUS);
        circle.setFill(Color.TRANSPARENT);
        circle.setStroke(Color.BLACK);

        for (int i = 0; i < 5; i++) {
            pointsInCircle[i] = randomPointOnCircle(circle.getCenterX(), circle.getCenterY(), RADIUS);
        }
        drawCircleWithPolygonPoints(pointsInCircle, primaryStage, circle);

    }

    private void drawCircleWithPolygonPoints(double[][] points, Stage stage, Circle circle) {
        Pane pane = new Pane();
        pane.getChildren().add(circle);

        for (int i = 0; i < points.length - 1; i++) {
            Line line = new Line(points[i][0], points[i][1], points[i + 1][0], points[i + 1][1]);
            pane.getChildren().add(line);
        }

        Scene scene = new Scene(pane, WIDTH, HEIGHT);
        stage.setScene(scene);
        stage.setTitle(getClass().getName());
        stage.show();

    }

    private double[] randomPointOnCircle(double centerX, double centerY, double radius) {
        double angle = Math.random() * 2 * Math.PI,
                A = Math.sqrt(Math.random()) * radius,
                B = Math.cos(angle) * A,
                C = Math.sin(angle) * A;
        return new double[]{centerX + B, centerY + C};
    }

    public static void main(String[] args) {
        launch(args);
    }

}

package ch_20;

import javafx.animation.KeyFrame;
import javafx.animation.Timeline;
import javafx.application.Application;
import javafx.beans.property.DoubleProperty;
import javafx.geometry.Pos;
import javafx.scene.Scene;
import javafx.scene.control.Button;
import javafx.scene.control.ScrollBar;
import javafx.scene.layout.BorderPane;
import javafx.scene.layout.HBox;
import javafx.scene.layout.Pane;
import javafx.scene.paint.Color;
import javafx.scene.shape.Circle;
import javafx.stage.Stage;
import javafx.util.Duration;

import java.util.Comparator;


public class Exercise20_05 extends Application {

    @Override
    public void start(Stage primaryStage) throws Exception {
        MulitpleBallPane multiBallPane = new MulitpleBallPane();

        Button addButton = new Button("+");
        Button subtractButton = new Button("-");
        Button suspendButton = new Button("Suspend");
        Button resumeButton = new Button("Resume");

        HBox hBox = new HBox(10);
        hBox.getChildren().addAll(suspendButton, resumeButton, addButton, subtractButton);
        hBox.setAlignment(Pos.CENTER);

        addButton.setOnAction(ev1 -> {
            multiBallPane.addOne();
        });
        subtractButton.setOnAction(ev2 -> {
            multiBallPane.removeOne();
        });

        multiBallPane.setOnMouseClicked(event -> {
            multiBallPane.reactToMouseClick(event.getX(), event.getY());
        });

        suspendButton.setOnAction(e -> multiBallPane.pause());
        resumeButton.setOnAction(e -> multiBallPane.play());

        ScrollBar sbSpeed = new ScrollBar();
        sbSpeed.setMax(20);
        sbSpeed.setValue(10);
        multiBallPane.rateProperty().bind(sbSpeed.valueProperty());

        BorderPane pane = new BorderPane();
        pane.setCenter(multiBallPane);
        pane.setTop(sbSpeed);
        pane.setBottom(hBox);

        Scene scene = new Scene(pane, 450, 350);
        primaryStage.setResizable(false);
        primaryStage.setTitle(getClass().getName());
        primaryStage.setScene(scene);
        primaryStage.show();

    }

    public static void main(String[] args) {
        launch(args);
    }

    private class MulitpleBallPane extends Pane {
        public BallOverlapComparator overlapComparator;
        private Timeline animation;

        MulitpleBallPane() {
            animation = new Timeline(new KeyFrame(Duration.millis(50), event -> moveBall()));
            animation.setCycleCount(Timeline.INDEFINITE);
            animation.play();
            overlapComparator = new BallOverlapComparator();
        }

        public void addOne() {
            Color color = new Color(Math.random(), Math.random(), Math.random(), 0.5);
            getChildren().add(new Ball(30, 30, 20, color));
        }

        public void removeOne() {
            if (getChildren().size() > 0) {
                getChildren().remove(getChildren().size() - 1);
            }
        }

        public void play() {
            animation.play();
        }

        public void pause() {
            animation.pause();
        }

        public void reactToMouseClick(double x, double y) {
            for (int i = 0; i < this.getChildren().size(); i++) {
                Ball ball = (Ball) this.getChildren().get(i);
                double centerDistanceFromClick =
                        Math.sqrt(Math.pow(Math.abs(x - ball.getCenterX()), 2) + Math.pow(Math.abs(y - ball.getCenterY()), 2));
                if (centerDistanceFromClick <= ball.getRadius()) {
                    this.getChildren().remove(i);
                }
            }

        }

        public DoubleProperty rateProperty() {
            return animation.rateProperty();
        }


        protected void moveBall() {
            for (int i = 0; i < this.getChildren().size(); i++) {
                Ball ball = (Ball) this.getChildren().get(i);
                // Calculate boundaries
                if (ball.getCenterX() < ball.getRadius() || ball.getCenterX() > getWidth() - ball.getRadius()) {
                    ball.dx *= -1; // Change ball move direction
                }
                if (ball.getCenterY() < ball.getRadius() || ball.getCenterY() > getHeight() - ball.getRadius()) {
                    ball.dy *= -1; // Change ball move direction
                }
                //Move ball forward
                ball.setCenterX(ball.dx + ball.getCenterX());
                ball.setCenterY(ball.dy + ball.getCenterY());

                for (int j = 0; j < this.getChildren().size(); j++) {
                    Ball otherBall = (Ball) this.getChildren().get(j);
                    if (i == j) { // If they are the same ball (node)
                        continue; // continue to next node in the loop
                    }
                    int touching = overlapComparator.compare(ball, otherBall);
                    if (touching == 1 || touching == 0) {// 1 meaning touching, 0 meaning overlapping
                        double currentRadius = ball.getRadius();
                        ball.setRadius(currentRadius + otherBall.getRadius());// Combine balls into one
                        this.getChildren().remove(j);
                        // Calculate boundaries
                        if (ball.getCenterX() < ball.getRadius() || ball.getCenterX() > getWidth() - ball.getRadius()) {
                            ball.dx *= -1; // Change ball move direction
                        }
                        if (ball.getCenterY() < ball.getRadius() || ball.getCenterY() > getHeight() - ball.getRadius()) {
                            ball.dy *= -1; // Change ball move direction
                            //Move ball forward
                            ball.setCenterX(ball.dx + ball.getCenterX());
                            ball.setCenterY(ball.dy + ball.getCenterY());
                        }
                    }
                }
            }
        }

    }
}

class Ball extends Circle implements Comparable<Ball> {
    double dx = 1, dy = 1;

    Ball(double x, double y, double radius, Color color) {
        super(x, y, radius);
        setFill(color);
    }

    @Override
    public int compareTo(Ball that) {
        if (this.getCenterX() < that.getCenterX()) {
            return -1;
        } else if (this.getCenterX() > that.getCenterX()) {
            return 1;
        } else {
            if (this.getCenterY() < that.getCenterY()) {
                return -1;
            } else if (this.getCenterY() > that.getCenterY()) {
                return 1;
            }
        }
        return 0;

    }
}

class BallOverlapComparator implements Comparator<Ball> {

    @Override
    public int compare(Ball b1, Ball b2) {
        double distanceSquared = (b1.getCenterX() - b2.getCenterX()) * (b1.getCenterX() - b2.getCenterX()) +
                (b1.getCenterY() - b2.getCenterY()) * (b1.getCenterY() - b2.getCenterY());
        double radiusSumSquared = (b1.getRadius() + b2.getRadius()) * (b1.getRadius() + b2.getRadius());
        if (distanceSquared == radiusSumSquared) {
            return 1;
        } else if (distanceSquared > radiusSumSquared) {
            return -1;
        } else {
            return 0;
        }
    }
}

package ch_03;


import java.util.Scanner;


public class Exercise03_01 {
    public static void main(String[] args) {

        Scanner input = new Scanner(System.in);

        System.out.println("Enter values for a, b, and c now: ");

        double a, b, c;

        a = input.nextDouble();
        b = input.nextDouble();
        c = input.nextDouble();

        double discriminant = (b * b) - (4 * a * c);

        if (discriminant < 0) {
            System.out.println("The discriminate is negative, the equation has no real roots.");
        } else if (discriminant > 0) {
            double r1 = ((-1 * b) + Math.pow(discriminant, 0.5)) / (2 * a);
            double r2 = ((-1 * b) - Math.pow(discriminant, 0.5)) / (2 * a);

            System.out.print("Two real roots: " + r1 + ", " + r2);


        } else {
            double r = ((-1 * b) + Math.pow(discriminant, 0.5)) / (2 * a);
            System.out.print("One real root: " + r);
        }
        input.close();
    }

}

package ch_10.exercise10_08;


//_________________________UML DIAGRAM______________________________*
/*																	|
 * 							  Tax     								|
 *------------------------------------------------------------------|
 *           + SINGLE_FILER : int                                   |
 *           + MARRIED_JOINTLY_OR_QUALIFYING_WIDOW_ER : int         |
 *            + MARRIED_SEPARATELY : int                            |
 *            + HEAD_OF_HOUSEHOLD : int                             |
 *            - filingStatus : int                                  |
 *            - brackets : int[][]                                  |
 *            -  taxableIncome : double                             |
 *            - rates: double[]                                     |
 *                                                                  |
 *                                                                  |
 *------------------------------------------------------------------|
 *                     +Tax()          	    			       		|
 *                     +Tax(int[][], double[],double)       		|
 * 	 																|
 * 					+getTax(int[],double[],double):double           |
 * 						                                        	|
 * 				    ***** getters and setters  *****                |
 * 	 																|
 * 																	|
 *__________________________________________________________________|  */

import java.util.Arrays;


public class Tax {
    public static final int SINGLE_FILER = 0;
    public static final int MARRIED_JOINTLY_OR_QUALIFYING_WIDOW_ER = 1;
    public static final int MARRIED_SEPARATELY = 2;
    public static final int HEAD_OF_HOUSEHOLD = 3;

    private int filingStatus;
    private int[][] brackets;
    private double taxableIncome;
    private double[] rates;

    public Tax() {

    }

    Tax(int filingStatus, int[][] brackets, double[] rates, double taxableIncome) {
        this.filingStatus = filingStatus;
        this.brackets = brackets;
        this.rates = rates;
        this.taxableIncome = taxableIncome;
    }

    public double getTax() {
        int[] bracket = brackets[filingStatus];

        if (taxableIncome <= bracket[0]) {
            return taxableIncome * rates[0];
        }
        int i = 1;
        double tax = bracket[0] * rates[0];
        while (i < bracket.length) {
            if (taxableIncome <= bracket[i]) {
                return tax + (taxableIncome - bracket[i - 1]) * rates[i];
            }
            tax += (bracket[i] - bracket[i - 1]) * rates[i];
            i++;
        }
        return tax + (taxableIncome - bracket[bracket.length - 1]) * rates[rates.length - 1];
    }


    public int getFilingStatus() {
        return filingStatus;
    }

    public void setFilingStatus(int filingStatus) {
        this.filingStatus = filingStatus;
    }

    public int[][] getBrackets() {
        return brackets;
    }

    public void setBrackets(int[][] brackets) {
        this.brackets = brackets;
    }

    public double getTaxableIncome() {
        return taxableIncome;
    }

    public void setTaxableIncome(double taxableIncome) {
        this.taxableIncome = taxableIncome;
    }

    public double[] getRates() {
        return rates;
    }

    public void setRates(double[] rates) {
        this.rates = rates;
    }

    private int getNumRates() {
        return rates.length;
    }

    @Override
    public String toString() {
        int[] bracket = brackets[filingStatus];
        return "Tax{" +
                "filingStatus=" + filingStatus +
                ", brackets=" + Arrays.toString(bracket) +
                ", taxableIncome=" + taxableIncome +
                ", rates=" + Arrays.toString(rates) +
                '}';
    }
}

