package ch_04;


public class Exercise04_03 {

    static double addTwoTriangles(Triangle t1, Triangle t2) {
        return t1.area + t2.area;
    }

    public static void main(String[] args) {

        double radius = 6_371.01; // Mean radius of Planet Earth

        // Find distance between points for Triangle2D One
        double atlantaToCharlotte, charlotteToSavannah, savannahToAtlanta;

        atlantaToCharlotte = radius * Math.acos(Math.sin(-84.27822) * Math.sin(-81.5197542)
                + Math.cos(-84.2782200) * Math.cos(-81.5197542) * Math.cos(33.8901000 - 32.10815));

        charlotteToSavannah = radius * Math.acos(Math.sin(-80.95676) * Math.sin(-81.17461)
                + Math.cos(-80.95676) * Math.cos(-81.1746100) * Math.cos(35.20724 - 32.1081500));

        savannahToAtlanta = radius * Math.acos(Math.sin(-81.17461) * Math.sin(-84.27822)
                + Math.cos(-81.1746100) * Math.cos(-84.27822) * Math.cos(32.10815 - 33.8901));

        Triangle triangle1 = new Triangle(atlantaToCharlotte, charlotteToSavannah, savannahToAtlanta);
        triangle1.computeArea();

        // Find the distance need for Triangle2D two
        double savannahToOrlando, orlandoToAtlanta;

        savannahToOrlando = radius * Math.acos(Math.sin(-81.17461) * Math.sin(-81.5197542)
                + Math.cos(81.17461) * Math.cos(-81.5197542) * Math.cos(32.10815 - 28.4283959));

        orlandoToAtlanta = radius * Math.acos(Math.sin(-84.27822) * Math.sin(-81.519754)
                + Math.cos(81.17461) * Math.cos(-81.5197542) * Math.cos(33.8901000 - 28.4283959));

        Triangle triangle2 = new Triangle(savannahToOrlando, orlandoToAtlanta, savannahToAtlanta);
        triangle2.computeArea();

        double areaOfPolygon = addTwoTriangles(triangle1, triangle2);

        System.out.printf("Using the Great Circle calculation, the estimated area enclosed by "
                + "\nAtlanta, Charlotte, Savannah, and Orlando is %.4f", areaOfPolygon);

    }

}

class Triangle {

    double side1;
    double side2;
    double side3;
    double area;

    public Triangle(double side1, double side2, double side3) {
        this.side1 = side1;
        this.side2 = side2;
        this.side3 = side3;
    }

    void computeArea() {
        double s = side1 + side2 + side3;
        area = Math.sqrt(s * (s - side1) * (s - side2) * (s - side3));
    }


    public double getArea() {
        return area;
    }


    public void setArea(double area) {
        this.area = area;
    }
}

package ch_05;

import java.util.*;


public class Exercise05_18 {
    public static void main(String[] args) {
        patternA();
        System.out.println();

        patternB();
        System.out.println();

        patternC();
        System.out.println();

        patternD();
    }

    static void patternA() {
        System.out.println("Pattern A");
        int x = 1;
        for (int i = 0; i < 6; i++) {
            for (int j = 1; j <= x; j++) {
                System.out.print(j);
            }
            System.out.println();
            x++;
        }

    }

    static void patternB() {
        System.out.println("Pattern B");
        int x = 0;
        for (int i = 0; i < 6; i++) {
            for (int j = 1; j < 7 - x; j++) {
                System.out.print(j);
            }
            System.out.println();
            x++;
        }

    }

    static void patternC() {
        System.out.println("Pattern C");

        for (int i = 1; i <= 6; i++) {

            for (int j = 6 - i; j >= 1; j--) {
                System.out.print(" ");
            }
            for (int z = i; z >= 1; z--) {
                System.out.print(z);
            }
            System.out.println();

        }
    }

    static void patternD() {
        System.out.println("Pattern D");
        for (int i = 0; i < 6; i++) {

            for (int z = 0; z < i; z++) {
                System.out.print(" ");
            }
            for (int j = 1; j <= 6 - i; j++) {
                System.out.print(j);
            }
            System.out.println();

        }
    }
}

package com.sketchproject.infogue.modules;

import android.content.Context;
import android.graphics.Bitmap;
import android.support.v4.util.LruCache;

import com.android.volley.Request;
import com.android.volley.RequestQueue;
import com.android.volley.toolbox.ImageLoader;
import com.android.volley.toolbox.Volley;

/**
 * Singleton volley to populate request into single queue.
 * 
 * Sketch Project Studio
 * Created by Angga on 22/04/2016 22.58.
 */
public class VolleySingleton {
    private static VolleySingleton mInstance;
    private RequestQueue mRequestQueue;
    private ImageLoader mImageLoader;
    private static Context mCtx;

    /**
     * Private constructor, only initialization from getInstance.
     *
     * @param context parent context
     */
    private VolleySingleton(Context context) {
        mCtx = context;
        mRequestQueue = getRequestQueue();

        mImageLoader = new ImageLoader(mRequestQueue,
                new ImageLoader.ImageCache() {
                    private final LruCache<String, Bitmap> cache = new LruBitmapCache(mCtx);

                    @Override
                    public Bitmap getBitmap(String url) {
                        return cache.get(url);
                    }

                    @Override
                    public void putBitmap(String url, Bitmap bitmap) {
                        cache.put(url, bitmap);
                    }
                });
    }

    /**
     * Singleton construct design pattern.
     *
     * @param context parent context
     * @return single instance of VolleySingleton
     */
    public static synchronized VolleySingleton getInstance(Context context) {
        if (mInstance == null) {
            mInstance = new VolleySingleton(context);
        }
        return mInstance;
    }

    /**
     * Get current request queue.
     *
     * @return RequestQueue
     */
    public RequestQueue getRequestQueue() {
        if (mRequestQueue == null) {
            // getApplicationContext() is key, it keeps you from leaking the
            // Activity or BroadcastReceiver if someone passes one in.
            mRequestQueue = Volley.newRequestQueue(mCtx.getApplicationContext());
        }
        return mRequestQueue;
    }

    /**
     * Add new request depend on type like string, json object, json array request.
     *
     * @param req new request
     * @param <T> request type
     */
    public <T> void addToRequestQueue(Request<T> req) {
        getRequestQueue().add(req);
    }

    /**
     * Get image loader.
     *
     * @return ImageLoader
     */
    public ImageLoader getImageLoader() {
        return mImageLoader;
    }
}

package ch_06;


public class Exercise06_11 {
    public static void main(String[] args) {
        System.out.println("Sales  Commission Amount");
        for (int sales = 10000; sales <= 100000; sales += 5000) {
            System.out.print(sales);
            System.out.print("   ");
            System.out.printf("%.1f\n", computeCommission(sales));
        }

    }

    public static double computeCommission(double salesAmount) {
        double commission = 0;
        if (salesAmount <= 5000) {
            commission = salesAmount * 0.08;

        } else if (salesAmount <= 10000) {
            salesAmount -= 5000;
            commission = (5000 * 0.08) + (salesAmount * .10);

        } else if (salesAmount > 10000) {
            commission = (5000 * 0.08);
            salesAmount -= 5000;

            commission += (5000 * .10);
            salesAmount -= 5000;

            commission += salesAmount * .12;
        }
        return commission;
    }
}

