package ch_11;

import java.util.ArrayList;
import java.util.Scanner;


public class Exercise11_04 {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        System.out.print("Enter a sequence of numbers ending with a 0: ");

        ArrayList<Integer> list = new ArrayList<>();
        Integer integer;
        while ((integer = in.nextInt()) != 0) {
            list.add(integer);
        }

        System.out.println("The largest number is " + max(list));
        in.close();
    }

    public static Integer max(ArrayList<Integer> list) {
        if (list == null || list.isEmpty()) {
            return null;
        }
        Integer max = list.get(0);
        for (Integer integer : list) {
            max = Math.max(max, integer);
        }
        return max;
    }

}

package ch_21;

import java.io.IOException;
import java.net.URL;
import java.util.*;


public class Exercise21_12 {
    static final String BABY_NAMES_BASE_URL = "https://liveexample.pearsoncmg.com/data/";
    static final String START_FILE_NAME = "babynamesranking";

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        System.out.print("Enter a file name for baby name ranking: ");
        String fileName = in.next().trim();
        // Validate user input
        if (!fileName.startsWith(START_FILE_NAME)) {
            System.out.println("File name must start with: " + START_FILE_NAME);
            System.exit(1);
        }
        // Extract year value form filename
        int year = Integer.parseInt(fileName.split("\\.")[0].substring(START_FILE_NAME.length()));
        if (year < 2001 || year > 2010) { // Validate year
            System.out.println("Year in file name must be > 2000 and < 2011.");
            System.exit(2);
        }
        // Resolve the full URL path
        String fullFilePath = BABY_NAMES_BASE_URL + fileName;
        Set<String> set1 = new HashSet<>();
        Set<String> set2 = new HashSet<>();
        try {
            getNamesList(set2, set1, fullFilePath); // Use url path to fetch populate Sets
            set1.retainAll(set2); // Retain all values in set1 that exist in set2 (Intersection)
            System.out.println(set1.size() + " names used for both genders");
            System.out.print("They are ");
            int perLine = 0;
            for (String name : set1) {
                if (perLine % 10 == 0 && perLine != 0) {
                    System.out.print("\t\n"); // End line
                }
                System.out.print(name + " ");
                perLine++;
            }

        } catch (IOException e) {
            System.out.println("Something went wrong reading the URL created from the filename input...");
        }

        in.close();
    }

    static void getNamesList(Set<String> guyNameList,
                             Set<String> girlNameList,
                             String urlString) throws IOException {
        URL url = new URL(urlString);
        Scanner urlScanner = new Scanner(url.openStream());
        while (urlScanner.hasNextLine()) {
            String line = urlScanner.nextLine();
            String[] record = line.split("\\s+"); // Split line example result: {"1","Jacob","32,550","Emily","25,057"}
            String guyName = record[1];
            String girlName = record[3];
            guyNameList.add(guyName);
            girlNameList.add(girlName);

        }
        urlScanner.close();
    }

}

package ch_10.exercise10_11;
//__________________________UML DIAGRAM_____________________________*
/*																	|
 * 							 Circle2D  								|
 *------------------------------------------------------------------|
 *                     -x : double                					|
 *					   -y : double                                  |
 *                     -radius:double								|
 *------------------------------------------------------------------|
 *          	     +Circle2D()									|
 *          +Circle2D(x:double,y:double,radius:double)		        |
 * 	 																|
 * 	              +contains(x:double,y:double) : boolean   			|
 * 																	|
 * 	              +contains(circle2D: Circle2D): boolean            |
 *                +overlaps(circle2D: Circle2D): boolean           	|
 * 	 																|
 * 	               +getPerimeter(): double							|
 *  																|
 * 	               +getArea():double   								|
 * 																	|
 * _________________________________________________________________|  */


public class Circle2D {
    /* ■ Two double data fields named x and y that specify the center of the circle with getter methods.*/
    private double x;
    private double y;
    /* ■ A data field radius with a getter method. */
    private double radius;


    public Circle2D() {
        x = 0;
        y = 0;
        radius = 1;
    }


    public Circle2D(double x, double y, double radius) {
        this.x = x;
        this.y = y;
        this.radius = radius;
    }


    public double getArea() {
        return Math.PI * Math.pow(radius, 2);
    }


    public double getPerimeter() {
        return 2 * Math.PI * radius;
    }


    public boolean contains(double x, double y) {
        double distanceFromCenterPoint = Math.sqrt(Math.pow(this.x - x, 2) + Math.pow(this.y - y, 2));
        return distanceFromCenterPoint < radius;

    }


    public boolean contains(Circle2D circle2D) {
        double distFromCenterPoints =
                Math.sqrt(Math.pow(circle2D.getX() - this.x, 2) + Math.pow(circle2D.getY() - this.y,
                        2));
        return this.radius > (distFromCenterPoints + circle2D.getRadius());
    }


    public boolean overlaps(Circle2D circle2D) {
        double distCentPoints = Math.sqrt(Math.pow(circle2D.getX() - this.x, 2) + Math.pow(circle2D.getY() - this.y, 2));
        double rSqSum = Math.pow(circle2D.getRadius() + this.radius, 2);
        return distCentPoints < rSqSum;
    }

    /* Getters */
    public double getX() {
        return x;
    }

    public double getY() {
        return y;
    }

    public double getRadius() {
        return radius;
    }


}

