    @Override
    public void start(Stage primaryStage) throws Exception {
        Pane pane = new Pane();

        double wedge20Percent = 0.2 * 360;
        double wedge10Percent = 0.1 * 360;
        double wedge30Percent = 0.3 * 360;
        double wedge40Percent = 0.4 * 360;
