package ch_06;


public class Exercise06_24 {

    static int daysElapsedCurrentYear;
    static int getDaysElapsedCurrentMonth;

    public static void main(String[] args) {
        String time = getCurrentTime(System.currentTimeMillis());
        String date = getCurrentDate(System.currentTimeMillis());
        System.out.println("The current date is " + date + ". And the current time is " + time);
    }

    public static String getCurrentDate(long millis) {
        long seconds = millis / 1000;
        long min = seconds / 60;
        long hours = min / 60;
        long days = hours / 24;
        int year = getYear((int) days);
        int month = getCurrentMonth(year, daysElapsedCurrentYear);
        return month + "/" + getDaysElapsedCurrentMonth + "/" + year;
    }

    private static String getCurrentTime(long millis) {
        long seconds = millis / 1000;
        long currentSecond = seconds % 60;

        long min = seconds / 60;
        long currentMin = min % 60;

        long hours = min / 60;
        long currentHour = hours % 24;

        return currentHour + ":" + currentMin + ":" + currentSecond + "(GMT)";

    }

    public static int getYear(int totalDays) {
        int year = 1970;
        while (totalDays > 365) {
            totalDays -= numberOfDaysInAYear(year);
            year++;
            daysElapsedCurrentYear = totalDays;
        }
        return year;
    }


    public static int numberOfDaysInAYear(int year) {
        return isLeapYear(year) ? 366 : 365;
    }

    static boolean isLeapYear(int year) {
        return (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
    }

    public static int getCurrentMonth(int year, int daysElapsedInYear) {
        int month = 0;
        while (daysElapsedInYear > 0) {
            month++;
            getDaysElapsedCurrentMonth = daysElapsedInYear;
            daysElapsedInYear -= getNumberOfDaysInMonth(year, month);

        }
        return month;

    }

    public static int getNumberOfDaysInMonth(int year, int month) {
        if (month == 1 || month == 3 || month == 5 || month == 7 ||
                month == 8 || month == 10 || month == 12)
            return 31;
        if (month == 4 || month == 6 || month == 9 || month == 11)
            return 30;
        if (month == 2) return isLeapYear(year) ? 29 : 28;

        return 0;
    }
}

package ch_06;

import java.util.*;


public class Exercise06_06 {
    public static void displayPattern(int n) {
        int pad = n - 1; //Track padding to loop for each line
        for (int r = 1; r <= n; r++) { //Main loop

            for (int p = 0; p < pad; p++) {
                System.out.print("  ");
            }

            for (int i = r; i > 0; i--) {
                System.out.print(i + " ");
            }
            System.out.println();
            pad--; // decrease padding as we increase r in for loop
        }

    }

    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        System.out.println("Enter the number of rows to print: ");
        int userRows = input.nextInt();

        displayPattern(userRows);

    }
}

package ch_17.exercise17_18;

import java.io.BufferedInputStream;
import java.io.FileInputStream;
import java.util.ArrayList;
import java.util.Scanner;


public class Exercise17_18 {
    static BufferedInputStream bufferedInputStream;
    static ArrayList<String> strBytes;

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        strBytes = new ArrayList<>();
        System.out.println("Enter a filename: ");
        String fileName = in.nextLine().trim();
        try {
            bufferedInputStream = new BufferedInputStream(new FileInputStream(fileName));
            int b;
            while ((b = bufferedInputStream.read()) != -1) {
                String val = getBits(b);
                strBytes.add(val);
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
        System.out.println("The contents of the file, converted to bytes are: ");
        System.out.println(strBytes.toString());

        in.close();
    }

    public static String getBits(int value) {
        StringBuilder bits = new StringBuilder();
        long i;
        for (i = 128; i > 0; i /= 2) {
            bits.append((value & i) != 0 ? "1" : "0");
        }
        return bits.toString();
    }
}

import android.graphics.Bitmap;
import android.graphics.Bitmap.Config;
import android.graphics.BitmapShader;
import android.graphics.Canvas;
import android.graphics.Paint;
import android.graphics.RectF;
import android.graphics.Shader;

// enables hardware accelerated rounded corners
// original idea here : http://www.curious-creature.org/2012/12/11/android-recipe-1-image-with-rounded-corners/
public class RoundedTransformation implements com.squareup.picasso.Transformation {
    private final int radius;
    private final int margin;  // dp

    // radius is corner radii in dp
    // margin is the board in dp
    public RoundedTransformation(final int radius, final int margin) {
        this.radius = radius;
        this.margin = margin;
    }

    @Override
    public Bitmap transform(final Bitmap source) {
        final Paint paint = new Paint();
        paint.setAntiAlias(true);
        paint.setShader(new BitmapShader(source, Shader.TileMode.CLAMP, Shader.TileMode.CLAMP));

        Bitmap output = Bitmap.createBitmap(source.getWidth(), source.getHeight(), Config.ARGB_8888);
        Canvas canvas = new Canvas(output);
        canvas.drawRoundRect(new RectF(margin, margin, source.getWidth() - margin, source.getHeight() - margin), radius, radius, paint);

        if (source != output) {
            source.recycle();
        }

        return output;
    }

    @Override
    public String key() {
        return "rounded";
    }
}

