package ch_05;

import java.util.*;


public class Exercise05_20 {
    public static void main(String[] args) {

        int nextLineCount = 8;
        for (int i = 2; i <= 1000; i++) {

            if (isPrime(i)) {
                System.out.print(i + " ");
                --nextLineCount;
                if (nextLineCount == 0) {
                    System.out.println();
                    nextLineCount = 8;
                }
            }
        }
    }

    static boolean isPrime(int n) {
        boolean notPrime = false;
        int d = 2;
        while (d <= n / 2) {
            if (n % d == 0) {
                notPrime = true;
                break;
            }
            ++d;
        }
        return !notPrime;

    }
}

package ch_08;

import java.util.*;


public class Exercise08_23 {
    public static void main(String[] args) {
        int[][] test = new int[6][6];

        Scanner in = new Scanner(System.in);
        System.out.println("Enter a 6 x 6 matrix row by row: ");

        int invalidRow = -1; //Initialize

        for (int i = 0; i < 6; i++) {
            int rowCountOnes = 0;
            for (int j = 0; j < 6; j++) {
                int n = in.nextInt();
                if (n == 1) {
                    rowCountOnes++;
                }
                test[i][j] = n;
            }
            if (rowCountOnes % 2 != 0) {
                invalidRow = i;
            }
        }
        int invalidCol = evalColumns(test);
        System.out.println("The flipped cell is at (" + invalidRow + ", " + invalidCol + ")");
        in.close();
    }

    static int evalColumns(int[][] array) {
        int invalidColumn = -1;
        for (int i = 0; i < 6; i++) {
            int colCount = 0;
            for (int j = 0; j < 6; j++) {
                if (array[j][i] == 1) {
                    colCount++;
                }

            }
            if (colCount % 2 != 0) {
                invalidColumn = i;
            }
        }
        return invalidColumn;
    }

}

package ch_18;

import javafx.application.Application;
import javafx.geometry.Insets;
import javafx.geometry.Pos;
import javafx.scene.Scene;
import javafx.scene.control.Button;
import javafx.scene.control.Label;
import javafx.scene.layout.BorderPane;
import javafx.scene.layout.GridPane;
import javafx.scene.layout.HBox;
import javafx.scene.layout.StackPane;
import javafx.scene.paint.Color;
import javafx.scene.shape.Line;
import javafx.scene.shape.Rectangle;
import javafx.stage.Stage;



public class Exercise18_26 extends Application {
    //  The maze is represented by an 8 * 8 board
    private GameCell[][] board = new GameCell[8][8];

    private final double WIDTH = 400;
    private final double HEIGHT = 400;


    private final Button findButton = new Button("Find Path");
    private final Button clearButton = new Button("Clear Path");
    private final Label mainLabel = new Label();

    @Override
    public void start(Stage primaryStage) {
        GridPane gridPane = new GridPane();
        for (int i = 0; i < 8; i++) {
            for (int j = 0; j < 8; j++) {
                gridPane.add(board[i][j] = new GameCell(), j, i);
            }
        }

        HBox hBox = new HBox(5);
        hBox.setAlignment(Pos.CENTER);
        HBox.setMargin(findButton, new Insets(5, 5, 10, 5));
        HBox.setMargin(clearButton, new Insets(5, 5, 10, 5));

        hBox.getChildren().addAll(findButton, clearButton);

        BorderPane pane = new BorderPane();
        pane.setTop(mainLabel);
        BorderPane.setAlignment(mainLabel, Pos.CENTER);
        pane.setCenter(gridPane);
        pane.setBottom(hBox);
        BorderPane.setMargin(gridPane, new Insets(5, 5, 5, 5));

        Scene scene = new Scene(pane, WIDTH + 15, HEIGHT + 80);
        primaryStage.setTitle(getClass().getName());
        primaryStage.setScene(scene);
        primaryStage.setResizable(false);
        primaryStage.show();

        findButton.setOnAction(e -> findPath());
        clearButton.setOnAction(e -> clear());
    }

    public void findPath() {
        if (findPath(0, 0)) {
            mainLabel.setText("path found");
        } else {
            mainLabel.setText("No legal path exists");
        }
    }

    public boolean findPath(int row, int col) {
        board[row][col].visit();

        if ((col == 7) && (row == 7)) {
            board[row][col].select();
            return true;
        }

        if ((row > 0) && !board[row - 1][col].isMarked() &&
                !board[row - 1][col].blocked() && !board[row - 1][col].visited()) {
            block(row, col);

            if (findPath(row - 1, col)) {
                board[row][col].select();
                return true;
            }

            unblock(row, col);
        }

        if ((row < 7) && !board[row + 1][col].isMarked() &&
                !board[row + 1][col].blocked() && !board[row + 1][col].visited()) {
            block(row, col);

            if (findPath(row + 1, col)) {
                board[row][col].select();
                return true;
            }

            unblock(row, col);
        }

        if ((col > 0) && !board[row][col - 1].isMarked() &&
                !board[row][col - 1].blocked() && !board[row][col - 1].visited()) {
            block(row, col);
            if (findPath(row, col - 1)) {
                board[row][col].select();
                return true;
            }

            unblock(row, col);
        }

        if ((col < 7) && !board[row][col + 1].isMarked() &&
                !board[row][col + 1].blocked() && !board[row][col + 1].visited()) {
            block(row, col);
            if (findPath(row, col + 1)) {
                board[row][col].select();
                return true;
            }

            unblock(row, col);
        }

        return false;
    }

    public void block(int row, int col) {
        if (row > 0) {
            board[row - 1][col].block();
        }

        if (row < 7) {
            board[row + 1][col].block();
        }

        if (col > 0) {
            board[row][col - 1].block();
        }

        if (col < 7) {
            board[row][col + 1].block();
        }
    }

    public void unblock(int row, int col) {
        if (row > 0) {
            board[row - 1][col].unblock();
        }

        if (row < 7) {
            board[row + 1][col].unblock();
        }

        if (col > 0) {
            board[row][col - 1].unblock();
        }

        if (col < 7) {
            board[row][col + 1].unblock();
        }
    }

    public void clear() {
        for (GameCell[] gameCells : board) {
            for (GameCell gameCell : gameCells) {
                gameCell.unselect();
            }
        }
    }

    class GameCell extends StackPane {
        private boolean visited = false;
        private boolean blocked = false;

        private boolean selected = false;

        double width = WIDTH / 8;
        double height = HEIGHT / 8;
        private Rectangle rectangle = new Rectangle(0, 0, width, height);

        Line line1 = new Line(0, 0, width, height);
        Line line2 = new Line(width, 0, 0, height);

        public GameCell() {
            this.getChildren().add(rectangle);
            rectangle.setFill(Color.WHITE);
            rectangle.setStroke(Color.BLACK);

            this.setOnMousePressed(e -> {
                selected = !selected;
                if (selected) {
                    mark();
                } else {
                    unmark();
                }
            });
        }

        public void mark() {
            this.getChildren().addAll(line1, line2);
        }

        public void unmark() {
            this.getChildren().remove(line1);
            this.getChildren().remove(line2);
        }

        public boolean isMarked() {
            return selected;
        }

        public void visit() {
            visited = true;
        }

        public boolean visited() {
            return visited;
        }

        public boolean blocked() {
            return blocked;
        }

        public void block() {
            blocked = true;
        }

        public void unblock() {
            blocked = false;
        }

        public void select() {
            rectangle.setFill(Color.RED);
        }

        public void unselect() {
            rectangle.setFill(Color.WHITE);
            blocked = false;
            visited = false;
        }
    }


    public static void main(String[] args) {
        Application.launch(args);
    }

}

package ch_19;

import java.util.Arrays;


public class Exercise19_07 {
    public static void main(String[] args) {
        Double searchKey = 111.11;
        Double[] values = new Double[]{4400.1, 1203.3, 3100.0, 18700.8, 4100.6, 111.11, 2222.21, 4529.21};

        System.out.println("Generic Binary Search method found the search key value: " + searchKey + " at index: " + binarySearch(values,
                searchKey) + " in the above array.");

    }

    public static <E extends Comparable<E>> int binarySearch(E[] list, E key) {
        System.out.println("Sorting the array to ensure binarySearch is supported: ");
        Arrays.sort(list);
        System.out.println(Arrays.toString(list));
        int lowIdx = 0; // First element in the array
        int highIdx = list.length - 1; // Last element in the array
        while (highIdx >= lowIdx) {
            int midIdx = (lowIdx + highIdx) / 2;
            int compare = key.compareTo(list[midIdx]); // Compare key to value at midIdx
            if (compare < 0) { // Key is less than list[midIdx]
                highIdx = midIdx - 1; // Value can only be to the left of list[midIdx]
            } else if (compare == 0) { // Key equals list[midIdx]
                return midIdx; // Return the index of matched value
            } else { // Key is greater than list[midIdx]
                lowIdx = midIdx + 1; // Value can only be to the right of list[midIdx]
            }
        }
        return -1; // No matching value found in list
    }
}

package ch_07;

import java.util.Arrays;
import java.util.Scanner;


public class Exercise07_20 {

    public static void main(String[] args) {
        double[] arr = new double[10];

        Scanner in = new Scanner(System.in);
        System.out.println("Enter ten decimal numbers: ");
        for (int i = 0; i < 10; i++) {
            arr[i] = in.nextDouble();
        }
        selectionSort(arr);
        System.out.println("Sorted high to low: ");
        System.out.println(Arrays.toString(arr));


    }


    public static void selectionSort(double[] list) {
        for (int i = 0; i < list.length - 1; i++) {
            // Find the minimum in the list[i..list.length-1]
            double currentMax = list[i];
            int currentMaxIndex = i;
            for (int j = i + 1; j < list.length; j++) {
                if (currentMax < list[j]) {
                    currentMax = list[j];
                    currentMaxIndex = j;
                }
            }
            // Swap list[i] with list[currentMaxIndex] if necessary
            if (currentMaxIndex != i) {
                list[currentMaxIndex] = list[i];
                list[i] = currentMax;
            }
        }
    }
}

package ch_04;

import java.util.*;


public class Exercise04_07 {

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        System.out.print("Enter the radius of the bounding circle: ");
        double radius = in.nextDouble();
        double angleIncrement = Math.toRadians(360 / 5.0); // Divide by number of points

        // Find angle with 0,0 for five points on the the bounding circle
        double p1Angle = angleIncrement;
        double p2Angle = angleIncrement * 2;
        double p3Angle = angleIncrement * 3;
        double p4Angle = angleIncrement * 4;
        double p5Angle = angleIncrement * 5;

        System.out.printf("(%.4f, %.4f)\n", radius * Math.sin(p1Angle), radius * Math.cos(p1Angle));
        System.out.printf("(%.4f, %.4f)\n", radius * Math.sin(p2Angle), radius * Math.cos(p2Angle));
        System.out.printf("(%.4f, %.4f)\n", radius * Math.sin(p3Angle), radius * Math.cos(p3Angle));
        System.out.printf("(%.4f, %.4f)\n", radius * Math.sin(p4Angle), radius * Math.cos(p4Angle));
        System.out.printf("(%.4f, %.4f)\n", radius * Math.sin(p5Angle), radius * Math.cos(p5Angle));

        in.close();


    }
}

