package com.example.android.charsperline;

import android.content.Context;
import android.content.res.TypedArray;
import android.util.AttributeSet;
import android.view.View;
import android.view.ViewGroup;
import android.widget.LinearLayout;

/**
 * A simple {@link LinearLayout} subclass, useful only in the vertical orientation, that allows each
 * child to define a maximum width using a {@link LayoutParams#maxWidth layout_maxWidth} attribute
 * (only useful if the child's {@link ViewGroup.LayoutParams#width layout_width} is {@link
 * ViewGroup.LayoutParams#MATCH_PARENT}).
 */
public class MaxWidthLinearLayout extends LinearLayout {
    public MaxWidthLinearLayout(Context context) {
        super(context);
    }

    public MaxWidthLinearLayout(Context context, AttributeSet attrs) {
        super(context, attrs);
    }

    public MaxWidthLinearLayout(Context context, AttributeSet attrs, int defStyle) {
        super(context, attrs, defStyle);
    }

    /**
     * Temporarily assign a new {@link ViewGroup.LayoutParams#width} to the maximum width if the
     * child would normally exceed the maximum width.
     */
    private void assignTemporaryChildWidthDuringMeasure(View child, int parentWidthMeasureSpec) {
        LayoutParams lp = (LayoutParams) child.getLayoutParams();
        assert lp != null;
        int availableWidth = MeasureSpec.getSize(parentWidthMeasureSpec);
        if (lp.width == LayoutParams.MATCH_PARENT && availableWidth > lp.maxWidth) {
            lp.oldLayoutWidth = LayoutParams.MATCH_PARENT;
            lp.width = Math.min(lp.maxWidth, availableWidth);
        }
    }

    /**
     * Revert any changes caused by {@link #assignTemporaryChildWidthDuringMeasure(android.view.View,
     * int)}.
     */
    private void revertChildWidthDuringMeasure(View child) {
        LayoutParams lp = (LayoutParams) child.getLayoutParams();
        assert lp != null;
        if (lp.oldLayoutWidth != Integer.MIN_VALUE) {
            lp.width = lp.oldLayoutWidth;
        }
    }

    @Override
    protected void measureChild(View child, int parentWidthMeasureSpec,
            int parentHeightMeasureSpec) {
        assignTemporaryChildWidthDuringMeasure(child, parentWidthMeasureSpec);
        super.measureChild(child, parentWidthMeasureSpec, parentHeightMeasureSpec);
        revertChildWidthDuringMeasure(child);
    }

    @Override
    protected void measureChildWithMargins(View child, int parentWidthMeasureSpec,
            int widthUsed, int parentHeightMeasureSpec, int heightUsed) {
        assignTemporaryChildWidthDuringMeasure(child, parentWidthMeasureSpec);
        super.measureChildWithMargins(child, parentWidthMeasureSpec, widthUsed,
                parentHeightMeasureSpec, heightUsed);
        revertChildWidthDuringMeasure(child);
    }

    @Override
    protected MaxWidthLinearLayout.LayoutParams generateDefaultLayoutParams() {
        return new LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.MATCH_PARENT);
    }

    @Override
    public MaxWidthLinearLayout.LayoutParams generateLayoutParams(AttributeSet attrs) {
        return new MaxWidthLinearLayout.LayoutParams(getContext(), attrs);
    }

    @Override
    protected LinearLayout.LayoutParams generateLayoutParams(ViewGroup.LayoutParams lp) {
        return new MaxWidthLinearLayout.LayoutParams(lp);
    }

    @Override
    protected boolean checkLayoutParams(ViewGroup.LayoutParams lp) {
        return lp instanceof MaxWidthLinearLayout.LayoutParams;
    }

    /**
     * Provides additional layout params (specifically {@link #maxWidth layout_maxWidth}) for
     * children of {@link MaxWidthLinearLayout}.
     */
    public static class LayoutParams extends LinearLayout.LayoutParams {
        private int maxWidth;
        private int oldLayoutWidth = Integer.MIN_VALUE; // used to store old lp.width during measure

        public LayoutParams(Context c, AttributeSet attrs) {
            super(c, attrs);

            TypedArray a = c.obtainStyledAttributes(attrs, R.styleable.MaxWidthLinearLayout_Layout);
            assert a != null;
            maxWidth = a.getLayoutDimension(
                    R.styleable.MaxWidthLinearLayout_Layout_layout_maxWidth, Integer.MAX_VALUE);
        }

        public LayoutParams(int width, int height) {
            super(width, height);
        }

        public LayoutParams(int width, int height, int gravity) {
            super(width, height, gravity);
        }

        public LayoutParams(ViewGroup.LayoutParams source) {
            super(source);
        }

        public LayoutParams(MarginLayoutParams source) {
            super(source);
        }
    }
}

package ch_10.exercise10_14;

import java.util.GregorianCalendar;

//_________________________UML DIAGRAM______________________________*
/*																	|
 * 			    		      MyDate         			    		|
 *------------------------------------------------------------------|
 *                     	   -day : int	                       		|
 *                         -month : int  							|
 * 							-year:int   					 		|
 *------------------------------------------------------------------|
 *                     +MyDate()            	    				|
 *                     +MyDate(int, int,int)          		    	|
 *                     +MyDate(long)                       	    	|
 * 	 																|
 * 	 			        setDate(long):void 							|
 * 						                                        	|
 * 	 			    	getters and setters 						|
 * 																	|
 *__________________________________________________________________|  */


public class MyDate {
    GregorianCalendar gregorianCalendar = new GregorianCalendar();
    private int year;
    private int month;
    private int day;

    public MyDate() {
        this(System.currentTimeMillis());
    }

    public MyDate(long elapsedTime) {
        setDate(elapsedTime);
    }

    public MyDate(int year, int month, int day) {
        this.year = year;
        this.month = month;
        this.day = day;
    }


    public void setDate(long elapsedTime) {
        gregorianCalendar.setTimeInMillis(elapsedTime);
        this.year = gregorianCalendar.get(GregorianCalendar.YEAR);
        this.month = gregorianCalendar.get(GregorianCalendar.MONTH);
        this.day = gregorianCalendar.get(GregorianCalendar.DAY_OF_MONTH);
    }

    public int getYear() {
        return year;
    }

    public MyDate setYear(int year) {
        this.year = year;
        return this;
    }

    public int getMonth() {
        return month;
    }

    public MyDate setMonth(int month) {
        this.month = month;
        return this;
    }

    public int getDay() {
        return day;
    }

    public MyDate setDay(int day) {
        this.day = day;
        return this;
    }
}

package ch_23;

import java.util.Arrays;
import java.util.Comparator;


public class Exercise23_06 {

    public static void main(String[] args) {
        /* Test int[] */
        int[] listAsc = {1, 2, 3, 4, 7, 9, 11, 27};
        int[] listDesc = {27, 26, 23, 14, 11, 9, 6, 3, 2, 1};
        System.out.print("listAsc = ");
        System.out.print(Arrays.toString(listAsc));
        System.out.println();
        System.out.print("listDesc = ");
        System.out.print(Arrays.toString(listDesc));
        System.out.println();
        System.out.println("listAsc, is ascending?: " + ordered(listAsc));
        System.out.println("listDesc, is descending? " + ordered(listDesc, false));
        System.out.println("listDesc, is ascending?: " + ordered(listDesc));
        System.out.println("listAsc, is descending? " + ordered(listAsc, false));
        /* Test double[] */
        double[] listAscDoubles = {1.3, 2.1, 3.2, 3.4, 3.7, 3.9, 11.21, 27.54};
        double[] listDescDoubles = {27.6, 26.1, 23.3, 14.3, 11.54, 3.9, 3.6, 3.3, 3.2, 3.1};
        System.out.print("listAscDoubles = ");
        System.out.print(Arrays.toString(listAscDoubles));
        System.out.println();
        System.out.print("listDescDoubles = ");
        System.out.print(Arrays.toString(listDescDoubles));
        System.out.println();
        System.out.println("listAscDoubles, is ascending?: " + ordered(listAscDoubles));
        System.out.println("listDescDoubles, is descending? " + ordered(listDescDoubles, false));
        System.out.println("listDescDoubles, is ascending?: " + ordered(listDescDoubles));
        System.out.println("listAscDoubles, is descending? " + ordered(listAscDoubles, false));
        /* Test E[] where E implements Comparable */
        Integer[] listAscInteger = {1, 2, 3, 4, 7, 9, 11, 27};
        Integer[] listDescInteger = {27, 26, 23, 14, 11, 9, 6, 3, 2, 1};
        System.out.print("listAscInteger = ");
        System.out.print(Arrays.toString(listAscInteger));
        System.out.println();
        System.out.print("listDescInteger = ");
        System.out.print(Arrays.toString(listDescInteger));
        System.out.println();
        System.out.println("listAscInteger, is ascending?: " + ordered(listAscInteger));
        System.out.println("listDescInteger, is descending? " + ordered(listDescInteger, false));
        System.out.println("listDescInteger, is ascending?: " + ordered(listDescInteger));
        System.out.println("listAscInteger, is descending? " + ordered(listAscInteger, false));

        /* Test E[] using Comparator */
        Integer[] listAscWithComparator = {1, 2, 3, 4, 7, 9, 11, 27};
        Integer[] listDescWithComparator = {27, 26, 23, 14, 11, 9, 6, 3, 2, 1};
        System.out.print("listAscWithComparator = ");
        System.out.print(Arrays.toString(listAscWithComparator));
        System.out.println();
        System.out.print("listDescWithComparator = ");
        System.out.print(Arrays.toString(listDescWithComparator));
        System.out.println();
        System.out.println("listAscWithComparator, is ascending?: " + ordered(listAscWithComparator,
                (o1, o2) -> {
                    if (o1 > o2) return 1;
                    if (o1 < o2) return -1;
                    return 0;
                }));
        System.out.println("listDescWithComparator, is descending? " + ordered(listDescWithComparator, (o1, o2) -> {
            if (o1 > o2) return 1;
            if (o1 < o2) return -1;
            return 0;
        }, false));
        System.out.println("listDescWithComparator, is ascending?: " + ordered(listDescWithComparator, (o1, o2) -> {
            if (o1 > o2) return 1;
            if (o1 < o2) return -1;
            return 0;
        }));
        System.out.println("listAscWithComparator, is descending? " + ordered(listAscWithComparator, (o1, o2) -> {
            if (o1 > o2) return 1;
            if (o1 < o2) return -1;
            return 0;
        }, false));

    }

    public static boolean ordered(int[] list) {
        for (int i = 0; i < list.length - 1; i++) {
            if (list[i] > list[i + 1]) return false;
        }
        return true;
    }

    public static boolean ordered(int[] list,
                                  boolean ascending) {
        if (!ascending) {
            for (int i = 0; i < list.length - 1; i++) {
                if (list[i] < list[i + 1]) return false;
            }
            return true;
        }
        for (int i = 0; i < list.length - 1; i++) {
            if (list[i] > list[i + 1]) return false;
        }
        return true;
    }

    public static boolean ordered(double[] list) {
        for (int i = 0; i < list.length - 1; i++) {
            if (list[i] > list[i + 1]) return false;
        }
        return true;
    }

    public static boolean ordered(double[] list,
                                  boolean ascending) {
        if (!ascending) {
            for (int i = 0; i < list.length - 1; i++) {
                if (list[i] < list[i + 1]) return false;
            }
            return true;
        }
        for (int i = 0; i < list.length - 1; i++) {
            if (list[i] > list[i + 1]) return false;
        }
        return true;
    }

    public static <E extends Comparable<E>> boolean ordered(E[] list) {
        for (int i = 0; i < list.length - 1; i++) {
            if (list[i].compareTo(list[i + 1]) > 0) return false;
        }
        return true;
    }

    public static <E extends Comparable<E>> boolean ordered(
            E[] list,
            boolean ascending) {
        if (!ascending) {
            for (int i = 0; i < list.length - 1; i++) {
                if (list[i].compareTo(list[i + 1]) < 0) return false;
            }
            return true;
        }

        for (int i = 0; i < list.length - 1; i++) {
            if (list[i].compareTo(list[i + 1]) > 0) return false;
        }
        return true;
    }

    public static <E> boolean ordered(E[] list,
                                      Comparator<? super E> comparator) {
        for (int i = 0; i < list.length - 1; i++) {
            if (comparator.compare(list[i], list[i + 1]) > 0) return false;
        }
        return true;
    }

    public static <E> boolean ordered(E[] list,
                                      Comparator<? super E> comparator,
                                      boolean ascending) {
        if (!ascending) {
            for (int i = 0; i < list.length - 1; i++) {
                if (comparator.compare(list[i], list[i + 1]) < 0) return false;
            }
            return true;
        }

        for (int i = 0; i < list.length - 1; i++) {
            if (comparator.compare(list[i], list[i + 1]) > 0) return false;
        }
        return true;
    }
}

package ch_20;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.PriorityQueue;


public class Exercise20_10 {
    private static String[] l1 = new String[]{"George", "Jim", "John", "Blake", "Kevin", "Michael"};
    private static String[] l2 = new String[]{"George", "Katie", "Kevin", "Michelle", "Ryan"};


    public static void main(String[] args) {
        PriorityQueue<String> priorityQueue1 = new PriorityQueue<>(Arrays.asList(l1));
        PriorityQueue<String> priorityQueue2 = new PriorityQueue<>(Arrays.asList(l2));

        HashSet<String> union = new HashSet<>(priorityQueue1);
        union.addAll(priorityQueue2);
        System.out.println("Union: " + union);

        PriorityQueue<String> difference = new PriorityQueue<>(priorityQueue1);
        difference.removeAll(priorityQueue2);
        System.out.println("Difference: " + difference);

        PriorityQueue<String> intersection = new PriorityQueue<>(priorityQueue1);
        intersection.retainAll(priorityQueue2);
        System.out.println("Intersection: " + intersection);
    }
}

package ch_14;


import javafx.application.Application;
import javafx.scene.Scene;
import javafx.scene.image.Image;
import javafx.scene.image.ImageView;
import javafx.scene.layout.GridPane;
import javafx.scene.layout.Pane;
import javafx.stage.Stage;

import java.io.File;
import java.util.Random;


public class Exercise14_02 extends Application {
    Random random = new Random();
    static final String resourcePath = "resources" + File.separator + "tictactoe";

    @Override
    public void start(Stage primaryStage) throws Exception {
        GridPane gameBoard = new GridPane();
        Image X = new Image(resourcePath + File.separator + "x.png");
        Image O = new Image(resourcePath + File.separator + "o.png");

        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                Pane pane = new Pane();
                ImageView imageView = new ImageView();
                if (getRandomXO()) {
                    if (getRandomXO()) {
                        imageView.setImage(X);
                    } else {
                        imageView.setImage(O);
                    }

                }
                imageView.setPreserveRatio(true);
                imageView.setFitHeight(100);
                pane.getChildren().add(imageView);
                gameBoard.add(pane, i, j);
            }
        }
        Scene scene = new Scene(gameBoard, 315, 315);
        primaryStage.setTitle(getClass().getName());
        primaryStage.setScene(scene);
        primaryStage.show();
    }

    boolean getRandomXO() {
        return random.nextBoolean();
    }
}

package ch_13.exercise13_12;

import java.util.Random;


public class Exercise13_12 {
    static Random randomDbl = new Random(99999);

    public static void main(String[] args) {
        GeometricObject[] test = new GeometricObject[4];
        for (int i = 0; i < 2; i++) {
            test[i] = new Rectangle(randomDbl.nextDouble() * 9, randomDbl.nextDouble() * 9);
            System.out.println("Created a Rectangle with area: " + test[i].getArea());
        }
        for (int i = 2; i < test.length; i++) {
            test[i] = new Circle(randomDbl.nextDouble() * 9);
            System.out.println("Created Circle with area: " + test[i].getArea());
        }
        double sumOfArea = sumArea(test);
        System.out.println("Total area is " + sumOfArea);
    }

    public static double sumArea(GeometricObject[] a) {
        double totalArea = 0.0;
        for (GeometricObject geometricObject : a) {
            totalArea += geometricObject.getArea();
        }
        return totalArea;

    }

}

public final class ApiHeaders implements RequestInterceptor {

  private Application application;

  @Inject
  public ApiHeaders(Application application) {
    this.application = application;
  }

  @Override
  public void intercept(RequestFacade request) {
    AccountManager accountManager = AccountManager.get(application);
    Account[] accounts = accountManager.getAccountsByType(AuthConstants.ACCOUNT_TYPE);
    if (accounts.length != 0) {
      String token =
          accountManager.peekAuthToken(accounts[0], AuthConstants.AUTHTOKEN_TYPE);
      if (token != null) {
        request.addHeader("Authorization", "Bearer " + token);
      }
    }
    request.addHeader("Accept", "application/javascript, application/json");
  }
}

