package ch_09.exercise09_13;


public class Location {

    public double maxValue = Integer.MIN_VALUE;
    public int row;
    public int column;


    public static Location locateLargest(double[][] a) {
        Location location = new Location();
        for (int i = 0; i < a.length; i++) {
            for (int j = 0; j < a[i].length; j++) {
                if (a[i][j] > location.maxValue) {
                    location.maxValue = a[i][j];
                    location.row = i;
                    location.column = j;
                }

            }
        }
        return location;
    }
}

package ch_18;

import java.util.Scanner;


public class Exercise18_17 {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        System.out.print("Enter a list of characters in one line: ");
        String line = in.nextLine();
        char[] chars = line.toCharArray();

        System.out.println("Enter a single character: ");
        char ch = in.next().charAt(0);
        System.out.println("The character " + ch + " occurs " + count(chars, ch) + " times.");
        in.close();
    }

    public static int count(char[] chars, char ch) {
        return count(chars, ch, chars.length - 1);
    }

    public static int count(char[] chars, char ch, int high) {
        if (high > 0) {
            return chars[high] == ch ? (1 + count(chars, ch, high - 1)) : (count(chars, ch, high - 1));
        } else {
            return 0;
        }
    }
}

package ch_07;

import java.util.*;


public class Exercise07_11 {
    static double mean;

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        double[] nums = new double[10];
        System.out.print("Enter 10 numbers: ");
        for (int i = 0; i < nums.length; i++) {
            nums[i] = in.nextDouble();
        }
        mean = mean(nums);
        double std = deviation(nums);

        System.out.printf("The mean is %.2f" + "\n", mean);
        System.out.printf("The standard deviation is %.5f", std);
    }

    public static double deviation(double[] x) {
        double numerator = 0.0;
        double denominator = x.length - 1;
        for (double d : x) {
            numerator += Math.pow((d - mean), 2);
        }
        return Math.sqrt((numerator / denominator));

    }

    public static double mean(double[] x) {
        double sum = 0;
        double total = x.length;
        for (double d : x) {
            sum += d;
        }
        return sum / total;

    }
}

package ch_08;

import java.util.*;


public class Exercise08_20 {
    private static final String RED = "R";
    private static final String YELLOW = "Y";
    private static final String WIN = "win";
    private static final String CONTINUE = "continue";
    private static final String DRAW = "draw";
    private static final String EMPTY = " ";
    private static final String DASH = "-";
    private static final String SEP = "|";

    static boolean turn = true; //false is reds turn

    public static void main(String[] args) {
        int numMoves = 0;
        String[][] board = new String[6][7];
        for (String[] strings : board) {
            Arrays.fill(strings, EMPTY);
        }
        Scanner in = new Scanner(System.in);
        String result = CONTINUE; //Initialize result of a move
        while (true) {
            turn = !turn; //Other players turn
            int move = printBoard(board, turn ? YELLOW : RED, in);
            playerMove(move, board, turn ? YELLOW : RED);
            result = evaluateGame(board);
            if (result.equals(WIN)) {
                printBoard(board);
                if (turn) { // Yellow won
                    System.out.println("The yellow player won.");
                } else { // Red Won
                    System.out.println("The red player won.");
                }
                break;
            } else if (result.equals(DRAW)) {
                System.out.println("The game is a draw.");
            }

        }

    }

    static void playerMove(int column, String[][] board, String player) {

        for (int r = (board.length - 1); r >= 0; r--) {
            String val = board[r][column];
            if (val.equals(EMPTY)) {
                board[r][column] = player;
                break;
            }
        }

    }

    static String evaluateGame(String[][] board) {
        int redPoints;
        int yellowPoints = 0;

        /* Check rows */
        for (int r = 0; r < board.length; r++) {
            redPoints = 0;
            yellowPoints = 0;
            for (int c = 0; c < board[r].length; c++) {
                String g = board[r][c];
                if (!g.equals(EMPTY)) {
                    if (g.equals(RED)) {
                        redPoints++;
                        yellowPoints = 0;
                    } else if (g.equals(YELLOW)) {
                        yellowPoints++;
                        redPoints = 0;
                    }
                    if (redPoints >= 4) {
                        return WIN;
                    } else if (yellowPoints >= 4) {
                        return WIN;
                    }
                } else {
                    redPoints = 0;
                    yellowPoints = 0;
                }
            }


        }

        /* Check Columns */
        for (int c = 0; c < board[0].length; c++) {
            redPoints = 0;
            yellowPoints = 0;
            for (int r = 0; r < board.length; r++) {
                String g = board[r][c];
                if (!g.equals(EMPTY)) {
                    if (g.equals(RED)) {
                        redPoints++;
                        yellowPoints = 0;
                    } else if (g.equals(YELLOW)) {
                        yellowPoints++;
                        redPoints = 0;
                    }
                    if (redPoints >= 4) {
                        return WIN;
                    }
                    if (yellowPoints >= 4) {
                        return WIN;
                    }

                } else {
                    redPoints = 0;
                    yellowPoints = 0;
                }
            }
        }


        /* Check Diagonals */
        for (int r = 0; r < board.length; r++) {
            for (int c = 0; c < board[r].length; c++) {
                String g = board[r][c];
                if (!g.equals(EMPTY)) {
                    if (g.equals(RED)) {
                        redPoints = 1;
                        /* Check down and right diagonal */
                        for (int d = 1; (r + d) < board.length && (c + d) < board[r].length; d++) {
                            if (board[r + d][c + d].equals(RED)) {
                                redPoints++;
                            } else {
                                break;
                            }
                            if (redPoints == 4) {
                                return WIN;
                            }
                        }
                        redPoints = 1;
                        /* Check up and right diagonal */
                        for (int d = 1; (r - d) >= 0 && (c + d) < board[r].length; d++) {
                            if (board[r - d][c + d].equals(RED)) {
                                redPoints++;
                            } else {
                                break;
                            }
                            if (redPoints == 4) {
                                return WIN;
                            }
                        }
                        redPoints = 1;
                        /* Check down and left diagonal */
                        for (int d = 1; (r + d) < board.length && (c - d) >= 0; d++) {
                            if (board[r + d][c - d].equals(RED)) {
                                redPoints++;
                            } else {
                                break;
                            }
                            if (redPoints == 4) {
                                return WIN;
                            }
                        }
                        redPoints = 1;
                        /* Check up and left diagonal */
                        for (int d = 1; (r - d) >= 0 && (c - d) >= 0; d++) {
                            if (board[r - d][c - d].equals(RED)) {
                                redPoints++;
                            } else {
                                break;
                            }
                            if (redPoints == 4) {
                                return WIN;
                            }
                        }
                    } else if (g.equals(YELLOW)) {
                        yellowPoints = 1;
                        /* Check down and right diagonal */
                        for (int d = 1; (r + d) < board.length && (c + d) < board[r].length; d++) {
                            if (board[r + d][c + d].equals(YELLOW)) {
                                yellowPoints++;
                            } else {
                                break;
                            }
                            if (yellowPoints == 4) {
                                return WIN;
                            }
                        }
                        yellowPoints = 1;
                        /* Check up and right diagonal */
                        for (int d = 1; (r - d) >= 0 && (c + d) < board[r].length; d++) {
                            if (board[r - d][c + d].equals(YELLOW)) {
                                yellowPoints++;
                            } else {
                                break;
                            }
                            if (yellowPoints == 4) {
                                return WIN;
                            }
                        }
                        yellowPoints = 1;
                        /* Check down and left diagonal */
                        for (int d = 1; (r + d) < board.length && (c - d) >= 0; d++) {
                            if (board[r + d][c - d].equals(YELLOW)) {
                                yellowPoints++;
                            } else {
                                break;
                            }
                            if (yellowPoints == 4) {
                                return WIN;
                            }
                        }
                        yellowPoints = 1;
                        /* Check up and left diagonal */
                        for (int d = 1; (r - d) >= 0 && (c - d) >= 0; d++) {
                            if (board[r - d][c - d].equals(YELLOW)) {
                                yellowPoints++;
                            } else {
                                break;
                            }
                            if (yellowPoints == 4) {
                                return WIN;
                            }
                        }

                    }
                }
            }
        }
        return CONTINUE;

    }

    static int printBoard(String[][] board, String player, Scanner in) {
        printBoard(board);
        System.out.print("Drop a " + (player.equals(RED) ? "red" : "yellow") + " disk at column (0" + DASH + "6): ");
        int move = in.nextInt();
        return move;
    }

    static void printBoard(String[][] board) {
        for (String[] strings : board) {
            for (String s : strings) {
                System.out.print(SEP + s);
            }
            System.out.println(SEP);
        }
        System.out.println(DASH + DASH + DASH + DASH + DASH + DASH + DASH + DASH + DASH + DASH + DASH + DASH + DASH + DASH + DASH);


    }
}

// Copyright 2012 Square, Inc.
package com.squareup.widgets;

import android.content.Context;
import android.content.res.TypedArray;
import android.util.AttributeSet;
import android.widget.ImageView;

/** Maintains an aspect ratio based on either width or height. Disabled by default. */
public class AspectRatioImageView extends ImageView {
  // NOTE: These must be kept in sync with the AspectRatioImageView attributes in attrs.xml.
  public static final int MEASUREMENT_WIDTH = 0;
  public static final int MEASUREMENT_HEIGHT = 1;

  private static final float DEFAULT_ASPECT_RATIO = 1f;
  private static final boolean DEFAULT_ASPECT_RATIO_ENABLED = false;
  private static final int DEFAULT_DOMINANT_MEASUREMENT = MEASUREMENT_WIDTH;

  private float aspectRatio;
  private boolean aspectRatioEnabled;
  private int dominantMeasurement;

  public AspectRatioImageView(Context context) {
    this(context, null);
  }

  public AspectRatioImageView(Context context, AttributeSet attrs) {
    super(context, attrs);

    TypedArray a = context.obtainStyledAttributes(attrs, R.styleable.AspectRatioImageView);
    aspectRatio = a.getFloat(R.styleable.AspectRatioImageView_aspectRatio, DEFAULT_ASPECT_RATIO);
    aspectRatioEnabled = a.getBoolean(R.styleable.AspectRatioImageView_aspectRatioEnabled,
        DEFAULT_ASPECT_RATIO_ENABLED);
    dominantMeasurement = a.getInt(R.styleable.AspectRatioImageView_dominantMeasurement,
        DEFAULT_DOMINANT_MEASUREMENT);
    a.recycle();
  }

  @Override protected void onMeasure(int widthMeasureSpec, int heightMeasureSpec) {
    super.onMeasure(widthMeasureSpec, heightMeasureSpec);
    if (!aspectRatioEnabled) return;

    int newWidth;
    int newHeight;
    switch (dominantMeasurement) {
      case MEASUREMENT_WIDTH:
        newWidth = getMeasuredWidth();
        newHeight = (int) (newWidth * aspectRatio);
        break;

      case MEASUREMENT_HEIGHT:
        newHeight = getMeasuredHeight();
        newWidth = (int) (newHeight * aspectRatio);
        break;

      default:
        throw new IllegalStateException("Unknown measurement with ID " + dominantMeasurement);
    }

    setMeasuredDimension(newWidth, newHeight);
  }

  /** Get the aspect ratio for this image view. */
  public float getAspectRatio() {
    return aspectRatio;
  }

  /** Set the aspect ratio for this image view. This will update the view instantly. */
  public void setAspectRatio(float aspectRatio) {
    this.aspectRatio = aspectRatio;
    if (aspectRatioEnabled) {
      requestLayout();
    }
  }

  /** Get whether or not forcing the aspect ratio is enabled. */
  public boolean getAspectRatioEnabled() {
    return aspectRatioEnabled;
  }

  /** set whether or not forcing the aspect ratio is enabled. This will re-layout the view. */
  public void setAspectRatioEnabled(boolean aspectRatioEnabled) {
    this.aspectRatioEnabled = aspectRatioEnabled;
    requestLayout();
  }

  /** Get the dominant measurement for the aspect ratio. */
  public int getDominantMeasurement() {
    return dominantMeasurement;
  }

  /**
   * Set the dominant measurement for the aspect ratio.
   *
   * @see #MEASUREMENT_WIDTH
   * @see #MEASUREMENT_HEIGHT
   */
  public void setDominantMeasurement(int dominantMeasurement) {
    if (dominantMeasurement != MEASUREMENT_HEIGHT && dominantMeasurement != MEASUREMENT_WIDTH) {
      throw new IllegalArgumentException("Invalid measurement type.");
    }
    this.dominantMeasurement = dominantMeasurement;
    requestLayout();
  }
}

package ch_14;

import javafx.application.Application;
import javafx.scene.Scene;
import javafx.scene.layout.Pane;
import javafx.scene.paint.Color;
