package ch_05;

import java.util.*;


public class Exercise05_47 {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);

        System.out.print("Enter the first 12 digits of an ISBN-13 as a string: ");
        String isbn = in.nextLine();

        // Verify string length
        if (isbn.length() != 12) {
            System.out.println("Invalid input " + isbn + " input MUST be exactly 12 numbers");
            System.exit(0);
        }

        int check = 0;
        for (int i = 0; i < isbn.length(); i++) {
            int value = Integer.parseInt(String.valueOf(isbn.charAt(i)));
            check += i % 2 == 0 ? 3 * value
                    : value;
        }
        check = 10 - check % 10;

        System.out.println("ISBN-13 number is " + isbn +
                (check == 10 ? 0 : check));

        in.close();
    }
}

package ch_15;

import javafx.application.Application;
import javafx.geometry.Pos;
import javafx.scene.Scene;
import javafx.scene.control.Button;
import javafx.scene.layout.HBox;
import javafx.scene.layout.Priority;
import javafx.scene.layout.VBox;
import javafx.scene.paint.Color;
import javafx.scene.shape.Rectangle;
import javafx.stage.Stage;

import java.util.logging.Logger;


public class Exercise15_02 extends Application {
    Logger LOGGER = Logger.getLogger(getClass().getName());
    private static double rotation = 0;

    public static void main(String[] args) {
        Application.launch(args);
    }

    @Override
    public void start(Stage primaryStage) throws Exception {
        VBox vbox = new VBox();
        HBox mainBox = new HBox();
        HBox buttonBar = new HBox();
        vbox.setFillWidth(true);
        VBox.setVgrow(mainBox, Priority.ALWAYS);

        mainBox.setAlignment(Pos.CENTER);
        mainBox.setFillHeight(true);

        Rectangle rectangle = new Rectangle(200, 100);
        rectangle.setFill(Color.WHITE);
        rectangle.setStroke(Color.BLACK);

        Button rotateButton = new Button("Rotate");
        rotateButton.setOnAction(e -> rotate(rectangle));

        buttonBar.getChildren().add(rotateButton);
        buttonBar.setAlignment(Pos.BOTTOM_CENTER);
        mainBox.setCenterShape(true);
        mainBox.getChildren().add(rectangle);
        vbox.getChildren().add(mainBox);

        vbox.getChildren().add(buttonBar);
        Scene scene = new Scene(vbox, 400, 300);
        primaryStage.setScene(scene);
        primaryStage.setTitle(getClass().getName());
        primaryStage.show();
    }

    private void rotate(Rectangle rectangle) {
        if (rotation == 360) {
            rotation = 0;
        }
        rotation += 15;
        rectangle.setRotate(rotation);
        LOGGER.info("Rotation value is: " + rotation);

    }
}

