        System.out.print("\n(0-single filer, 1-married jointly or "
                + "qualifying widow(er), 2-married separately, 3-head of " + "household) Enter the filing status: ");
        int status = input.nextInt();
        if (status > 3) {
            System.out.println("Error, Invalid Filling Status");
            return;
        }

        // Prompt the user to enter taxable income
        System.out.print("\nEnter the taxable income: ");
        double income = input.nextDouble();


        System.out.printf("Tax is $%.2f", calcTax(income, brackets[status], rates));
        input.close();

    }


    static double calcTax(double income, int[] bracket, double[] rates) {
        double tax = 0;
        if (income <= bracket[0]) {
            tax = income * rates[0];
        } else if (income <= bracket[1]) {
            tax = bracket[0] * rates[0] + (income - bracket[0]) * rates[1];
        } else if (income <= bracket[2]) {
            tax = bracket[0] * rates[0] + (bracket[1] - bracket[0]) * rates[1] + (income - bracket[1]) * rates[2];
        } else if (income <= bracket[3]) {
            tax = bracket[0] * rates[0] + (bracket[1] - bracket[0]) * rates[1] + (bracket[2] - bracket[1]) * rates[2]
                    + (income - bracket[2]) * rates[3];
        } else if (income <= bracket[4]) {
            tax = bracket[0] * rates[0] + (bracket[1] - bracket[0]) * rates[1] + (bracket[2] - bracket[1]) * rates[2]
                    + (bracket[3] - bracket[2]) * rates[3] + (income - bracket[4]) * rates[4];
        } else
            tax = bracket[0] * rates[0] + (bracket[1] - bracket[0]) * rates[1] + (bracket[2] - bracket[1]) * rates[2]
                    + (bracket[3] - bracket[2]) * rates[3] + (bracket[4] - bracket[3]) * rates[4] + (income - bracket[4]) * rates[5];

        return tax;

    }
}

package ch_06;

import java.util.*;


public class Exercise06_31 {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        System.out.println("Enter a credit card number as a long integer: ");
        String ccNum = in.next();

        System.out.println(ccNum + (isValid(Long.parseLong(ccNum)) ? " is valid." : " is invalid."));
    }


    public static boolean isValid(long number) {
        String s = String.valueOf(number);
        if (s.length() < 13 || s.length() > 16) {
            return false;
        } else if (prefixMatched(number, 4) || prefixMatched(number, 6) || prefixMatched(number, 5) || prefixMatched(number, 37)) {
            int sumEven = sumOfDoubleEvenPlace(number);
            int sumOdd = sumOfOddPlace(number);
            int total = sumEven + sumOdd;
            return total % 10 == 0;
        }
        return false;
    }


    public static int sumOfDoubleEvenPlace(long number) {
        System.out.println("Sum of Double Even Place Numbers: ");
        int sum = 0;
        String n = String.valueOf(number);
        for (int i = n.length() - 2; i >= 0; i -= 2) {
            int digit = Integer.parseInt(n.substring(i, i + 1));
            System.out.println("extracted digit:" + digit);
            int temp = digit + digit;
            int d = getDigit(temp);
            System.out.println("Digit processed into: " + d);
            sum += d;
        }
        return sum;
    }


    public static int getDigit(int number) {
        if (getSize(number) > 1) {
            int d1 = number % 10;
            int d2 = number / 10;
            return d1 + d2;
        }
        return number;
    }


    public static int sumOfOddPlace(long number) {
        System.out.println("Sum of Odd Place Numbers: ");
        int sum = 0;
        String n = String.valueOf(number);
        for (int i = n.length() - 1; i >= 0; i -= 2) {
            int x = Integer.parseInt(n.substring(i, i + 1));
            System.out.println("Extracted digit " + x);
            sum += x;
        }
        return sum;
    }


    public static boolean prefixMatched(long number, int d) {
        String s = String.valueOf(number);
        if (s.startsWith(String.valueOf(d))) {
            return true;
        }
        return false;
    }


    public static int getSize(long d) {
        String s = String.valueOf(d);
        return s.length();
    }


    public static long getPrefix(long number, int k) {
        if (getSize(number) < k) {
            return number;
        }
        String s = String.valueOf(number);
        return Long.parseLong(s.substring(0, k));
    }
}

package ch_23;

import java.util.Arrays;
import java.util.Comparator;


public class Exercise23_02 {
    public static void main(String[] args) {
        Integer[] arr = new Integer[]{23, 25, 7, 14, 85, 65};
        mergeSort(arr);
        System.out.println(Arrays.toString(arr));

        Integer[] arr2 = new Integer[]{3, 2, 7, 4, 8, 6, 1, 7};
        mergeSort(arr2, Integer::compareTo);
        System.out.println(Arrays.toString(arr2));

    }

    public static <E> void mergeSort(E[] list,
                                     Comparator<? super E> comparator) {
        if (list.length > 1) {
            E[] firstHalf = Arrays.copyOf(list, list.length / 2);
            System.arraycopy(list, 0, firstHalf, 0, list.length / 2);
            mergeSort(firstHalf, comparator);

            int secondHalfLength = list.length - list.length / 2;
            E[] secondHalf = Arrays.copyOf(list, secondHalfLength);
            System.arraycopy(list, list.length / 2,
                    secondHalf, 0, secondHalfLength);
            mergeSort(secondHalf, comparator);

            int current1, current2, current3;
            current1 = current2 = current3 = 0;

            while (current1 < firstHalf.length && current2 < secondHalf.length) {
                if (comparator.compare(firstHalf[current1], secondHalf[current2]) < 0)
                    list[current3++] = firstHalf[current1++];
                else
                    list[current3++] = secondHalf[current2++];
            }

            while (current1 < firstHalf.length)
                list[current3++] = firstHalf[current1++];

            while (current2 < secondHalf.length)
                list[current3++] = secondHalf[current2++];
        }
    }


    public static <E extends Comparable<E>> void mergeSort(E[] list) {
        if (list.length > 1) {

            E[] firstHalf = Arrays.copyOf(list, list.length / 2);
            System.arraycopy(list, 0, firstHalf, 0, list.length / 2);
            mergeSort(firstHalf);

            int secondHalfLength = list.length - list.length / 2;
            E[] secondHalf = Arrays.copyOf(list, secondHalfLength);
            System.arraycopy(list, list.length / 2,
                    secondHalf, 0, secondHalfLength);
            mergeSort(secondHalf);

            int current1, current2, current3;
            current1 = current2 = current3 = 0;

            while (current1 < firstHalf.length && current2 < secondHalf.length) {
                if (firstHalf[current1].compareTo(secondHalf[current2]) < 0)
                    list[current3++] = firstHalf[current1++];
                else
                    list[current3++] = secondHalf[current2++];
            }

            while (current1 < firstHalf.length)
                list[current3++] = firstHalf[current1++];

            while (current2 < secondHalf.length)
                list[current3++] = secondHalf[current2++];
        }
    }

}

/**
 * @author Gabriele Mariotti (gabri.mariotti@gmail.com)
 */
public class SimpleAdapter extends RecyclerView.Adapter<SimpleAdapter.SimpleViewHolder> {
    private static final int COUNT = 100;

    private final Context mContext;
    private final List<Integer> mItems;
    private int mCurrentItemId = 0;

    public static class SimpleViewHolder extends RecyclerView.ViewHolder {
        public final TextView title;

        public SimpleViewHolder(View view) {
            super(view);
            title = (TextView) view.findViewById(R.id.title);
        }
    }

    public SimpleAdapter(Context context) {
        mContext = context;
        mItems = new ArrayList<Integer>(COUNT);
        for (int i = 0; i < COUNT; i++) {
            addItem(i);
        }
    }

    public SimpleViewHolder onCreateViewHolder(ViewGroup parent, int viewType) {
        final View view = LayoutInflater.from(mContext).inflate(R.layout.item, parent, false);
        return new SimpleViewHolder(view);
    }

    @Override
    public void onBindViewHolder(SimpleViewHolder holder, final int position) {
        holder.title.setText(mItems.get(position).toString());
    }

    public void addItem(int position) {
        final int id = mCurrentItemId++;
        mItems.add(position, id);
        notifyItemInserted(position);
    }

    public void removeItem(int position) {
        mItems.remove(position);
        notifyItemRemoved(position);
    }

    @Override
    public int getItemCount() {
        return mItems.size();
    }
}

package ch_11;

import java.util.ArrayList;
import java.util.Scanner;


public class Exercise11_15 {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);

        System.out.print("Enter the number of points: ");
        int numPoints = in.nextInt();

        ArrayList<double[]> pts = new ArrayList<>();

        System.out.print("Enter the coordinates of the points in the convex polygon: ");

        for (int i = 0; i < numPoints; i++) {
            double[] pt = new double[2];
            for (int xy = 0; xy < 2; xy++) {
                pt[xy] = in.nextDouble();
            }
            pts.add(pt);
        }

        System.out.print("The area of the convex polygon is ");
        System.out.println(getAreaConvexPolygon(pts) + "");

        in.close();

    }

    static double getAreaConvexPolygon(ArrayList<double[]> pts) {
        double[] lastPoint = pts.get(pts.size() - 1);
        double[] firstPoint = pts.get(0);
        double operand1 = lastPoint[0] * firstPoint[1]; // xn * y1
        for (int i = 0; i < pts.size() - 1; i++) {
            double[] pt = pts.get(i);
            double[] nextPt = pts.get(i + 1);
            operand1 += pt[0] * nextPt[1]; // x1 * y2 + x2 * y3 + x(n) * y(n+1) + {x(n) * y1}
        }
        double operand2 = lastPoint[1] * firstPoint[0]; // yn * x1
        for (int i = 0; i < pts.size() - 1; i++) {
            double[] pt = pts.get(i);
            double[] nextPt = pts.get(i + 1);
            operand2 += pt[1] * nextPt[0]; // y1 * x2 + y2 * x3 + y(n) + x(n+1) + {y(n) * x1}

        }
        return Math.abs((operand1 - operand2) * 0.5);

    }

}

package resources;

import java.io.File;
import java.io.FileOutputStream;
import java.io.IOException;
import java.nio.file.FileAlreadyExistsException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;


public class FileWriterUtil {

    public static void main(String[] args) {

        String packageName = args[0];
        String CHAPTER = args[1];
        int numExercises = Integer.valueOf(args[2]);

        for (int i = 1; i <= numExercises; i++) {
            String exerciseId = "";
            if (i < 10) {
                exerciseId = "0" + i;
            } else {
                exerciseId = "" + i;
            }

            File file = new File(new File(".").getAbsolutePath());
            String currentDirectoryPath = file.getAbsolutePath();
            Path pathCurrWd = Paths.get(currentDirectoryPath);

            System.out.println(pathCurrWd.toString());

            String filename = "";

            if (Integer.parseInt(CHAPTER) < 10) {
                filename = "E0" + CHAPTER + exerciseId;

            } else {
                filename = "E" + CHAPTER + exerciseId;
            }
            String javaFileName = filename + ".java";

            Path fullPath = pathCurrWd.resolve(javaFileName);

            System.out.println(fullPath.toString());

            try {
                Files.createFile(fullPath);

                String contents = "package " + packageName + ";" + " \n \nimport java.util.*; \n \npublic class " + filename
                        + "{\n     public static void main(String[] args) {\n    }\n}";

                try (FileOutputStream fOs = new FileOutputStream(fullPath.toFile())) {
                    byte[] bytes = contents.getBytes();
                    fOs.write(bytes);

                } catch (IOException ie) {
                    System.out.println("IOException while writing: " + filename);
                }

            } catch (FileAlreadyExistsException ex) {
                System.out.println("Skipping write file because " + javaFileName + " already exists...");
            } catch (IOException e) {
                System.out.print("IO Exception occured while creating: " + fullPath.toString());
                e.printStackTrace();
            }
        }
        System.out.println("FileWriter complete");

    }

}

package ch_23;

import java.util.Arrays;
import java.util.Comparator;


public class Exercise23_03 {

    public static void main(String[] args) {
        Integer[] arr = new Integer[]{23, 25, 7, 14, 85, 65};
        quickSort(arr);
        System.out.println(Arrays.toString(arr));

        Integer[] arr2 = new Integer[]{3, 2, 7, 4, 8, 6, 1, 7};
        quickSort(arr2, Integer::compareTo);
        System.out.println(Arrays.toString(arr2));

    }

    // Using Comparable
    public static <E extends Comparable<E>> void quickSort(E[] list) {
        quickSort(list, 0, list.length - 1);
    }

    public static <E extends Comparable<E>> void quickSort(E[] list, int first, int last) {
        if (last > first) {
            int pivotIndex = partition(list, first, last);
            quickSort(list, first, pivotIndex - 1);
            quickSort(list, pivotIndex + 1, last);
        }
    }

    public static <E extends Comparable<E>> int partition(E[] list, int first, int last) {
        E pivot = list[first]; // Choose the first element as the pivot
        int low = first + 1; // Index for forward search
        int high = last; // Index for backward search

        while (high > low) {
            // Search forward from left
            while (low <= high && list[low].compareTo(pivot) <= 0) low++;

            // Search backward from right
            while (low <= high && list[high].compareTo(pivot) > 0) high--;

            // Swap two elements in the list
            if (high > low) {
                E temp = list[high];
                list[high] = list[low];
                list[low] = temp;
            }
        }

        while (high > first && list[high].compareTo(pivot) >= 0)
            high--;

        // Swap pivot with list[high]
        if (pivot.compareTo(list[high]) > 0) {
            list[first] = list[high];
            list[high] = pivot;
            return high;
        } else {
            return first;
        }
    }

    // Using Comparator
    public static <E> void quickSort(E[] list,
                                     Comparator<? super E> comparator) {
        quickSort(list, 0, list.length - 1, comparator);


    }

    // Using Comparator
    public static <E> void quickSort(E[] list, int first, int last,
                                     Comparator<? super E> comparator) {
        if (last > first) {
            int pivotIndex;
            // find pivot index
            E pivot = list[first]; // Choose the first element as the pivot
            int low = first + 1; // Index for forward search
            int high = last; // Index for backward search

            while (high > low) {
                // Search forward from left
                while (low <= high && comparator.compare(list[low], pivot) <= 0) low++;

                // Search backward from right
                while (low <= high && comparator.compare(list[high], pivot) > 0) high--;

                // Swap two elements in the list
                if (high > low) {
                    E temp = list[high];
                    list[high] = list[low];
                    list[low] = temp;
                }
            }

            while (high > first && comparator.compare(list[high], pivot) >= 0)
                high--;

            // Swap pivot with list[high]
            if (comparator.compare(pivot, list[high]) > 0) {
                list[first] = list[high];
                list[high] = pivot;
                pivotIndex = high;
            } else {
                pivotIndex = first;
            }

            quickSort(list, first, pivotIndex - 1, comparator);
            quickSort(list, pivotIndex + 1, last, comparator);
        }
    }

}

package ch_07;

import java.util.*;


public class Exercise07_35 {
    static int missed = 0;
    final static String[] words = {"words", "bread", "signal", "time", "display", "friend", "computer",
            "forget",
            "java"};
    static boolean wordLoop = true;
    static boolean gameLoop = true;
    final static String prompt = "(Guess) Enter a letter in word ";
    static String currentWord;
    static int[] guessed;
    static String display;

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);

        while (gameLoop) {
            currentWord = getRandomWord();
            handleNewWord();
            do {
                System.out.print(prompt + display + " >");
                String guess = in.next();
                handleGuess(guess.charAt(0));
                wordLoop = validateWord();
                if (!wordLoop) {
                    System.out.println("The word is " + currentWord + " you missed " + missed + " times.");
                }
            } while (wordLoop);
            System.out.println("Do you want to guess another word? y or n >");
            gameLoop = in.next().charAt(0) == 'y';
        }
        System.out.println("Thanks for playing hangman!");
        in.close();
    }

    private static boolean validateWord() {
        boolean gameNotOver = false;
        for (int pos : guessed) {
            if (pos == 0) {
                gameNotOver = true;
                break;
            }
        }
        return gameNotOver;
    }

    static String getRandomWord() {
        return words[(int) (Math.random() * words.length)];
    }

    static void handleAsterisk() {
        char[] letters = currentWord.toCharArray();
        for (int i = 0; i < letters.length; i++) {
            if (guessed[i] == 0) {
                letters[i] = '*';
            }
        }
        display = String.valueOf(letters);
    }

    static void handleNewWord() {
        guessed = new int[currentWord.length()];
        char[] d = new char[currentWord.length()];
        Arrays.fill(d, '*');
        display = String.valueOf(d);
    }

    static void handleGuess(char guess) {
        char[] letters = currentWord.toCharArray();
        for (int i = 0; i < letters.length; i++) {
            if (letters[i] == guess) {
                if (guessed[i] != 0) {
                    System.out.println(guess + " is already in the word.");
                } else {
                    guessed[i] = 1;
                    handleAsterisk();
                    return;
                }
                break;
            }
        }
        missed++;
        System.out.println(guess + " is not in the word.");
    }
}

