package ch_11;

import java.util.ArrayList;
import java.util.Scanner;


public class Exercise11_17 {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        System.out.print("Enter an integer: ");
        int m = in.nextInt();

        int n = findN(findSmallestFactors(m));
        System.out.println("The smallest number n for m * n to be a perfect square is " + n);
        System.out.println("m * n is " + m * n);

    }

    static ArrayList<Integer> findSmallestFactors(int m) {

        ArrayList<Integer> smallFactors = new ArrayList<>();

        for (int f = 2; m != 1; f++) {
            if (m % f == 0) {
                smallFactors.add(f);
                m /= f;
                f = 1; // Reset the test factor
            }
        }
        return smallFactors;
    }

    static Integer findN(ArrayList<Integer> factors) {
        ArrayList<Integer> oddCounts = new ArrayList<>();
        for (int i = 0; i < factors.size(); i++) {
            int num = factors.get(i);
            int count = 0;
            for (Integer integer : factors) {
                if (integer == num) {
                    count++;
                }
            }
            if (count % 2 != 0 && !oddCounts.contains(num)) {
                oddCounts.add(num);
            }

        }

        Integer result = 1;
        for (Integer oddCount : oddCounts) {
            result *= oddCount;
        }
        return result;
    }

}

package ch_07;

import java.util.Scanner;


public class Exercise07_30 {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);

        System.out.print("Enter the number of values: ");
        int len = in.nextInt();
        int[] nums = new int[len];

        System.out.print("Enter the values: ");
        for (int i = 0; i < len; i++) {
            nums[i] = in.nextInt();
        }
        if (isConsecutiveFour(nums)) {
            System.out.println("The list has consecutive fours.");
        } else {
            System.out.println("The list does not have consecutive fours.");
        }
    }


    public static boolean isConsecutiveFour(int[] values) {
        int lastNum = values[0];
        int count = 1;
        for (int j = 1; j < values.length; j++) {
            if (lastNum == values[j]) {
                count++;
            } else {
                lastNum = values[j];
                count = 1;
            }
            if (count == 4) {
                return true;
            }
        }
        return false;

    }

}

