package ch_03;

import java.util.*;


public class Exercise03_28 {
    public static void main(String[] args) {
        //This program only tests if rectangle two is inside rectangle one or if
        //rectangle two overlaps rectangle one per the instructions


        Scanner input = new Scanner(System.in);

        System.out.println("Please enter rectangle one's center point x "
                + "and y coordinates followed by its width and height:");

        double recOneX = input.nextDouble();

        double recOneY = input.nextDouble();

        double recOnewidth = input.nextDouble();

        double recOneheight = input.nextDouble();

        System.out.println("Please enter rectangle two's center point x "
                + "and y coordinates followed by its width and height:");

        double recTwoX = input.nextDouble();

        double recTwoY = input.nextDouble();

        double recTwowidth = input.nextDouble();

        double recTwoheight = input.nextDouble();

        double recOnetopX = recOneX + recOnewidth / 2;

        double recOnetopY = recOneY + recOneheight / 2;

        double recOnebottomX = recOneX - recOnewidth / 2;

        double recOnebottomY = recOneY - recOneheight / 2;

        double recTwotopX = recTwoX + recTwowidth / 2;

        double recTwotopY = recTwoY + recTwoheight / 2;

        double recTwobottomX = recTwoX - recTwowidth / 2;

        double recTwobottomY = recTwoY - recTwoheight / 2;

        boolean isInside = checkIfinside(recOnetopX, recTwotopX, recOnebottomX, recTwobottomX, recOnetopY, recTwotopY, recOnebottomY, recTwobottomY);

        boolean overlap = checkIfoverlaps(recOnetopX, recTwotopX, recOnebottomX, recTwobottomX, recOnetopY, recTwotopY, recOnebottomY, recTwobottomY);

        if (isInside) {
            System.out.println("Rectangle two is inside of rectangle one");

        } else if (overlap) {
            System.out.println("Rectangle two overlaps rectangle one");

        } else {
            System.out.println("Rectangle two does not overlap rectangle one and is not inside of rectangle one");
        }


    }

    public static boolean checkIfinside(double x1top, double x2top, double x1bottom, double x2bottom,
                                        double y1top, double y2top, double y1bottom, double y2bottom) {


        if (x2top <= x1top & x2bottom >= x1bottom & y2top <= y1top
                & y2bottom >= y1bottom) {

            return true;

        } else

            return false;
    }

    public static boolean checkIfoverlaps(double x1top, double x2top, double x1bottom, double x2bottom,
                                          double y1top, double y2top, double y1bottom, double y2bottom) {
        return !(x1top < x2bottom | x1bottom > x2top | y1top < y2bottom
                | y1bottom > y2top);
    }

}

package ch_23;

import java.util.Arrays;


public class Exercise23_04 {
    public static void quickSort(int[] list) {
        /* Exercise 23.4 */
        int medianIdx = indexOfMedian(list);
        quickSort(list, medianIdx, list.length - 1);
    }

    public static void quickSort(int[] list, int first, int last) {
        if (last > first) {
            int pivotIndex = partition(list, first, last);
            quickSort(list, first, pivotIndex - 1);
            quickSort(list, pivotIndex + 1, last);
        }
    }


    public static int partition(int[] list, int first, int last) {
        int pivot = list[first]; // Choose the first element as the pivot
        int low = first + 1; // Index for forward search
        int high = last; // Index for backward search

        while (high > low) {
            // Search forward from left
            while (low <= high && list[low] <= pivot)
                low++;

            // Search backward from right
            while (low <= high && list[high] > pivot)
                high--;

            // Swap two elements in the list
            if (high > low) {
                int temp = list[high];
                list[high] = list[low];
                list[low] = temp;
            }
        }

        while (high > first && list[high] >= pivot)
            high--;

        // Swap pivot with list[high]
        if (pivot > list[high]) {
            list[first] = list[high];
            list[high] = pivot;
            return high;
        } else {
            return first;
        }
    }


    static int indexOfMedian(int[] list) {
        int[] temp = {list[0], list[list.length / 2], list[list.length - 1]};
        Arrays.sort(temp);
        if (list[0] == temp[1]) {
            return 0;
        }
        else if (list[list.length / 2] == temp[1]) {
            return list.length / 2;
        }

        return list.length - 1;
    }


    public static void main(String[] args) {
        int[] list = {2, 3, 2, 5, 6, 1, -2, 3, 14, 12};
        quickSort(list);
        for (int i = 0; i < list.length; i++)
            System.out.print(list[i] + " ");
    }
}

package com.mkyong.io.api.inputstream;

import java.io.*;
import java.nio.charset.StandardCharsets;

public class FileInputStreamExample {

    public static void main(String[] args) {
        String file = "c:\\test\\file.txt";
        String fileUnicode = "c:\\test\\file-unicode.txt";

        readFile(file);
        //readFileBetterPerformance(fileUnicode);
        //readFileBetterInputStreamReader(fileUnicode);

    }

    private static void readFile(String fileName) {

        try (FileInputStream fis = new FileInputStream(new File(fileName))) {

            // remaining bytes that can be read
            System.out.println("Remaining bytes that can be read : " + fis.available());

            int content;
            // reads a byte at a time, if end of the file, returns -1
            while ((content = fis.read()) != -1) {
                System.out.println((char) content);

                System.out.println("Remaining bytes that can be read : " + fis.available());
            }
        } catch (IOException e) {
            e.printStackTrace();
        }

    }

    private static void readFileBetterPerformance(String fileName) {

        try (FileInputStream fis = new FileInputStream(new File(fileName))) {

            // remaining bytes that can be read
            System.out.println("Remaining bytes that can be read : " + fis.available());

            // 8k a time
            byte[] bytes = new byte[8192];

            // reads 8192 bytes at a time, if end of the file, returns -1
            while (fis.read(bytes) != -1) {

                // convert bytes to string for demo
                // also convert unicode to string
                System.out.println(new String(bytes, StandardCharsets.UTF_8));

                System.out.println("Remaining bytes that can be read : " + fis.available());
            }
        } catch (IOException e) {
            e.printStackTrace();
        }

    }

    private static void readFileBetterPerformance2(String fileName) {

        try (BufferedInputStream bis =
                     new BufferedInputStream(
                             new FileInputStream(new File(fileName)))) {

            // remaining bytes that can be read
            System.out.println("Remaining bytes that can be read : " + bis.available());

            int content;
            // reads 8192 bytes at a time and buffers them until they are needed,
            // if end of the file, returns -1
            while ((content = bis.read()) != -1) {

                // convert bytes to string for demo
                System.out.println((char) content);

                System.out.println("Remaining bytes that can be read : " + bis.available());
            }
        } catch (IOException e) {
            e.printStackTrace();
        }

    }

    private static void readFileBetterInputStreamReader(String fileName) {

        try (BufferedReader br =
                     new BufferedReader(
                             new InputStreamReader(
                                     new FileInputStream(new File(fileName))))) {

            String line;
            while ((line = br.readLine()) != null) {
                System.out.println(line);
            }

        } catch (IOException e) {
            e.printStackTrace();
        }

    }


}

package ch_05;

import java.util.*;


public class Exercise05_29 {
    public static void main(String[] args) {

        Scanner input = new Scanner(System.in);

        System.out.print("Enter a year: ");
        int year = input.nextInt();

        System.out.print("Enter the first day of the year: ");
        int startDay = input.nextInt();

        int days = 0;
        for (int month = 1; month <= 12; month++) {
            switch (month) {
                case 1:
                    System.out.println("\t\t\tJanuary " + year);
                    days = 31;
                    break;
                case 2:
                    System.out.println("\t\t\tFebruary " + year);
                    if ((year % 400 == 0) || ((year % 4 == 0) && (year % 100 != 0))) {
                        days = 29;
                    } else {
                        days = 28;
                    }
                    break;
                case 3:
                    System.out.println("\t\t\tMarch " + year);
                    days = 31;
                    break;
                case 4:
                    System.out.println("\t\t\tApril " + year);
                    days = 30;
                    break;
                case 5:
                    System.out.println("\t\t\tMay " + year);
                    days = 31;
                    break;
                case 6:
                    System.out.println("\t\t\tJune " + year);
                    days = 30;
                    break;
                case 7:
                    System.out.println("\t\t\tJuly " + year);
                    days = 31;
                    break;
                case 8:
                    System.out.println("\t\t\tAugust " + year);
                    days = 31;
                    break;
                case 9:
                    System.out.println("\t\t\tSeptember " + year);
                    days = 30;
                    break;
                case 10:
                    System.out.println("\t\t\tOctober " + year);
                    days = 31;
                    break;
                case 11:
                    System.out.println("\t\t\tNovember " + year);
                    days = 30;
                    break;
                case 12:
                    System.out.println("\t\t\tDecember " + year);
                    days = 31;
            }
            for (int t = 0; t < 30; t++) {
                System.out.print("-");
            }
            System.out.println(" \nSun Mon Tue Wed Thu Fri Sat");


            for (int i = 0; i < startDay; i++) {
                System.out.print("    ");
            }
            for (int i = 1; i <= days; i++) {
                if (i < 10) {
                    System.out.print("   " + i);
                } else {
                    System.out.print("  " + i);
                }
                if ((i + startDay) % 7 == 0) {
                    System.out.println();
                }
            }
            System.out.println("");


            startDay = (startDay + days) % 7;
        }
    }
}

package ch_17.exercise17_09;

import javafx.application.Application;
import javafx.geometry.Insets;
import javafx.geometry.Pos;
import javafx.scene.Scene;
import javafx.scene.control.*;
import javafx.scene.layout.HBox;
import javafx.scene.layout.VBox;
import javafx.stage.Stage;

import java.io.*;
import java.util.ArrayList;
import java.util.List;


public class Exercise17_09 extends Application {
    static String[] packageParts = Exercise17_09.class.getPackage().getName().split("\\.");
    final static String path = packageParts[0] + File.separator + packageParts[1] + File.separator + "address_store" +
            ".dat";
    static File storage;

    static int pointer;
    static List<String> addresses = new ArrayList<>();

    static final int NAME_SIZE = 32;
    static final int STREET_SIZE = 32;
    static final int CITY_SIZE = 20;
    static final int STATE_SIZE = 2;
    static final int ZIP_SIZE = 5;
    static final int TOTAL = 91;

    static TextField nameField;
    static TextField streetField;
    static TextField cityField;
    static TextField stateField;
    static TextField zipField;

    @Override
    public void start(Stage primaryStage) {
        storage = new File(path);
        String s = retrieve(storage);
        initAddressList(s);

        VBox rootBox = initUserInterface();
        Scene scene = new Scene(rootBox, 500, 170);

        primaryStage.setTitle("Exercise-17.09");
        primaryStage.setScene(scene);
        primaryStage.setOnCloseRequest(event -> {
            System.out.println("Window close requested, saving Addresses now...");
            try {
                store(storage);
            } catch (IOException ioException) {
                ioException.printStackTrace();
                displayError("Something went wrong storing the address file. Please check the log messages in the " +
                        "console output.");
            }
        });
        primaryStage.setOnShowing(event -> {
            if (addresses.size() > 0) {
                setCurrentAddress(addresses.get(0));
            }
        });
        primaryStage.show();
    }


    private void initAddressList(String s) {
        int len = s.length();
        while (len > 0) {
            len = len - TOTAL;
            addresses.add(s.substring(len));
            s = s.substring(0, len);
        }
    }


    private VBox initUserInterface() {
        VBox showBox = new VBox(5.0);

        Label name = new Label("Name");
        Exercise17_09.nameField = new TextField();

        Exercise17_09.nameField.setMinWidth(400);
        HBox topBox = new HBox(name, Exercise17_09.nameField);
        topBox.setSpacing(10);
        topBox.setPadding(new Insets(5, 5, 5, 5));

        showBox.getChildren().add(topBox);

        Label street = new Label("Street");
        Exercise17_09.streetField = new TextField();

        Exercise17_09.streetField.setMinWidth(400);
        HBox midBox = new HBox(street, Exercise17_09.streetField);
        midBox.setSpacing(10);
        midBox.setPadding(new Insets(5, 5, 5, 5));

        showBox.getChildren().add(midBox);

        Label city = new Label("City");
        Exercise17_09.cityField = new TextField();

        HBox h1 = new HBox(city, Exercise17_09.cityField);
        h1.setPadding(new Insets(2, 2, 2, 2));
        h1.setSpacing(10);

        Label state = new Label("State");
        Exercise17_09.stateField = new TextField();

        Exercise17_09.stateField.setMaxWidth(45);

        HBox h2 = new HBox(state, Exercise17_09.stateField);
        h2.setPadding(new Insets(2, 2, 2, 2));
        h2.setSpacing(10);

        Label zip = new Label("Zip");
        Exercise17_09.zipField = new TextField();

        Exercise17_09.zipField.setMaxWidth(65);
        HBox h3 = new HBox(zip, Exercise17_09.zipField);
        h3.setPadding(new Insets(2, 2, 2, 2));
        h3.setSpacing(10);

        HBox bottomBox = new HBox(h1, h2, h3);
        bottomBox.setAlignment(Pos.CENTER);

        showBox.getChildren().add(bottomBox);

        Button addButton = new Button("Add");
        addButton.setOnAction(event -> add());

        Button firstButton = new Button("First");
        firstButton.setOnAction(event -> first());

        Button nextButton = new Button("Next");
        nextButton.setOnAction(event -> next());

        Button previousButton = new Button("Previous");
        previousButton.setOnAction(event -> previous());

        Button lastButton = new Button("Last");
        lastButton.setOnAction(event -> last());

        Button updateButton = new Button("Update");
        updateButton.setOnAction(event -> update(pointer));
        HBox buttonBox = new HBox(addButton, firstButton, nextButton, previousButton, lastButton, updateButton);
        buttonBox.setSpacing(10.0);
        buttonBox.setAlignment(Pos.CENTER);

        showBox.getChildren().add(buttonBox);

        return showBox;
    }

    static void displayError(String error) {
        Alert alert = new Alert(Alert.AlertType.ERROR);
        alert.setContentText(error);
        alert.show();
    }


    private void add() {
        System.out.println(getAddressString());
        addresses.add(getAddressString());
    }

    private void first() {
        if (addresses.size() > 0) {
            pointer = 0;
            setCurrentAddress(addresses.get(pointer));
        } else {
            displayError("Create an address to add to the list.");
        }

    }

    private void next() {
        if (pointer < addresses.size() - 1) {
            ++pointer;
            setCurrentAddress(addresses.get(pointer));
        } else {
            displayError("End of address list reached.");
        }

    }

    private void previous() {
        if (pointer > 0) {
            --pointer;
            setCurrentAddress(addresses.get(pointer));
        } else {
            displayError("Beginning of address list reached.");

        }
    }


    private void last() {
        setCurrentAddress(addresses.get(addresses.size() - 1));
    }


    private void setCurrentAddress(String fixLenStr) {
        Exercise17_09.nameField.setText(fixLenStr.substring(0, 32));
        Exercise17_09.streetField.setText(fixLenStr.substring(32, 64));
        Exercise17_09.cityField.setText(fixLenStr.substring(64, 84));
        Exercise17_09.stateField.setText(fixLenStr.substring(84, 86));
        Exercise17_09.zipField.setText(fixLenStr.substring(86));

    }

    private void update(int pointer) {
        addresses.set(pointer, getAddressString());
        displayInfo("Updated the address!");

    }

    private void displayInfo(String updated) {
        Alert alert = new Alert(Alert.AlertType.INFORMATION);
        alert.setContentText(updated);
        alert.show();
    }


    protected void store(File f) throws IOException {
        boolean b = false;
        if (!f.exists()) {
            try {
                b = f.createNewFile();
            } catch (Exception e) {
                try {
                    f.setWritable(true);
                    b = f.createNewFile();
                } catch (Exception ex) {
                    ex.printStackTrace();
                }
            }
        }

        try {
            RandomAccessFile raf = new RandomAccessFile(f, "rw");
            for (String address : addresses) {
                raf.writeUTF(address);
            }

            raf.close();

        } catch (IOException e) {
            e.printStackTrace();
        }
    }


    protected String retrieve(File file) {
        String read = "";
        if (!file.exists()) {
            try {
                file.createNewFile();
            } catch (IOException e) {
                displayError("File does note exist and encountered an error while creating it.");
            }
        } else {
            try {
                RandomAccessFile raf = new RandomAccessFile(file, "r");
                while (true) {
                    read = read.concat(raf.readUTF());
                }

            } catch (EOFException eof) {
                System.out.println("End of File reached!");
                return read;
            } catch (IOException ioException) {
                displayError(ioException.getMessage());
            }
        }
        return read;
    }


    protected String getAddressString() {
        String address = "";
        String name = nameField.getText();

        for (int i = name.length(); i < NAME_SIZE; i++) {
            name += " ";
        }
        address += name;

        String street = streetField.getText();
        for (int i = street.length(); i < STREET_SIZE; i++) {
            street += " ";
        }
        address += street;

        String city = cityField.getText();
        for (int i = city.length(); i < CITY_SIZE; i++) {
            city += " ";
        }
        address += city;

        String state = stateField.getText();
        for (int i = state.length(); i < STATE_SIZE; i++) {
            state += " ";
        }
        address += state;

        String zip = zipField.getText();

        for (int i = zip.length(); i < ZIP_SIZE; i++) {
            zip += " ";
        }
        address += zip;

        return address;

    }

}

