package ch_03;

import java.awt.*;
import java.util.*;


public class Exercise03_30 {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);

        System.out.println("Enter the time zone offset to GMT: ");
        int offset = in.nextInt();
        boolean pm = false;

        long timeInMillis = System.currentTimeMillis();
        long secondsSinceJan1st1970 = timeInMillis / 1000;
        long second = secondsSinceJan1st1970 % 60;
        long minutesSinceJan1st1970 = secondsSinceJan1st1970 / 60;
        long minute = minutesSinceJan1st1970 % 60;
        long hoursSinceJan1st1970 = minutesSinceJan1st1970 / 60;

        System.out.println(hoursSinceJan1st1970);

        long hour = hoursSinceJan1st1970 % 24;
        hour += offset;

        if (hour > 12) {
            pm = true;
            hour -= 12;
        }

        System.out.println("Your current time is " + hour + ":" + minute + ":" + second + (pm ? " PM" : " AM"));

    }
}

package ch_18;

import java.io.File;
import java.util.Scanner;


public class Exercise18_29 {

    public static void main(String[] args) {
        System.out.print("Enter a directory: ");
        Scanner input = new Scanner(System.in);
        String directory = input.nextLine().trim();
        File file = new File(directory);
        if (file.isDirectory()) {
            System.out.println("The directory: " + file.getName() + " contains " + getFileCount(file) +
                    " files.");
        } else {
            System.out.println("Please ensue you are entering a directory.");
        }
    }

    public static long getFileCount(File file) {
        long TOTAL_FILES = 0;
        File[] files = file.listFiles();
        if (files != null && files.length > 0) {
            for (File f : files) {
                if (f.isFile()) {
                    TOTAL_FILES += 1;
                }

            }
        }
        return TOTAL_FILES;
    }
}

