package mini;
import java.util.Scanner;

public class Mini08 {
    static long inCome;            // 소득
    static long rateTax;           // 세율
    static long progressiveTax;    // 누진공제
    static long[] taxArr = {0, 12000000L, 46000000L, 88000000L, 150000000L, 300000000L, 500000000L, 1000000000L, Long.MAX_VALUE};
    static int[] rate = {0, 6, 15, 24, 35, 38, 40, 42, 45};
    static long[] progressive = {0, 0, 1080000, 5220000, 14900000, 19400000, 25400000, 35400000, 65400000};

    public static void data(){
        Scanner sc = new Scanner(System.in);
        System.out.println("[과세금액 계산 프로그램]");
        System.out.print("연소득을 입력해 주세요.:");
        inCome = sc.nextLong();
        sc.close();
    }
    public static long rateTax(Long inCome) {
        for(int i = 1; i < taxArr.length; i++){
            if(inCome <= taxArr[i]){
                long money = (inCome - taxArr[i - 1]) * rate[i] / 100;
                System.out.printf("%10d * %2d%% = %10d\n\n",inCome - taxArr[i - 1], rate[i], money);
                rateTax += money;
                break;
            }else{
                long money = (taxArr[i] - taxArr[i - 1]) * rate[i] / 100;
                System.out.printf("%10d * %2d%% = %10d\n",taxArr[i] - taxArr[i - 1], rate[i], money);
                rateTax += money;
            }
        }
        return rateTax;
    }
    public static long progressiveTax(Long inCome){
        for (int i = 1; i < taxArr.length; i++) {
            if (inCome <= taxArr[i]) {
                progressiveTax = (inCome * rate[i] / 100) - progressive[i];
                break;
            }
        }
        return progressiveTax;
    }
    public static void main(String[] args) {
        data();
        rateTax(inCome);
        progressiveTax(inCome);
        System.out.println("[세율에 의한 세금]:\t\t\t" + rateTax);
        System.out.println("[누진공제 계산에 의한 세금]:\t" + progressiveTax);
    }
}

import android.content.Context;
import android.support.v7.widget.RecyclerView;
import android.util.AttributeSet;
import android.view.View;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;

public class EmptyRecyclerView extends RecyclerView {
  @Nullable View emptyView;

  public EmptyRecyclerView(Context context) { super(context); }

  public EmptyRecyclerView(Context context, AttributeSet attrs) { super(context, attrs); }

  public EmptyRecyclerView(Context context, AttributeSet attrs, int defStyle) {
    super(context, attrs, defStyle);
  }

  void checkIfEmpty() {
    if (emptyView != null) {
      emptyView.setVisibility(getAdapter().getItemCount() > 0 ? GONE : VISIBLE);
    }
  }

  final @NotNull AdapterDataObserver observer = new AdapterDataObserver() {
    @Override public void onChanged() {
      super.onChanged();
      checkIfEmpty();
    }
  };

  @Override public void setAdapter(@Nullable Adapter adapter) {
    final Adapter oldAdapter = getAdapter();
    if (oldAdapter != null) {
      oldAdapter.unregisterAdapterDataObserver(observer);
    }
    super.setAdapter(adapter);
    if (adapter != null) {
      adapter.registerAdapterDataObserver(observer);
    }
  }

  public void setEmptyView(@Nullable View emptyView) {
    this.emptyView = emptyView;
    checkIfEmpty();
  }
}

package ch_18;


public class Exercise18_05 {
    public static void main(String[] args) {
        for (int i = 1; i <= 10; i++) {
            System.out.printf("\nm(" + i + ") = %.4f", m(i));
        }

    }

    private static double m(int target) {
        int numerator = 1;
        double sum = numerator / ((2.0 * numerator) + 1);
        return m(sum, numerator, target);
    }

    private static double m(double sum, int numerator, int target) {
        if (numerator == target) {
            return sum;
        }
        numerator++;
        sum += numerator / ((2.0 * numerator) + 1);

        return m(sum, numerator, target);
    }
}

package ch_06;


public class Exercise06_15 {
    static final String space = "       ";
    static final String spacex2 = space + "    ";

    public static void main(String[] args) {
        System.out.print("Taxable" + space + "Single" + space + "Married Joint" + space + "Married" + space + "Head " +
                "of");
        System.out.print("\nIncome" + space + "     " + space + "  Or Qualifying" + space + "Separate" + "      " + "a " +
                "House");
        System.out.print("\n      " + space + "       " + space + "Widow(er)" + space + "       " + space + "     ");
        System.out.print(
                "\n_____________________________________________________________________");

        for (int i = 50000; i <= 60000; i += 50) {

            System.out.print("\n" + i);
            System.out.print(spacex2 + Math.round(computeTax(0, i)));
            System.out.print(spacex2 + Math.round(computeTax(1, i)));
            System.out.print(spacex2 + Math.round(computeTax(2, i)));
            System.out.print(spacex2 + Math.round(computeTax(3, i)));
        }
    }

    public static double computeTax(int status, double taxableIncome) {
        double tax = 0;

        int upBound10 = 0, upBound15 = 0, upBound25 = 0, upBound28 = 0, upBound33 = 0;

        if (status == 0) { // Compute tax for single filers
            upBound10 = 8350;
            upBound15 = 33950;
            upBound25 = 82250;
            upBound28 = 171550;
            upBound33 = 372950;

        } else if (status == 1) { // Married Filing Jointly or Qualifying Widow(er)
            upBound10 = 16700;
            upBound15 = 67900;
            upBound25 = 137050;
            upBound28 = 208850;
            upBound33 = 372950;

        } else if (status == 2) { // Compute tax for married separately
            upBound10 = 8350;
            upBound15 = 33950;
            upBound25 = 68525;
            upBound28 = 104425;
            upBound33 = 186475;

        } else if (status == 3) { // Compute tax for head of household
            upBound10 = 11950;
            upBound15 = 45500;
            upBound25 = 117450;
            upBound28 = 190200;
            upBound33 = 372950;
        } else {
            System.out.println("Error: invalid status");
            System.exit(1);
        }

        if (taxableIncome <= upBound10)
            tax = taxableIncome * 0.10;
        else if (taxableIncome <= upBound15)
            tax = upBound10 * 0.10 + (taxableIncome - upBound10) * 0.15;
        else if (taxableIncome <= upBound25)
            tax = upBound10 * 0.10 + (upBound15 - upBound10) * 0.15 + (taxableIncome - upBound15) * 0.25;
        else if (taxableIncome <= upBound28)
            tax = upBound10 * 0.10 + (upBound15 - upBound10) * 0.15 + (upBound25 - upBound15) * 0.25
                    + (taxableIncome - upBound25) * 0.28;
        else if (taxableIncome <= upBound33)
            tax = upBound10 * 0.10 + (upBound15 - upBound10) * 0.15 + (upBound25 - upBound15) * 0.25
                    + (upBound28 - upBound25) * 0.28 + (taxableIncome - upBound28) * 0.33;
        else
            tax = upBound10 * 0.10 + (upBound15 - upBound10) * 0.15 + (upBound25 - upBound15) * 0.25
                    + (upBound28 - upBound25) * 0.28 + (upBound33 - upBound28) * 0.33 + (taxableIncome - upBound33) * 0.35;

        return tax;
    }
}

package ch_08;



public class Exercise08_03 {

	public static void main(String[] args) {
		// Students' answers to the questions
		char[][] answers = { { 'A', 'B', 'A', 'C', 'C', 'D', 'E', 'E', 'A', 'D' },
				{ 'D', 'B', 'A', 'B', 'C', 'A', 'E', 'E', 'A', 'D' },
				{ 'E', 'D', 'D', 'A', 'C', 'B', 'E', 'E', 'A', 'D' },
				{ 'C', 'B', 'A', 'E', 'D', 'C', 'E', 'E', 'A', 'D' },
				{ 'A', 'B', 'D', 'C', 'C', 'D', 'E', 'E', 'A', 'D' },
				{ 'B', 'B', 'E', 'C', 'C', 'D', 'E', 'E', 'A', 'D' },
				{ 'B', 'B', 'A', 'C', 'C', 'D', 'E', 'E', 'A', 'D' },
				{ 'E', 'B', 'E', 'C', 'C', 'D', 'E', 'E', 'A', 'D' } };
		// Answer Key
		char[] keys = { 'D', 'B', 'D', 'C', 'C', 'D', 'A', 'E', 'A', 'D' };

		// stuScore = integer [totalScore][Student number zero to 7]
		int[][] stuScores = new int[answers.length][2];

		for (int i = 0; i < answers.length; i++) {
			int ptsCount = 0;

			for (int j = 0; j < answers[i].length; j++) {
				if (answers[i][j] == keys[j]) {
					ptsCount++;
				}

				stuScores[i][0] = ptsCount;
				stuScores[i][1] = i; //Track index of student
			}
		}

		// Selection Sort to sort student scores in ascending order
		for (int i = 0; i < stuScores.length - 1; i++) {

			for (int j = i + 1; j < stuScores.length; j++) {
				if (stuScores[j][0] < stuScores[i][0]) {
					int[] temp = stuScores[i];
					stuScores[i] = stuScores[j];
					stuScores[j] = temp;
				}
			}

		}

		for (int a = 0; a < stuScores.length; a++) {
			System.out.println("Student " + stuScores[a][1] + ": " + stuScores[a][0]);
		}

	}

}

import com.google.auto.value.AutoValue;
import java.lang.annotation.Retention;
import java.lang.annotation.Target;

import static java.lang.annotation.ElementType.TYPE;
import static java.lang.annotation.RetentionPolicy.RUNTIME;

/**
 * Marks an {@link AutoValue @AutoValue}-annotated type for proper Gson serialization.
 * <p>
 * This annotation is needed because the {@linkplain Retention retention} of {@code @AutoValue}
 * does not allow reflection at runtime.
 */
@Target(TYPE)
@Retention(RUNTIME)
public @interface AutoGson {
}

import javafx.application.Application;
import javafx.beans.binding.Bindings;
import javafx.beans.property.*;
import javafx.geometry.Pos;
import javafx.scene.Scene;
import javafx.scene.control.*;
import javafx.scene.input.KeyEvent;
import javafx.scene.layout.*;
import javafx.stage.*;

import java.util.*;

// a simple JavaFX calculator.
public class Calc extends Application {
    private static final String[][] template = {
            {"7", "8", "9", "/"},
            {"4", "5", "6", "*"},
            {"1", "2", "3", "-"},
            {"0", "c", "=", "+"}
    };

    private final Map<String, Button> accelerators = new HashMap<>();

    private final DoubleProperty stackValue = new SimpleDoubleProperty();
    private final DoubleProperty value = new SimpleDoubleProperty();

    private enum Op {NOOP, ADD, SUBTRACT, MULTIPLY, DIVIDE}

    private Op curOp = Op.NOOP;
    private Op stackOp = Op.NOOP;

    public static void main(String[] args) {
        launch(args);
    }

    @Override
    public void start(Stage stage) {
        final TextField screen = createScreen();
        final TilePane buttons = createButtons();

        stage.setTitle("Calc");
        stage.initStyle(StageStyle.UTILITY);
        stage.setResizable(false);
        stage.setScene(new Scene(createLayout(screen, buttons)));
        stage.show();
    }

    private VBox createLayout(TextField screen, TilePane buttons) {
        final VBox layout = new VBox(20);
        layout.setAlignment(Pos.CENTER);
        layout.setStyle("-fx-background-color: chocolate; -fx-padding: 20; -fx-font-size: 20;");
        layout.getChildren().setAll(screen, buttons);
        handleAccelerators(layout);
        screen.prefWidthProperty().bind(buttons.widthProperty());
        return layout;
    }

    private void handleAccelerators(VBox layout) {
        layout.addEventFilter(KeyEvent.KEY_PRESSED, keyEvent -> {
            Button activated = accelerators.get(keyEvent.getText());
            if (activated != null) {
                activated.fire();
            }
        });
    }

    private TextField createScreen() {
        final TextField screen = new TextField();
        screen.setStyle("-fx-background-color: aquamarine;");
        screen.setAlignment(Pos.CENTER_RIGHT);
        screen.setEditable(false);
        screen.textProperty().bind(Bindings.format("%.0f", value));
        return screen;
    }

    private TilePane createButtons() {
        TilePane buttons = new TilePane();
        buttons.setVgap(7);
        buttons.setHgap(7);
        buttons.setPrefColumns(template[0].length);
        for (String[] r : template) {
            for (String s : r) {
                buttons.getChildren().add(createButton(s));
            }
        }
        return buttons;
    }

    private Button createButton(final String s) {
        Button button = makeStandardButton(s);

        if (s.matches("[0-9]")) {
            makeNumericButton(s, button);
        } else {
            final ObjectProperty<Op> triggerOp = determineOperand(s);
            if (triggerOp.get() != Op.NOOP) {
                makeOperandButton(button, triggerOp);
            } else if ("c".equals(s)) {
                makeClearButton(button);
            } else if ("=".equals(s)) {
                makeEqualsButton(button);
            }
        }

        return button;
    }

    private ObjectProperty<Op> determineOperand(String s) {
        final ObjectProperty<Op> triggerOp = new SimpleObjectProperty<>(Op.NOOP);
        switch (s) {
            case "+" -> triggerOp.set(Op.ADD);
            case "-" -> triggerOp.set(Op.SUBTRACT);
            case "*" -> triggerOp.set(Op.MULTIPLY);
            case "/" -> triggerOp.set(Op.DIVIDE);
        }
        return triggerOp;
    }

    private void makeOperandButton(Button button, final ObjectProperty<Op> triggerOp) {
        button.setStyle("-fx-base: lightgray;");
        button.setOnAction(actionEvent -> curOp = triggerOp.get());
    }

    private Button makeStandardButton(String s) {
        Button button = new Button(s);
        button.setStyle("-fx-base: beige;");
        accelerators.put(s, button);
        button.setMaxSize(Double.MAX_VALUE, Double.MAX_VALUE);
        return button;
    }

    private void makeNumericButton(final String s, Button button) {
        button.setOnAction(actionEvent -> {
            if (curOp == Op.NOOP) {
                value.set(value.get() * 10 + Integer.parseInt(s));
            } else {
                stackValue.set(value.get());
                value.set(Integer.parseInt(s));
                stackOp = curOp;
                curOp = Op.NOOP;
            }
        });
    }

    private void makeClearButton(Button button) {
        button.setStyle("-fx-base: mistyrose;");
        button.setOnAction(actionEvent -> value.set(0));
    }

    private void makeEqualsButton(Button button) {
        button.setStyle("-fx-base: ghostwhite;");
        button.setOnAction(actionEvent -> {
            switch (stackOp) {
                case ADD -> value.set(stackValue.get() + value.get());
                case SUBTRACT -> value.set(stackValue.get() - value.get());
                case MULTIPLY -> value.set(stackValue.get() * value.get());
                case DIVIDE -> value.set(stackValue.get() / value.get());
            }
        });
    }
}

package ch_09.exercise09_13;

import java.util.Scanner;


public class Exercise09_13 {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        System.out.print("Enter the number of rows and columns in the array: ");

        int numRow = in.nextInt();
        int numCol = in.nextInt();
        double[][] numbers = new double[numRow][numCol];

        System.out.println("Enter the array: ");

        for (int r = 0; r < numbers.length; r++) {
            for (int c = 0; c < numbers[r].length; c++) {
                numbers[r][c] = in.nextDouble();
            }
        }
        Location location = Location.locateLargest(numbers);

        System.out.printf("The location of the largest element is: %.2f at (%d, %d)", location.maxValue, location.row,
                location.column
        );


    }
}

package ch_07;

import java.util.*;


public class Exercise07_09 {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        double[] a = new double[10];

        System.out.println("Enter ten numbers: ");
        for (int i = 0; i < 10; i++) {
            a[i] = in.nextDouble();
        }
        System.out.println("The minimum number is: " + min(a));
        in.close();
    }

    public static double min(double[] array) {
        double min = Double.MAX_VALUE;
        for (int i = 0; i < array.length; i++) {
            min = Math.min(min, array[i]);
        }
        return min;
    }
}

package com.mkyong.crypto.hash;

import com.mkyong.crypto.utils.CryptoUtils;

import java.io.FileInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.nio.ByteBuffer;
import java.nio.charset.Charset;
import java.nio.charset.StandardCharsets;
import java.security.DigestInputStream;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class ShaUtils {

    private static final Charset UTF_8 = StandardCharsets.UTF_8;
    private static final String OUTPUT_FORMAT = "%-20s:%s";

    public static byte[] digest(byte[] input, String algorithm) {
        MessageDigest md;
        try {
            md = MessageDigest.getInstance(algorithm);
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalArgumentException(e);
        }
        byte[] result = md.digest(input);
        return result;
    }

    private static byte[] checksum(String filePath, String algorithm) {

        MessageDigest md;
        try {
            md = MessageDigest.getInstance(algorithm);
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalArgumentException(e);
        }

        try (InputStream is = new FileInputStream(filePath);
             DigestInputStream dis = new DigestInputStream(is, md)) {
            while (dis.read() != -1) ; //empty loop to clear the data
            md = dis.getMessageDigest();
        } catch (IOException e) {
            throw new IllegalArgumentException(e);
        }
        return md.digest();

    }

    public static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    public static void main(String[] args) {

        //String algorithm = "SHA-256";
        String algorithm = "SHA3-256";

        String pText = "Hello World";
        System.out.println(String.format(OUTPUT_FORMAT, "Input (string)", pText));
        System.out.println(String.format(OUTPUT_FORMAT, "Input (length)", pText.length()));

        byte[] shaInBytes = ShaUtils.digest(pText.getBytes(UTF_8), algorithm);
        System.out.println(String.format(OUTPUT_FORMAT, algorithm + " (hex) ", bytesToHex(shaInBytes)));

        System.out.println(String.format(OUTPUT_FORMAT, algorithm + " (length)", shaInBytes.length));

        // get file path from resources
        /*String filePath = ClassLoader.getSystemResource("sha-file.txt").getFile();

        byte[] hashInBytes = checksum(filePath, algorithm);
        System.out.println(bytesToHex(hashInBytes));*/

        // get a 16 bytes random salt.
        /*byte[] salt = CryptoUtils.getRandomNonce(16);
        byte[] pText = "Hello World".getBytes(StandardCharsets.UTF_8);

        // combine two byte arrays
        byte[] input = ByteBuffer.allocate(salt.length + pText.length)
                .put(salt)
                .put(pText)
                .array();

        // no salt, SHA3-256
        System.out.println(bytesToHex(ShaUtils.digest(pText, "SHA3-256")));

        // 16 bytes salt, SHA3-256
        System.out.println(bytesToHex(ShaUtils.digest(input, "SHA3-256")));*/

    }
}

