package ch_05;

import java.util.*;


public class Exercise05_24 {
    public static void main(String[] args) {
        double res = 0.0;
        System.out.println("Cancellation error example calculating from right to left: ");
        for (int i = 1000; i >= 1; i--) {
            res += 1.0 / i;
        }
        System.out.println("Total Sum: " + res);
        double res2 = 0.0;
        System.out.println("Cancellation error example calculating from left to right: ");
        for (int i = 1; i <= 1000; i++) {
            res2 += 1.0 / i;
        }
        System.out.println("Total Sum: " + res2);
        double d = res - res2;
        System.out.println("By going from left to right, we lost accuracy of " + d);
    }
}

package ch_08;

import java.util.*;


public class Exercise08_25 {
    static String markovMatrix = "It is a Markov matrix";
    static String notMarkovMatrix = "It is not a Markov matrix";

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        double[][] test = new double[3][3];

        System.out.println("Enter a 3-by-3 matrix row by row: ");

        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                test[i][j] = in.nextDouble();
            }
        }
        if (isMarkovMatrix(test)) {
            System.out.println(markovMatrix);
        } else {
            System.out.println(notMarkovMatrix);
        }
        in.close();


    }

    public static boolean isMarkovMatrix(double[][] m) {
        for (int i = 0; i < 3; i++) {
            double sum = 0;
            for (int j = 0; j < 3; j++) {
                if (m[j][i] < 0) {
                    return false;
                }
                sum += m[j][i];
            }
            if (sum != 1) {
                return false;
            }
        }
        return true;

    }
}

package ch_17.exercise17_08;

import ch_17.exercise17_01.Exercise17_01;

import java.io.*;
import java.util.*;


public class Exercise17_08 {
    public static void main(String[] args) throws FileNotFoundException {
        int runs = 0;
        String[] packageParts = Exercise17_01.class.getPackage().getName().split("\\.");
        String path = packageParts[0] + File.separator + packageParts[1] + File.separator +
                "Exercise17_08.dat";

        File file = new File(path);
        if (!file.exists()) {
            runs = 1;
            writeFile(runs, file);
        } else {
            runs = readFile(file);
            writeFile(++runs, file);
        }
        System.out.println("Number of runs: " + runs);
    }

    static int readFile(File file) {
        int i = 0;
        try (DataInputStream dIs = new DataInputStream(new FileInputStream(file))) {
            i = dIs.readInt();
        } catch (IOException e) {
            e.printStackTrace();
            System.out.println("Something went wrong reading the data file...@ -> " + file.getName());
        }
        return i;

    }

    static void writeFile(int i, File file) {
        try (DataOutputStream das = new DataOutputStream(new FileOutputStream(file))) {
            das.writeInt(i);
        } catch (IOException e) {
            e.printStackTrace();
            System.out.println("Something went wrong writing the data file...@ -> " + file.getName());

        }
    }
}

package ch_19;


public class Exercise19_11 {
    // Test Program
    public static void main(String[] args) {
        ComplexMatrix complexMatrix = new ComplexMatrix();
        Complex[][] m1 = new Complex[][]{
                {new Complex(1, 5), new Complex(1, 6), new Complex(1, 7)},
                {new Complex(2, 5), new Complex(1, 3), new Complex(2, 7)},
                {new Complex(3, 5), new Complex(1, 2), new Complex(3, 7)}
        };

        Complex[][] m2 = new Complex[][]{
                {new Complex(1, 6), new Complex(1, 7), new Complex(1, 8)},
                {new Complex(1, 3), new Complex(2, 7), new Complex(1, 4)},
                {new Complex(1, 2), new Complex(3, 7), new Complex(3, 8)}
        };

        Complex[][] additionResult = complexMatrix.addMatrix(m1, m2);
        ComplexMatrix.printResult(m1, m2, additionResult, '+');

        Complex[][] multipliedResult = complexMatrix.multiplyMatrix(m1, m2);
        ComplexMatrix.printResult(m1, m2, multipliedResult, '*');


    }

}


abstract class GenericMatrix<E extends Number> {

    protected abstract E add(E o1, E o2);


    protected abstract E multiply(E o1, E o2);


    protected abstract E zero();


    public E[][] addMatrix(E[][] matrix1, E[][] matrix2) {
        // Check bounds of the two matrices
        if ((matrix1.length != matrix2.length) ||
                (matrix1[0].length != matrix2[0].length)) {
            throw new RuntimeException(
                    "The matrices do not have the same size");
        }


        E[][] result =
                (E[][]) new Number[matrix1.length][matrix1[0].length];
        // Perform addition
        for (int i = 0; i < result.length; i++)
            for (int j = 0; j < result[i].length; j++) {
                result[i][j] = add(matrix1[i][j], matrix2[i][j]);
            }
        return result;
    }


    public E[][] multiplyMatrix(E[][] matrix1, E[][] matrix2) {
        // Check bounds
        if (matrix1[0].length != matrix2.length) {
            throw new RuntimeException(
                    "The matrices do not have compatible size");
        }
        // Create result matrix
        E[][] result =
                (E[][]) new Number[matrix1.length][matrix2[0].length];
        // Perform multiplication of two matrices
        for (int i = 0; i < result.length; i++) {
            for (int j = 0; j < result[0].length; j++) {
                result[i][j] = zero();
                for (int k = 0; k < matrix1[0].length; k++) {
                    result[i][j] = add(result[i][j],
                            multiply(matrix1[i][k], matrix2[k][j]));
                }
            }
        }
        return result;
    }


    public static void printResult(
            Number[][] m1, Number[][] m2, Number[][] m3, char op) {
        for (int i = 0; i < m1.length; i++) {
            for (int j = 0; j < m1[0].length; j++)
                System.out.print(" " + m1[i][j]);
            if (i == m1.length / 2)
                System.out.print(" " + op + " ");
            else
                System.out.print(" ");
            for (int j = 0; j < m2.length; j++)
                System.out.print(" " + m2[i][j]);
            if (i == m1.length / 2)
                System.out.print(" = ");
            else
                System.out.print(" ");
            for (int j = 0; j < m3.length; j++)

                System.out.print(m3[i][j] + " ");
            System.out.println();
        }
    }
}


class ComplexMatrix extends GenericMatrix<Complex> {

    @Override
    protected Complex add(Complex c1, Complex c2) {
        return new Complex(c1.add(c2));
    }

    @Override
    protected Complex multiply(Complex c1, Complex c2) {
        return new Complex(c1.multiply(c2));
    }

    @Override
    protected Complex zero() {
        return new Complex(0.0);
    }

    @Override
    public Complex[][] multiplyMatrix(Complex[][] c1s, Complex[][] c2s) {
        if (c1s[0].length != c2s.length) {
            throw new RuntimeException("The matrices do not have compatible size");
        }

        Complex[][] result = new Complex[c1s.length][c2s[0].length];
        for (int i = 0; i < result.length; i++) {
            for (int j = 0; j < result[0].length; j++) {
                result[i][j] = zero();
                for (int k = 0; k < c1s[0].length; k++) {
                    result[i][j] = add(result[i][j],
                            multiply(c1s[i][k], c2s[k][j]));
                }
            }
        }
        return result;
    }

    @Override
    public Complex[][] addMatrix(Complex[][] c1s, Complex[][] c2s) {
        if ((c1s.length != c2s.length) || (c1s[0].length != c2s[0].length)) {
            throw new RuntimeException("The matrices do not have the same size");
        }
        Complex[][] result = new Complex[c1s.length][c1s[0].length];
        for (int i = 0; i < result.length; i++) {
            for (int j = 0; j < result[i].length; j++) {
                result[i][j] = add(c1s[i][j], c2s[i][j]);
            }
        }
        return result;
    }

    public static void printResult(
            Complex[][] m1, Complex[][] m2, Complex[][] m3, char op) {
        for (int i = 0; i < m1.length; i++) {
            for (int j = 0; j < m1[0].length; j++)
                System.out.print(" " + m1[i][j]);
            if (i == m1.length / 2)
                System.out.print(" " + op + " ");
            else
                System.out.print(" ");
            for (int j = 0; j < m2.length; j++)
                System.out.print(" " + m2[i][j]);
            if (i == m1.length / 2)
                System.out.print(" = ");
            else
                System.out.print(" ");
            for (int j = 0; j < m3.length; j++)

                System.out.print(m3[i][j] + " ");
            System.out.println();
        }
    }

}


class Complex extends Number implements Cloneable {

    private double a;
    private double b;
    private static double i = Math.sqrt(-1);

    public Complex() {
        this(0);
    }

    public Complex(double a) {
        this(a, 0);
    }

    public Complex(double a, double b) {
        this.a = a;
        this.b = b;
    }


    public double add(Complex complex) {
        return (this.a + complex.a) + (this.b + complex.b) * i;
    }


    public double subtract(Complex complex) {
        return (this.a - complex.a) + (this.b - complex.b) * i;

    }


    public double multiply(Complex complex) {
        return (this.a * complex.a - this.b * complex.b) + ((this.b * complex.a + this.a * complex.b) * i);
    }


    public double divide(Complex complex) {
        return (this.a * complex.a + this.b * complex.b) / (Math.pow(complex.a, 2) + Math.pow(complex.b, 2)) + ((this.b * complex.a - this.a * complex.b) * i) / (Math.pow(complex.a, 2) + Math.pow(complex.b, 2));
    }

    public double abs(Complex complex) {
        return Math.sqrt(Math.pow(this.a, 2) + Math.pow(this.b, 2));
    }

    public double getRealPart() {
        return a;
    }

    public double getImaginaryPart() {
        return b * i;
    }

    @Override
    public Complex clone() throws CloneNotSupportedException {
        return (Complex) super.clone();

    }

    @Override
    public int intValue() {
        return (int) Math.round(a + b * i);
    }

    @Override
    public long longValue() {
        return Math.round(a + b * i);
    }

    @Override
    public float floatValue() {
        return (float) (a + b * i);
    }

    @Override
    public double doubleValue() {
        return a + b * i;
    }

    @Override
    public String toString() {
        return "( " + a + " + " + b + "(" + i + ")" + " )";
    }
}

package net.mastermank.corridorsbackrooms.event;

import net.mastermank.corridorsbackrooms.CorridorsBackrooms;
import net.mastermank.corridorsbackrooms.entity.BackroomsEntityRegistry;
import net.mastermank.corridorsbackrooms.entity.custom.*;
import net.mastermank.corridorsbackrooms.sanity.PlayerSanity;
import net.mastermank.corridorsbackrooms.sanity.PlayerSanityProvider;
import net.mastermank.corridorsbackrooms.world.dimension.BackroomsLevels;
import net.minecraft.world.entity.EntityType;
import net.minecraft.world.entity.MobSpawnType;
import net.minecraft.world.entity.monster.Zombie;
import net.minecraft.world.entity.player.Player;
import net.minecraftforge.common.MinecraftForge;
import net.minecraftforge.common.capabilities.RegisterCapabilitiesEvent;
import net.minecraftforge.event.TickEvent;
import net.minecraftforge.event.entity.EntityAttributeCreationEvent;
import net.minecraftforge.event.entity.living.LivingDeathEvent;
import net.minecraftforge.event.entity.living.LivingSpawnEvent;
import net.minecraftforge.event.entity.player.PlayerEvent;
import net.minecraftforge.eventbus.api.EventPriority;
import net.minecraftforge.eventbus.api.SubscribeEvent;
import net.minecraftforge.fml.LogicalSide;
import net.minecraftforge.fml.common.Mod;


public class ModEvents {

    @Mod.EventBusSubscriber(modid = CorridorsBackrooms.MOD_ID)
    public static class ForgeEvents {

    }

    @Mod.EventBusSubscriber(modid = CorridorsBackrooms.MOD_ID, bus = Mod.EventBusSubscriber.Bus.MOD)
    public static class ModEventBusEvents {
        @SubscribeEvent
        public static void entityAttributeEvent(EntityAttributeCreationEvent event) {
            event.put(BackroomsEntityRegistry.SMILER.get(), SmilerEntity.setAttributes());
            event.put(BackroomsEntityRegistry.DECAYEDGLORY.get(), DecayedGloryEntity.setAttributes());
            event.put(BackroomsEntityRegistry.BASHER.get(), BasherEntity.setAttributes());
            event.put(BackroomsEntityRegistry.PARTYGOER.get(), PartygoerEntity.setAttributes());
            event.put(BackroomsEntityRegistry.HOUND.get(), HoundEntity.setAttributes());

            MinecraftForge.EVENT_BUS.register(ModEvents.class);
        }
    }

    @SubscribeEvent
    public static void onPlayerCloned(PlayerEvent.Clone event) {
        if (event.isWasDeath()) {
            event.getOriginal().getCapability(PlayerSanityProvider.PLAYER_SANITY).ifPresent(oldStore -> {
                event.getOriginal().getCapability(PlayerSanityProvider.PLAYER_SANITY).ifPresent(newStore -> {
                    newStore.copyFrom(oldStore);
                });
            });
        }
    }

    @SubscribeEvent
    public static void onRegisterCapabilities(RegisterCapabilitiesEvent event) {
        event.register(PlayerSanity.class);
    }

    @SubscribeEvent
    public static void onPlayerTick(TickEvent.PlayerTickEvent event) {
        if (event.side == LogicalSide.SERVER) {
            event.player.getCapability(PlayerSanityProvider.PLAYER_SANITY).ifPresent(sanity -> {
                if (sanity.getSanity() > 0 && event.player.getRandom().nextFloat() < 0.005f) { // Once Every 10 Seconds on Avg
                    sanity.subsanity(1);
                }
            });
        }
    }
    @SubscribeEvent
    public static void onPartygoerPlayerKill(LivingDeathEvent event) {
        if (event.getEntity() instanceof Player player) {
            if (!(event.getSource().getEntity() instanceof PartygoerEntity)) return;
            PartygoerEntity partygoer =
                    BackroomsEntityRegistry.PARTYGOER.get().create(event.getEntity().getLevel());
            EntityType.PLAYER.create(event.getEntity().getLevel());
            partygoer.setPos(player.getX(), player.getY(), player.getZ());
            event.getEntity().level.addFreshEntity(partygoer);
        }
    }
    @SubscribeEvent(priority = EventPriority.HIGH)
    public static void onSpecialSpawn(LivingSpawnEvent.SpecialSpawn event) {
        if (!event.getLevel().isClientSide() && (event.getEntity() instanceof Zombie && !(event.getSpawnReason() == MobSpawnType.SPAWN_EGG) && !(event.getSpawnReason() == MobSpawnType.COMMAND))) {
            if (event.getEntity().level.dimension().equals(BackroomsLevels.LEVEL0)) {
                event.getEntity().discard();
            }
        }
    }
}

package ch_18;

import java.util.Scanner;


public class Exercise18_13 {
    static int currIdx = 0;

    public static void main(String[] args) {
        int[] arr = new int[8];
        Scanner in = new Scanner(System.in);
        System.out.println("Enter a list of eight integers: ");
        for (int i = 0; i < 8; i++) {
            arr[i] = in.nextInt();
        }
        in.close();
        System.out.println("The largest integer in the list is " + largestInteger(Integer.MIN_VALUE, arr));


    }

    static int largestInteger(int large, int[] integers) {
        if (currIdx == integers.length) {
            return large;
        }
        large = Math.max(large, integers[currIdx++]);
        return largestInteger(large, integers);
    }
}

