import java.time.Duration;
import java.time.Instant;
import java.util.Arrays;
import java.util.concurrent.ThreadLocalRandom;

public class QuickSort {

    public static void main(String[] args) {
        int size = args.length >= 1 ? Integer.parseInt(args[0]) : 10;
        int[] numbers = getRandomArray(size);

        System.out.printf("Array before: %s%n", Arrays.toString(numbers));

        Instant start = Instant.now();
        quickSort(numbers, 0, numbers.length - 1);
        Instant end = Instant.now();

        System.out.printf("Array after: %s%n", Arrays.toString(numbers));

        long nanos = Duration.between(start, end).toNanos();
        System.out.printf("Took %,2dμs (%.3fms)%n", nanos / 1000, (float) nanos / 1000000);
    }

    /**
     * Swaps two elements in an array with the use of a temporary variable.
     * 
     * @param array        The array
     * @param leftMarker   The index of the first element
     * @param rightMarker  The index of the second element
     */
    public static void swap(int[] array, int leftMarker, int rightMarker) {
        int temp = array[leftMarker];
        array[leftMarker] = array[rightMarker];
        array[rightMarker] = temp;
    }

    /**
     * Performs the quick sort algorithm on an array. Works by partitioning an
     * array into two sub-arrays around a pivot element, and then recursively
     * sorting the two sub-arrays.
     *  
     * If the array is too large it will use the {@link Main#insertionSort(int[], int, int)}
     * instead. This prevents what I can only assume is a {@link StackOverflowError} because
     * the code just does not run on arrays of around size 14 or higher.
     * 
     * @param array  The array to sort
     * @param left   The index of the leftmost element of the array
     * @param right  The index of the rightmost element of the array.
     */
    public static int[] quickSort(int[] array, int left, int right) {
        int recursionThreshold = 12;

        if (array.length > recursionThreshold) {
            insertionSort(array, left, right); 
        } else {
            while (left < right) {
                int pivotIndex = partition(array, left, right);
                if (pivotIndex - left < right - pivotIndex) {
                    quickSort(array, left, pivotIndex - 1); 
                    left = pivotIndex + 1;
                } else {
                    quickSort(array, pivotIndex + 1, right);
                    right = pivotIndex - 1;
                }
            }
        }
        return array;
    }

    /**
     * Performs the insertion sort algorithm on an array. Works by iterating 
     * over the array, comparing each element to the previous elements,
     * and swapping them if necessary to maintain the order.
     * 
     * @param array  The array to sort.
     * @param left   The index of the leftmost element of the sub-array.
     * @param right  The index of the rightmost element of the sub-array.
     */
    private static void insertionSort(int[] array, int left, int right) {
        for (int i = left + 1; i <= right; i++) {
            int key = array[i];
            int j = i - 1;
            while (j >= left && array[j] > key) {
                array[j + 1] = array[j];
                j--;
            }
            array[j + 1] = key;
        }
    }

    /**
     * Partitions an array into two subarrays around a pivot element
     * and rearranges the array such that all the elements less than 
     * the pivot are to its left and all the elements greater are to 
     * the right.
     * 
     * @param array  The array to be partitioned.
     * @param left   The index of the leftmost element of the sub-array.
     * @param right  The index of the rightmost element of the sub-array.
     */
    private static int partition(int[] array, int left, int right) {
        int leftMarker = left;
        int rightMarker = right;

        int pivot = array[leftMarker];
        while (leftMarker < rightMarker) {
            while (array[leftMarker] < pivot) {
                leftMarker++;
            }
            while (array[rightMarker] > pivot) {
                rightMarker--;
            }
            swap(array, leftMarker, rightMarker);
        }
        return leftMarker;
    }

    /**
     * Generates an array of random numbers of a given size.
     * 
     * @param size  The size of the array to generate.
     */
    private static int[] getRandomArray(int size) {
        int[] array = new int[size];
        for (int i = 0; i < array.length; i++) {
            array[i] = ThreadLocalRandom.current().nextInt(100);
        }

        return array;
    }
}

package ch_11.exercise11_05;

import java.util.ArrayList;


//_________________________UML DIAGRAM______________________________*
/*																	|
 * 							  Course  								|
 *------------------------------------------------------------------|
 * 				                                                    |
 * 	                    -courseName: String	                 		|
 *                      -students: ArrayList<String>               	|
 * 	                                                        		|
 *------------------------------------------------------------------|
 * 	                  +Course(courseName: String) 					|
 * 	                  +getCourseName(): String		    			|
 * 	                  +addStudent(student: String): void			|
 * 	 																|
 * 																	|
 *__________________________________________________________________|  */


public class Course {
    private String courseName;
    private ArrayList<String> students = new ArrayList<>();

    public Course(String courseName) {
        this.courseName = courseName;
    }

    public void addStudent(String student) {
        students.add(student);
    }

    public ArrayList<String> getStudents() {
        return students;
    }

    public int getNumberOfStudents() {
        return students.size();
    }

    public String getCourseName() {
        return courseName;
    }

    public void dropStudent(String student) {
        students.remove(student);
        System.out.println("Dropped student: " + student);
    }
}

package ch_15;

import javafx.application.Application;
import javafx.geometry.Pos;
import javafx.scene.Scene;
import javafx.scene.control.Button;
import javafx.scene.image.Image;
import javafx.scene.image.ImageView;
import javafx.scene.layout.HBox;
import javafx.scene.layout.VBox;
import javafx.stage.Stage;


public class Exercise15_01 extends Application {
    String[] cards;
    int[] picked = new int[4];
    int pick = 0;

    private void setCards() {
        cards = new String[52];
        int cardNum = 1;
        for (int i = 0; i < cards.length; i++) {
            String path = "resources/cards/" + cardNum + ".png";
            cards[i] = path;
            cardNum++;

        }

    }


    @Override
    public void start(Stage primaryStage) throws Exception {
        setCards();
        VBox vbox = new VBox();
        HBox cardBox = new HBox();
        HBox buttonBar = new HBox();
        vbox.setFillWidth(true);

        Image i1 = new Image(cards[randomCard()]);
        Image i2 = new Image(cards[randomCard()]);
        Image i3 = new Image(cards[randomCard()]);
        Image i4 = new Image(cards[randomCard()]);


        ImageView card1 = new ImageView(i1);
        card1.setPreserveRatio(true);
        card1.setFitHeight(300);

        ImageView card2 = new ImageView(i2);
        card2.setPreserveRatio(true);
        card2.setFitHeight(300);

        ImageView card3 = new ImageView(i3);
        card3.setPreserveRatio(true);
        card3.setFitHeight(300);

        ImageView card4 = new ImageView(i4);
        card4.setPreserveRatio(true);
        card4.setFitHeight(300);

        Button refreshButton = new Button("Refresh");
        refreshButton.setOnAction(e -> {
            refreshCards(cardBox);
        });

        buttonBar.getChildren().add(refreshButton);
        buttonBar.setAlignment(Pos.CENTER);

        cardBox.getChildren().addAll(card1, card2, card3, card4);
        vbox.getChildren().add(cardBox);
        vbox.getChildren().add(buttonBar);
        Scene scene = new Scene(vbox);
        primaryStage.setScene(scene);
        primaryStage.show();

    }

    private void refreshCards(HBox hBox) {
        pick = 0;
        Image i1 = new Image(cards[randomCard()]);
        Image i2 = new Image(cards[randomCard()]);
        Image i3 = new Image(cards[randomCard()]);
        Image i4 = new Image(cards[randomCard()]);

        ImageView card1 = new ImageView(i1);
        card1.setPreserveRatio(true);
        card1.setFitHeight(300);

        ImageView card2 = new ImageView(i2);
        card2.setPreserveRatio(true);
        card2.setFitHeight(300);

        ImageView card3 = new ImageView(i3);
        card3.setPreserveRatio(true);
        card3.setFitHeight(300);

        ImageView card4 = new ImageView(i4);
        card4.setPreserveRatio(true);
        card4.setFitHeight(300);
        hBox.getChildren().setAll(card1, card2, card3, card4);
    }

    int randomCard() {
        int ran = -1;
        do {
            ran = (int) (Math.random() * 52);

        } while (ran == picked[0] || ran == picked[1] || ran == picked[2] || ran == picked[3]);

        picked[pick++] = ran;
        return ran;
    }

}

package ch_20;

import java.util.Stack;
import java.util.StringTokenizer;


public class Exercise20_14 {
    public static void main(String[] args) {
        if (args.length < 1) {
            System.out.println(
                    "Usage: java Exercise20_14 expression");
            System.exit(1);
        }
        String expression = "";
        for (int i = 0; i < args.length; i++) {
            expression += args[i] + " ";
        }
        try {
            System.out.println(evaluateExpression(expression));
        } catch (Exception ex) {
            System.out.println("Expression was incorrect format");
        }
    }

    static int evaluateExpression(String expression) {
        Stack<Integer> operandStack = new Stack<>();
        StringTokenizer tokens = new StringTokenizer(expression, " +-/*%", true);

        while (tokens.hasMoreTokens()) {
            String token = tokens.nextToken().trim();
            if (token.length() == 0) {
                continue;
            } else if (token.charAt(0) == '+' || token.charAt(0) == '-' ||
                    token.charAt(0) == '*' || token.charAt(0) == '/') {
                processAnOperator(token.charAt(0), operandStack);
            } else {
                operandStack.push(new Integer(token));
            }
        }

        return operandStack.pop();
    }


    static void processAnOperator(char op, Stack<Integer> operandStack) {
        if (op == '+') {
            int op1 = operandStack.pop();
            int op2 = operandStack.pop();
            operandStack.push(op2 + op1);
        } else if (op == '-') {
            int op1 = operandStack.pop();
            int op2 = operandStack.pop();
            operandStack.push(op2 - op1);
        } else if ((op == '*')) {
            int op1 = operandStack.pop();
            int op2 = operandStack.pop();
            operandStack.push(op2 * op1);
        } else if (op == '/') {
            int op1 = operandStack.pop();
            int op2 = operandStack.pop();
            operandStack.push(op2 / op1);
        }
    }
}

