        mCoverImage = (ImageView) findViewById(R.id.cover);

        // do anything before post data.. or triggered after button clicked
        saveProfileAccount();
    }

    private void saveProfileAccount() {
        // loading or check internet connection or something...
        // ... then
        String url = "http://www.angga-ari.com/api/something/awesome";
        VolleyMultipartRequest multipartRequest = new VolleyMultipartRequest(Request.Method.POST, url, new Response.Listener<NetworkResponse>() {
            @Override
            public void onResponse(NetworkResponse response) {
                String resultResponse = new String(response.data);
                try {
                    JSONObject result = new JSONObject(resultResponse);
                    String status = result.getString("status");
                    String message = result.getString("message");

                    if (status.equals(Constant.REQUEST_SUCCESS)) {
                        // tell everybody you have succed upload image and post strings
                        Log.i("Messsage", message);
                    } else {
                        Log.i("Unexpected", message);
                    }
                } catch (JSONException e) {
                    e.printStackTrace();
                }
            }
        }, new Response.ErrorListener() {
            @Override
            public void onErrorResponse(VolleyError error) {
                NetworkResponse networkResponse = error.networkResponse;
                String errorMessage = "Unknown error";
                if (networkResponse == null) {
                    if (error.getClass().equals(TimeoutError.class)) {
                        errorMessage = "Request timeout";
                    } else if (error.getClass().equals(NoConnectionError.class)) {
                        errorMessage = "Failed to connect server";
                    }
                } else {
                    String result = new String(networkResponse.data);
                    try {
                        JSONObject response = new JSONObject(result);
                        String status = response.getString("status");
                        String message = response.getString("message");

                        Log.e("Error Status", status);
                        Log.e("Error Message", message);

                        if (networkResponse.statusCode == 404) {
                            errorMessage = "Resource not found";
                        } else if (networkResponse.statusCode == 401) {
                            errorMessage = message+" Please login again";
                        } else if (networkResponse.statusCode == 400) {
                            errorMessage = message+ " Check your inputs";
                        } else if (networkResponse.statusCode == 500) {
                            errorMessage = message+" Something is getting wrong";
                        }
                    } catch (JSONException e) {
                        e.printStackTrace();
                    }
                }
                Log.i("Error", errorMessage);
                error.printStackTrace();
            }
        }) {
            @Override
            protected Map<String, String> getParams() {
                Map<String, String> params = new HashMap<>();
                params.put("api_token", "gh659gjhvdyudo973823tt9gvjf7i6ric75r76");
                params.put("name", mNameInput.getText().toString());
                params.put("location", mLocationInput.getText().toString());
                params.put("about", mAboutInput.getText().toString());
                params.put("contact", mContactInput.getText().toString());
                return params;
            }

            @Override
            protected Map<String, DataPart> getByteData() {
                Map<String, DataPart> params = new HashMap<>();
                // file name could found file base or direct access from real path
                // for now just get bitmap data from ImageView
                params.put("avatar", new DataPart("file_avatar.jpg", AppHelper.getFileDataFromDrawable(getBaseContext(), mAvatarImage.getDrawable()), "image/jpeg"));
                params.put("cover", new DataPart("file_cover.jpg", AppHelper.getFileDataFromDrawable(getBaseContext(), mCoverImage.getDrawable()), "image/jpeg"));

                return params;
            }
        };

        VolleySingleton.getInstance(getBaseContext()).addToRequestQueue(multipartRequest);
    }

}

package ch_11.exercise11_08;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Date;



public class Account {

    private String ownerName;
    private ArrayList<Transaction> transactions;

    private int id;
    private double balance;
    private double annualInterestRate;
    private Date dateCreated;


    public Account() {
        id = 0;
        balance = 0;
        annualInterestRate = 0;
        transactions = new ArrayList<>();
    }

    public Account(String ownerName, int id, double balance) {
        this.ownerName = ownerName;
        this.id = id;
        this.balance = balance;
        transactions = new ArrayList<>();
    }

    public Account(int newId, double newBalance) {
        this.id = newId;
        this.balance = newBalance;
        dateCreated = new Date();
        annualInterestRate = 0;
        transactions = new ArrayList<>();

    }

    public int getID() {

        return id;
    }

    public void setID(int newID) {

        this.id = newID;
    }

    public double getBalance() {

        return balance;
    }

    public void setBalance(double newBalance) {

        this.balance = newBalance;
    }

    public double getAnnualInterestRate() {
        return annualInterestRate;
    }

    public void setAnnualInterestRate(double newInterestRate) {

        this.annualInterestRate = newInterestRate;
    }

    public Date getDateCreated() {

        Date startDate = dateCreated;

        return startDate;
    }

    public double getMonthlyInterestRate() {

        return (annualInterestRate / 12);
    }

    public double getMonthlyInterest() {

        return balance * (this.getMonthlyInterestRate() / 100);
    }

    public void withdraw(double amount) {
        balance -= amount;
        Transaction transaction = new Transaction(Transaction.WITHDRAWAL, amount, this.balance, "Standard");
        transactions.add(transaction);

    }

    public void deposit(double amountDeposit) {
        balance += amountDeposit;
        Transaction transaction = new Transaction(Transaction.DEPOSIT, amountDeposit, this.balance, "Standard");
        transactions.add(transaction);

    }

    @Override
    public String toString() {
        return "Account Summary: \n" +
                "ownerName=" + ownerName +
                ", annualInterestRate=" + annualInterestRate + "%" +
                ", balance=$" + balance + "\n" +
                "Transactions:\n" + Arrays.toString(transactions.toArray());
    }

}

package ch_18;

import java.util.Scanner;


public class Exercise18_11 {
    static int sum;

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        System.out.println("Enter an integer: ");
        long num = in.nextInt();
        System.out.println("Sum of the digits in " + num + " is " + sumDigits(num));

    }

    public static int sumDigits(long n) {
        if (n == 0) {
            return sum;
        }
        long i = n % 10;
        sum += i;
        n /= 10;
      return sumDigits(n);
    }
}

public class Marks {
    private int[] marks;
    private int numdata;

    public Marks() {
        numdata = 0;
    }

    public Marks(int num) {
        marks = new int[num];
        numdata = num;
    }

    public void createData(int num) {
        marks = new int[num];
        numdata = num;
    }

    public float calcAvg() {
        float sum = 0;
        for (int i = 0; i < numdata; i++) {
            sum += marks[i];
        }
        float avg = sum / numdata;
        return avg;
    }

    public void setMark(int mark, int index) throws Exception {
        if (mark < 0)
            throw new Exception("Mark is incorrect");

        this.marks[index] = mark;
    }

    public float getMark(int index) {
        return marks[index];
    }
}

