                        mStatusView.setTextColor(badCpl ? 0xffff4444 : 0x88ffffff);
                        mStatusView.setText("Maximum measure: " + maxCharsPerLine + " CPL");
                    }
                });
    }
}

package ch_23;

import java.util.Comparator;


public class Exercise23_01 {

    public static <E extends Comparable<E>> void bubbleSort(E[] list) {
        boolean needNextPass = true;
        for (int k = 0; k < list.length && needNextPass; k++) {
            needNextPass = false;
            for (int i = 0; i < list.length - k; i++) {
                if (list[i].compareTo(list[i + 1]) < 0) {
                    E temp = list[i];
                    list[i] = list[i + 1];
                    list[i + 1] = temp;
                    needNextPass = true;
                }
            }
        }
    }

    public static <E> void bubbleSort(E[] list,
                                      Comparator<? super E> comparator) {
        boolean needNextPass = true;
        for (int k = 0; k < list.length && needNextPass; k++) {
            needNextPass = false;
            for (int i = 0; i < list.length - k; i++) {
                if (comparator.compare(list[i], list[i + 1]) < 0) {
                    E temp = list[i];
                    list[i] = list[i + 1];
                    list[i + 1] = temp;
                    needNextPass = true;
                }
            }

        }
    }
}

package ch_07;

import java.util.*;


public class Exercise07_19 {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);

        System.out.println("Enter list: ");
        int[] nums = new int[in.nextInt()];

        for (int i = 0; i < nums.length; i++) {
            nums[i] = in.nextInt();
        }

        if (isSorted(nums)) {
            System.out.println("The list is sorted");

        } else {
            System.out.println("The list is not sorted");

        }
    }

    public static boolean isSorted(int[] list) {
        boolean sorted = true;
        for (int i = 1; i < list.length; i++) {
            for (int j = 0; j < list.length - i; j++) {
                if (list[j] > list[j + 1]) {
                    sorted = false;
                    break;
                }

            }
        }
        return sorted;
    }

}

