    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        System.out.print("Enter a String and a character to count it's occurrences:");
        String str = in.next();
        char ch = in.next().charAt(0);

        System.out.println("Character " + ch + " occurs " + count(str, ch) + " times in " + str);
        in.close();
    }

    public static int count(String str, char a) {
        if (str.length() > 0) {
            if (str.charAt(str.length() - 1) == a) {
                return 1 + count(str.substring(0, str.length() - 1), a);
            } else {
                return count(str.substring(0, str.length() - 1), a);
            }
        }
        return 0;

    }
}

package ch_10.exercise10_10;

//__________________________UML DIAGRAM_____________________________*
/*																	|
 * 							 Queue  								|
 *------------------------------------------------------------------|
 *                     -elements : int[]          					|
 *					   -size : int                                  |
 *                     +capacity:int								|
 *------------------------------------------------------------------|
 *          	     +Queue()										|
 * 	 																|
 * 	              +enqueue(int) : void				       			|
 * 																	|
 * 	              +dequeue():  void    					    		|
 * 	 																|
 * 	               +empty(): boolean								|
 *  																|
 * 	               getSize():int   									|
 * 																	|
 * _________________________________________________________________|  */

import java.util.Arrays;


public class Queue {
    int[] elements;
    int size;
    static final int DEFAULT_CAPACITY = 8;

    public Queue() {
        elements = new int[DEFAULT_CAPACITY];
        size = 0;
    }

    void enqueue(int v) {
        if ((size + 1) > elements.length) {
            elements = Arrays.copyOf(elements, elements.length * 2);
        }
        elements[size] = v;
        size++;
    }

    int dequeue() {
        int res = -1;
        if (size > 0) {
            res = elements[0];
            for (int i = 1; i < size; i++) {
                elements[i - 1] = elements[i];
            }
            size--;
        }
        return res;
    }

    boolean empty() {
        return size == 0;
    }

    int getSize() {
        return size;
    }


}

public class WrappingTarget<Z> implements Target<Z> {
	protected final Target<Z> target;
	public WrappingTarget(Target<Z> target) {
		this.target = target;
	}

	@Override public void getSize(SizeReadyCallback cb) {
		target.getSize(cb);
	}

