public class EmirpNumbers {
    public static boolean isPrime(int number) {
        if (number <= 1) {
            return false;
        }
        for (int i = 2; i <= Math.sqrt(number); i++) {
            if (number % i == 0) {
                return false;
            }
        }
        return true;
    }

    public static int reverse(int number) {
        int reverse = 0;
        while (number != 0) {
            int digit = number % 10;
            reverse = reverse * 10 + digit;
            number /= 10;
        }
        return reverse;
    }

    public static boolean isEmirp(int number) {
        int reverse = reverse(number);
        return number != reverse && isPrime(number) && isPrime(reverse);
    }

    public static void main(String[] args) {
        int count = 0;
        int number = 13;
        while (count < 100) {
            if (isEmirp(number)) {
                System.out.print(number + " ");
                count++;
                if (count % 10 == 0) {
                    System.out.println();
                }
            }
            number++;
        }
    }
}

import java.util.ArrayList;
import java.util.List;

public class BinaryHeap<E extends Comparable<E>> {
    private List<E> heap;

    public BinaryHeap() {
        heap = new ArrayList<>();
    }

    public void insert(E key) {
        heap.add(key);
        int i = heap.size() - 1;
        while (i > 0 && heap.get((i - 1) / 2).compareTo(heap.get(i)) > 0) {
            E temp = heap.get(i);
            heap.set(i, heap.get((i - 1) / 2));
            heap.set((i - 1) / 2, temp);
            i = (i - 1) / 2;
        }
    }

    public E delete() {
        if (heap.isEmpty()) {
            throw new IllegalStateException("Heap is empty");
        }
        E result = heap.get(0);
        E last = heap.remove(heap.size() - 1);
        if (!heap.isEmpty()) {
            heap.set(0, last);
            int i = 0;
            while (true) {
                int leftChild = 2 * i + 1;
                int rightChild = 2 * i + 2;
                if (leftChild >= heap.size()) {
                    break;
                }
                int minChild = leftChild;
                if (rightChild < heap.size() && heap.get(rightChild).compareTo(heap.get(leftChild)) < 0) {
                    minChild = rightChild;
                }
                if (heap.get(i).compareTo(heap.get(minChild)) > 0) {
                    E temp = heap.get(i);
                    heap.set(i, heap.get(minChild));
                    heap.set(minChild, temp);
                    i = minChild;
                } else {
                    break;
                }
            }
        }
        return result;
    }

    public boolean isEmpty() {
        return heap.isEmpty();
    }
}

import java.util.Comparator;

public class BubbleSort {

    // Bubble sort using the Comparable interface
    public static <E extends Comparable<E>> void bubbleSort(E[] list) {
        boolean swapped = true;
        int lastUnsorted = list.length - 1;

        while (swapped) {
            swapped = false;
            for (int i = 0; i < lastUnsorted; i++) {
                if (list[i].compareTo(list[i+1]) > 0) {
                    E temp = list[i];
                    list[i] = list[i+1];
                    list[i+1] = temp;
                    swapped = true;
                }
            }
            lastUnsorted--;
        }
    }

    // Bubble sort using the Comparator interface
    public static <E> void bubbleSort(E[] list, Comparator<? super E> comparator) {
        boolean swapped = true;
        int lastUnsorted = list.length - 1;

        while (swapped) {
            swapped = false;
            for (int i = 0; i < lastUnsorted; i++) {
                if (comparator.compare(list[i], list[i+1]) > 0) {
                    E temp = list[i];
                    list[i] = list[i+1];
                    list[i+1] = temp;
                    swapped = true;
                }
            }
            lastUnsorted--;
        }
    }
}

import java.util.Arrays;

public class ClosestPair {

    public static Pair getClosestPair(double[][] points) {
        Arrays.sort(points, (a, b) -> Double.compare(a[0], b[0])); // sort the points by x-coordinate
        return getClosestPair(points, 0, points.length - 1);
    }

    private static Pair getClosestPair(double[][] points, int low, int high) {
        if (low >= high) { // base case: only one or two points
            return low == high ? null : new Pair(points[low], points[high]);
        }

        int mid = (low + high) / 2;
        Pair leftPair = getClosestPair(points, low, mid);
        Pair rightPair = getClosestPair(points, mid + 1, high);
        Pair minPair = (leftPair == null) ? rightPair
                : (rightPair == null) ? leftPair
                : (leftPair.getDistance() < rightPair.getDistance()) ? leftPair : rightPair;

        // find the closest pair that crosses the midline
        double midX = points[mid][0];
        double[] strip = new double[high - low + 1];
        int j = 0;
        for (int i = low; i <= high; i++) {
            if (Math.abs(points[i][0] - midX) < minPair.getDistance()) {
                strip[j++] = points[i][1];
            }
        }
        Arrays.sort(strip, 0, j);
        for (int i = 0; i < j; i++) {
            for (int k = i + 1; k < j && strip[k] - strip[i] < minPair.getDistance(); k++) {
                double[] p1 = {midX, strip[i]};
                double[] p2 = {midX, strip[k]};
                Pair crossPair = new Pair(p1, p2);
                if (crossPair.getDistance() < minPair.getDistance()) {
                    minPair = crossPair;
                }
            }
        }

        return minPair;
    }

    public static void main(String[] args) {
        double[][] points = {{2, 3}, {12, 30}, {40, 50}, {5, 1}, {12, 10}, {3, 4}};
        Pair closestPair = getClosestPair(points);
        System.out.println("The closest pair of points are " + Arrays.toString(closestPair.getP1()) 
                + " and " + Arrays.toString(closestPair.getP2()) + " with distance " + closestPair.getDistance());
    }
}

class Pair {
    private double[] p1;
    private double[] p2;

    public Pair(double[] p1, double[] p2) {
        this.p1 = p1;
        this.p2 = p2;
    }

    public double[] getP1() {
        return p1;
    }

    public double[] getP2() {
        return p2;
    }

    public double getDistance() {
        double dx = p1[0] - p2[0];
        double dy = p1[1] - p2[1];
        return Math.sqrt(dx * dx + dy * dy);
    }
}

public class ComparableCircle extends Circle implements Comparable<ComparableCircle> {

    public ComparableCircle(double radius) {
        super(radius);
    }

    @Override
    public int compareTo(ComparableCircle otherCircle) {
        if (getArea() > otherCircle.getArea()) {
            return 1;
        } else if (getArea() < otherCircle.getArea()) {
            return -1;
        } else {
            return 0;
        }
    }
}

import javafx.application.Application;
import javafx.scene.Scene;
import javafx.scene.layout.Pane;
import javafx.scene.paint.Color;
import javafx.scene.shape.Circle;
import javafx.scene.shape.Line;
import javafx.scene.text.Text;
import javafx.stage.Stage;

import java.util.Random;

public class CirclesAndLineExample extends Application {

    @Override
    public void start(Stage primaryStage) {
        // create a pane to hold the circles and line
        Pane pane = new Pane();

        // create a random number generator
        Random random = new Random();

        // create the first circle
        double centerX1 = random.nextDouble() * (pane.getWidth() - 30) + 15;
        double centerY1 = random.nextDouble() * (pane.getHeight() - 30) + 15;
        Circle circle1 = new Circle(centerX1, centerY1, 15);
        circle1.setFill(Color.RED);

        // create the second circle
        double centerX2 = random.nextDouble() * (pane.getWidth() - 30) + 15;
        double centerY2 = random.nextDouble() * (pane.getHeight() - 30) + 15;
        Circle circle2 = new Circle(centerX2, centerY2, 15);
        circle2.setFill(Color.BLUE);

        // create the line between the circles
        Line line = new Line(centerX1, centerY1, centerX2, centerY2);
        line.setStroke(Color.BLACK);
        line.setStrokeWidth(2.0);

        // calculate the distance between the centers of the circles
        double distance = Math.sqrt(Math.pow(centerX2 - centerX1, 2) + Math.pow(centerY2 - centerY1, 2));

        // create the text showing the distance between the centers
        Text distanceText = new Text((centerX1 + centerX2) / 2, (centerY1 + centerY2) / 2, String.format("%.2f", distance));
        distanceText.setFill(Color.BLACK);
        distanceText.setStroke(Color.WHITE);
        distanceText.setStrokeWidth(2.0);

        // add the circles, line, and text to the pane
        pane.getChildren().addAll(circle1, circle2, line, distanceText);

        // create a scene and add the pane to it
        Scene scene = new Scene(pane, 400, 300);

        // set the stage's title and scene, then show the stage
        primaryStage.setTitle("Circles and Line Example");
        primaryStage.setScene(scene);
        primaryStage.show();
    }

    public static void main(String[] args) {
        launch(args);
    }

}

import java.util.Scanner;

public class MonthDays {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);

        System.out.print("Enter the month (1-12): ");
        int month = input.nextInt();

        System.out.print("Enter the year: ");
        int year = input.nextInt();

        int days = 0;

        switch (month) {
            case 1:
            case 3:
            case 5:
            case 7:
            case 8:
            case 10:
            case 12:
                days = 31;
                break;
            case 4:
            case 6:
            case 9:
            case 11:
                days = 30;
                break;
            case 2:
                if ((year % 4 == 0 && year % 100 != 0) || (year % 400 == 0)) {
                    days = 29;
                } else {
                    days = 28;
                }
                break;
            default:
                System.out.println("Invalid month.");
                System.exit(1);
        }

        System.out.println(getMonthName(month) + " " + year + " had " + days + " days.");
    }

    public static String getMonthName(int month) {
        String monthName = "";
        switch (month) {
            case 1: monthName = "January"; break;
            case 2: monthName = "February"; break;
            case 3: monthName = "March"; break;
            case 4: monthName = "April"; break;
            case 5: monthName = "May"; break;
            case 6: monthName = "June"; break;
            case 7: monthName = "July"; break;
            case 8: monthName = "August"; break;
            case 9: monthName = "September"; break;
            case 10: monthName = "October"; break;
            case 11: monthName = "November"; break;
            case 12: monthName = "December"; break;
        }
        return monthName;
    }
}

public static double min(double[] array) {
    if (array == null || array.length == 0) {
        throw new IllegalArgumentException("Array must not be null or empty");
    }

    double min = array[0];
    for (int i = 1; i < array.length; i++) {
        if (array[i] < min) {
            min = array[i];
        }
    }

    return min;
}
