import java.io.*;
import java.net.Socket;

public class FTPClient {
    private static final String serverAddress = "ftp.example.com"; // replace with your FTP server address
    private static final int serverPort = 21; // default FTP port
    private static final String username = "yourusername"; // replace with your FTP username
    private static final String password = "yourpassword"; // replace with your FTP password

    public static void main(String[] args) throws Exception {
        Socket socket = new Socket(serverAddress, serverPort);

        BufferedReader input = new BufferedReader(new InputStreamReader(socket.getInputStream()));
        BufferedWriter output = new BufferedWriter(new OutputStreamWriter(socket.getOutputStream()));

        String response = input.readLine();
        if (!response.startsWith("220 ")) {
            throw new Exception("FTP server not ready");
        }

        output.write("USER " + username + "\r\n");
        output.flush();
        response = input.readLine();
        if (!response.startsWith("331 ")) {
            throw new Exception("Wrong username or password");
        }

        output.write("PASS " + password + "\r\n");
        output.flush();
        response = input.readLine();
        if (!response.startsWith("230 ")) {
            throw new Exception("Wrong username or password");
        }

        output.write("PWD\r\n");
        output.flush();
        response = input.readLine();
        if (!response.startsWith("257 ")) {
            throw new Exception("Could not determine current directory");
        }
        String currentDirectory = response.substring(4, response.length() - 1);

        output.write("QUIT\r\n");
        output.flush();

        socket.close();

        System.out.println("Current directory: " + currentDirectory);
    }
}

import java.util.*;

public class KnightsTour {
    private static int[][] board;
    private static int[] dx = {1, 2, 2, 1, -1, -2, -2, -1};
    private static int[] dy = {2, 1, -1, -2, -2, -1, 1, 2};

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        System.out.println("Enter the size of the board:");
        int n = sc.nextInt();

        board = new int[n][n];

        System.out.println("Enter the starting position:");
        int startX = sc.nextInt();
        int startY = sc.nextInt();

        if (solve(startX, startY, 1)) {
            System.out.println("The solution is:");
            printBoard();
        } else {
            System.out.println("No solution exists.");
        }
    }

    private static boolean solve(int x, int y, int move) {
        if (move == board.length * board.length + 1) {
            return true;
        }

        for (int i = 0; i < dx.length; i++) {
            int nextX = x + dx[i];
            int nextY = y + dy[i];

            if (isValid(nextX, nextY)) {
                board[nextX][nextY] = move;

                if (solve(nextX, nextY, move + 1)) {
                    return true;
                }

                board[nextX][nextY] = 0;
            }
        }

        return false;
    }

    private static boolean isValid(int x, int y) {
        return x >= 0 && x < board.length && y >= 0 && y < board.length && board[x][y] == 0;
    }

    private static void printBoard() {
        for (int i = 0; i < board.length; i++) {
            for (int j = 0; j < board.length; j++) {
                System.out.print(board[i][j] + " ");
            }
            System.out.println();
        }
    }
}

class SieveOfEratosthenes {
    void sieveOfEratosthenes(int n) {
        // Create a boolean array "prime[0..n]" and initialize
        // all entries it as true. A value in prime[i] will
        // finally be false if i is Not a prime, else true.
        boolean prime[] = new boolean[n+1];
        for(int i=0;i<n;i++)
            prime[i] = true;

        for(int p = 2; p*p <=n; p++) {
            // If prime[p] is not changed, then it is a prime
            if(prime[p] == true) {
                // Update all multiples of p
                for(int i = p*p; i <= n; i += p)
                    prime[i] = false;
            }
        }

        // Print all prime numbers
        for(int i = 2; i <= n; i++) {
            if(prime[i] == true)
                System.out.print(i + " ");
        }
    }

    // Driver Program to test above function
    public static void main(String args[]) {
        int n = 30;
        System.out.print("Following are the prime numbers smaller than or equal to " + n);
        SieveOfEratosthenes g = new SieveOfEratosthenes();
        g.sieveOfEratosthenes(n);
    }
}

import java.util.List;

public class NDCG {
    public static double calculateNDCG(List<Double> relevanceScores, List<Integer> ranking) {
        int size = relevanceScores.size();
        double dcg = 0;
        double idcg = calculateIDCG(relevanceScores);
        for (int i = 0; i < size; i++) {
            dcg += (Math.pow(2, relevanceScores.get(ranking.get(i))) - 1) / (Math.log(i + 2) / Math.log(2));
        }
        return dcg / idcg;
    }

    private static double calculateIDCG(List<Double> relevanceScores) {
        int size = relevanceScores.size();
        double idcg = 0;
        relevanceScores.sort((a, b) -> -Double.compare(a, b));
        for (int i = 0; i < size; i++) {
            idcg += (Math.pow(2, relevanceScores.get(i)) - 1) / (Math.log(i + 2) / Math.log(2));
        }
        return idcg;
    }
}

import java.util.LinkedList;
import java.util.ListIterator;

class HashTable {
    private LinkedList<Node>[] arr;
    private int size;

    public HashTable(int size) {
        this.size = size;
        arr = new LinkedList[size];
        for (int i = 0; i < size; i++) {
            arr[i] = new LinkedList<Node>();
        }
    }

    public void put(String key, String value) {
        int index = getIndex(key);
        LinkedList<Node> list = arr[index];
        ListIterator<Node> iterator = list.listIterator();
        while (iterator.hasNext()) {
            Node node = iterator.next();
            if (node.key.equals(key)) {
                node.value = value;
                return;
            }
        }
        list.add(new Node(key, value));
    }

    public String get(String key) {
        int index = getIndex(key);
        LinkedList<Node> list = arr[index];
        ListIterator<Node> iterator = list.listIterator();
        while (iterator.hasNext()) {
            Node node = iterator.next();
            if (node.key.equals(key)) {
                return node.value;
            }
        }
        return null;
    }

    public void remove(String key) {
        int index = getIndex(key);
        LinkedList<Node> list = arr[index];
        ListIterator<Node> iterator = list.listIterator();
        while (iterator.hasNext()) {
            Node node = iterator.next();
            if (node.key.equals(key)) {
                iterator.remove();
                return;
            }
        }
    }

    private int getIndex(String key) {
        int hashCode = key.hashCode();
        int index = hashCode % size;
        return index;
    }

    private class Node {
        String key;
        String value;

        public Node(String key, String value) {
            this.key = key;
            this.value = value;
        }
    }
}

