import java.util.List;
import java.util.ArrayList;
import java.util.Arrays;

public class CosineSimilarity {
    public static double cosineSimilarity(List<Double> vectorA, List<Double> vectorB) {
        double dotProduct = 0.0;
        double normA = 0.0;
        double normB = 0.0;
        for (int i = 0; i < vectorA.size(); i++) {
            dotProduct += vectorA.get(i) * vectorB.get(i);
            normA += Math.pow(vectorA.get(i), 2);
            normB += Math.pow(vectorB.get(i), 2);
        }
        return dotProduct / (Math.sqrt(normA) * Math.sqrt(normB));
    }

    public static void main(String[] args) {
        List<Double> vectorA = Arrays.asList(1.0, 2.0, 3.0);
        List<Double> vectorB = Arrays.asList(4.0, 5.0, 6.0);
        double similarity = cosineSimilarity(vectorA, vectorB);
        System.out.println("Cosine similarity: " + similarity);
    }
}

import java.util.concurrent.locks.Condition;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class ArrayBlockingQueue<T> {
    private final T[] buffer;
    private final int capacity;
    private int size;
    private int head;
    private int tail;
    private final Lock lock;
    private final Condition notEmpty;
    private final Condition notFull;

    public ArrayBlockingQueue(int capacity) {
        this.buffer = (T[]) new Object[capacity];
        this.capacity = capacity;
        this.size = 0;
        this.head = 0;
        this.tail = 0;
        this.lock = new ReentrantLock();
        this.notEmpty = lock.newCondition();
        this.notFull = lock.newCondition();
    }

    public void put(T element) throws InterruptedException {
        lock.lock();
        try {
            while (size == capacity) {
                notFull.await();
            }
            buffer[tail] = element;
            tail = (tail + 1) % capacity;
            size++;
            notEmpty.signal();
        } finally {
            lock.unlock();
        }
    }

    public T take() throws InterruptedException {
        lock.lock();
        try {
            while (size == 0) {
                notEmpty.await();
            }
            T element = buffer[head];
            head = (head + 1) % capacity;
            size--;
            notFull.signal();
            return element;
        } finally {
            lock.unlock();
        }
    }

    public int size() {
        lock.lock();
        try {
            return size;
        } finally {
            lock.unlock();
        }
    }
}


public static void main(String[] args) throws InterruptedException {
    ArrayBlockingQueue<String> queue = new ArrayBlockingQueue<>(10);
    queue.put("apple");
    queue.put("banana");
    queue.put("cherry");
    System.out.println(queue.take());
    System.out.println(queue.take());
    System.out.println(queue.take());
}

import java.util.ArrayList;
import java.util.Scanner;

public class LargestRowsColumns {

    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        System.out.print("Enter the array size n: ");
        int n = input.nextInt();

        int[][] matrix = new int[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                matrix[i][j] = (int)(Math.random() * 2);
            }
        }

        // Print the matrix
        System.out.println("The random array is");
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                System.out.print(matrix[i][j]);
            }
            System.out.println();
        }

        // Find the largest rows
        ArrayList<Integer> largestRows = new ArrayList<>();
        int maxRowCount = 0;
        for (int i = 0; i < n; i++) {
            int rowCount = 0;
            for (int j = 0; j < n; j++) {
                if (matrix[i][j] == 1) {
                    rowCount++;
                }
            }
            if (rowCount > maxRowCount) {
                maxRowCount = rowCount;
                largestRows.clear();
                largestRows.add(i);
            } else if (rowCount == maxRowCount) {
                largestRows.add(i);
            }
        }

        // Find the largest columns
        ArrayList<Integer> largestColumns = new ArrayList<>();
        int maxColumnCount = 0;
        for (int j = 0; j < n; j++) {
            int columnCount = 0;
            for (int i = 0; i < n; i++) {
                if (matrix[i][j] == 1) {
                    columnCount++;
                }
            }
            if (columnCount > maxColumnCount) {
                maxColumnCount = columnCount;
                largestColumns.clear();
                largestColumns.add(j);
            } else if (columnCount == maxColumnCount) {
                largestColumns.add(j);
            }
        }

        // Print the results
        System.out.print("The largest row index: ");
        for (int i = 0; i < largestRows.size(); i++) {
            System.out.print(largestRows.get(i) + " ");
        }
        System.out.println();
        System.out.print("The largest column index: ");
        for (int i = 0; i < largestColumns.size(); i++) {
            System.out.print(largestColumns.get(i) + " ");
        }
        System.out.println();
    }

}

import javafx.application.Application;
import javafx.scene.Scene;
import javafx.scene.layout.Pane;
import javafx.scene.paint.Color;
import javafx.scene.shape.Circle;
import javafx.scene.input.KeyCode;
import javafx.stage.Stage;

public class CircleMove extends Application {

    private Circle circle;
    private double dx = 0;
    private double dy = 0;

    @Override
    public void start(Stage primaryStage) {
        // Create a circle with radius 50 at the center of the pane
        circle = new Circle(150, 150, 50);
        circle.setFill(Color.RED);

        // Add the circle to a pane
        Pane pane = new Pane(circle);

        // Create a scene
        Scene scene = new Scene(pane, 300, 300);

        // Add an event handler to move the circle when the arrow keys are pressed
        scene.setOnKeyPressed(event -> {
            KeyCode keyCode = event.getCode();
            if (keyCode == KeyCode.UP) {
                dy -= 5;
            } else if (keyCode == KeyCode.DOWN) {
                dy += 5;
            } else if (keyCode == KeyCode.LEFT) {
                dx -= 5;
            } else if (keyCode == KeyCode.RIGHT) {
                dx += 5;
            }
        });

        // Add an event handler to update the position of the circle
        scene.setOnKeyReleased(event -> {
            KeyCode keyCode = event.getCode();
            if (keyCode == KeyCode.UP) {
                dy = 0;
            } else if (keyCode == KeyCode.DOWN) {
                dy = 0;
            } else if (keyCode == KeyCode.LEFT) {
                dx = 0;
            } else if (keyCode == KeyCode.RIGHT) {
                dx = 0;
            }
        });

        // Update the position of the circle every frame
        javafx.animation.AnimationTimer timer = new javafx.animation.AnimationTimer() {
            @Override
            public void handle(long now) {
                circle.setCenterX(circle.getCenterX() + dx);
                circle.setCenterY(circle.getCenterY() + dy);
            }
        };
        timer.start();

        // Set the scene and show the stage
        primaryStage.setScene(scene);
        primaryStage.setTitle("Circle Move");
        primaryStage.show();

        // Request focus on the scene so that it can receive key events
        scene.requestFocus();
    }

    public static void main(String[] args) {
        launch(args);
    }
}

import java.util.HashSet;
import java.util.Set;

public class DocumentSimilarity {
    public static double jaccardSimilarity(String doc1, String doc2) {
        Set<String> set1 = new HashSet<>();
        Set<String> set2 = new HashSet<>();

        for (String word : doc1.split(" ")) {
            set1.add(word);
        }

        for (String word : doc2.split(" ")) {
            set2.add(word);
        }

        Set<String> union = new HashSet<>(set1);
        union.addAll(set2);

        Set<String> intersection = new HashSet<>(set1);
        intersection.retainAll(set2);

        return (double) intersection.size() / (double) union.size();
    }

    public static void main(String[] args) {
        String doc1 = "This is the first document";
        String doc2 = "This is the second document";

        double similarity = jaccardSimilarity(doc1, doc2);
        System.out.println("Similarity: " + similarity);
    }
}

public static double[][] sortColumns(double[][] m) {
    double[][] sortedM = new double[m.length][m[0].length];

    // Copy the original array to a new array
    for (int i = 0; i < m.length; i++) {
        for (int j = 0; j < m[0].length; j++) {
            sortedM[i][j] = m[i][j];
        }
    }

    // Sort the columns in ascending order
    for (int j = 0; j < sortedM[0].length; j++) {
        for (int i = 0; i < sortedM.length - 1; i++) {
            double min = sortedM[i][j];
            int minIndex = i;

            for (int k = i + 1; k < sortedM.length; k++) {
                if (sortedM[k][j] < min) {
                    min = sortedM[k][j];
                    minIndex = k;
                }
            }

            if (minIndex != i) {
                for (int k = 0; k < sortedM[0].length; k++) {
                    double temp = sortedM[i][k];
                    sortedM[i][k] = sortedM[minIndex][k];
                    sortedM[minIndex][k] = temp;
                }
            }
        }
    }

    return sortedM;
}

