  public MyLinkedList(E[] objects) {
    super(objects);
  }

  /** Return the last element in the list */
  public E getLast() {
    if (size == 0) {
      return null;
    } else {
      return tail.element;
    }
  }

  /** Return true if this list contains the element e */
  public boolean contains(E e) {
    Node<E> current = head;
    while (current != null) {
      if (e.equals(current.element)) {
        return true;
      }
      current = current.next;
    }
    return false;
  }

  /** Return the element from this list at the specified index */
  public E get(int index) {
    checkIndex(index);
    Node<E> current = head;
    for (int i = 0; i < index; i++) {
      current = current.next;
    }
    return current.element;
  }

  /** Return the index of the first matching element in this list.
   * Return -1 if no match. */
  public int indexOf(E e) {
    Node<E> current = head;
    for (int i = 0; i < size; i++) {
      if (e.equals(current.element)) {
        return i;
      }
      current = current.next;
    }
    return -1;
  }

  /** Return the index of the last matching element in this list.
   * Return -1 if no match. */
  public int lastIndexOf(E e) {
    Node<E> current = tail;
    for (int i = size - 1; i >= 0; i--) {
      if (e.equals(current.element)) {
        return i;
      }
      current = current.previous;
    }
    return -1;
  }

  /** Replace the element at the specified position in this list
   * with the specified element and return the old element. */
  public E set(int index, E e) {
    checkIndex(index);
    Node<E> current = head;
    for (int i = 0; i < index; i++) {
      current = current.next;
    }
    E oldElement = current.element;
    current.element = e;
    return oldElement;
  }

  /** Node class */
  private static class Node<E> {
    E element;
    Node<E> next;
    Node<E> previous;

    public Node(E element) {
      this.element = element;
    }
  }

}

import java.util.Scanner;

public class TriangleConstructor {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        System.out.print("Enter the length of side 1: ");
        double side1 = input.nextDouble();
        System.out.print("Enter the length of side 2: ");
        double side2 = input.nextDouble();
        System.out.print("Enter the length of side 3: ");
        double side3 = input.nextDouble();

        if (isValidTriangle(side1, side2, side3)) {
            double perimeter = side1 + side2 + side3;
            double semiPerimeter = perimeter / 2;
            double area = Math.sqrt(semiPerimeter * (semiPerimeter - side1) * (semiPerimeter - side2) * (semiPerimeter - side3));
            System.out.printf("Perimeter: %.2f%n", perimeter);
            System.out.printf("Area: %.2f%n", area);
            System.out.println("The triangle is valid.");
        } else {
            System.out.println("The sides entered do not form a valid triangle.");
        }
    }

    public static boolean isValidTriangle(double side1, double side2, double side3) {
        return side1 + side2 > side3 && side2 + side3 > side1 && side1 + side3 > side2;
    }
}

import java.util.Scanner;

public class IntersectingPoint {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);

        // Prompt the user to enter the endpoints of the line segments
        System.out.print("Enter x1, y1, x2, y2, x3, y3, x4, y4: ");
        double x1 = input.nextDouble();
        double y1 = input.nextDouble();
        double x2 = input.nextDouble();
        double y2 = input.nextDouble();
        double x3 = input.nextDouble();
        double y3 = input.nextDouble();
        double x4 = input.nextDouble();
        double y4 = input.nextDouble();

        // Create a LinearEquation object
        LinearEquation eq = new LinearEquation(y1 - y2, x2 - x1, y3 - y4, x4 - x3, (y1 - y2) * x1 - (x1 - x2) * y1, (y3 - y4) * x3 - (x3 - x4) * y3);

        // Check if the lines are parallel
        if (eq.isSolvable()) {
            // Display the intersecting point
            System.out.println("The intersecting point is (" + eq.getX() + ", " + eq.getY() + ")");
        } else {
            System.out.println("The two lines are parallel");
        }
    }
}

public class Occurrence {
    public static int count(String word, String sentence) {
        int count = 0;
        int index = 0;
        while (index >= 0) {
            index = sentence.indexOf(word, index);
            if (index >= 0) {
                count++;
                index++;
            }
        }
        return count;
    }

    public static void main(String[] args) {
        String sentence = "This is a test. This is a TEST.";
        String word = "is";
        int count = count(word, sentence);
        System.out.println("The word " + word + " appears " + count + " times in the sentence.");
    }
}

