import java.util.concurrent.ConcurrentHashMap;

public class ConcurrentHashMapExample {
    public static void main(String[] args) {
        // create a new ConcurrentHashMap instance
        ConcurrentHashMap<Integer, String> myMap = new ConcurrentHashMap<Integer, String>();

        // add some elements to the map
        myMap.put(1, "apple");
        myMap.put(2, "banana");
        myMap.put(3, "cherry");

        // print the contents of the map
        System.out.println("Initial Map: " + myMap);

        // add an element at a specific key
        myMap.put(4, "orange");
        System.out.println("Map after adding 'orange' at key 4: " + myMap);

        // remove an element at a specific key
        myMap.remove(2);
        System.out.println("Map after removing element at key 2: " + myMap);

        // get the element at a specific key
        String element = myMap.get(1);
        System.out.println("Element at key 1: " + element);

        // get the size of the map
        int size = myMap.size();
        System.out.println("Size of Map: " + size);
    }
}

import javafx.application.Application;
import javafx.geometry.Pos;
import javafx.scene.Scene;
import javafx.scene.control.Label;
import javafx.scene.control.TextField;
import javafx.scene.layout.HBox;
import javafx.scene.layout.VBox;
import javafx.stage.Stage;

public class MilesKilometersConverter extends Application {

    private TextField milesField;
    private TextField kilometersField;

    @Override
    public void start(Stage primaryStage) {
        // Create the input fields for miles and kilometers
        milesField = new TextField();
        kilometersField = new TextField();

        // Set the event handlers for when the user presses Enter in the input fields
        milesField.setOnAction(e -> convertMilesToKilometers());
        kilometersField.setOnAction(e -> convertKilometersToMiles());

        // Create labels for the input fields
        Label milesLabel = new Label("Miles:");
        Label kilometersLabel = new Label("Kilometers:");

        // Create a layout for the input fields and labels
        HBox inputBox = new HBox(10, milesLabel, milesField, kilometersLabel, kilometersField);
        inputBox.setAlignment(Pos.CENTER);

        // Create the main layout of the scene
        VBox root = new VBox(20, inputBox);
        root.setAlignment(Pos.CENTER);

        // Set the scene and show the stage
        Scene scene = new Scene(root, 400, 200);
        primaryStage.setTitle("Miles/Kilometers Converter");
        primaryStage.setScene(scene);
        primaryStage.show();
    }

    private void convertMilesToKilometers() {
        try {
            // Get the value from the miles input field and convert it to kilometers
            double miles = Double.parseDouble(milesField.getText());
            double kilometers = miles * 1.609344;

            // Update the kilometers input field with the converted value
            kilometersField.setText(String.format("%.2f", kilometers));
        } catch (NumberFormatException e) {
            // Handle invalid input (e.g. non-numeric values)
            kilometersField.setText("Invalid input");
        }
    }

    private void convertKilometersToMiles() {
        try {
            // Get the value from the kilometers input field and convert it to miles
            double kilometers = Double.parseDouble(kilometersField.getText());
            double miles = kilometers / 1.609344;

            // Update the miles input field with the converted value
            milesField.setText(String.format("%.2f", miles));
        } catch (NumberFormatException e) {
            // Handle invalid input (e.g. non-numeric values)
            milesField.setText("Invalid input");
        }
    }

    public static void main(String[] args) {
        launch(args);
    }
}

public class MatrixMultiplication {
    public static void main(String[] args) {
        int[][] firstMatrix = { {1, 2, 3}, {4, 5, 6}, {7, 8, 9} };
        int[][] secondMatrix = { {9, 8, 7}, {6, 5, 4}, {3, 2, 1} };
        int[][] resultMatrix = new int[firstMatrix.length][secondMatrix[0].length];

        for (int i = 0; i < resultMatrix.length; i++) {
            for (int j = 0; j < resultMatrix[i].length; j++) {
                for (int k = 0; k < firstMatrix[0].length; k++) {
                    resultMatrix[i][j] += firstMatrix[i][k] * secondMatrix[k][j];
                }
            }
        }

        System.out.println("The result of matrix multiplication is: ");
        for (int[] row : resultMatrix) {
            for (int element : row) {
                System.out.print(element + " ");
            }
            System.out.println();
        }
    }
}

public class BMI {
   private String name;
   private int age;
   private double weight; // in pounds
   private double height; // in inches
   private double feet; // in feet
   private double inches; // in inches

   public BMI(String name, int age, double weight, double height) {
      this.name = name;
      this.age = age;
      this.weight = weight;
      this.height = height;
   }

   public BMI(String name, int age, double weight, double feet, double inches) {
      this.name = name;
      this.age = age;
      this.weight = weight;
      this.feet = feet;
      this.inches = inches;
      this.height = (feet * 12) + inches;
   }

   public double getBMI() {
      double bmi = weight / Math.pow(height, 2) * 703;
      return Math.round(bmi * 100) / 100.0;
   }

   public String getStatus() {
      double bmi = getBMI();
      if (bmi < 18.5)
         return "Underweight";
      else if (bmi < 25)
         return "Normal";
      else if (bmi < 30)
         return "Overweight";
      else
         return "Obese";
   }

   public String getName() {
      return name;
   }

   public int getAge() {
      return age;
   }

   public double getWeight() {
      return weight;
   }

   public double getHeight() {
      return height;
   }

   public double getFeet() {
      return feet;
   }

   public double getInches() {
      return inches;
   }
}

import java.util.ArrayList;
import java.util.Scanner;

public class RepeatAdditionQuiz {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        ArrayList<Integer> answers = new ArrayList<>();
        int num1 = (int)(Math.random() * 10);
        int num2 = (int)(Math.random() * 10);
        System.out.print("What is " + num1 + " + " + num2 + "? ");
        int answer = input.nextInt();
        while (num1 + num2 != answer) {
            if (answers.contains(answer)) {
                System.out.println("You already entered " + answer);
            } else {
                System.out.print("Wrong answer. Try again. What is " + num1 + " + " + num2 + "? ");
                answers.add(answer);
            }
            answer = input.nextInt();
        }
        System.out.println("You got it!");
    }
}

import java.util.Scanner;

public class PayrollStatement {
   public static void main(String[] args) {
      Scanner input = new Scanner(System.in);

      // Prompt user to input employee information
      System.out.print("Enter employee's name: ");
      String name = input.nextLine();

      System.out.print("Enter number of hours worked in a week: ");
      double hoursWorked = input.nextDouble();

      System.out.print("Enter hourly pay rate: ");
      double hourlyPayRate = input.nextDouble();

      System.out.print("Enter federal tax withholding rate (%): ");
      double federalTaxRate = input.nextDouble();

      System.out.print("Enter state tax withholding rate (%): ");
      double stateTaxRate = input.nextDouble();

      // Calculate gross pay, federal withholding, state withholding, and net pay
      double grossPay = hoursWorked * hourlyPayRate;
      double federalWithholding = grossPay * (federalTaxRate / 100);
      double stateWithholding = grossPay * (stateTaxRate / 100);
      double totalDeduction = federalWithholding + stateWithholding;
      double netPay = grossPay - totalDeduction;

      // Print payroll statement
      System.out.println("Employee Name: " + name);
      System.out.println("Hours Worked: " + hoursWorked);
      System.out.println("Pay Rate: $" + hourlyPayRate);
      System.out.println("Gross Pay: $" + grossPay);
      System.out.println("Deductions:");
      System.out.printf("\tFederal Withholding (%.1f%%): $%.2f\n", federalTaxRate, federalWithholding);
      System.out.printf("\tState Withholding (%.1f%%): $%.2f\n", stateTaxRate, stateWithholding);
      System.out.printf("\tTotal Deduction: $%.2f\n", totalDeduction);
      System.out.println("Net Pay: $" + netPay);
   }
}

public class DrawingPanel extends JPanel {
    private boolean filled;
    private String shape;

    public DrawingPanel() {
        this.filled = false;
        this.shape = "none";
    }

    public void setFilled(boolean filled) {
        this.filled = filled;
    }

    public void setShape(String shape) {
        this.shape = shape;
    }

    @Override
    protected void paintComponent(Graphics g) {
        super.paintComponent(g);
        if (shape.equals("square")) {
            int x = 50;
            int y = 50;
            int size = 100;
            g.drawRect(x, y, size, size);
            if (filled) {
                g.fillRect(x, y, size, size);
            }
        } else if (shape.equals("circle")) {
            int x = 100;
            int y = 100;
            int size = 100;
            g.drawOval(x, y, size, size);
            if (filled) {
                g.fillOval(x, y, size, size);
            }
        } else if (shape.equals("triangle")) {
            int[] xPoints = {50, 100, 150};
            int[] yPoints = {150, 50, 150};
            int nPoints = 3;
            g.drawPolygon(xPoints, yPoints, nPoints);
            if (filled) {
                g.fillPolygon(xPoints, yPoints, nPoints);
            }
        }
    }
}

public class MyLinkedList<E> implements MyList<E> {

    private Node<E> head;
    private Node<E> tail;
    private int size;

    private static class Node<E> {
        E element;
        Node<E> next;

        public Node(E element) {
            this.element = element;
        }
    }

    public MyLinkedList() {
    }

    public MyLinkedList(E[] elements) {
        for (E element : elements) {
            add(element);
        }
    }

    public E getLast() {
        if (size == 0) {
            return null;
        } else {
            return tail.element;
        }
    }

    @Override
    public boolean contains(E e) {
        Node<E> current = head;
        while (current != null) {
            if (e.equals(current.element)) {
                return true;
            }
            current = current.next;
        }
        return false;
    }

    @Override
    public E get(int index) {
        if (index < 0 || index >= size) {
            throw new IndexOutOfBoundsException("Index: " + index + ", Size: " + size);
        }
        Node<E> current = head;
        for (int i = 0; i < index; i++) {
            current = current.next;
        }
        return current.element;
    }

    @Override
    public int indexOf(E e) {
        Node<E> current = head;
        for (int i = 0; i < size; i++) {
            if (e.equals(current.element)) {
                return i;
            }
            current = current.next;
        }
        return -1;
    }

    @Override
    public int lastIndexOf(E e) {
        Node<E> current = head;
        int lastIndex = -1;
        for (int i = 0; i < size; i++) {
            if (e.equals(current.element)) {
                lastIndex = i;
            }
            current = current.next;
        }
        return lastIndex;
    }

    @Override
    public E set(int index, E e) {
        if (index < 0 || index >= size) {
            throw new IndexOutOfBoundsException("Index: " + index + ", Size: " + size);
        }
        Node<E> current = head;
        for (int i = 0; i < index; i++) {
            current = current.next;
        }
        E oldElement = current.element;
        current.element = e;
        return oldElement;
    }

    // Other methods from MyList interface

}

import java.util.Scanner;

public class MyTriangle {
    public static boolean isValid(double side1, double side2, double side3) {
        return side1 + side2 > side3 && side1 + side3 > side2 && side2 + side3 > side1;
    }

    public static double area(double side1, double side2, double side3) {
        double s = (side1 + side2 + side3) / 2;
        return Math.sqrt(s * (s - side1) * (s - side2) * (s - side3));
    }

    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);

        System.out.print("Enter three sides of a triangle: ");
        double side1 = input.nextDouble();
        double side2 = input.nextDouble();
        double side3 = input.nextDouble();

        if (isValid(side1, side2, side3)) {
            double area = area(side1, side2, side3);
            System.out.println("The area of the triangle is " + area);
        } else {
            System.out.println("Invalid input. The sum of any two sides must be greater than the third side.");
        }
    }
}

import java.util.Scanner;

public class Cylinder {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);

        System.out.print("Enter the radius of the cylinder: ");
        double radius = input.nextDouble();

        System.out.print("Enter the length of the cylinder: ");
        double length = input.nextDouble();

        double area = radius * radius * Math.PI;
        double volume = area * length;

        System.out.printf("The area of the cylinder is %.2f%n", area);
        System.out.printf("The volume of the cylinder is %.2f%n", volume);
    }
}

import javafx.application.Application;
import javafx.scene.Scene;
import javafx.scene.layout.Pane;
import javafx.scene.paint.Color;
import javafx.scene.shape.Circle;
import javafx.scene.shape.Line;
import javafx.scene.text.Font;
import javafx.scene.text.Text;
import javafx.stage.Stage;

public class TwoCircles extends Application {

    private double distance;
    private Circle circle1, circle2;
    private Line line;
    private Text distanceText;

    @Override
    public void start(Stage primaryStage) {

        // Initialize the circles and line
        circle1 = new Circle(40, 40, 10, Color.BLUE);
        circle2 = new Circle(120, 150, 10, Color.BLUE);
        line = new Line(circle1.getCenterX(), circle1.getCenterY(), circle2.getCenterX(), circle2.getCenterY());
        line.setStroke(Color.RED);

        // Calculate the initial distance and create the distance text
        distance = calculateDistance();
        distanceText = new Text(distance / 2, distance / 2, String.format("%.2f", distance));
        distanceText.setFont(new Font(20));

        // Add event handlers to allow circles to be dragged
        circle1.setOnMouseDragged(event -> {
            circle1.setCenterX(event.getX());
            circle1.setCenterY(event.getY());
            updateLineAndDistance();
        });
        circle2.setOnMouseDragged(event -> {
            circle2.setCenterX(event.getX());
            circle2.setCenterY(event.getY());
            updateLineAndDistance();
        });

        // Create the pane and add the circles, line, and distance text
        Pane pane = new Pane();
        pane.getChildren().addAll(circle1, circle2, line, distanceText);

        // Create the scene and show the stage
        Scene scene = new Scene(pane, 300, 300);
        primaryStage.setScene(scene);
        primaryStage.setTitle("Two Circles");
        primaryStage.show();
    }

    // Calculates the distance between the two circles
    private double calculateDistance() {
        double dx = circle1.getCenterX() - circle2.getCenterX();
        double dy = circle1.getCenterY() - circle2.getCenterY();
        return Math.sqrt(dx * dx + dy * dy);
    }

    // Updates the line and distance text
    private void updateLineAndDistance() {
        line.setStartX(circle1.getCenterX());
        line.setStartY(circle1.getCenterY());
        line.setEndX(circle2.getCenterX());
        line.setEndY(circle2.getCenterY());
        distance = calculateDistance();
        distanceText.setX((circle1.getCenterX() + circle2.getCenterX()) / 2 - 15);
        distanceText.setY((circle1.getCenterY() + circle2.getCenterY()) / 2 + 15);
        distanceText.setText(String.format("%.2f", distance));
    }

    public static void main(String[] args) {
        launch(args);
    }
}

import java.util.*;

public class Point implements Comparable<Point> {
    private int x;
    private int y;

    public Point(int x, int y) {
        this.x = x;
        this.y = y;
    }

    public int getX() {
        return x;
    }

    public int getY() {
        return y;
    }

    @Override
    public int compareTo(Point other) {
        if (this.x == other.x) {
            return Integer.compare(this.y, other.y);
        }
        return Integer.compare(this.x, other.x);
    }

    public static class CompareY implements Comparator<Point> {
        @Override
        public int compare(Point p1, Point p2) {
            if (p1.getY() == p2.getY()) {
                return Integer.compare(p1.getX(), p2.getX());
            }
            return Integer.compare(p1.getY(), p2.getY());
        }
    }

    public static void main(String[] args) {
        // Create 100 random points
        List<Point> points = new ArrayList<>();
        Random random = new Random();
        for (int i = 0; i < 100; i++) {
            points.add(new Point(random.nextInt(100), random.nextInt(100)));
        }

        // Sort the points by x-coordinates
        Collections.sort(points);
        System.out.println("Sorted by x-coordinates:");
        for (Point p : points) {
            System.out.println("(" + p.getX() + ", " + p.getY() + ")");
        }

        // Sort the points by y-coordinates
        Collections.sort(points, new CompareY());
        System.out.println("\nSorted by y-coordinates:");
        for (Point p : points) {
            System.out.println("(" + p.getX() + ", " + p.getY() + ")");
        }
    }
}

public class BinarySearchExample {
    public static int binarySearch(int[] arr, int key) {
        int low = 0;
        int high = arr.length - 1;
        while (low <= high) {
            int mid = (low + high) / 2;
            if (arr[mid] == key) {
                return mid;
            } else if (arr[mid] < key) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return -1;
    }

    public static void main(String[] args) {
        int[] arr = { 2, 3, 4, 10, 40 };
        int key = 10;
        int index = binarySearch(arr, key);
        if (index == -1) {
            System.out.println("Element not present in the array");
        } else {
            System.out.println("Element found at index " + index);
        }
    }
}

import java.util.Scanner;

public class LetterToNumber {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter a letter: ");
        char letter = scanner.nextLine().toUpperCase().charAt(0);

        int number = getNumberFromLetter(letter);

        if (number != -1) {
            System.out.println("The corresponding number for " + letter + " is " + number);
        } else {
            System.out.println(letter + " is not a letter.");
        }
    }

    public static int getNumberFromLetter(char letter) {
        switch (letter) {
            case 'A': case 'B': case 'C': return 2;
            case 'D': case 'E': case 'F': return 3;
            case 'G': case 'H': case 'I': return 4;
            case 'J': case 'K': case 'L': return 5;
            case 'M': case 'N': case 'O': return 6;
            case 'P': case 'Q': case 'R': case 'S': return 7;
            case 'T': case 'U': case 'V': return 8;
            case 'W': case 'X': case 'Y': case 'Z': return 9;
            default: return -1;
        }
    }
}

import java.util.Scanner;

public class IdenticalArrays {

    public static boolean areIdentical(int[] list1, int[] list2) {
        if (list1.length != list2.length) {
            return false;
        }
        for (int i = 0; i < list1.length; i++) {
            if (list1[i] != list2[i]) {
                return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);

        System.out.print("Enter list1: ");
        int n1 = input.nextInt();
        int[] list1 = new int[n1];
        for (int i = 0; i < n1; i++) {
            list1[i] = input.nextInt();
        }

        System.out.print("Enter list2: ");
        int n2 = input.nextInt();
        int[] list2 = new int[n2];
        for (int i = 0; i < n2; i++) {
            list2[i] = input.nextInt();
        }

        if (areIdentical(list1, list2)) {
            System.out.println("Two lists are strictly identical");
        } else {
            System.out.println("Two lists are not strictly identical");
        }
    }
}

import java.util.Scanner;

public class DecimalToFraction {

    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);

        System.out.print("Enter a decimal number: ");
        String decimal = input.next();

        int integerPart = Integer.parseInt(decimal.split("\\.")[0]);
        String fractionalPart = decimal.split("\\.")[1];
        int denominator = (int) Math.pow(10, fractionalPart.length());
        int numerator = Integer.parseInt(fractionalPart) + integerPart * denominator;

        int gcd = gcd(numerator, denominator);
        numerator /= gcd;
        denominator /= gcd;

        System.out.println(decimal + " = " + numerator + "/" + denominator);
    }

    private static int gcd(int a, int b) {
        if (b == 0) {
            return a;
        }
        return gcd(b, a % b);
    }
}

