class Node {
    int data;
    Node left, right;

    public Node(int data) {
        this.data = data;
        this.left = null;
        this.right = null;
    }
}

class BinaryTree {
    Node root;

    public BinaryTree() {
        this.root = null;
    }

    public boolean isFullBinaryTree(Node node) {
        // If the tree is empty, it is a full binary tree
        if (node == null) {
            return true;
        }

        // If both the left and right subtrees are null, it is a leaf node
        if (node.left == null && node.right == null) {
            return true;
        }

        // If either the left or right subtree is null, it is not a full binary tree
        if (node.left == null || node.right == null) {
            return false;
        }

        // Recursively check if both the left and right subtrees are full binary trees
        return isFullBinaryTree(node.left) && isFullBinaryTree(node.right);
    }

    public static void main(String[] args) {
        BinaryTree tree = new BinaryTree();
        tree.root = new Node(1);
        tree.root.left = new Node(2);
        tree.root.right = new Node(3);
        tree.root.left.left = new Node(4);
        tree.root.left.right = new Node(5);
        tree.root.right.left = new Node(6);
        tree.root.right.right = new Node(7);

        if (tree.isFullBinaryTree(tree.root)) {
            System.out.println("The tree is a full binary tree.");
        } else {
            System.out.println("The tree is not a full binary tree.");
        }
    }
}

import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

import org.tartarus.snowball.ext.PorterStemmer;
import org.tartarus.snowball.ext.englishStemmer;

import opennlp.tools.stemmer.PorterStemmerAlgorithm;
import opennlp.tools.tokenize.SimpleTokenizer;

public class DocumentSimilarity {
    public static double jaccardSimilarity(String doc1, String doc2) {
        Set<String> set1 = new HashSet<>();
        Set<String> set2 = new HashSet<>();

        Set<String> stopWords = getStopWords();

        // Tokenize the documents
        String[] tokens1 = SimpleTokenizer.INSTANCE.tokenize(doc1);
        String[] tokens2 = SimpleTokenizer.INSTANCE.tokenize(doc2);

        // Perform stemming
        englishStemmer stemmer = new englishStemmer();

        for (String token : tokens1) {
            // Remove stop words
            if (stopWords.contains(token)) {
                continue;
            }

            // Stem the token
            stemmer.setCurrent(token);
            stemmer.stem();
            set1.add(stemmer.getCurrent());
        }

        for (String token : tokens2) {
            // Remove stop words
            if (stopWords.contains(token)) {
                continue;
            }

            // Stem the token
            stemmer.setCurrent(token);
            stemmer.stem();
            set2.add(stemmer.getCurrent());
        }

        Set<String> union = new HashSet<>(set1);
        union.addAll(set2);

        Set<String> intersection = new HashSet<>(set1);
        intersection.retainAll(set2);

        return (double) intersection.size() / (double) union.size();
    }

    private static Set<String> getStopWords() {
        Set<String> stopWords = new HashSet<>();
        try {
            List<String> lines = Files.readAllLines(Paths.get(new File("src/main/resources/stopwords.txt").toURI()));
            for (String line : lines) {
                stopWords.add(line);
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
        return stopWords;
    }

    public static void main(String[] args) {
        String doc1 = "This is the first document";
        String doc2 = "This is the second document";

        double similarity = jaccardSimilarity(doc1, doc2);
        System.out.println("Similarity: " + similarity);
    }
}

public class LineIntersectionTest {
    public static void main(String[] args) {
        // Define the first line
        double x1 = 1.0;
        double y1 = 1.0;
        double x2 = 5.0;
        double y2 = 5.0;

        // Define the second line
        double x3 = 1.0;
        double y3 = 5.0;
        double x4 = 5.0;
        double y4 = 1.0;

        // Calculate the slopes and y-intercepts of the two lines
        double slope1 = (y2 - y1) / (x2 - x1);
        double yIntercept1 = y1 - slope1 * x1;

        double slope2 = (y4 - y3) / (x4 - x3);
        double yIntercept2 = y3 - slope2 * x3;

        // Check whether the two lines are parallel
        if (slope1 == slope2) {
            System.out.println("The two lines are parallel and do not intersect.");
        } else {
            // Calculate the point of intersection
            double xIntersect = (yIntercept2 - yIntercept1) / (slope1 - slope2);
            double yIntersect = slope1 * xIntersect + yIntercept1;

            // Check whether the point of intersection lies on both lines
            if (xIntersect >= Math.min(x1, x2) && xIntersect <= Math.max(x1, x2) &&
                yIntersect >= Math.min(y1, y2) && yIntersect <= Math.max(y1, y2) &&
                xIntersect >= Math.min(x3, x4) && xIntersect <= Math.max(x3, x4) &&
                yIntersect >= Math.min(y3, y4) && yIntersect <= Math.max(y3, y4)) {
                System.out.println("The two lines intersect at (" + xIntersect + ", " + yIntersect + ").");
            } else {
                System.out.println("The two lines do not intersect.");
            }
        }
    }
}

