public static int gcd(int... numbers) {
    int result = numbers[0];
    for (int i = 1; i < numbers.length; i++) {
        result = gcd(result, numbers[i]);
    }
    return result;
}

private static int gcd(int a, int b) {
    if (b == 0) {
        return a;
    }
    return gcd(b, a % b);
}

public static int hex2Dec(String hexString) throws NumberFormatException {
    // Check that the input string is not null or empty
    if (hexString == null || hexString.isEmpty()) {
        throw new NumberFormatException("Input string is null or empty");
    }

    // Check that the input string contains only hexadecimal digits
    for (int i = 0; i < hexString.length(); i++) {
        char c = hexString.charAt(i);
        if (!Character.isDigit(c) && !("ABCDEFabcdef".indexOf(c) >= 0)) {
            throw new NumberFormatException("Input string is not a hex string");
        }
    }

    // Convert the input string to decimal
    int decimal = 0;
    for (int i = 0; i < hexString.length(); i++) {
        char c = hexString.charAt(i);
        int digit = Character.digit(c, 16);
        decimal = decimal * 16 + digit;
    }

    return decimal;
}

import java.awt.Point;

public class CirclePointTest {

    public static void main(String[] args) {
        Point center = new Point(0, 0); // center of the circle
        int radius = 5; // radius of the circle
        Point testPoint = new Point(3, 4); // point to test

        if (isInsideCircle(center, radius, testPoint)) {
            System.out.println("The point is inside the circle.");
        } else {
            System.out.println("The point is outside the circle.");
        }
    }

    public static boolean isInsideCircle(Point center, int radius, Point testPoint) {
        int distanceSquared = (testPoint.x - center.x) * (testPoint.x - center.x)
                            + (testPoint.y - center.y) * (testPoint.y - center.y);
        return distanceSquared < radius * radius;
    }
}

