        System.out.print("Enter point 2 (latitude and longitude) in degrees: ");
        double x2 = input.nextDouble();
        double y2 = input.nextDouble();

        double radius = 6371.01; // average earth radius in km

        // convert degrees to radians
        double x1Radians = Math.toRadians(x1);
        double y1Radians = Math.toRadians(y1);
        double x2Radians = Math.toRadians(x2);
        double y2Radians = Math.toRadians(y2);

        // calculate great circle distance
        double distance = radius * Math.acos(Math.sin(x1Radians) * Math.sin(x2Radians)
                + Math.cos(x1Radians) * Math.cos(x2Radians) * Math.cos(y1Radians - y2Radians));

        System.out.println("The distance between the two points is " + distance + " km.");
    }
}

import java.util.Scanner;

public class Quadratic {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter the coefficients a, b, and c: ");
        double a = sc.nextDouble();
        double b = sc.nextDouble();
        double c = sc.nextDouble();

        double discriminant = b * b - 4 * a * c;
        double root1, root2;

        if (discriminant > 0) {
            root1 = (-b + Math.sqrt(discriminant)) / (2 * a);
            root2 = (-b - Math.sqrt(discriminant)) / (2 * a);
            System.out.println("The roots are " + root1 + " and " + root2);
        } else if (discriminant == 0) {
            root1 = root2 = -b / (2 * a);
            System.out.println("The root is " + root1);
        } else {
            double realPart = -b / (2 * a);
            double imaginaryPart = Math.sqrt(-discriminant) / (2 * a);
            System.out.println("The roots are " + realPart + " + " + imaginaryPart + "i and " + realPart + " - " + imaginaryPart + "i");
        }
    }
}

public static <E extends Comparable<E>> void sort(ArrayList<E> list) {
    quickSort(list, 0, list.size() - 1);
}

private static <E extends Comparable<E>> void quickSort(ArrayList<E> list, int left, int right) {
    if (left < right) {
        int pivotIndex = partition(list, left, right);
        quickSort(list, left, pivotIndex - 1);
        quickSort(list, pivotIndex + 1, right);
    }
}

private static <E extends Comparable<E>> int partition(ArrayList<E> list, int left, int right) {
    E pivot = list.get(right);
    int i = left - 1;
    for (int j = left; j < right; j++) {
        if (list.get(j).compareTo(pivot) <= 0) {
            i++;
            swap(list, i, j);
        }
    }
    swap(list, i + 1, right);
    return i + 1;
}

private static <E> void swap(ArrayList<E> list, int i, int j) {
    E temp = list.get(i);
    list.set(i, list.get(j));
    list.set(j, temp);
}

