import java.util.Comparator;

public class OrderChecker {

    public static boolean ordered(int[] list) {
        return ordered(list, true);
    }

    public static boolean ordered(int[] list, boolean ascending) {
        if (ascending) {
            for (int i = 0; i < list.length - 1; i++) {
                if (list[i] > list[i+1]) {
                    return false;
                }
            }
        } else {
            for (int i = 0; i < list.length - 1; i++) {
                if (list[i] < list[i+1]) {
                    return false;
                }
            }
        }
        return true;
    }

    public static boolean ordered(double[] list) {
        return ordered(list, true);
    }

    public static boolean ordered(double[] list, boolean ascending) {
        if (ascending) {
            for (int i = 0; i < list.length - 1; i++) {
                if (list[i] > list[i+1]) {
                    return false;
                }
            }
        } else {
            for (int i = 0; i < list.length - 1; i++) {
                if (list[i] < list[i+1]) {
                    return false;
                }
            }
        }
        return true;
    }

    public static <E extends Comparable<E>> boolean ordered(E[] list) {
        return ordered(list, true);
    }

    public static <E extends Comparable<E>> boolean ordered(E[] list, boolean ascending) {
        if (ascending) {
            for (int i = 0; i < list.length - 1; i++) {
                if (list[i].compareTo(list[i+1]) > 0) {
                    return false;
                }
            }
        } else {
            for (int i = 0; i < list.length - 1; i++) {
                if (list[i].compareTo(list[i+1]) < 0) {
                    return false;
                }
            }
        }
        return true;
    }

    public static <E> boolean ordered(E[] list, Comparator<? super E> comparator) {
        return ordered(list, comparator, true);
    }

    public static <E> boolean ordered(E[] list, Comparator<? super E> comparator, boolean ascending) {
        if (ascending) {
            for (int i = 0; i < list.length - 1; i++) {
                if (comparator.compare(list[i], list[i+1]) > 0) {
                    return false;
                }
            }
        } else {
            for (int i = 0; i < list.length - 1; i++) {
                if (comparator.compare(list[i], list[i+1]) < 0) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.util.*;

public class PolygonAreaSlicker {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        System.out.print("Enter the number of vertices in the polygon: ");
        int n = sc.nextInt();

        double[] x = new double[n];
        double[] y = new double[n];

        System.out.println("Enter the x and y coordinates of the vertices:");
        for (int i = 0; i < n; i++) {
            System.out.print("Vertex " + (i+1) + ": ");
            x[i] = sc.nextDouble();
            y[i] = sc.nextDouble();
        }

        double area = calculateArea(x, y, n);

        System.out.println("The area of the polygon is " + area);
    }

    private static double calculateArea(double[] x, double[] y, int n) {
        double area = 0.0;

        for (int i = 0; i < n; i++) {
            int j = (i + 1) % n;
            area += x[i] * y[j] - x[j] * y[i];
        }

        area = Math.abs(area) / 2.0;

        return area;
    }
}

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class CollaborativeFilteringRecommender {

    private int[][] ratings;
    private Map<Integer, List<Integer>> userToItems;

    public CollaborativeFilteringRecommender(int[][] ratings) {
        this.ratings = ratings;
        this.userToItems = new HashMap<>();
        for (int i = 0; i < ratings.length; i++) {
            List<Integer> items = new ArrayList<>();
            for (int j = 0; j < ratings[i].length; j++) {
                if (ratings[i][j] > 0) {
                    items.add(j);
                }
            }
            userToItems.put(i, items);
        }
    }

    public List<Integer> recommend(int user, int k) {
        List<Integer> similarUsers = findSimilarUsers(user, k);
        Map<Integer, Double> itemToScore = new HashMap<>();
        for (int i : userToItems.get(user)) {
            double sum = 0.0;
            double count = 0.0;
            for (int j : similarUsers) {
                if (userToItems.get(j).contains(i)) {
                    sum += ratings[j][i];
                    count += 1.0;
                }
            }
            if (count > 0.0) {
                itemToScore.put(i, sum / count);
            }
        }
        List<Integer> recommendations = new ArrayList<>();
        for (int i = 0; i < ratings[user].length; i++) {
            if (ratings[user][i] == 0 && itemToScore.containsKey(i)) {
                recommendations.add(i);
            }
        }
        recommendations.sort((i1, i2) -> Double.compare(itemToScore.get(i2), itemToScore.get(i1)));
        return recommendations;
    }

    private List<Integer> findSimilarUsers(int user, int k) {
        List<Integer> similarUsers = new ArrayList<>();
        double[] similarities = new double[ratings.length];
        for (int i = 0; i < ratings.length; i++) {
            if (i != user) {
                similarities[i] = cosineSimilarity(ratings[user], ratings[i]);
            }
        }
        for (int i = 0; i < k; i++) {
            int maxIndex = -1;
            double maxSimilarity = -1.0;
            for (int j = 0; j < similarities.length; j++) {
                if (similarities[j] > maxSimilarity) {
                    maxIndex = j;
                    maxSimilarity = similarities[j];
                }
            }
            similarUsers.add(maxIndex);
            similarities[maxIndex] = -1.0;
        }
        return similarUsers;
    }

    private double cosineSimilarity(int[] v1, int[] v2) {
        double dotProduct = 0.0;
        double norm1 = 0.0;
        double norm2 = 0.0;
        for (int i = 0; i < v1.length; i++) {
            dotProduct += v1[i] * v2[i];
            norm1 += v1[i] * v1[i];
            norm2 += v2[i] * v2[i];
        }
        return dotProduct / (Math.sqrt(norm1) * Math.sqrt(norm2));
    }
}

import java.util.Scanner;

public class PalindromeTester {
    public static int reverse(int number) {
        int reverse = 0;

        while (number != 0) {
            reverse = reverse * 10 + number % 10;
            number /= 10;
        }

        return reverse;
    }

    public static boolean isPalindrome(int number) {
        int reverse = reverse(number);

        return (number == reverse);
    }

    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);

        System.out.print("Enter an integer: ");
        int number = input.nextInt();

        if (isPalindrome(number)) {
            System.out.println(number + " is a palindrome");
        } else {
            System.out.println(number + " is not a palindrome");
        }
    }
}

