public class MyStringBuilder2 {
    private char[] value;
    private int count;

    public MyStringBuilder2() {
        value = new char[16];
    }

    public MyStringBuilder2(char[] chars) {
        value = chars;
        count = chars.length;
    }

    public MyStringBuilder2(String s) {
        value = s.toCharArray();
        count = s.length();
    }

    public MyStringBuilder2 insert(int offset, MyStringBuilder2 s) {
        if (offset < 0 || offset > count) {
            throw new StringIndexOutOfBoundsException(offset);
        }
        int len = s.length();
        ensureCapacity(count + len);
        System.arraycopy(value, offset, value, offset + len, count - offset);
        System.arraycopy(s.value, 0, value, offset, len);
        count += len;
        return this;
    }

    public MyStringBuilder2 reverse() {
        for (int i = 0, j = count - 1; i < j; i++, j--) {
            char temp = value[i];
            value[i] = value[j];
            value[j] = temp;
        }
        return this;
    }

    public MyStringBuilder2 substring(int begin) {
        return substring(begin, count);
    }

    public MyStringBuilder2 substring(int begin, int end) {
        if (begin < 0 || begin > end || end > count) {
            throw new StringIndexOutOfBoundsException();
        }
        int len = end - begin;
        char[] newvalue = new char[len];
        System.arraycopy(value, begin, newvalue, 0, len);
        return new MyStringBuilder2(newvalue);
    }

    public MyStringBuilder2 toUpperCase() {
        for (int i = 0; i < count; i++) {
            value[i] = Character.toUpperCase(value[i]);
        }
        return this;
    }

    private void ensureCapacity(int minimumCapacity) {
        if (minimumCapacity > value.length) {
            expandCapacity(minimumCapacity);
        }
    }

    private void expandCapacity(int minimumCapacity) {
        int newCapacity = value.length * 2 + 2;
        if (newCapacity < minimumCapacity) {
            newCapacity = minimumCapacity;
        }
        char[] newValue = new char[newCapacity];
        System.arraycopy(value, 0, newValue, 0, count);
        value = newValue;
    }

    public int length() {
        return count;
    }

    public char charAt(int index) {
        if (index < 0 || index >= count) {
            throw new StringIndexOutOfBoundsException(index);
        }
        return value[index];
    }

    public String toString() {
        return new String(value, 0, count);
    }
}

public static void main(String[] args) {
    try {
        // Check that there are three command-line arguments
        if (args.length != 3) {
            throw new IllegalArgumentException("Usage: java Calculator operand1 operator operand2");
        }

        // Parse the operands as doubles
        double operand1 = Double.parseDouble(args[0]);
        double operand2 = Double.parseDouble(args[2]);

        // Perform the operation based on the operator
        double result = 0;
        switch (args[1]) {
            case "+":
                result = operand1 + operand2;
                break;
            case "-":
                result = operand1 - operand2;
                break;
            case "*":
                result = operand1 * operand2;
                break;
            case "/":
                result = operand1 / operand2;
                break;
            default:
                throw new IllegalArgumentException("Invalid operator: " + args[1]);
        }

        // Print the result
        System.out.println(args[0] + " " + args[1] + " " + args[2] + " = " + result);
    } catch (NumberFormatException e) {
        System.err.println("Error: non-numeric operand");
        System.exit(1);
    } catch (IllegalArgumentException e) {
        System.err.println(e.getMessage());
        System.exit(1);
    }
}

private static void processOperator(Stack<Integer> operandStack, Stack<Character> operatorStack) {
    char op = operatorStack.pop();
    int op1 = operandStack.pop();
    int op2 = operandStack.pop();
    if (op == '+') {
        operandStack.push(op2 + op1);
    } else if (op == '-') {
        operandStack.push(op2 - op1);
    } else if (op == '*') {
        operandStack.push(op2 * op1);
    } else if (op == '/') {
        if (op1 == 0) {
            System.out.println("Error: division by zero");
            return;
        }
        operandStack.push(op2 / op1);
    }
}

