import javafx.application.Application;
import javafx.scene.Scene;
import javafx.scene.layout.Pane;
import javafx.scene.paint.Color;
import javafx.scene.shape.Circle;
import javafx.scene.input.KeyCode;
import javafx.stage.Stage;

public class CircleMove extends Application {

    @Override
    public void start(Stage primaryStage) {

        // Create a circle with radius 50 at the center of the pane
        Circle circle = new Circle(150, 150, 50);
        circle.setFill(Color.RED);

        // Add an event handler to move the circle when the arrow keys are pressed
        circle.setOnKeyPressed(event -> {
            KeyCode keyCode = event.getCode();
            if (keyCode == KeyCode.UP) {
                circle.setCenterY(circle.getCenterY() - 10);
            } else if (keyCode == KeyCode.DOWN) {
                circle.setCenterY(circle.getCenterY() + 10);
            } else if (keyCode == KeyCode.LEFT) {
                circle.setCenterX(circle.getCenterX() - 10);
            } else if (keyCode == KeyCode.RIGHT) {
                circle.setCenterX(circle.getCenterX() + 10);
            }
        });

        // Set the focus to the circle so that it can receive key events
        circle.requestFocus();

        // Create the pane and add the circle
        Pane pane = new Pane();
        pane.getChildren().add(circle);

        // Create the scene and show the stage
        Scene scene = new Scene(pane, 300, 300);
        primaryStage.setScene(scene);
        primaryStage.setTitle("Circle Move");
        primaryStage.show();
    }

    public static void main(String[] args) {
        launch(args);
    }
}

import java.util.Scanner;

public class SmallestFactors {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);

        // Prompt the user to enter an integer
        System.out.print("Enter an integer: ");
        int number = input.nextInt();

        // Find and display the smallest factors
        System.out.print("The smallest factors of " + number + " are: ");
        int factor = 2;
        while (factor <= number) {
            if (number % factor == 0) {
                System.out.print(factor + " ");
                number /= factor;
            } else {
                factor++;
            }
        }
    }
}

public static int[] locateLargest(double[][] a) {
    int[] result = {0, 0};
    double max = a[0][0];
    for (int i = 0; i < a.length; i++) {
        for (int j = 0; j < a[i].length; j++) {
            if (a[i][j] > max) {
                max = a[i][j];
                result[0] = i;
                result[1] = j;
            }
        }
    }
    return result;
}

import java.util.Scanner;
import java.util.Stack;

class Node {
    int val;
    Node left;
    Node right;

    public Node(int val) {
        this.val = val;
        left = null;
        right = null;
    }
}

class BST {
    Node root;

    public void insert(int val) {
        root = insert(root, val);
    }

    private Node insert(Node node, int val) {
        if (node == null) {
            return new Node(val);
        }
        if (val < node.val) {
            node.left = insert(node.left, val);
        } else if (val > node.val) {
            node.right = insert(node.right, val);
        }
        return node;
    }

    public void inorder() {
        if (root == null) {
            return;
        }
        Stack<Node> stack = new Stack<>();
        Node current = root;
        while (current != null || !stack.isEmpty()) {
            while (current != null) {
                stack.push(current);
                current = current.left;
            }
            current = stack.pop();
            System.out.print(current.val + " ");
            current = current.right;
        }
    }
}

