import org.apache.http.client.HttpClient;
import org.apache.http.client.methods.HttpPost;
import org.apache.http.entity.ContentType;
import org.apache.http.entity.mime.MultipartEntityBuilder;
import org.apache.http.entity.mime.content.FileBody;
import org.apache.http.entity.mime.content.StringBody;
import org.apache.http.impl.client.HttpClients;

public class FileUploader {
    public static void main(String[] args) {
        String url = "http://example.com/upload";
        String filePath = "/path/to/file.txt";
        String fileName = "file.txt";

        try {
            HttpClient httpClient = HttpClients.createDefault();
            HttpPost httpPost = new HttpPost(url);

            FileBody fileBody = new FileBody(new File(filePath), ContentType.DEFAULT_BINARY);
            StringBody fileNameBody = new StringBody(fileName, ContentType.DEFAULT_BINARY);

            MultipartEntityBuilder builder = MultipartEntityBuilder.create();
            builder.addPart("file", fileBody);
            builder.addPart("fileName", fileNameBody);
            HttpEntity entity = builder.build();

            httpPost.setEntity(entity);

            HttpResponse response = httpClient.execute(httpPost);
            HttpEntity responseEntity = response.getEntity();

            if (responseEntity != null) {
                InputStream inputStream = responseEntity.getContent();
                try {
                    // process the input stream
                } finally {
                    inputStream.close();
                }
            }

        } catch (ClientProtocolException e) {
            Logger.getLogger(FileUploader.class.getName()).log(Level.SEVERE, null, e);
        } catch (IOException e) {
            Logger.getLogger(FileUploader.class.getName()).log(Level.SEVERE, null, e);
        }
    }
}

public class Series {
    public static void main(String[] args) {
        for (int i = 1; i <= 10; i++) {
            System.out.println("m(" + i + ") = " + computeM(i));
        }
    }

    public static double computeM(int i) {
        if (i == 1) {
            return 1.0/3;
        } else {
            return i/(2.0*i + 1) + computeM(i - 1);
        }
    }
}

public class MyString2 {
    private char[] chars;

    public MyString2(String s) {
        chars = new char[s.length()];
        for (int i = 0; i < s.length(); i++) {
            chars[i] = s.charAt(i);
        }
    }

    public int compare(String s) {
        int len1 = chars.length;
        int len2 = s.length();
        int minLen = Math.min(len1, len2);

        for (int i = 0; i < minLen; i++) {
            if (chars[i] != s.charAt(i)) {
                return chars[i] - s.charAt(i);
            }
        }

        return len1 - len2;
    }

    public MyString2 substring(int begin) {
        int length = chars.length - begin;
        char[] newChars = new char[length];
        for (int i = 0; i < length; i++) {
            newChars[i] = chars[begin + i];
        }
        return new MyString2(new String(newChars));
    }

    public MyString2 toUpperCase() {
        int length = chars.length;
        char[] newChars = new char[length];
        for (int i = 0; i < length; i++) {
            char c = chars[i];
            if (c >= 'a' && c <= 'z') {
                c = (char) (c - 'a' + 'A');
            }
            newChars[i] = c;
        }
        return new MyString2(new String(newChars));
    }

    public char[] toChars() {
        char[] copyChars = new char[chars.length];
        System.arraycopy(chars, 0, copyChars, 0, chars.length);
        return copyChars;
    }

    public static MyString2 valueOf(boolean b) {
        if (b) {
            return new MyString2("true");
        } else {
            return new MyString2("false");
        }
    }
}

import java.util.ArrayList;
import java.util.List;

public class xQuAD {
    public static List<Integer> reRank(List<Double> relevanceScores, List<Double> popularityScores, double lambda) {
        int size = relevanceScores.size();
        List<Integer> ranking = new ArrayList<>();
        for (int i = 0; i < size; i++) {
            ranking.add(i);
        }
        ranking.sort((a, b) -> -Double.compare(lambda * relevanceScores.get(a) + (1 - lambda) * popularityScores.get(a),
                lambda * relevanceScores.get(b) + (1 - lambda) * popularityScores.get(b)));
        return ranking;
    }
}

import java.util.Arrays;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        List<Double> relevanceScores = Arrays.asList(0.8, 0.7, 0.9, 0.6);
        List<Double> popularityScores = Arrays.asList(0.2, 0.1, 0.3, 0.4);
        double lambda = 0.8;
        List<Integer> ranking = xQuAD.reRank(relevanceScores, popularityScores, lambda);
        System.out.println("New ranking: " + ranking);
    }
}


