        double xDistance = Math.abs(r.getX() - this.x);
        double yDistance = Math.abs(r.getY() - this.y);
        return xDistance <= (width + r.getWidth()) / 2 &&
                yDistance <= (height + r.getHeight()) / 2;
    }

