            }
            if (allZerosOrOnes) {
                System.out.printf("All %ds on column %d\n", matrix[0][j], j + 1);
            }
        }

        // check major diagonal
        allZerosOrOnes = true;
        for (int i = 1; i < n; i++) {
            if (matrix[i][i] != matrix[0][0]) {
                allZerosOrOnes = false;
                break;
            }
        }
        if (allZerosOrOnes) {
            System.out.printf("All %ds on the major diagonal\n", matrix[0][0]);
        }

        // check sub-diagonal
        allZerosOrOnes = true;
        for (int i = 1; i < n; i++) {
            if (matrix[i][n - i - 1] != matrix[0][n - 1]) {
                allZerosOrOnes = false;
                break;
            }
        }
        if (allZerosOrOnes) {
            System.out.printf("All %ds on the sub-diagonal\n", matrix[0][n - 1]);
        }
    }

    public static void printMatrix(int[][] matrix) {
        for (int[] row : matrix) {
            for (int cell : row) {
                System.out.print(cell);
            }
            System.out.println();
        }
    }
}

import java.util.Scanner;

public class PentagonalCoordinates {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        System.out.print("Enter the radius of the bounding circle: ");
        double radius = input.nextDouble();

        double angle = Math.toRadians(18); // 18 degrees is the angle between two adjacent vertices
        double x, y;
        System.out.println("The coordinates of five points on the pentagon are");
        for (int i = 0; i < 5; i++) {
            x = radius * Math.sin(i * angle);
            y = radius * Math.cos(i * angle);
            System.out.printf("(%.4f, %.4f)\n", x, y);
        }
    }
}

import javafx.application.Application;
import javafx.geometry.Insets;
import javafx.geometry.Pos;
import javafx.scene.Scene;
import javafx.scene.control.Button;
import javafx.scene.control.Label;
import javafx.scene.control.TextField;
import javafx.scene.layout.GridPane;
import javafx.scene.layout.HBox;
import javafx.scene.text.Font;
import javafx.stage.Stage;

public class InvestmentValueCalculator extends Application {

    private TextField investmentAmountField;
    private TextField yearsField;
    private TextField annualInterestRateField;
    private TextField futureValueField;

    @Override
    public void start(Stage primaryStage) throws Exception {
        // Create labels and text fields
        Label investmentAmountLabel = new Label("Investment Amount:");
        investmentAmountField = new TextField();
        investmentAmountField.setPromptText("Enter investment amount");

        Label yearsLabel = new Label("Number of Years:");
        yearsField = new TextField();
        yearsField.setPromptText("Enter number of years");

        Label annualInterestRateLabel = new Label("Annual Interest Rate:");
        annualInterestRateField = new TextField();
        annualInterestRateField.setPromptText("Enter annual interest rate");

        Label futureValueLabel = new Label("Future Value:");
        futureValueField = new TextField();
        futureValueField.setEditable(false);

        // Create Calculate button
        Button calculateButton = new Button("Calculate");
        calculateButton.setOnAction(e -> calculateFutureValue());

        // Create grid pane and add labels and text fields
        GridPane gridPane = new GridPane();
        gridPane.setAlignment(Pos.CENTER);
        gridPane.setHgap(10);
        gridPane.setVgap(10);
        gridPane.setPadding(new Insets(10));
        gridPane.add(investmentAmountLabel, 0, 0);
        gridPane.add(investmentAmountField, 1, 0);
        gridPane.add(yearsLabel, 0, 1);
        gridPane.add(yearsField, 1, 1);
        gridPane.add(annualInterestRateLabel, 0, 2);
        gridPane.add(annualInterestRateField, 1, 2);
        gridPane.add(futureValueLabel, 0, 3);
        gridPane.add(futureValueField, 1, 3);

        // Create HBox for button
        HBox hbox = new HBox(calculateButton);
        hbox.setAlignment(Pos.CENTER);

        // Create scene and add grid pane and HBox to it
        Scene scene = new Scene(new HBox(gridPane), 400, 200);
        primaryStage.setScene(scene);
        primaryStage.setTitle("Investment Value Calculator");
        primaryStage.show();
    }

    private void calculateFutureValue() {
        // Parse values from text fields
        double investmentAmount = Double.parseDouble(investmentAmountField.getText());
        int years = Integer.parseInt(yearsField.getText());
        double annualInterestRate = Double.parseDouble(annualInterestRateField.getText()) / 100;

        // Calculate future value
        double monthlyInterestRate = annualInterestRate / 12;
        double futureValue = investmentAmount * Math.pow(1 + monthlyInterestRate, years * 12);

        // Set future value text field
        futureValueField.setText(String.format("$%.2f", futureValue));
    }

    public static void main(String[] args) {
        launch(args);
    }
}

import java.util.Scanner;

public class SubstringTest {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);

        System.out.print("Enter a string s1: ");
        String s1 = input.nextLine();

        System.out.print("Enter a string s2: ");
        String s2 = input.nextLine();

        int index = findSubstringIndex(s1, s2);
        if (index == -1) {
            System.out.println("s2 is not a substring of s1");
        } else {
            System.out.println("matched at index " + index);
        }
    }

    public static int findSubstringIndex(String s1, String s2) {
        int s1Length = s1.length();
        int s2Length = s2.length();
        for (int i = 0; i <= s1Length - s2Length; i++) {
            int j;
            for (j = 0; j < s2Length; j++) {
                if (s1.charAt(i + j) != s2.charAt(j)) {
                    break;
                }
            }
            if (j == s2Length) {
                return i;
            }
        }
        return -1;
    }
}

import java.util.ArrayList;
import java.util.HashMap;

public class ContextAwareRecommender {
    // Store user preferences
    private HashMap<String, ArrayList<String>> userPreferences;

    // Store context information
    private HashMap<String, String> context;

    public ContextAwareRecommender() {
        userPreferences = new HashMap<>();
        context = new HashMap<>();
    }

    public void addUserPreference(String user, String preference) {
        ArrayList<String> preferences = userPreferences.get(user);
        if (preferences == null) {
            preferences = new ArrayList<>();
            userPreferences.put(user, preferences);
        }
        preferences.add(preference);
    }

    public void setContext(String key, String value) {
        context.put(key, value);
    }

    public ArrayList<String> getRecommendations(String user) {
        ArrayList<String> recommendations = new ArrayList<>();

        // Get user preferences
        ArrayList<String> preferences = userPreferences.get(user);
        if (preferences == null) {
            return recommendations;
        }

        // Get current context
        String location = context.get("location");
        String timeOfDay = context.get("timeOfDay");
        String activity = context.get("activity");

        // Use context to filter recommendations
        for (String preference : preferences) {
            if (location != null && preference.contains(location)) {
                recommendations.add(preference);
            }
            if (timeOfDay != null && preference.contains(timeOfDay)) {
                recommendations.add(preference);
            }
            if (activity != null && preference.contains(activity)) {
                recommendations.add(preference);
            }
        }

        return recommendations;
    }
}

