class BinomialCoefficient {
    public static int binomialCoefficient(int n, int k) {
        if (k == 0 || k == n) {
            return 1;
        }
        return binomialCoefficient(n - 1, k - 1) + binomialCoefficient(n - 1, k);
    }

    public static void main(String[] args) {
        int n = 5;
        int k = 2;
        System.out.println("C(" + n + ", " + k + ") = " + binomialCoefficient(n, k));
    }
}

import java.util.Scanner;

public class LoanCalculator {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);

        // Prompt the user to enter the loan amount and loan period
        System.out.print("Loan Amount: ");
        double loanAmount = input.nextDouble();
        System.out.print("Number of Years: ");
        int numberOfYears = input.nextInt();

        // Display the table header
        System.out.printf("%-15s%-15s%-15s\n", "Interest Rate", "Monthly Payment", "Total Payment");

        // Compute and display the monthly and total payments for each interest rate
        for (double annualInterestRate = 5.0; annualInterestRate <= 8.0; annualInterestRate += 0.125) {
            double monthlyInterestRate = annualInterestRate / 1200.0;
            double monthlyPayment = loanAmount * monthlyInterestRate / (1 - 1 / Math.pow(1 + monthlyInterestRate, numberOfYears * 12));
            double totalPayment = monthlyPayment * numberOfYears * 12;

            // Display the results for the current interest rate
            System.out.printf("%-15.3f%-15.2f%-15.2f\n", annualInterestRate, monthlyPayment, totalPayment);
        }
    }
}

import java.util.Scanner;

public class LoanAmortizationSchedule {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);

        // Get loan details from user
        System.out.print("Loan Amount: ");
        double loanAmount = input.nextDouble();

        System.out.print("Number of Years: ");
        int numberOfYears = input.nextInt();

        System.out.print("Annual Interest Rate: ");
        double annualInterestRate = input.nextDouble();

        // Calculate monthly interest rate
        double monthlyInterestRate = annualInterestRate / 1200;

        // Calculate monthly payment and total payment
        double monthlyPayment = loanAmount * monthlyInterestRate /
                (1 - 1 / Math.pow(1 + monthlyInterestRate, numberOfYears * 12));
        double totalPayment = monthlyPayment * numberOfYears * 12;

        // Display monthly payment and total payment
        System.out.printf("Monthly Payment: %.2f\n", monthlyPayment);
        System.out.printf("Total Payment: %.2f\n", totalPayment);

        // Display amortization schedule
        System.out.println("Payment#\tInterest\tPrincipal\tBalance");
        double balance = loanAmount;
        for (int i = 1; i <= numberOfYears * 12; i++) {
            double interest = monthlyInterestRate * balance;
            double principal = monthlyPayment - interest;
            balance -= principal;

            System.out.printf("%-10d\t%-10.2f\t%-10.2f\t%.2f\n", i, interest, principal, balance);

            // Check if balance is zero or negative
            if (balance <= 0) {
                // If balance is negative, add it to the last payment
                if (balance < 0) {
                    monthlyPayment += balance;
                    totalPayment = monthlyPayment * i;
                }
                break;
            }
        }

        // Display last payment if balance is not zero
        if (balance > 0) {
            System.out.printf("%-10d\t%-10.2f\t%-10.2f\t0.00\n", numberOfYears * 12, monthlyInterestRate * balance, balance);
        }
    }
}

public class Tax {
    private int filingStatus;
    private int[][] brackets;
    private double[] rates;
    private double taxableIncome;

    public static final int SINGLE_FILER = 0;
    public static final int MARRIED_JOINTLY_OR_QUALIFYING_WIDOW = 1;
    public static final int MARRIED_SEPARATELY = 2;
    public static final int HEAD_OF_HOUSEHOLD = 3;

    public Tax() {
    }

    public Tax(int filingStatus, int[][] brackets, double[] rates, double taxableIncome) {
        this.filingStatus = filingStatus;
        this.brackets = brackets;
        this.rates = rates;
        this.taxableIncome = taxableIncome;
    }

    public int getFilingStatus() {
        return filingStatus;
    }

    public void setFilingStatus(int filingStatus) {
        this.filingStatus = filingStatus;
    }

    public int[][] getBrackets() {
        return brackets;
    }

    public void setBrackets(int[][] brackets) {
        this.brackets = brackets;
    }

    public double[] getRates() {
        return rates;
    }

    public void setRates(double[] rates) {
        this.rates = rates;
    }

    public double getTaxableIncome() {
        return taxableIncome;
    }

    public void setTaxableIncome(double taxableIncome) {
        this.taxableIncome = taxableIncome;
    }

    public double getTax() {
        double tax = 0.0;
        int i;
        for (i = 0; i < brackets[filingStatus].length; i++) {
            if (taxableIncome <= brackets[filingStatus][i]) {
                break;
            }
        }
        if (i == 0) {
            tax = taxableIncome * rates[i];
        } else {
            tax = brackets[filingStatus][i - 1] * rates[i - 1];
            tax += (taxableIncome - brackets[filingStatus][i - 1]) * rates[i];
        }
        return tax;
    }
}

 public static double computeCommission(double salesAmount) {
    double commission = 0;
    if (salesAmount <= 5000) {
        commission = salesAmount * 0.08;
    } else if (salesAmount <= 10000) {
        commission = 5000 * 0.08 + (salesAmount - 5000) * 0.1;
    } else {
        commission = 5000 * 0.08 + 5000 * 0.1 + (salesAmount - 10000) * 0.12;
    }
    return commission;
}

public static void main(String[] args) {
    System.out.println("Sales Amount Commission");
    for (int i = 10000; i <= 100000; i += 5000) {
        System.out.printf("%-10d%-10.1f\n", i, computeCommission(i));
    }
}

import java.io.File;
import java.io.FileNotFoundException;
import java.util.Scanner;

public class BabyNameRanking {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);

        // Prompt the user to enter the year, gender, and name
        System.out.print("Enter the year (2001-2010): ");
        int year = input.nextInt();
        System.out.print("Enter the gender (M/F): ");
        char gender = input.next().charAt(0);
        System.out.print("Enter the name: ");
        String name = input.next();

        // Read the corresponding file
        String filename = "babynameranking" + year + ".txt";
        File file = new File(filename);
        try {
            Scanner fileInput = new Scanner(file);

            // Search for the name and print the ranking
            int rank = 0;
            while (fileInput.hasNextLine()) {
                String line = fileInput.nextLine();
                rank++;
                if (gender == 'M') {
                    if (line.contains(name + " ")) {
                        System.out.println(name + " is ranked #" + rank + " in year " + year + ".");
                        return;
                    }
                } else if (gender == 'F') {
                    if (line.contains(" " + name + " ")) {
                        System.out.println(name + " is ranked #" + rank + " in year " + year + ".");
                        return;
                    }
                }
            }
            System.out.println("The name " + name + " is not ranked in year " + year + ".");
        } catch (FileNotFoundException e) {
            System.out.println("File " + filename + " not found.");
        }
    }
}

