public class Time {
    private int hour;
    private int minute;
    private int second;

    public Time() {
        this(System.currentTimeMillis());
    }

    public Time(long elapsedTime) {
        setTime(elapsedTime);
    }

    public Time(int hour, int minute, int second) {
        this.hour = hour;
        this.minute = minute;
        this.second = second;
    }

    public int getHour() {
        return hour;
    }

    public int getMinute() {
        return minute;
    }

    public int getSecond() {
        return second;
    }

    public void setTime(long elapsedTime) {
        long totalSeconds = elapsedTime / 1000;
        second = (int) (totalSeconds % 60);
        long totalMinutes = totalSeconds / 60;
        minute = (int) (totalMinutes % 60);
        long totalHours = totalMinutes / 60;
        hour = (int) (totalHours % 24);
    }

    @Override
    public String toString() {
        return String.format("%02d:%02d:%02d", hour, minute, second);
    }
}

public class HexFormatException extends Exception {
    public HexFormatException(String message) {
        super(message);
    }
}

public class HexConverter {
    public static int hex2Dec(String hexString) throws HexFormatException {
        int decimalValue = 0;
        for (int i = 0; i < hexString.length(); i++) {
            char hexChar = hexString.charAt(i);
            if (!(hexChar >= '0' && hexChar <= '9') &&
                !(hexChar >= 'A' && hexChar <= 'F') &&
                !(hexChar >= 'a' && hexChar <= 'f')) {
                throw new HexFormatException("Invalid hex string: " + hexString);
            }
            decimalValue = decimalValue * 16 + hexToDecimal(hexChar);
        }
        return decimalValue;
    }

    public static int hexToDecimal(char ch) {
        if (ch >= 'A' && ch <= 'F')
            return 10 + ch - 'A';
        else
            return ch - '0';
    }
}

import java.util.Scanner;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.time.ZoneOffset;

public class TimeZone {

    public static void main(String[] args) {

        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter the time zone offset to GMT: ");
        int offset = scanner.nextInt();

        LocalDateTime currentTime = LocalDateTime.now(ZoneOffset.UTC);
        LocalDateTime offsetTime = currentTime.plusHours(offset);

        DateTimeFormatter formatter = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss");

        String utcTime = formatter.format(currentTime);
        String offsetTimeStr = formatter.format(offsetTime);

        System.out.println("UTC Time: " + utcTime);
        System.out.println("Time in GMT+" + offset + ": " + offsetTimeStr);
    }
}

import javafx.application.Application;
import javafx.scene.Scene;
import javafx.scene.input.MouseButton;
import javafx.scene.layout.Pane;
import javafx.scene.paint.Color;
import javafx.scene.shape.Circle;
import javafx.stage.Stage;

public class AddRemovePoints extends Application {

    private Pane pane;

    @Override
    public void start(Stage primaryStage) {
        pane = new Pane();
        Scene scene = new Scene(pane, 400, 400);

        // Add event listeners to pane
        pane.setOnMouseClicked(event -> {
            if (event.getButton() == MouseButton.PRIMARY) {
                // Create point on left-click
                double x = event.getX();
                double y = event.getY();
                Circle point = new Circle(x, y, 5.0, Color.RED);
                pane.getChildren().add(point);
            } else if (event.getButton() == MouseButton.SECONDARY) {
                // Remove point on right-click
                for (int i = 0; i < pane.getChildren().size(); i++) {
                    Circle point = (Circle) pane.getChildren().get(i);
                    if (point.contains(event.getX(), event.getY())) {
                        pane.getChildren().remove(point);
                        break;
                    }
                }
            }
        });

        primaryStage.setScene(scene);
        primaryStage.setTitle("Add/Remove Points");
        primaryStage.show();
    }

    public static void main(String[] args) {
        launch(args);
    }
}

import java.util.Scanner;

public class MeanAndStdDeviation {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);

        // Prompt the user to enter ten numbers
        System.out.print("Enter ten numbers: ");
        double[] numbers = new double[10];
        for (int i = 0; i < 10; i++) {
            numbers[i] = input.nextDouble();
        }

        // Calculate the mean
        double sum = 0;
        for (double number : numbers) {
            sum += number;
        }
        double mean = sum / 10;

        // Calculate the standard deviation
        double deviation = 0;
        for (double number : numbers) {
            deviation += Math.pow(number - mean, 2);
        }
        deviation = Math.sqrt(deviation / 9);

        // Display the results
        System.out.printf("The mean is %.2f\n", mean);
        System.out.printf("The standard deviation is %.5f\n", deviation);
    }
}

import javafx.application.Application;
import javafx.scene.Scene;
import javafx.scene.canvas.Canvas;
import javafx.scene.canvas.GraphicsContext;
import javafx.scene.input.KeyCode;
import javafx.scene.layout.Pane;
import javafx.scene.paint.Color;
import javafx.stage.Stage;

public class LineDrawing extends Application {

    private double centerX;
    private double centerY;
    private double currentX;
    private double currentY;

    @Override
    public void start(Stage primaryStage) throws Exception {
        // Create a canvas to draw on
        Canvas canvas = new Canvas(400, 400);
        GraphicsContext gc = canvas.getGraphicsContext2D();

        // Set the initial position of the line to the center of the canvas
        centerX = canvas.getWidth() / 2;
        centerY = canvas.getHeight() / 2;
        currentX = centerX;
        currentY = centerY;

        // Create a pane to hold the canvas
        Pane root = new Pane(canvas);

        // Create a scene and add it to the stage
        Scene scene = new Scene(root);
        primaryStage.setScene(scene);
        primaryStage.show();

        // Set up the key event handler
        scene.setOnKeyPressed(event -> {
            KeyCode keyCode = event.getCode();
            switch (keyCode) {
                case RIGHT:
                    drawLine(gc, currentX, currentY, currentX + 50, currentY);
                    currentX += 50;
                    break;
                case UP:
                    drawLine(gc, currentX, currentY, currentX, currentY - 50);
                    currentY -= 50;
                    break;
                case LEFT:
                    drawLine(gc, currentX, currentY, currentX - 50, currentY);
                    currentX -= 50;
                    break;
                case DOWN:
                    drawLine(gc, currentX, currentY, currentX, currentY + 50);
                    currentY += 50;
                    break;
            }
        });
    }

    private void drawLine(GraphicsContext gc, double startX, double startY, double endX, double endY) {
        gc.setStroke(Color.BLACK);
        gc.setLineWidth(2);
        gc.strokeLine(startX, startY, endX, endY);
    }

    public static void main(String[] args) {
        launch(args);
    }
}

