import java.util.Scanner;

public class DistinctNumbers {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);

        int[] numbers = new int[10];
        int distinctCount = 0;

        for (int i = 0; i < numbers.length; i++) {
            int number = input.nextInt();

            if (isNewNumber(numbers, number)) {
                numbers[distinctCount] = number;
                distinctCount++;
            }
        }

        System.out.println("Number of distinct numbers: " + distinctCount);
        System.out.print("Distinct numbers: ");

        for (int i = 0; i < distinctCount; i++) {
            System.out.print(numbers[i] + " ");
        }

        input.close();
    }

    public static boolean isNewNumber(int[] numbers, int number) {
        for (int i = 0; i < numbers.length; i++) {
            if (numbers[i] == number) {
                return false;
            }
        }

        return true;
    }
}

import java.util.HashMap;
import java.util.Map;

public class RecommenderSystem {

    private Map<String, Map<String, Double>> userRatings;

    public RecommenderSystem() {
        userRatings = new HashMap<>();
    }

    public void addRating(String user, String item, double rating) {
        if (!userRatings.containsKey(user)) {
            userRatings.put(user, new HashMap<>());
        }
        userRatings.get(user).put(item, rating);
    }

    public double getSimilarity(String user1, String user2) {
        Map<String, Double> ratings1 = userRatings.get(user1);
        Map<String, Double> ratings2 = userRatings.get(user2);
        double dotProduct = 0;
        double magnitude1 = 0;
        double magnitude2 = 0;
        for (String item : ratings1.keySet()) {
            if (ratings2.containsKey(item)) {
                dotProduct += ratings1.get(item) * ratings2.get(item);
                magnitude1 += Math.pow(ratings1.get(item), 2);
                magnitude2 += Math.pow(ratings2.get(item), 2);
            }
        }
        return dotProduct / (Math.sqrt(magnitude1) * Math.sqrt(magnitude2));
    }

    public double predictRating(String user, String item) {
        double weightedSum = 0;
        double similaritySum = 0;
        for (String otherUser : userRatings.keySet()) {
            if (!otherUser.equals(user) && userRatings.get(otherUser).containsKey(item)) {
                double similarity = getSimilarity(user, otherUser);
                weightedSum += similarity * userRatings.get(otherUser).get(item);
                similaritySum += similarity;
            }
        }
        return weightedSum / similaritySum;
    }

    public static void main(String[] args) {
        RecommenderSystem system = new RecommenderSystem();
        system.addRating("user1", "item1", 5);
        system.addRating("user1", "item2", 3);
        system.addRating("user1", "item3", 4);
        system.addRating("user2", "item1", 3);
        system.addRating("user2", "item2", 4);
        system.addRating("user2", "item3", 5);
        system.addRating("user3", "item1", 2);
        system.addRating("user3", "item2", 3);
        System.out.println(system.predictRating("user1", "item3")); // should return 4
    }
}

import java.util.Scanner;

public class SavingsAccount {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Get input from user
        System.out.print("Enter the initial amount: $");
        double amount = scanner.nextDouble();
        System.out.print("Enter the annual interest rate (as a percentage): ");
        double annualRate = scanner.nextDouble();
        System.out.print("Enter the number of months: ");
        int months = scanner.nextInt();

        // Compute monthly interest rate
        double monthlyRate = annualRate / 1200.0;  // 12 months in a year, 100 to convert percentage to decimal

        // Compute balance after specified number of months
        for (int i = 1; i <= months; i++) {
            amount = amount + (100 * monthlyRate) + 100;  // add monthly deposit and interest
        }

        // Output balance
        System.out.printf("The balance after %d months is: $%.2f", months, amount);
    }
}

import java.util.Comparator;

public class HeapSort {

    public static <E extends Comparable<E>> void heapSort(E[] list) {
        int n = list.length;

        for (int i = n / 2 - 1; i >= 0; i--) {
            heapify(list, n, i);
        }

        for (int i = n - 1; i >= 0; i--) {
            E temp = list[0];
            list[0] = list[i];
            list[i] = temp;
            heapify(list, i, 0);
        }
    }

    public static <E> void heapSort(E[] list, Comparator<? super E> comparator) {
        int n = list.length;

        for (int i = n / 2 - 1; i >= 0; i--) {
            heapify(list, n, i, comparator);
        }

        for (int i = n - 1; i >= 0; i--) {
            E temp = list[0];
            list[0] = list[i];
            list[i] = temp;
            heapify(list, i, 0, comparator);
        }
    }

    private static <E extends Comparable<E>> void heapify(E[] list, int n, int i) {
        int largest = i;
        int left = 2 * i + 1;
        int right = 2 * i + 2;

        if (left < n && list[left].compareTo(list[largest]) > 0) {
            largest = left;
        }

        if (right < n && list[right].compareTo(list[largest]) > 0) {
            largest = right;
        }

        if (largest != i) {
            E temp = list[i];
            list[i] = list[largest];
            list[largest] = temp;
            heapify(list, n, largest);
        }
    }

    private static <E> void heapify(E[] list, int n, int i, Comparator<? super E> comparator) {
        int largest = i;
        int left = 2 * i + 1;
        int right = 2 * i + 2;

        if (left < n && comparator.compare(list[left], list[largest]) > 0) {
            largest = left;
        }

        if (right < n && comparator.compare(list[right], list[largest]) > 0) {
            largest = right;
        }

        if (largest != i) {
            E temp = list[i];
            list[i] = list[largest];
            list[largest] = temp;
            heapify(list, n, largest, comparator);
        }
    }

}

public class SumSeries {
    public static void main(String[] args) {
        int n = 50000;
        double sumLR = 0.0; // sum from left to right
        double sumRL = 0.0; // sum from right to left

        // Compute sum from left to right
        for (int i = 1; i <= n; i += 2) {
            sumLR += (double)i / (i + 2);
        }

        // Compute sum from right to left
        for (int i = n; i >= 1; i -= 2) {
            sumRL += (double)i / (i + 2);
        }

        // Display results
        System.out.printf("Sum from left to right: %.5f\n", sumLR);
        System.out.printf("Sum from right to left: %.5f\n", sumRL);
    }
}

public static <E extends Comparable<E>> E max(E[] list) {
    E max = list[0];
    for (int i = 1; i < list.length; i++) {
        if (list[i].compareTo(max) > 0) {
            max = list[i];
        }
    }
    return max;
}

import java.util.Scanner;

public class SocialSecurityNumberValidator {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter a Social Security number (DDD-DD-DDDD): ");
        String ssn = scanner.nextLine();

        boolean isValidSSN = validateSSN(ssn);

        if (isValidSSN) {
            System.out.println(ssn + " is a valid Social Security number.");
        } else {
            System.out.println(ssn + " is not a valid Social Security number.");
        }
    }

    public static boolean validateSSN(String ssn) {
        if (ssn.length() != 11) {
            return false;
        }

        for (int i = 0; i < ssn.length(); i++) {
            char c = ssn.charAt(i);

            if (i == 3 || i == 6) {
                if (c != '-') {
                    return false;
                }
            } else {
                if (!Character.isDigit(c)) {
                    return false;
                }
            }
        }

        return true;
    }
}

