public class StackOfIntegers {
   private int[] elements;
   private int size;
   private int capacity;

   /**
    * Construct a stack with the default capacity 16
    */
   public StackOfIntegers() {
      this(16);
   }

   /**
    * Construct a stack with the specified maximum capacity
    */
   public StackOfIntegers(int capacity) {
      this.capacity = capacity;
      elements = new int[capacity];
   }

   /**
    * Push a new integer to the top of the stack
    */
   public void push(int value) {
      if (size >= capacity) {
         // create a new array with twice the current capacity
         int[] newElements = new int[capacity * 2];
         // copy the contents of the current array to the new array
         System.arraycopy(elements, 0, newElements, 0, size);
         // assign the reference of the new array to the current array in the stack
         elements = newElements;
         // update the capacity
         capacity *= 2;
      }
      elements[size++] = value;
   }

   /**
    * Return and remove the top element from the stack
    */
   public int pop() {
      if (size == 0) {
         throw new EmptyStackException();
      }
      return elements[--size];
   }

   /**
    * Return the top element from the stack
    */
   public int peek() {
      if (size == 0) {
         throw new EmptyStackException();
      }
      return elements[size - 1];
   }

   /**
    * Test whether the stack is empty
    */
   public boolean empty() {
      return size == 0;
   }

   /**
    * Return the number of elements in the stack
    */
   public int getSize() {
      return size;
   }
}

import java.util.Scanner;

public class ISBNGenerator {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);

        // Prompt the user to enter the first 9 digits of the ISBN
        System.out.print("Enter the first 9 digits of the ISBN: ");
        int isbn = input.nextInt();

        // Compute the last digit of the ISBN
        int checksum = 0;
        int factor = 10;
        for (int i = 0; i < 9; i++) {
            checksum += (isbn % factor) * (i + 1);
            isbn /= 10;
        }
        checksum %= 11;

        // Display the 10-digit ISBN
        System.out.printf("The 10-digit ISBN is %09d%d\n", isbn, (checksum == 10) ? "X" : checksum);
    }
}

import java.util.ArrayList;
import java.util.LinkedList;
import java.util.Queue;

public class Main {
    // Number of vertices
    private int V;
    // Adjacency List
    private ArrayList<Integer>[] adj;

    public Main(int V) {
        this.V = V;
        // Create a new array of lists
        adj = (ArrayList<Integer>[]) new ArrayList[V];
        // Initialize each list
        for (int i = 0; i < V; i++) {
            adj[i] = new ArrayList<Integer>();
        }
    }

    // Function to add an edge to the graph
    public void addEdge(int v, int w) {
        adj[v].add(w);
    }

    // BFS traversal of the vertices reachable from v
    public void BFS(int s) {
        // Create a queue for BFS
        Queue<Integer> queue = new LinkedList<Integer>();
        // Mark all the vertices as not visited
        boolean[] visited = new boolean[V];
        // Mark the current node as visited and enqueue it
        visited[s] = true;
        queue.add(s);
        while (queue.size() != 0) {
            // Dequeue a vertex from queue and print it
            s = queue.poll();
            System.out.print(s + " ");
            // Get all adjacent vertices of the dequeued vertex s
            // If a adjacent has not been visited, then mark it visited and enqueue it
            for (int i = 0; i < adj[s].size(); i++) {
                int n = adj[s].get(i);
                if (!visited[n]) {
                    visited[n] = true;
                    queue.add(n);
                }
            }
        }
    }

    public static void main(String[] args) {
        // Create a graph
        Main g = new Main(4);
        g.addEdge(0, 1);
        g.addEdge(0, 2);
        g.addEdge(1, 2);
        g.addEdge(2, 0);
        g.addEdge(2, 3);
        g.addEdge(3, 3);

        System.out.println("Following is Breadth First Traversal");

        g.BFS(2);
    }
}



