    private static final int HEIGHT = 400;
    private static final int RADIUS = 20;
    private static final int SPEED = 50; // pixels per second

    private Circle ball;
    private Pane pane;
    private TranslateTransition transition;

    @Override
    public void start(Stage primaryStage) {
        // Create ball
        ball = new Circle(RADIUS, Color.RED);
        ball.setTranslateX(WIDTH / 2);
        ball.setTranslateY(HEIGHT / 2);

        // Create pane and add ball to it
        pane = new Pane();
        pane.setPrefSize(WIDTH, HEIGHT);
        pane.getChildren().add(ball);

        // Create transition to move ball
        transition = new TranslateTransition(Duration.seconds(1), ball);
        transition.setByX(0); // start with no movement
        transition.setByY(0); // start with no movement
        transition.setAutoReverse(true);
        transition.setCycleCount(Animation.INDEFINITE);

        // Add event listeners to move ball on arrow key presses
        pane.setOnKeyPressed(event -> {
            switch (event.getCode()) {
                case UP:
                    moveUp();
                    break;
                case DOWN:
                    moveDown();
                    break;
                case LEFT:
                    moveLeft();
                    break;
                case RIGHT:
                    moveRight();
                    break;
                default:
                    break;
            }
        });
        pane.requestFocus(); // make sure pane has focus for key events

        // Create scene and add pane to it
        Scene scene = new Scene(pane);
        primaryStage.setScene(scene);
        primaryStage.setTitle("Move Ball");
        primaryStage.show();
    }

    private void moveUp() {
        if (ball.getTranslateY() - RADIUS > 0) {
            transition.stop();
            transition.setByX(0);
            transition.setByY(-SPEED);
            transition.play();
        }
    }

    private void moveDown() {
        if (ball.getTranslateY() + RADIUS < HEIGHT) {
            transition.stop();
            transition.setByX(0);
            transition.setByY(SPEED);
            transition.play();
        }
    }

    private void moveLeft() {
        if (ball.getTranslateX() - RADIUS > 0) {
            transition.stop();
            transition.setByX(-SPEED);
            transition.setByY(0);
            transition.play();
        }
    }

    private void moveRight() {
        if (ball.getTranslateX() + RADIUS < WIDTH) {
            transition.stop();
            transition.setByX(SPEED);
            transition.setByY(0);
            transition.play();
        }
    }

    public static void main(String[] args) {
        launch(args);
    }
}

import java.io.*;
import java.net.*;
import java.util.*;

public class ChatServer {
    private static List<ClientThread> clients = new ArrayList<ClientThread>();

    public static void main(String[] args) throws IOException {
        ServerSocket serverSocket = null;
        try {
            serverSocket = new ServerSocket(8080);
            System.out.println("Chat server started on port " + serverSocket.getLocalPort());
            while (true) {
                Socket clientSocket = serverSocket.accept();
                ClientThread client = new ClientThread(clientSocket);
                clients.add(client);
                client.start();
            }
        } catch (IOException e) {
            System.err.println("Could not listen on port " + 8080);
            System.exit(-1);
        } finally {
            if (serverSocket != null) {
                serverSocket.close();
            }
        }
    }

    private static class ClientThread extends Thread {
        private Socket clientSocket;
        private PrintWriter out;
        private BufferedReader in;
        private String name;

        public ClientThread(Socket socket) {
            this.clientSocket = socket;
        }

        public void run() {
            try {
                out = new PrintWriter(clientSocket.getOutputStream(), true);
                in = new BufferedReader(new InputStreamReader(clientSocket.getInputStream()));
                out.println("Welcome to the chat server! Please enter your name:");
                name = in.readLine();
                out.println("Hello, " + name + "!");
                for (ClientThread client : clients) {
                    if (client != this) {
                        client.out.println(name + " has joined the chat.");
                    }
                }
                while (true) {
                    String input = in.readLine();
                    if (input == null) {
                        break;
                    }
                    for (ClientThread client : clients) {
                        if (client != this) {
                            client.out.println(name + ": " + input);
                        }
                    }
                }
            } catch (IOException e) {
                System.out.println("Error handling client");
            } finally {
                try {
                    clientSocket.close();
                    clients.remove(this);
                    for (ClientThread client : clients) {
                        client.out.println(name + " has left the chat.");
                    }
                } catch (IOException e) {
                    System.out.println("Error closing client");
                }
            }
        }
    }
}


// In this program, we first define a ChatServer class that creates a ServerSocket on port 8080 and listens for new client connections. When a client connects, we create a new ClientThread object for the client and add it to the clients list. We then start the ClientThread object, which handles the communication with the client.

// The ClientThread class extends Thread and is responsible for handling the communication with a single client. When a ClientThread object is created, it opens input and output streams to the client socket and sends a welcome message to the client. It then waits for the client to send its name and broadcasts to all clients that the new client has joined the chat.

// The ClientThread object then enters a loop where it waits for the client to send messages. When a message is received, the ClientThread object broadcasts the message to all clients except the sender. If the client socket is closed or an error occurs, the ClientThread object removes itself from the clients list and broadcasts to all clients that the client has left the chat.

