import java.awt.BorderLayout;
import java.awt.event.ActionEvent;
import java.awt.event.ActionListener;
import java.util.Collections;
import java.util.HashSet;
import java.util.LinkedList;
import java.util.Set;

import javax.swing.JButton;
import javax.swing.JFrame;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextArea;
import javax.swing.JTextField;

public class NumberListGUI extends JFrame implements ActionListener {
    private LinkedList<Integer> numbers;
    private Set<Integer> uniqueNumbers;
    private JTextField inputField;
    private JTextArea outputArea;

    public NumberListGUI() {
        numbers = new LinkedList<>();
        uniqueNumbers = new HashSet<>();

        // Create input panel with text field and add button
        JPanel inputPanel = new JPanel();
        inputField = new JTextField(10);
        JButton addButton = new JButton("Add");
        addButton.addActionListener(this);
        inputPanel.add(inputField);
        inputPanel.add(addButton);

        // Create control panel with sort, shuffle, and reverse buttons
        JPanel controlPanel = new JPanel();
        JButton sortButton = new JButton("Sort");
        sortButton.addActionListener(this);
        controlPanel.add(sortButton);
        JButton shuffleButton = new JButton("Shuffle");
        shuffleButton.addActionListener(this);
        controlPanel.add(shuffleButton);
        JButton reverseButton = new JButton("Reverse");
        reverseButton.addActionListener(this);
        controlPanel.add(reverseButton);

        // Create output panel with text area
        JPanel outputPanel = new JPanel(new BorderLayout());
        outputArea = new JTextArea(10, 20);
        JScrollPane scrollPane = new JScrollPane(outputArea);
        outputPanel.add(scrollPane, BorderLayout.CENTER);

        // Add all panels to main frame
        this.add(inputPanel, BorderLayout.NORTH);
        this.add(controlPanel, BorderLayout.CENTER);
        this.add(outputPanel, BorderLayout.SOUTH);

        // Set main frame properties and display it
        this.setTitle("Number List");
        this.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        this.pack();
        this.setVisible(true);
    }

    public void actionPerformed(ActionEvent e) {
        String actionCommand = e.getActionCommand();

        switch (actionCommand) {
            case "Add":
                try {
                    int number = Integer.parseInt(inputField.getText());

                    if (uniqueNumbers.add(number)) {
                        numbers.add(number);
                        outputArea.append(number + "\n");
                    }

                    inputField.setText("");
                } catch (NumberFormatException ex) {
                    System.out.println("Invalid input: " + inputField.getText());
                    inputField.setText("");
                }
                break;

            case "Sort":
                Collections.sort(numbers);
                outputArea.setText("");

                for (int number : numbers) {
                    outputArea.append(number + "\n");
                }

                break;

            case "Shuffle":
                Collections.shuffle(numbers);
                outputArea.setText("");

                for (int number : numbers) {
                    outputArea.append(number + "\n");
                }

                break;

            case "Reverse":
                Collections.reverse(numbers);
                outputArea.setText("");

                for (int number : numbers) {
                    outputArea.append(number + "\n");
                }

                break;
        }
    }

    public static void main(String[] args) {
        new NumberListGUI();
    }
}

import java.util.Scanner;

public class CharacterCount {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter a list of characters: ");
        String input = scanner.nextLine();
        char[] chars = input.toCharArray();
        System.out.print("Enter a character to count: ");
        char ch = scanner.nextLine().charAt(0);
        int count = count(chars, ch);
        System.out.printf("The character %c occurs %d times in the list.%n", ch, count);
    }

    public static int count(char[] chars, char ch) {
        return countHelper(chars, ch, chars.length - 1);
    }

    public static int countHelper(char[] chars, char ch, int high) {
        if (high < 0) {
            return 0;
        } else {
            int count = countHelper(chars, ch, high - 1);
            if (chars[high] == ch) {
                count++;
            }
            return count;
        }
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);

        // prompt the user to enter the number of students
        System.out.print("Enter the number of students: ");
        int numStudents = input.nextInt();

        // initialize variables to keep track of highest and second-highest scores and their corresponding names
        String highestName = "";
        int highestScore = Integer.MIN_VALUE;
        String secondHighestName = "";
        int secondHighestScore = Integer.MIN_VALUE;

        // loop through each student and update highest and second-highest scores if necessary
        for (int i = 0; i < numStudents; i++) {
            // prompt the user to enter the student's name and score
            System.out.print("Enter the name and score of student " + (i + 1) + ": ");
            String name = input.next();
            int score = input.nextInt();

            // update highest and second-highest scores if necessary
            if (score > highestScore) {
                secondHighestName = highestName;
                secondHighestScore = highestScore;
                highestName = name;
                highestScore = score;
            } else if (score > secondHighestScore) {
                secondHighestName = name;
                secondHighestScore = score;
            }
        }

        // display the student with the highest score and the student with the second-highest score
        System.out.println("Student with the highest score: " + highestName + " (" + highestScore + ")");
        System.out.println("Student with the second-highest score: " + secondHighestName + " (" + secondHighestScore + ")");
    }
}

import java.util.*;

class Dijkstra {

    private static final int V = 9;

    int minDistance(int dist[], Boolean sptSet[]) {
        int min = Integer.MAX_VALUE, min_index = -1;
        for (int v = 0; v < V; v++) {
            if (sptSet[v] == false && dist[v] <= min) {
                min = dist[v];
                min_index = v;
            }
        }
        return min_index;
    }

    void printSolution(int dist[], int n) {
        System.out.println("Vertex   Distance from Source");
        for (int i = 0; i < V; i++) {
            System.out.println(i + " \t\t " + dist[i]);
        }
    }

    void dijkstra(int graph[][], int src) {
        int dist[] = new int[V];
        Boolean sptSet[] = new Boolean[V];
        for (int i = 0; i < V; i++) {
            dist[i] = Integer.MAX_VALUE;
            sptSet[i] = false;
        }
        dist[src] = 0;
        for (int count = 0; count < V - 1; count++) {
            int u = minDistance(dist, sptSet);
            sptSet[u] = true;
            for (int v = 0; v < V; v++) {
                if (!sptSet[v] && graph[u][v] != 0 && dist[u] != Integer.MAX_VALUE && dist[u] + graph[u][v] < dist[v]) {
                    dist[v] = dist[u] + graph[u][v];
                }
            }
        }
        printSolution(dist, V);
    }

    public static void main(String[] args) {
        int graph[][] = new int[][] { { 0, 4, 0, 0, 0, 0, 0, 8, 0 }, 
                                      { 4, 0, 8, 0, 0, 0, 0, 11, 0 }, 
                                      { 0, 8, 0, 7, 0, 4, 0, 0, 2 }, 
                                      { 0, 0, 7, 0, 9, 14, 0, 0, 0 }, 
                                      { 0, 0, 0, 9, 0, 10, 0, 0, 0 }, 
                                      { 0, 0, 4, 14, 10, 0, 2, 0, 0 }, 
                                      { 0, 0, 0, 0, 0, 2, 0, 1, 6 }, 
                                      { 8, 11, 0, 0, 0, 0, 1, 0, 7 }, 
                                      { 0, 0, 2, 0, 0, 0, 6, 7, 0 } };
        Dijkstra t = new Dijkstra();
        t.dijkstra(graph, 0);
    }
}

import java.util.Scanner;

public class QuadraticEquation {
    private double a;
    private double b;
    private double c;

    public QuadraticEquation(double a, double b, double c) {
        this.a = a;
        this.b = b;
        this.c = c;
    }

    public double getA() {
        return a;
    }

    public double getB() {
        return b;
    }

    public double getC() {
        return c;
    }

    public double getDiscriminant() {
        return b * b - 4 * a * c;
    }

    public double getRoot1() {
        if (getDiscriminant() < 0) {
            return 0;
        }
        return (-b + Math.sqrt(getDiscriminant())) / (2 * a);
    }

    public double getRoot2() {
        if (getDiscriminant() < 0) {
            return 0;
        }
        return (-b - Math.sqrt(getDiscriminant())) / (2 * a);
    }

    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);

        System.out.print("Enter a, b, c: ");
        double a = input.nextDouble();
        double b = input.nextDouble();
        double c = input.nextDouble();

        QuadraticEquation equation = new QuadraticEquation(a, b, c);

        double discriminant = equation.getDiscriminant();

        if (discriminant > 0) {
            double root1 = equation.getRoot1();
            double root2 = equation.getRoot2();
            System.out.println("The roots are " + root1 + " and " + root2);
        } else if (discriminant == 0) {
            double root = -b / (2 * a);
            System.out.println("The root is " + root);
        } else {
            System.out.println("The equation has no roots.");
        }
    }
}

import java.io.*;
import java.util.zip.*;

public class Main {
    public static void main(String[] args) {
        // The file to compress
        String fileToCompress = "file.txt";
        // The compressed file
        String compressedFile = "file.zip";

        try (FileInputStream fis = new FileInputStream(fileToCompress);
             FileOutputStream fos = new FileOutputStream(compressedFile);
             ZipOutputStream zos = new ZipOutputStream(fos)) {

            // Create a new zip entry
            ZipEntry entry = new ZipEntry(fileToCompress);
            zos.putNextEntry(entry);

            // Write the file to the zip
            byte[] buffer = new byte[1024];
            int len;
            while ((len = fis.read(buffer)) > 0) {
                zos.write(buffer, 0, len);
            }

            // Close the zip entry and the zip output stream
            zos.closeEntry();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

import java.util.Scanner;

public class WindChill {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Get input from user
        System.out.print("Enter the temperature (in degrees Fahrenheit): ");
        double ta = scanner.nextDouble();

        if (ta < -58 || ta > 41) { // check if ta is within valid range
            System.out.println("Temperature must be between -58 ºF and 41ºF.");
            System.exit(1);
        }

        System.out.print("Enter the wind speed (in miles per hour): ");
        double v = scanner.nextDouble();

        if (v < 2) { // check if v is within valid range
            System.out.println("Wind speed must be greater than or equal to 2 mph.");
            System.exit(1);
        }

        // Calculate wind-chill temperature
        double twc = 35.74 + 0.6215*ta - 35.75*Math.pow(v, 0.16) + 0.4275*ta*Math.pow(v, 0.16);

        // Output result
        System.out.printf("The wind-chill temperature is: %.2f ºF", twc);
    }
}

public class StopWatch {
    private long startTime;
    private long endTime;

    public StopWatch() {
        startTime = System.currentTimeMillis();
    }

    public long getStartTime() {
        return startTime;
    }

    public long getEndTime() {
        return endTime;
    }

    public void start() {
        startTime = System.currentTimeMillis();
    }

    public void stop() {
        endTime = System.currentTimeMillis();
    }

    public long getElapsedTime() {
        return endTime - startTime;
    }
}

import java.util.*;

public class ConvexHull {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);

        System.out.print("How many points are in the set? ");
        int size = input.nextInt();

        double[][] points = new double[size][2];
        System.out.print("Enter " + size + " points: ");
        for (int i = 0; i < size; i++) {
            points[i][0] = input.nextDouble();
            points[i][1] = input.nextDouble();
        }

        ArrayList<Point2D> hull = getConvexHull(points);

        System.out.println("The convex hull is");
        for (Point2D p : hull) {
            System.out.print("(" + p.getX() + ", " + p.getY() + ") ");
        }
    }

    public static ArrayList<Point2D> getConvexHull(double[][] points) {
        ArrayList<Point2D> hull = new ArrayList<>();

        // Find the rightmost lowest point
        int startingIndex = 0;
        for (int i = 1; i < points.length; i++) {
            if (points[i][1] < points[startingIndex][1] ||
                (points[i][1] == points[startingIndex][1] &&
                 points[i][0] > points[startingIndex][0])) {
                startingIndex = i;
            }
        }

        int currentIndex = startingIndex;
        do {
            hull.add(new Point2D(points[currentIndex][0], points[currentIndex][1]));
            int nextIndex = (currentIndex + 1) % points.length;
            for (int i = 0; i < points.length; i++) {
                if (orient(points[currentIndex], points[i], points[nextIndex]) < 0) {
                    nextIndex = i;
                }
            }
            currentIndex = nextIndex;
        } while (currentIndex != startingIndex);

        return hull;
    }

    public static double orient(double[] p, double[] q, double[] r) {
        return (q[1] - p[1]) * (r[0] - q[0]) - (q[0] - p[0]) * (r[1] - q[1]);
    }
}

import java.util.Scanner;

public class ISBNGenerator {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);

        System.out.print("Enter the first 9 digits of the ISBN: ");
        int digits = input.nextInt();

        int d1 = digits / 100000000;   // First digit
        int d2 = digits % 100000000 / 10000000;   // Second digit
        int d3 = digits % 10000000 / 1000000;   // Third digit
        int d4 = digits % 1000000 / 100000;   // Fourth digit
        int d5 = digits % 100000 / 10000;   // Fifth digit
        int d6 = digits % 10000 / 1000;   // Sixth digit
        int d7 = digits % 1000 / 100;   // Seventh digit
        int d8 = digits % 100 / 10;   // Eighth digit
        int d9 = digits % 10;   // Ninth digit

        int checksum = (d1 * 1 + d2 * 2 + d3 * 3 + d4 * 4 + d5 * 5 + d6 * 6 + d7 * 7 + d8 * 8 + d9 * 9) % 11;

        System.out.print("The ISBN-10 number is ");
        System.out.print(d1);
        System.out.print(d2);
        System.out.print(d3);
        System.out.print(d4);
        System.out.print(d5);
        System.out.print(d6);
        System.out.print(d7);
        System.out.print(d8);
        System.out.print(d9);

        if (checksum == 10) {
            System.out.print("X");
        } else {
            System.out.print(checksum);
        }
    }
}

