import java.io.File;
import java.io.FileNotFoundException;
import java.util.Arrays;
import java.util.Comparator;
import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

public class WordCounter {

    public static void main(String[] args) {
        if (args.length == 0) {
            System.out.println("Usage: java WordCounter filename");
            System.exit(1);
        }

        String fileName = args[0];
        File file = new File(fileName);
        if (!file.exists()) {
            System.out.println("File not found: " + fileName);
            System.exit(1);
        }

        Map<String, Integer> wordCounts = new HashMap<>();
        try (Scanner input = new Scanner(file)) {
            while (input.hasNext()) {
                String line = input.nextLine();
                String[] words = line.split("[\\s\\p{Punct}&&[^']&&[^-]]+");
                for (String word : words) {
                    if (word.matches("[a-zA-Z]+.*")) {
                        String lowercaseWord = word.toLowerCase();
                        wordCounts.put(lowercaseWord, wordCounts.getOrDefault(lowercaseWord, 0) + 1);
                    }
                }
            }
        } catch (FileNotFoundException e) {
            e.printStackTrace();
        }

        Object[] keys = wordCounts.keySet().toArray();
        Arrays.sort(keys, Comparator.comparing(String::toLowerCase));

        for (Object key : keys) {
            System.out.printf("%-15s%3d%n", key, wordCounts.get(key));
        }
    }

}

public class BubbleSort {
    static void bubbleSort(int[] arr) {
        int n = arr.length;
        for (int i = 0; i < n-1; i++) {
            for (int j = 0; j < n-i-1; j++) {
                if (arr[j] > arr[j+1]) {
                    int temp = arr[j];
                    arr[j] = arr[j+1];
                    arr[j+1] = temp;
                }
            }
        }
    }
    static void printArray(int arr[]) {
        int n = arr.length;
        for (int i=0; i<n; ++i)
            System.out.print(arr[i] + " ");
        System.out.println();
    }
    public static void main(String args[]) {
        int arr[] = {64, 34, 25, 12, 22, 11, 90};
        bubbleSort(arr);
        System.out.println("Sorted array:");
        printArray(arr);
    }
}



