import java.util.Scanner;

public class GcdCalculator {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);

        System.out.print("Enter the first positive integer: ");
        int n1 = input.nextInt();

        System.out.print("Enter the second positive integer: ");
        int n2 = input.nextInt();

        int gcd = 1;
        int d = Math.min(n1, n2);

        while (d >= 1) {
            if (n1 % d == 0 && n2 % d == 0) {
                gcd = d;
                break;
            }
            d--;
        }

        System.out.println("The greatest common divisor of " + n1 + " and " + n2 + " is " + gcd);
    }
}

public abstract class MyAbstractList<E> implements MyList<E> {

  protected int size;

  protected MyAbstractList() {
  }

  protected MyAbstractList(E[] objects) {
    for (int i = 0; i < objects.length; i++)
      add(objects[i]);
  }

  @Override
  public boolean addAll(MyList<E> otherList) {
    int oldSize = size;
    for (E e : otherList)
      add(e);
    return size > oldSize;
  }

  @Override
  public boolean removeAll(MyList<E> otherList) {
    int oldSize = size;
    for (E e : otherList)
      remove(e);
    return size < oldSize;
  }

  @Override
  public boolean retainAll(MyList<E> otherList) {
    int oldSize = size;
    MyList<E> tempList = new MyArrayList<>();
    for (E e : this) {
      if (otherList.contains(e))
        tempList.add(e);
    }
    clear();
    addAll(tempList);
    return size < oldSize;
  }

  @Override
  public int size() {
    return size;
  }

  @Override
  public boolean isEmpty() {
    return size == 0;
  }

  @Override
  public boolean contains(E e) {
    return indexOf(e) >= 0;
  }

  @Override
  public boolean add(E e) {
    add(size, e);
    return true;
  }

  @Override
  public void add(int index, E e) {
    if (index < 0 || index > size)
      throw new IndexOutOfBoundsException("Index: " + index + ", Size: " + size);
    ensureCapacity();

    for (int i = size - 1; i >= index; i--)
      this.set(i + 1, this.get(i));

    this.set(index, e);

    size++;
  }

  @Override
  public E remove(int index) {
    if (index < 0 || index >= size)
      throw new IndexOutOfBoundsException("Index: " + index + ", Size: " + size);

    E e = get(index);

    for (int j = index; j < size - 1; j++)
      this.set(j, this.get(j + 1));

    this.set(size - 1, null);

    size--;

    return e;
  }

  @Override
  public int indexOf(E e) {
    for (int i = 0; i < size; i++)
      if (e.equals(get(i)))
        return i;

    return -1;
  }

  @Override
  public int lastIndexOf(E e) {
    for (int i = size - 1; i >= 0; i--)
      if (e.equals(get(i)))
        return i;

    return -1;
  }

  @Override
  public E set(int index, E e) {
    if (index < 0 || index >= size)
      throw new IndexOutOfBoundsException("Index: " + index + ", Size: " + size);

    E old = get(index);
    data[index] = e;
    return old;
  }

  @Override
  public String toString() {
    StringBuilder result = new StringBuilder("[");

    for (int i = 0; i < size; i++) {
      result.append(data[i]);
      if (i < size - 1)
        result.append(", ");
    }

    return result.toString() + "]";
  }
}

import java.io.*;

public class BitOutputStream extends FilterOutputStream {
    private int buffer; // 8-bit buffer for storing bits
    private int numBitsInBuffer; // number of bits in the buffer

    public BitOutputStream(File file) throws FileNotFoundException {
        super(new FileOutputStream(file));
        buffer = 0;
        numBitsInBuffer = 0;
    }

    public void writeBit(char bit) throws IOException {
        if (bit != '0' && bit != '1') {
            throw new IllegalArgumentException("Invalid bit value: " + bit);
        }
        buffer = (buffer << 1) | (bit - '0');
        numBitsInBuffer++;
        if (numBitsInBuffer == 8) {
            flush();
        }
    }

    public void writeBit(String bit) throws IOException {
        for (int i = 0; i < bit.length(); i++) {
            writeBit(bit.charAt(i));
        }
    }

    public void close() throws IOException {
        if (numBitsInBuffer > 0 && numBitsInBuffer < 8) {
            buffer <<= (8 - numBitsInBuffer); // fill buffer with zeros
            out.write(buffer);
        }
        super.close();
    }

    public void flush() throws IOException {
        if (numBitsInBuffer > 0) {
            out.write(buffer);
            buffer = 0;
            numBitsInBuffer = 0;
        }
    }
}

public class Circle2D {
    private double x;
    private double y;
    private double radius;

    public Circle2D() {
        this(0, 0, 1);
    }

    public Circle2D(double x, double y, double radius) {
        this.x = x;
        this.y = y;
        this.radius = radius;
    }

    public double getX() {
        return x;
    }

    public double getY() {
        return y;
    }

    public double getRadius() {
        return radius;
    }

    public double getArea() {
        return Math.PI * radius * radius;
    }

    public double getPerimeter() {
        return 2 * Math.PI * radius;
    }

    public boolean contains(double x, double y) {
        double distance = Math.sqrt((this.x - x) * (this.x - x) + (this.y - y) * (this.y - y));
        return distance < radius;
    }

    public boolean contains(Circle2D circle) {
        double distance = Math.sqrt((this.x - circle.x) * (this.x - circle.x) + (this.y - circle.y) * (this.y - circle.y));
        return distance + circle.radius <= radius;
    }

    public boolean overlaps(Circle2D circle) {
        double distance = Math.sqrt((this.x - circle.x) * (this.x - circle.x) + (this.y - circle.y) * (this.y - circle.y));
        return distance < this.radius + circle.radius;
    }
}

import javafx.application.Application;
import javafx.geometry.Point2D;
import javafx.scene.Scene;
import javafx.scene.canvas.Canvas;
import javafx.scene.canvas.GraphicsContext;
import javafx.scene.layout.BorderPane;
import javafx.scene.paint.Color;
import javafx.stage.Stage;

public class CircleIntersection extends Application {
    private Circle circle1 = new Circle(new Point2D(100, 100), 50);
    private Circle circle2 = new Circle(new Point2D(200, 200), 50);
    private Canvas canvas;

    public void start(Stage primaryStage) {
        BorderPane root = new BorderPane();
        canvas = new Canvas(400, 400);
        root.setCenter(canvas);

        drawCircles();

        canvas.setOnMousePressed(event -> {
            if (circle1.contains(event.getX(), event.getY())) {
                circle1.setCenter(new Point2D(event.getX(), event.getY()));
                drawCircles();
            } else if (circle2.contains(event.getX(), event.getY())) {
                circle2.setCenter(new Point2D(event.getX(), event.getY()));
                drawCircles();
            }
        });

        canvas.setOnMouseDragged(event -> {
            if (circle1.contains(event.getX(), event.getY())) {
                circle1.setCenter(new Point2D(event.getX(), event.getY()));
                drawCircles();
            } else if (circle2.contains(event.getX(), event.getY())) {
                circle2.setCenter(new Point2D(event.getX(), event.getY()));
                drawCircles();
            }
        });

        Scene scene = new Scene(root, 400, 400);
        primaryStage.setScene(scene);
        primaryStage.show();
    }

    private void drawCircles() {
        GraphicsContext gc = canvas.getGraphicsContext2D();
        gc.clearRect(0, 0, canvas.getWidth(), canvas.getHeight());

        if (circle1.intersects(circle2)) {
            gc.setFill(Color.RED);
        } else {
            gc.setFill(Color.GREEN);
        }
        gc.fillOval(circle1.getCenter().getX() - circle1.getRadius(), circle1.getCenter().getY() - circle1.getRadius(),
                circle1.getRadius() * 2, circle1.getRadius() * 2);

        if (circle2.intersects(circle1)) {
            gc.setFill(Color.RED);
        } else {
            gc.setFill(Color.GREEN);
        }
        gc.fillOval(circle2.getCenter().getX() - circle2.getRadius(), circle2.getCenter().getY() - circle2.getRadius(),
                circle2.getRadius() * 2, circle2.getRadius() * 2);
    }

    public static void main(String[] args) {
        launch(args);
    }
}

import java.util.Arrays;

public class NeuralNetwork {
    // Number of input, hidden, and output neurons
    private final int inputSize;
    private final int hiddenSize;
    private final int outputSize;
    // Weights and biases
    private final double[][] weightsInputHidden;
    private final double[] biasesHidden;
    private final double[][] weightsHiddenOutput;
    private final double[] biasesOutput;

    public NeuralNetwork(int inputSize, int hiddenSize, int outputSize) {
        this.inputSize = inputSize;
        this.hiddenSize = hiddenSize;
        this.outputSize = outputSize;
        // Initialize weights and biases with random values
        this.weightsInputHidden = new double[inputSize][hiddenSize];
        for (int i = 0; i < inputSize; i++) {
            for (int j = 0; j < hiddenSize; j++) {
                this.weightsInputHidden[i][j] = Math.random();
            }
        }
        this.biasesHidden = new double[hiddenSize];
        Arrays.fill(this.biasesHidden, Math.random());
        this.weightsHiddenOutput = new double[hiddenSize][outputSize];
        for (int i = 0; i < hiddenSize; i++) {
            for (int j = 0; j < outputSize; j++) {
                this.weightsHiddenOutput[i][j] = Math.random();
            }
        }
        this.biasesOutput = new double[outputSize];
        Arrays.fill(this.biasesOutput, Math.random());
    }

    public double[] predict(double[] inputs) {
        // Perform the feedforward calculation
        double[] hidden = new double[hiddenSize];
        for (int i = 0; i < hiddenSize; i++) {
            for (int j = 0; j < inputSize; j++) {
                hidden[i] += inputs[j] * weightsInputHidden[j][i];
            }
            hidden[i] += biasesHidden[i];
            // Apply the activation function
            hidden[i] = sigmoid(hidden[i]);
        }
        double[] output = new double[outputSize];
        for (int i = 0; i < outputSize; i++) {
            for (int j = 0; j < hiddenSize; j++) {
                output[i] += hidden[j] * weightsHiddenOutput[j][i];
            }
            output[i] += biasesOutput[i];
            // Apply the activation function
            output[i] = sigmoid(output[i]);
        }
        return output;
    }

    private double sigmoid(double x) {
        return 1 / (1 + Math.exp(-x));
    }
}

