import java.util.Properties;
import javax.mail.Session;
import javax.mail.Message;
import javax.mail.Transport;
import javax.mail.internet.InternetAddress;
import javax.mail.internet.MimeMessage;

public class EmailClient {

    public static void main(String[] args) {
        try {
            Properties props = new Properties();
            props.put("mail.smtp.host", "smtp.example.com");
            props.put("mail.smtp.port", "587");
            props.put("mail.smtp.auth", "true");
            props.put("mail.smtp.starttls.enable", "true");

            Session session = Session.getInstance(props, null);

            Message message = new MimeMessage(session);
            message.setFrom(new InternetAddress("sender@example.com"));
            message.setRecipients(Message.RecipientType.TO, InternetAddress.parse("recipient@example.com"));
            message.setSubject("Test Email");
            message.setText("This is a test email sent from a Java program.");

            Transport transport = session.getTransport("smtp");
            transport.connect("smtp.example.com", "sender@example.com", "password");
            transport.sendMessage(message, message.getAllRecipients());
            transport.close();
            System.out.println("Email sent!");
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}

public class Octagon extends GeometricObject implements Comparable<Octagon>, Cloneable {
    private double side;

    public Octagon() {
        this(1.0);
    }

    public Octagon(double side) {
        this.side = side;
    }

    public double getSide() {
        return side;
    }

    public void setSide(double side) {
        this.side = side;
    }

    public double getArea() {
        return (2 + 4 / Math.sqrt(2)) * side * side;
    }

    public double getPerimeter() {
        return 8 * side;
    }

    @Override
    public int compareTo(Octagon o) {
        if (this.side < o.side)
            return -1;
        else if (this.side > o.side)
            return 1;
        else
            return 0;
    }

    @Override
    public Object clone() throws CloneNotSupportedException {
        return super.clone();
    }
}

import java.util.Scanner;

public class PhoneKeyPads {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        System.out.print("Enter a phone number: ");
        String phoneNumber = input.nextLine();

        String translatedNumber = "";
        for (int i = 0; i < phoneNumber.length(); i++) {
            char ch = phoneNumber.charAt(i);
            if (Character.isLetter(ch)) {
                translatedNumber += getNumber(Character.toUpperCase(ch));
            } else {
                translatedNumber += ch;
            }
        }

        System.out.println("The translated phone number is: " + translatedNumber);
    }

    public static int getNumber(char uppercaseLetter) {
        if (uppercaseLetter >= 'A' && uppercaseLetter <= 'C') {
            return 2;
        } else if (uppercaseLetter >= 'D' && uppercaseLetter <= 'F') {
            return 3;
        } else if (uppercaseLetter >= 'G' && uppercaseLetter <= 'I') {
            return 4;
        } else if (uppercaseLetter >= 'J' && uppercaseLetter <= 'L') {
            return 5;
        } else if (uppercaseLetter >= 'M' && uppercaseLetter <= 'O') {
            return 6;
        } else if (uppercaseLetter >= 'P' && uppercaseLetter <= 'S') {
            return 7;
        } else if (uppercaseLetter >= 'T' && uppercaseLetter <= 'V') {
            return 8;
        } else if (uppercaseLetter >= 'W' && uppercaseLetter <= 'Z') {
            return 9;
        } else {
            return -1; // Invalid character
        }
    }
}

import java.util.Scanner;

public class ConnectFour {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] board = new char[6][7]; // Define the game board
        initializeBoard(board); // Initialize the board to empty spaces
        char player = 'R'; // Start with player 1 (red)
        boolean gameOver = false;

        while (!gameOver) {
            printBoard(board); // Print the current board state
            int column = getColumn(scanner, player); // Prompt the current player to choose a column
            int row = dropDisk(board, column, player); // Drop the disk in the chosen column
            if (checkWin(board, row, column)) { // Check if the player has won
                System.out.println(player + " wins!");
                gameOver = true;
            } else if (isBoardFull(board)) { // Check if the board is full (i.e. a draw)
                System.out.println("Draw!");
                gameOver = true;
            } else {
                player = switchPlayer(player); // Switch to the other player
            }
        }
    }

    // Initializes the board to empty spaces
    public static void initializeBoard(char[][] board) {
        for (int i = 0; i < board.length; i++) {
            for (int j = 0; j < board[0].length; j++) {
                board[i][j] = ' ';
            }
        }
    }

    // Prints the current board state
    public static void printBoard(char[][] board) {
        for (int i = 0; i < board.length; i++) {
            for (int j = 0; j < board[0].length; j++) {
                System.out.print("|" + board[i][j]);
            }
            System.out.println("|");
        }
        System.out.println("---------------");
        System.out.println(" 0 1 2 3 4 5 6");
    }

    // Prompts the current player to choose a column
    public static int getColumn(Scanner scanner, char player) {
        System.out.print("Drop a " + player + " disk at column (0-6): ");
        int column = scanner.nextInt();
        return column;
    }

    // Drops the disk in the chosen column and returns the row where it landed
