import java.io.*;
import java.util.zip.*;

public class Main {
    public static void main(String[] args) {
        // The file to compress
        String fileToCompress = "file.txt";
        // The compressed file
        String compressedFile = "file.zip";

        try (FileInputStream fis = new FileInputStream(fileToCompress);
             FileOutputStream fos = new FileOutputStream(compressedFile);
             ZipOutputStream zos = new ZipOutputStream(fos)) {

            // Create a new zip entry
            ZipEntry entry = new ZipEntry(fileToCompress);
            zos.putNextEntry(entry);

            // Write the file to the zip
            byte[] buffer = new byte[1024];
            int len;
            while ((len = fis.read(buffer)) > 0) {
                zos.write(buffer, 0, len);
            }

            // Close the zip entry and the zip output stream
            zos.closeEntry();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

import java.util.ArrayList;
import java.util.Scanner;

public class PerfectSquare {
    public static void main(String[] args) {
        // Prompt the user to enter an integer m
        Scanner input = new Scanner(System.in);
        System.out.print("Enter an integer m: ");
        int m = input.nextInt();

        // Store all smallest factors of m into an array list
        ArrayList<Integer> factors = new ArrayList<>();
        int factor = 2;
        while (factor <= m) {
            if (m % factor == 0) {
                factors.add(factor);
                m /= factor;
            } else {
                factor++;
            }
        }

        // Find the factors that appear an odd number of times in the array list
        ArrayList<Integer> oddFactors = new ArrayList<>();
        for (int i = 0; i < factors.size(); i++) {
            int count = 1;
            for (int j = i + 1; j < factors.size(); j++) {
                if (factors.get(i).equals(factors.get(j))) {
                    count++;
                    i++;
                } else {
                    break;
                }
            }
            if (count % 2 == 1) {
                oddFactors.add(factors.get(i));
            }
        }

        // Compute the smallest number n for m * n to be a perfect square
        int n = 1;
        for (int factor2 : oddFactors) {
            n *= factor2;
        }

        // Display the result
        System.out.println("The smallest number n for m * n to be a perfect square is " + n);
        System.out.println("m * n is " + (m * n));
    }
}

