import org.deeplearning4j.nn.conf.layers.DenseLayer;
import org.deeplearning4j.nn.conf.layers.OutputLayer;
import org.deeplearning4j.nn.graph.ComputationGraph;
import org.deeplearning4j.optimize.listeners.ScoreIterationListener;
import org.nd4j.linalg.activations.Activation;
import org.nd4j.linalg.dataset.DataSet;
import org.nd4j.linalg.lossfunctions.LossFunctions.LossFunction;

public class ConvolutionalNeuralNetwork {

    public static void main(String[] args) throws Exception {
        int nChannels = 1;
        int outputNum = 10;
        int batchSize = 64;
        int nEpochs = 1;
        int iterations = 1;

        MnistDataSetIterator mnistTrain = new MnistDataSetIterator(batchSize, true, 12345);
        MnistDataSetIterator mnistTest = new MnistDataSetIterator(batchSize, false, 12345);

        ComputationGraphConfiguration conf = new NeuralNetConfiguration.Builder()
                .seed(12345)
                .iterations(iterations)
                .optimizationAlgo(OptimizationAlgorithm.STOCHASTIC_GRADIENT_DESCENT)
                .learningRate(0.1)
                .updater(Updater.NESTEROVS)
                .list()
                .layer(0, new ConvolutionLayer.Builder(5, 5)
                        .nIn(nChannels)
                        .stride(1, 1)
                        .nOut(20)
                        .activation(Activation.RELU)
                        .build())
                .layer(1, new DenseLayer.Builder()
                        .nOut(500)
                        .activation(Activation.RELU)
                        .build())
                .layer(2, new OutputLayer.Builder(LossFunction.NEGATIVELOGLIKELIHOOD)
                        .nOut(outputNum)
                        .activation(Activation.SOFTMAX)
                        .build())
                .setInputType(InputType.convolutionalFlat(28, 28, 1))
                .backprop(true).pretrain(false).build();

        ComputationGraph model = new ComputationGraph(conf);
        model.init();
        model.setListeners(new ScoreIterationListener(1));

        for (int i = 0; i < nEpochs; i++) {
            while (mnistTrain.hasNext()) {
                DataSet trainData = mnistTrain.next();
                model.fit(trainData);
            }
            mnistTrain.reset();
        }

        // Evaluate the model on the test set
        Evaluation eval = new Evaluation(outputNum);
        while (mnistTest.hasNext()) {
            DataSet testData = mnistTest.next();
            INDArray features = testData.getFeatures();
            INDArray labels = testData.getLabels();
            INDArray predicted = model.outputSingle(features);
            eval.eval(labels, predicted);
        }
        mnistTest.reset();
        System.out.println(eval.stats());
    }
}

public static boolean[] checkStringEndings(String[][] a, char[] c) {
    boolean[] b = new boolean[a.length];
    for (int i = 0; i < a.length; i++) {
        boolean rowEndsWithChar = true;
        for (int j = 0; j < a[i].length; j++) {
            if (!a[i][j].endsWith(Character.toString(c[i]))) {
                rowEndsWithChar = false;
                break;
            }
        }
        b[i] = rowEndsWithChar;
    }
    return b;
}

public class MyStringBuilder2 {
    private char[] value;
    private int count;

    public MyStringBuilder2() {
        value = new char[16];
        count = 0;
    }

    public MyStringBuilder2(char[] chars) {
        value = new char[chars.length + 16];
        System.arraycopy(chars, 0, value, 0, chars.length);
        count = chars.length;
    }

    public MyStringBuilder2(String s) {
        value = new char[s.length() + 16];
        s.getChars(0, s.length(), value, 0);
        count = s.length();
    }

    public MyStringBuilder2 insert(int offset, MyStringBuilder2 s) {
        if (offset < 0 || offset > count) {
            throw new StringIndexOutOfBoundsException(offset);
        }
        int newCount = count + s.length();
        if (newCount > value.length) {
            expandCapacity(newCount);
        }
        System.arraycopy(value, offset, value, offset + s.length(), count - offset);
        System.arraycopy(s.value, 0, value, offset, s.length());
        count = newCount;
        return this;
    }

    public MyStringBuilder2 reverse() {
        int len = length();
        for (int i = 0; i < len / 2; i++) {
            char temp = value[i];
            value[i] = value[len - i - 1];
            value[len - i - 1] = temp;
        }
        return this;
    }

    public MyStringBuilder2 substring(int begin) {
        if (begin < 0 || begin >= count) {
            throw new StringIndexOutOfBoundsException(begin);
        }
        return new MyStringBuilder2(value, begin, count - begin);
    }

    public MyStringBuilder2 toUpperCase() {
        for (int i = 0; i < count; i++) {
            if (Character.isLowerCase(value[i])) {
                value[i] = Character.toUpperCase(value[i]);
            }
        }
        return this;
    }

    public int length() {
        return count;
    }

    public char charAt(int index) {
        if (index < 0 || index >= count) {
            throw new StringIndexOutOfBoundsException(index);
        }
        return value[index];
    }

    public String toString() {
        return new String(value, 0, count);
    }

    private void expandCapacity(int minimumCapacity) {
        int newCapacity = value.length * 2 + 2;
        if (newCapacity < 0) {
            newCapacity = Integer.MAX_VALUE;
        } else if (minimumCapacity > newCapacity) {
            newCapacity = minimumCapacity;
        }
        char[] newValue = new char[newCapacity];
        System.arraycopy(value, 0, newValue, 0, count);
        value = newValue;
    }

    private MyStringBuilder2(char[] value, int offset, int count) {
        this.value = value;
        this.count = count;
    }
}

import java.util.concurrent.locks.Condition;
import java.util.ArrayDeque;

public class ArrayDequeExample {
    public static void main(String[] args) {
        // Create a new ArrayDeque
        ArrayDeque<String> deque = new ArrayDeque<>();

        // Add elements to the deque
        deque.add("apple");
        deque.add("banana");
        deque.add("cherry");
        deque.add("date");
        deque.add("elderberry");
        System.out.println("Initial ArrayDeque: " + deque);

        // Remove elements from the deque
        System.out.println("Removed element: " + deque.remove());
        System.out.println("Removed first element: " + deque.removeFirst());
        System.out.println("Removed last element: " + deque.removeLast());
        System.out.println("Updated ArrayDeque: " + deque);

        // Get elements from the deque
        System.out.println("First element: " + deque.getFirst());
        System.out.println("Last element: " + deque.getLast());

        // Check if the deque contains an element
        System.out.println("Does deque contain 'banana'? " + deque.contains("banana"));
        System.out.println("Does deque contain 'fig'? " + deque.contains("fig"));

        // Get the size of the deque
        System.out.println("Size of deque: " + deque.size());

        // Clear the deque
        deque.clear();
        System.out.println("Cleared ArrayDeque: " + deque);
    }
}

public class TowerOfHanoi {
    public static void main(String[] args) {
        int n = 3; // number of disks
        char fromPeg = 'A';
        char toPeg = 'C';
        char auxPeg = 'B';

        System.out.println("Steps to move " + n + " disks from peg " + fromPeg + " to peg " + toPeg + ":");
        moveDisks(n, fromPeg, toPeg, auxPeg);
    }

    private static void moveDisks(int n, char fromPeg, char toPeg, char auxPeg) {
        if (n == 1) {
            System.out.println("Move disk 1 from peg " + fromPeg + " to peg " + toPeg);
            return;
        }

        moveDisks(n - 1, fromPeg, auxPeg, toPeg);
        System.out.println("Move disk " + n + " from peg " + fromPeg + " to peg " + toPeg);
        moveDisks(n - 1, auxPeg, toPeg, fromPeg);
    }
}

