                segmentsIntersect(p2, p3, t.p1, t.p2) ||
                segmentsIntersect(p2, p3, t.p2, t.p3) ||
                segmentsIntersect(p2, p3, t.p3, t.p1) ||
                segmentsIntersect(p3, p1, t.p1, t.p2) ||
                segmentsIntersect(p3, p1, t.p2, t.p3) ||
