    }
}

public class DeadlockDemo {

    public static Object resource1 = new Object();
    public static Object resource2 = new Object();

    public static void main(String[] args) {
        Thread t1 = new Thread(new Task1());
        Thread t2 = new Thread(new Task2());
        t1.start();
        t2.start();
    }

    static class Task1 implements Runnable {
        public void run() {
            synchronized (resource1) {
                System.out.println("Task 1: locked resource 1");
                try {
                    Thread.sleep(100);
                } catch (InterruptedException e) {}
                synchronized (resource2) {
                    System.out.println("Task 1: locked resource 2");
                }
            }
        }
    }

    static class Task2 implements Runnable {
        public void run() {
            synchronized (resource2) {
                System.out.println("Task 2: locked resource 2");
                try {
                    Thread.sleep(100);
                } catch (InterruptedException e) {}
                synchronized (resource1) {
                    System.out.println("Task 2: locked resource 1");
                }
            }
        }
    }
}

public class MersennePrimes {
    public static void main(String[] args) {
        for (int p = 2; p <= 31; p++) {
            int mersenne = (int)Math.pow(2, p) - 1;
            if (isPrime(mersenne)) {
                System.out.println("Mersenne prime with p = " + p + ": " + mersenne);
            }
        }
    }

    public static boolean isPrime(int n) {
        if (n <= 1) {
            return false;
        }
        for (int i = 2; i <= Math.sqrt(n); i++) {
            if (n % i == 0) {
                return false;
            }
        }
        return true;
    }
}

import java.util.Scanner;

public class MonthDays {
    public static void main(String[] args) {
        // Create a scanner to read input from the user
        Scanner scanner = new Scanner(System.in);

        // Prompt the user to enter the month and year
        System.out.print("Enter the month (1-12): ");
        int month = scanner.nextInt();
        System.out.print("Enter the year: ");
        int year = scanner.nextInt();

        // Compute the number of days in the month
        int days;
        if (month == 2) {
            if ((year % 4 == 0 && year % 100 != 0) || year % 400 == 0) {
                days = 29;
            } else {
                days = 28;
            }
        } else if (month == 4 || month == 6 || month == 9 || month == 11) {
            days = 30;
        } else {
            days = 31;
        }

        // Output the result
        System.out.println("The number of days in the month is " + days);
    }
}

import java.util.Random;

public class PlateNumberGenerator {
    public static void main(String[] args) {
        Random random = new Random();

        String plateNumber = "";

        for (int i = 0; i < 3; i++) {
            char letter = (char) (random.nextInt(26) + 'A');
            plateNumber += letter;
        }

        for (int i = 0; i < 4; i++) {
            int digit = random.nextInt(10);
            plateNumber += digit;
        }

        System.out.println("Generated plate number: " + plateNumber);
    }
}

public static String format(int number, int width) {
    String numString = Integer.toString(number);
    int numZeroes = width - numString.length();
    if (numZeroes <= 0) {
        return numString;
    }
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < numZeroes; i++) {
        sb.append('0');
    }
    sb.append(numString);
    return sb.toString();
}

