import java.util.Scanner;

public class WindChill {

    public static void main(String[] args) {

        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter the temperature in Fahrenheit: ");
        double temperature = scanner.nextDouble();

        System.out.print("Enter the wind speed in miles per hour: ");
        double windSpeed = scanner.nextDouble();

        if (temperature < -58 || temperature > 41) {
            System.out.println("Invalid temperature. Please enter a temperature between -58°F and 41°F.");
        } else if (windSpeed < 2) {
            System.out.println("Invalid wind speed. Please enter a wind speed of 2 miles per hour or greater.");
        } else {
            double windChill = 35.74 + 0.6215 * temperature - 35.75 * Math.pow(windSpeed, 0.16) + 0.4275 * temperature * Math.pow(windSpeed, 0.16);
            System.out.printf("The wind-chill temperature is %.2f°F.\n", windChill);
        }
    }
}

import java.io.*;
import java.util.*;

public class Exercise17_18 {

    /**
     * Displays the bit representation of the last byte in an integer
     *
     * @param value an integer value
     * @return a string of the bit representation of the last byte
     */
    public static String getBits(int value) {
        StringBuilder bitString = new StringBuilder();
        for (int i = 7; i >= 0; i--) {
            bitString.append((value & (1 << i)) == 0 ? '0' : '1');
        }
        return bitString.toString();
    }

    public static void main(String[] args) throws IOException {
        Scanner input = new Scanner(System.in);
        System.out.print("Enter a file name: ");
        File file = new File(input.nextLine());

        if (!file.exists()) {
            System.out.println("File " + file.getName() + " does not exist");
            System.exit(1);
        }

        try (DataInputStream inputStream = new DataInputStream(new FileInputStream(file))) {
            while (inputStream.available() > 0) {
                int value = inputStream.readUnsignedByte();
                String bits = getBits(value);
                System.out.println(value + " is " + bits);
            }
        }
    }
}

public static <E> ArrayList<E> removeDuplicates(ArrayList<E> list) {
    ArrayList<E> distinctList = new ArrayList<E>();
    for (E element : list) {
        if (!distinctList.contains(element)) {
            distinctList.add(element);
        }
    }
    return distinctList;
}

