import java.util.Scanner;

public class DaysInMonth {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter the month (1-12): ");
        int month = scanner.nextInt();

        System.out.print("Enter the year: ");
        int year = scanner.nextInt();

        int days = getDaysInMonth(month, year);

        if (days == -1) {
            System.out.println("Invalid month or year");
        } else {
            System.out.println("Number of days in month " + month + " and year " + year + " is: " + days);
        }
    }

    public static int getDaysInMonth(int month, int year) {
        if (month < 1 || month > 12) {
            return -1;
        }

        boolean isLeapYear = (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);

        switch (month) {
            case 2:
                return isLeapYear ? 29 : 28;
            case 4:
            case 6:
            case 9:
            case 11:
                return 30;
            default:
                return 31;
        }
    }
}

public class LunarCalendar {

    public static void main(String[] args) {
        int month = 5;
        int year = 2022;
        int days = getDaysInLunarMonth(month, year);
        System.out.println("Number of days in month " + month + " and year " + year + " of the Lunar Calendar is: " + days);
    }

    public static int getDaysInLunarMonth(int month, int year) {
        if (month < 1 || month > 12) {
            return -1;
        }

        // The number of days in a lunar month is 29.5 days
        // in average, but the length of a month can vary
        // between 29 and 30 days depending on the phase
        // of the moon.
        // The first month of a lunar year always has 29 days
        // and the last month of a lunar year always has 30 days
        // The number of days in the middle months of a lunar year
        // can be calculated using the following formula:
        // days = (year + 8) % 12 == 0 ? 30 : 29;
        if (month == 1) {
            return 29;
        } else if (month == 12) {
            return 30;
        } else {
            return (year + 8) % 12 == 0 ? 30 : 29;
        }
    }
}

import java.util.Random;

public class RandomTriangleAngles {
    public static void main(String[] args) {
        final int RADIUS = 40;
        final double PI = 3.14159;

        // Generate three random angles in radians
        Random random = new Random();
        double angle1 = random.nextDouble() * 2 * PI;
        double angle2 = random.nextDouble() * 2 * PI;
        double angle3 = random.nextDouble() * 2 * PI;

        // Calculate the x and y coordinates of the three points
        double x1 = RADIUS * Math.cos(angle1);
        double y1 = RADIUS * Math.sin(angle1);
        double x2 = RADIUS * Math.cos(angle2);
        double y2 = RADIUS * Math.sin(angle2);
        double x3 = RADIUS * Math.cos(angle3);
        double y3 = RADIUS * Math.sin(angle3);

        // Calculate the three sides of the triangle
        double side1 = Math.sqrt(Math.pow(x2 - x1, 2) + Math.pow(y2 - y1, 2));
        double side2 = Math.sqrt(Math.pow(x3 - x2, 2) + Math.pow(y3 - y2, 2));
        double side3 = Math.sqrt(Math.pow(x1 - x3, 2) + Math.pow(y1 - y3, 2));

        // Calculate the three angles of the triangle in degrees
        double angleA = Math.toDegrees(Math.acos((side1 * side1 + side2 * side2 - side3 * side3) / (2 * side1 * side2)));
        double angleB = Math.toDegrees(Math.acos((side2 * side2 + side3 * side3 - side1 * side1) / (2 * side2 * side3)));
        double angleC = Math.toDegrees(Math.acos((side3 * side3 + side1 * side1 - side2 * side2) / (2 * side3 * side1)));

        // Display the angles
        System.out.println("Angle A = " + angleA);
        System.out.println("Angle B = " + angleB);
        System.out.println("Angle C = " + angleC);
    }
}

