System.out.println("Prediction for new input: " + prediction);

import java.awt.Color;
import java.awt.Graphics;
import java.util.Random;
import javax.swing.JFrame;
import javax.swing.JPanel;

public class CirclePolygon extends JPanel {
    private int centerX = 200;
    private int centerY = 200;
    private int radius = 100;
    private int numPoints = 5;
    private int[] xPoints = new int[numPoints];
    private int[] yPoints = new int[numPoints];

    public CirclePolygon() {
        // generate random points on the circle
        Random random = new Random();
        for (int i = 0; i < numPoints; i++) {
            double angle = i * 2 * Math.PI / numPoints;
            int x = (int)(centerX + radius * Math.cos(angle));
            int y = (int)(centerY + radius * Math.sin(angle));
            xPoints[i] = x;
            yPoints[i] = y;
        }
    }

    public void paintComponent(Graphics g) {
        super.paintComponent(g);

        // draw the circle
        g.drawOval(centerX - radius, centerY - radius, 2 * radius, 2 * radius);

        // draw the polygon
        g.setColor(Color.BLUE);
        g.fillPolygon(xPoints, yPoints, numPoints);
    }

    public static void main(String[] args) {
        JFrame frame = new JFrame("Circle and Polygon");
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        CirclePolygon panel = new CirclePolygon();
        panel.setBackground(Color.WHITE);
        frame.add(panel);
        frame.setSize(400, 400);
        frame.setVisible(true);
    }
}

public static int partition(int[] list) {
    int pivot = list[0];
    int low = 1;
    int high = list.length - 1;

    while (high > low) {
        while (low <= high && list[low] <= pivot) {
            low++;
        }
        while (low <= high && list[high] > pivot) {
            high--;
        }
        if (high > low) {
            int temp = list[high];
            list[high] = list[low];
            list[low] = temp;
        }
    }
    while (high > 0 && list[high] >= pivot) {
        high--;
    }
    if (pivot > list[high]) {
        list[0] = list[high];
        list[high] = pivot;
        return high;
    } else {
        return 0;
    }
}
import java.util.Scanner;

public class PartitionTest {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        System.out.print("Enter list: ");
        int size = input.nextInt();
        int[] list = new int[size];
        for (int i = 0; i < size; i++) {
            list[i] = input.nextInt();
        }
        partition(list);
        System.out.print("After the partition, the list is ");
        for (int i = 0; i < size; i++) {
            System.out.print(list[i] + " ");
        }
        System.out.println();
    }
}

