public class SortStudents {
    public static void main(String[] args) {
        List<Student> students = new ArrayList<>();
        students.add(new Student("Alice", 8));
        students.add(new Student("Bob", 6));
        students.add(new Student("Charlie", 9));
        students.add(new Student("Dave", 7));

        Collections.sort(students, new Comparator<Student>() {
            @Override
            public int compare(Student s1, Student s2) {
                return Integer.compare(s1.getNumCorrectAnswers(), s2.getNumCorrectAnswers());
            }
        });

        for (Student student : students) {
            System.out.println(student);
        }
    }
}

import java.io.*;
import java.net.*;

class HttpServer {

    public static void main(String[] args) throws IOException {
        // Create a server socket on port 8080
        ServerSocket serverSocket = new ServerSocket(8080);

        while (true) {
            // Wait for a client to connect
            Socket clientSocket = serverSocket.accept();

            // Get input and output streams for the socket
            BufferedReader in = new BufferedReader(new InputStreamReader(clientSocket.getInputStream()));
            PrintWriter out = new PrintWriter(clientSocket.getOutputStream(), true);

            // Read the incoming HTTP request
            String request = in.readLine();

            // Send back an HTTP response
            out.println("HTTP/1.1 200 OK");
            out.println("Content-Type: text/html");
            out.println("Content-Length: " + "Hello World!".length());
            out.println();
            out.println("Hello World!");

            // Close the socket
            clientSocket.close();
        }
    }
}

import java.io.*;
import java.net.*;

public class ScoreReader {
    public static void main(String[] args) {
        try {
            URL url = new URL("http://cs.armstrong.edu/liang/data/Scores.txt");
            BufferedReader in = new BufferedReader(new InputStreamReader(url.openStream()));

            String line;
            double sum = 0;
            int count = 0;

            while ((line = in.readLine()) != null) {
                String[] scores = line.split("\\s+");
                for (String score : scores) {
                    sum += Double.parseDouble(score);
                    count++;
                }
            }

            in.close();

            System.out.println("Total: " + sum);
            System.out.println("Average: " + sum / count);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

public class MyRectangle2D {
    private double x;
    private double y;
    private double width;
    private double height;

    public MyRectangle2D() {
        this(0, 0, 1, 1);
    }

    public MyRectangle2D(double x, double y, double width, double height) {
        this.x = x;
        this.y = y;
        this.width = width;
        this.height = height;
    }

    public double getX() {
        return x;
    }

    public void setX(double x) {
        this.x = x;
    }

    public double getY() {
        return y;
    }

    public void setY(double y) {
        this.y = y;
    }

    public double getWidth() {
        return width;
    }

    public void setWidth(double width) {
        this.width = width;
    }

    public double getHeight() {
        return height;
    }

    public void setHeight(double height) {
        this.height = height;
    }

    public double getArea() {
        return width * height;
    }

    public double getPerimeter() {
        return 2 * (width + height);
    }

    public boolean contains(double x, double y) {
        return Math.abs(x - this.x) <= width / 2 && Math.abs(y - this.y) <= height / 2;
    }

    public boolean contains(MyRectangle2D r) {
        return contains(r.getX() - r.getWidth() / 2, r.getY() + r.getHeight() / 2) &&
               contains(r.getX() - r.getWidth() / 2, r.getY() - r.getHeight() / 2) &&
               contains(r.getX() + r.getWidth() / 2, r.getY() + r.getHeight() / 2) &&
               contains(r.getX() + r.getWidth() / 2, r.getY() - r.getHeight() / 2);
    }

    public boolean overlaps(MyRectangle2D r) {
        double x1 = x - width / 2;
        double y1 = y + height / 2;
        double x2 = x + width / 2;
        double y2 = y - height / 2;

        double rx1 = r.getX() - r.getWidth() / 2;
        double ry1 = r.getY() + r.getHeight() / 2;
        double rx2 = r.getX() + r.getWidth() / 2;
        double ry2 = r.getY() - r.getHeight() / 2;

        return !(rx2 < x1 || rx1 > x2 || ry2 > y1 || ry1 < y2);
    }
}

import com.ibm.icu.util.ChineseCalendar;
import java.util.Scanner;

public class LunarMonthDays {
    public static void main(String[] args) {
        // Create a scanner to read input from the user
        Scanner scanner = new Scanner(System.in);

        // Prompt the user to enter the lunar month and year
        System.out.print("Enter the lunar month (1-12): ");
        int month = scanner.nextInt();
        System.out.print("Enter the lunar year: ");
        int year = scanner.nextInt();

        // Create a Chinese Calendar object for the given year and month
        ChineseCalendar calendar = new ChineseCalendar();
        calendar.set(ChineseCalendar.EXTENDED_YEAR, year + 2637); // Convert from the lunar year to the Gregorian year
        calendar.set(ChineseCalendar.MONTH, month - 1); // ChineseCalendar.MONTH is 0-based

        // Compute the number of days in the lunar month
        int days = calendar.getActualMaximum(ChineseCalendar.DAY_OF_MONTH);

        // Output the result
        System.out.println("The number of days in the lunar month is " + days);
    }
}

import java.util.*;

public class CountOccurrenceOfWords {
    public static void main(String[] args) {
        // Set text in a string
        String text = "Good morning. Have a good class. " +
                "Have a good visit. Have fun!";

        // Create a TreeMap to hold words as key and count as value
        Map<String, Integer> map = new TreeMap<>();

        String[] words = text.split("[\\s+\\p{P}]");
        for (String word : words) {
            String key = word.toLowerCase();

            if (key.length() > 0) {
                if (!map.containsKey(key)) {
                    map.put(key, 1);
                } else {
                    int value = map.get(key);
                    value++;
                    map.put(key, value);
                }
            }
        }

        // Create an array list from the entries in the map
        List<WordOccurrence> list = new ArrayList<>();
        for (Map.Entry<String, Integer> entry : map.entrySet()) {
            list.add(new WordOccurrence(entry.getKey(), entry.getValue()));
        }

        // Sort the list
        Collections.sort(list);

        // Display the words in ascending order of occurrence counts
        for (WordOccurrence wo : list) {
            System.out.println(wo.getWord() + " " + wo.getCount());
        }
    }
}

class WordOccurrence implements Comparable<WordOccurrence> {
    private String word;
    private int count;

    public WordOccurrence(String word, int count) {
        this.word = word;
        this.count = count;
    }

    public String getWord() {
        return word;
    }

    public int getCount() {
        return count;
    }

    @Override
    public int compareTo(WordOccurrence o) {
        if (count > o.count) {
            return 1;
        } else if (count < o.count) {
            return -1;
        } else {
            return 0;
        }
    }
}

public class Course {
    private String courseName;
    private String[] students = new String[1];
    private int numberOfStudents;

    public Course(String courseName) {
        this.courseName = courseName;
    }

    public String getCourseName() {
        return courseName;
    }

    public void addStudent(String student) {
        if (numberOfStudents == students.length) {
            String[] newStudents = new String[students.length * 2];
            System.arraycopy(students, 0, newStudents, 0, students.length);
            students = newStudents;
        }
        students[numberOfStudents++] = student;
    }

    public void dropStudent(String student) {
        for (int i = 0; i < numberOfStudents; i++) {
            if (students[i].equals(student)) {
                students[i] = null;
                System.arraycopy(students, i + 1, students, i, numberOfStudents - i - 1);
                numberOfStudents--;
                break;
            }
        }
    }

    public void clear() {
        students = new String[1];
        numberOfStudents = 0;
    }

    public String[] getStudents() {
        return students;
    }

    public int getNumberOfStudents() {
        return numberOfStudents;
    }
}

import java.util.Scanner;

public class ISBNChecker {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter the first 12 digits of the ISBN-13: ");
        String input = scanner.nextLine();

        // Convert input to integer array
        int[] digits = new int[12];
        for (int i = 0; i < 12; i++) {
            digits[i] = Character.getNumericValue(input.charAt(i));
        }

        // Calculate checksum
        int sum = 0;
        for (int i = 0; i < 12; i++) {
            if (i % 2 == 0) {
                sum += digits[i];
            } else {
                sum += digits[i] * 3;
            }
        }
        int checksum = 10 - (sum % 10);
        if (checksum == 10) {
            checksum = 0;
        }

        // Output complete ISBN-13
        System.out.println("The complete ISBN-13 is: " + input + checksum);
    }
}

import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.File;
import java.io.FileReader;
import java.io.FileWriter;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Random;

public class IntegerFileIO {

    public static void main(String[] args) {
        File file = new File("Exercise12_15.txt");

        // Create the file if it does not exist
        if (!file.exists()) {
            try {
                file.createNewFile();
            } catch (IOException e) {
                System.err.println("Error creating file: " + e.getMessage());
                System.exit(1);
            }
        }

        // Generate 100 random integers and write them to the file
        Random random = new Random();
        try (BufferedWriter bw = new BufferedWriter(new FileWriter(file))) {
            for (int i = 0; i < 100; i++) {
                int num = random.nextInt(1000);
                bw.write(num + " ");
            }
        } catch (IOException e) {
            System.err.println("Error writing to file: " + e.getMessage());
            System.exit(1);
        }

        // Read the integers from the file and store them in an ArrayList
        ArrayList<Integer> nums = new ArrayList<>();
        try (BufferedReader br = new BufferedReader(new FileReader(file))) {
            String line = br.readLine();
            String[] tokens = line.split(" ");
            for (String token : tokens) {
                nums.add(Integer.parseInt(token));
            }
        } catch (IOException e) {
            System.err.println("Error reading from file: " + e.getMessage());
            System.exit(1);
        }

        // Sort the integers in increasing order
        Collections.sort(nums);

        // Display the integers in increasing order
        for (int num : nums) {
            System.out.println(num);
        }
    }

}

