import java.util.Scanner;

public class VowelConsonantChecker {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter a letter: ");
        String letter = scanner.nextLine().toLowerCase();

        if (letter.length() != 1) {
            System.out.println("Please enter a single letter.");
            return;
        }

        char ch = letter.charAt(0);

        if (ch >= 'a' && ch <= 'z') {
            if (ch == 'a' || ch == 'e' || ch == 'i' || ch == 'o' || ch == 'u') {
                System.out.println("The letter " + ch + " is a vowel.");
            } else {
                System.out.println("The letter " + ch + " is a consonant.");
            }
        } else {
            System.out.println("Please enter a valid letter.");
        }
    }
}

class Node {
    int data;
    Node left, right;

    public Node(int item) {
        data = item;
        left = right = null;
    }
}

class BinaryTree {
    Node root;

    // Returns true if the given tree is perfect
    public boolean isPerfect(Node root) {
        // An empty tree is perfect
        if (root == null) {
            return true;
        }

        // Get the height of left and right sub-trees
        int leftHeight = height(root.left);
        int rightHeight = height(root.right);

        // If the height of left and right sub-trees differ more than 1,
        // the tree is not perfect
        if (Math.abs(leftHeight - rightHeight) > 1) {
            return false;
        }

        // If the left and right sub-trees are perfect and the current node
        // is a leaf node, the tree is perfect
        if (isPerfect(root.left) && isPerfect(root.right) && isLeaf(root)) {
            return true;
        }

        // If none of the above conditions are true, the tree is not perfect
        return false;
    }

    // Returns true if the given node is a leaf node
    public boolean isLeaf(Node node) {
        if (node == null) {
            return false;
        }
        if (node.left == null && node.right == null) {
            return true;
        }
        return false;
    }

    // Returns the height of the given tree
    public int height(Node node) {
        if (node == null) {
            return 0;
        }
        return 1 + Math.max(height(node.left), height(node.right));
    }
}



// The isPerfect method takes the root of a binary tree as input and returns true if the tree is perfect, and false otherwise. It uses recursion to check if the tree is perfect by checking the following conditions:

// The left and right sub-trees have the same height
// The left and right sub-trees are perfect
// The current node is a leaf node
// The method uses two helper methods, isLeaf and height, to check if a node is a leaf node and to find the height of the tree respectively.

// The isLeaf method checks if a node is a leaf node by checking if it has no children.
// The height method finds the height of the tree by recursively calling the method on the left and right children of a node and returning the maximum height.

// This program uses a class `Node

import java.io.*;

public class Exercise17_10 {
    public static void main(String[] args) throws IOException {
        // Check the number of arguments
        if (args.length != 2) {
            System.out.println("Usage: java Exercise17_10 sourceFile numberOfPieces");
            System.exit(1);
        }

        // Get the input file name and number of output files
        String sourceFile = args[0];
        int numberOfPieces = Integer.parseInt(args[1]);

        // Create a buffered input stream to read the source file
        BufferedInputStream input = new BufferedInputStream(new FileInputStream(sourceFile));

        // Get the size of the source file in bytes
        long fileSize = new File(sourceFile).length();

        // Calculate the size of each output file in bytes
        long pieceSize = fileSize / numberOfPieces;
        long lastPieceSize = fileSize - (numberOfPieces - 1) * pieceSize;

        // Create the output files
        for (int i = 0; i < numberOfPieces; i++) {
            String outputFileName = sourceFile + ".part" + i;
            BufferedOutputStream output = new BufferedOutputStream(new FileOutputStream(outputFileName));

            // Write the bytes to the output file
            if (i == numberOfPieces - 1) {
                // Last piece
                byte[] lastPiece = new byte[(int) lastPieceSize];
                input.read(lastPiece);
                output.write(lastPiece);
            } else {
                byte[] piece = new byte[(int) pieceSize];
                input.read(piece);
                output.write(piece);
            }

            // Close the output stream
            output.close();
        }

        // Close the input stream
        input.close();

        System.out.println("File split successfully into " + numberOfPieces + " pieces.");
    }
}

import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Scanner;

public class MD5Hash {
    public static void main(String[] args) throws NoSuchAlgorithmException {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter the string to be hashed: ");
        String input = sc.nextLine();
        sc.close();
        MessageDigest md = MessageDigest.getInstance("MD5");
        md.update(input.getBytes());
        byte[] digest = md.digest();
        StringBuilder sb = new StringBuilder();
        for (byte b : digest) {
            sb.append(String.format("%02x", b & 0xff));
        }
        System.out.println("MD5 hash of the input string is: " + sb.toString());
    }
}


// In this program, the user is prompted to enter a string, which is then read by a Scanner object. The MessageDigest class is used to create a message digest object with the algorithm "MD5" which is then used to calculate the hash of the input string. The update method is used to update the digest with the bytes of the input string. The digest method is used to calculate the hash and return it as a byte array.

// The bytes of the digest are then converted to a hexadecimal string using a StringBuilder object. The String.format("%02x", b & 0xff) is used to format each byte as a 2-digit hexadecimal number.

// The final output is the MD5 hash of the input string.

// Please note that MD5 is a hashing algorithm that has been found to be vulnerable to collisions and it is recommended to use a stronger hashing algorithm like SHA-256 or SHA-3.

// ====================================================

// 2nd attempt

import java.math.BigInteger;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class MD5Hash {
    public static String getMD5(String input) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] messageDigest = md.digest(input.getBytes());
            BigInteger no = new BigInteger(1, messageDigest);
            String hashtext = no.toString(16);
            while (hashtext.length() < 32) {
                hashtext = "0" + hashtext;
            }
            return hashtext;
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }
    }

    public static void main(String[] args) {
        String input = "example_string";
        System.out.println("MD5 hash of the input string is: " + getMD5(input));
    }
}


