import java.util.Scanner;

public class CalendarTable {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        System.out.print("Enter the year: ");
        int year = input.nextInt();
        System.out.print("Enter the first day of the year (0 for Sunday, 1 for Monday, etc.): ");
        int firstDay = input.nextInt();

        for (int month = 1; month <= 12; month++) {
            System.out.print(getMonthName(month) + " " + year + "\n");
            System.out.print("Sun Mon Tue Wed Thu Fri Sat\n");

            int numDays = getNumDays(month, year);
            int startDay = (firstDay + getNumDaysInYear(month, year)) % 7;
            int day = 1;
            for (int i = 0; i < startDay; i++) {
                System.out.print("    ");
            }
            for (int i = startDay; i < 7; i++) {
                System.out.printf("%3d ", day);
                day++;
            }
            System.out.println();

            while (day <= numDays) {
                for (int i = 0; i < 7 && day <= numDays; i++) {
                    System.out.printf("%3d ", day);
                    day++;
                }
                System.out.println();
            }
            System.out.println();

            firstDay = (firstDay + numDays) % 7;
        }
    }

    public static String getMonthName(int month) {
        switch (month) {
            case 1: return "January";
            case 2: return "February";
            case 3: return "March";
            case 4: return "April";
            case 5: return "May";
            case 6: return "June";
            case 7: return "July";
            case 8: return "August";
            case 9: return "September";
            case 10: return "October";
            case 11: return "November";
            case 12: return "December";
            default: return "";
        }
    }

    public static int getNumDays(int month, int year) {
        switch (month) {
            case 1: case 3: case 5: case 7: case 8: case 10: case 12:
                return 31;
            case 4: case 6: case 9: case 11:
                return 30;
            case 2:
                if (isLeapYear(year)) {
                    return 29;
                } else {
                    return 28;
                }
            default:
                return 0;
        }
    }

    public static boolean isLeapYear(int year) {
        return year % 4 == 0 && (year % 100 != 0 || year % 400 == 0);
    }

    public static int getNumDaysInYear(int month, int year) {
        int numDays = 0;
        for (int i = 1; i < month; i++) {
            numDays += getNumDays(i, year);
        }
        return numDays;
    }
}

import java.util.Scanner;

public class CommonPrefix {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter the first string: ");
        String str1 = scanner.nextLine();
        System.out.print("Enter the second string: ");
        String str2 = scanner.nextLine();

        // Find length of common prefix
        int len = Math.min(str1.length(), str2.length());
        int i;
        for (i = 0; i < len; i++) {
            if (str1.charAt(i) != str2.charAt(i)) {
                break;
            }
        }

        // Output common prefix
        String commonPrefix = str1.substring(0, i);
        if (commonPrefix.length() > 0) {
            System.out.println("The common prefix is: " + commonPrefix);
        } else {
            System.out.println("There is no common prefix.");
        }
    }
}

import java.util.ArrayList;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        ArrayList<Integer> list = new ArrayList<>();
        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter a sequence of numbers (end with 0): ");
        int number;
        do {
            number = scanner.nextInt();
            if (number != 0) {
                list.add(number);
            }
        } while (number != 0);

        Integer max = max(list);
        if (max != null) {
            System.out.println("The largest number is " + max);
        } else {
            System.out.println("The list is empty.");
        }
    }

    public static Integer max(ArrayList<Integer> list) {
        if (list == null || list.size() == 0) {
            return null;
        }

        int max = list.get(0);
        for (int i = 1; i < list.size(); i++) {
            int number = list.get(i);
            if (number > max) {
                max = number;
            }
        }

        return max;
    }
}

import java.util.Scanner;

public class ArrayAverage {

    public static int average(int[] array) {
        int sum = 0;
        for (int i = 0; i < array.length; i++) {
            sum += array[i];
        }
        return sum / array.length;
    }

    public static double average(double[] array) {
        double sum = 0.0;
        for (int i = 0; i < array.length; i++) {
            sum += array[i];
        }
        return sum / array.length;
    }

    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);

        double[] array = new double[10];

        System.out.print("Enter ten double values: ");
        for (int i = 0; i < array.length; i++) {
            array[i] = input.nextDouble();
        }

        System.out.println("The average value is " + average(array));
    }
}

