import java.util.LinkedList;
import java.util.List;
import java.util.ListIterator;
import java.util.Random;

public class LinkedListIteratorVsGetTest {
    public static void main(String[] args) {
        // Create a linked list and add 5 million random integers to it
        List<Integer> list = new LinkedList<>();
        Random random = new Random();
        for (int i = 0; i < 5000000; i++) {
            list.add(random.nextInt());
        }

        // Traverse the list using an iterator and measure the time it takes
        long start = System.currentTimeMillis();
        ListIterator<Integer> iterator = list.listIterator();
        while (iterator.hasNext()) {
            int value = iterator.next();
        }
        long end = System.currentTimeMillis();
        long iteratorTime = end - start;

        // Traverse the list using get(index) and measure the time it takes
        start = System.currentTimeMillis();
        for (int i = 0; i < list.size(); i++) {
            int value = list.get(i);
        }
        end = System.currentTimeMillis();
        long getTime = end - start;

        // Print the results
        System.out.println("Iterator time: " + iteratorTime + " ms");
        System.out.println("Get time: " + getTime + " ms");
    }
}

import java.io.File;
import java.util.Scanner;

public class FileCount {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        System.out.print("Enter a directory: ");
        String directoryPath = input.nextLine();
        File directory = new File(directoryPath);
        int fileCount = countFiles(directory);
        System.out.println("The directory " + directoryPath + " contains " + fileCount + " files.");
    }

    public static int countFiles(File directory) {
        int count = 0;
        File[] files = directory.listFiles();
        if (files != null) {
            // Count the files in the current directory
            for (File file : files) {
                if (file.isFile()) {
                    count++;
                }
            }
            // Recursively count the files in the subdirectories
            for (File subdir : files) {
                if (subdir.isDirectory()) {
                    count += countFiles(subdir);
                }
            }
        }
        return count;
    }
}

--------------------------------
|            Fan               |
--------------------------------
| - SLOW: int = 1              |
| - MEDIUM: int = 2            |
| - FAST: int = 3              |
| - speed: int = SLOW          |
| - on: boolean = false        |
| - radius: double = 5.0       |
| - color: String = "blue"     |
--------------------------------
| + getSpeed(): int            |
| + setSpeed(speed: int): void |
| + isOn(): boolean            |
| + setOn(on: boolean): void   |
| + getRadius(): double        |
| + setRadius(radius: double): void |
| + getColor(): String         |
| + setColor(color: String): void |
| + Fan()                      |
| + toString(): String         |
--------------------------------
 public class Fan {
    // Constants
    public static final int SLOW = 1;
    public static final int MEDIUM = 2;
    public static final int FAST = 3;

    // Fields
    private int speed;
    private boolean on;
    private double radius;
    private String color;

    // Constructors
    public Fan() {
        speed = SLOW;
        on = false;
        radius = 5.0;
        color = "blue";
    }

    // Accessor and mutator methods
    public int getSpeed() {
        return speed;
    }

    public void setSpeed(int speed) {
        this.speed = speed;
    }

    public boolean isOn() {
        return on;
    }

    public void setOn(boolean on) {
        this.on = on;
    }

    public double getRadius() {
        return radius;
    }

    public void setRadius(double radius) {
        this.radius = radius;
    }

    public String getColor() {
        return color;
    }

    public void setColor(String color) {
        this.color = color;
    }

    // toString method
    public String toString() {
        if (on) {
            return "speed=" + speed + ", color=" + color + ", radius=" + radius;
        } else {
            return "color=" + color + ", radius=" + radius + ", fan is off";
        }
    }
}

public static <E extends Comparable<E>> int linearSearch(E[] list, E key) {
    for (int i = 0; i < list.length; i++) {
        if (list[i].compareTo(key) == 0) {
            return i; // return the index of the key if found
        }
    }
    return -1; // return -1 if the key is not found
}

import java.util.Arrays;

public class LocalityOfReferenceSearch {

    private static final int CACHE_SIZE = 3; // Size of the cache

    public static int search(int[] arr, int x) {
        int cache[] = new int[CACHE_SIZE]; // Cache to store recently accessed elements
        Arrays.fill(cache, -1);

        int n = arr.length;
        int i = 0;
        while (i < n) {
            boolean found = false;
            for (int j = 0; j < CACHE_SIZE; j++) {
                if (cache[j] == arr[i]) { // If element is in cache, return its index
                    return i;
                }
            }
            for (int j = 0; j < CACHE_SIZE - 1; j++) {
                cache[j] = cache[j + 1]; // Shift the cache
            }
            cache[CACHE_SIZE - 1] = arr[i]; // Add current element to cache
            i++;
        }
        return -1; // Element not found
    }

    public static void main(String[] args) {
        int[] arr = { 1, 2, 3, 4, 5, 6, 7, 8, 9 };
        int x = 5;
        int index = search(arr, x);
        if (index != -1) {
            System.out.println("Element " + x + " found at index " + index);
        } else {
            System.out.println("Element " + x + " not found");
        }
    }
}

import java.awt.BorderLayout;
import java.awt.Dimension;
import java.awt.event.ActionEvent;
import java.awt.event.ActionListener;
import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.IOException;
import javax.swing.JButton;
import javax.swing.JFileChooser;
import javax.swing.JFrame;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextArea;
import javax.swing.JTextField;
import javax.swing.UIManager;
import javax.swing.UnsupportedLookAndFeelException;

public class BinaryEditor extends JFrame {

    private JTextField fileNameTextField;
    private JTextArea binaryTextArea;
    private JButton openButton;
    private JButton saveButton;

    public BinaryEditor() {
        super("Binary Editor");
        initComponents();
        setSize(new Dimension(800, 600));
        setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        setLocationRelativeTo(null);
        setVisible(true);
    }

    private void initComponents() {
        fileNameTextField = new JTextField();
        fileNameTextField.addActionListener(new ActionListener() {
            @Override
            public void actionPerformed(ActionEvent e) {
                openFile();
            }
        });

        binaryTextArea = new JTextArea();
        binaryTextArea.setEditable(true);

        JScrollPane scrollPane = new JScrollPane(binaryTextArea);

        openButton = new JButton("Open");
        openButton.addActionListener(new ActionListener() {
            @Override
            public void actionPerformed(ActionEvent e) {
                openFile();
            }
        });

        saveButton = new JButton("Save");
        saveButton.addActionListener(new ActionListener() {
            @Override
            public void actionPerformed(ActionEvent e) {
                saveFile();
            }
        });

        JPanel buttonPanel = new JPanel();
        buttonPanel.add(openButton);
        buttonPanel.add(saveButton);

        add(fileNameTextField, BorderLayout.NORTH);
        add(scrollPane, BorderLayout.CENTER);
        add(buttonPanel, BorderLayout.SOUTH);
    }

    private void openFile() {
        JFileChooser fileChooser = new JFileChooser();
        int result = fileChooser.showOpenDialog(this);
        if (result == JFileChooser.APPROVE_OPTION) {
            File file = fileChooser.getSelectedFile();
            fileNameTextField.setText(file.getAbsolutePath());
            try {
                FileInputStream fis = new FileInputStream(file);
                StringBuilder sb = new StringBuilder();
                int i = 0;
                while ((i = fis.read()) != -1) {
                    sb.append(String.format("%8s", Integer.toBinaryString(i)).replace(' ', '0'));
                    sb.append(" ");
                }
                binaryTextArea.setText(sb.toString());
                fis.close();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }

    private void saveFile() {
        JFileChooser fileChooser = new JFileChooser();
        int result = fileChooser.showSaveDialog(this);
        if (result == JFileChooser.APPROVE_OPTION) {
            File file = fileChooser.getSelectedFile();
            try {
                FileOutputStream fos = new FileOutputStream(file);
                String binaryText = binaryTextArea.getText().replaceAll("\\s", "");
                for (int i = 0; i < binaryText.length(); i += 8) {
                    String binaryByte = binaryText.substring(i, i + 8);
                    fos.write(Integer.parseInt(binaryByte, 2));
                }
                fos.close();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }

    public static void main(String[] args) {
        try {
            UIManager.setLookAndFeel(UIManager.getSystemLookAndFeelClassName());
        } catch (ClassNotFoundException | InstantiationException | IllegalAccessException | UnsupportedLookAndFeelException e) {
            e.printStackTrace();
        }
        new BinaryEditor();
    }
}

import java.util.Scanner;

public class DivisibleBy5And6 {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);

        System.out.print("Enter an integer: ");
        int number = input.nextInt();

        boolean divisibleBy5And6 = (number % 5 == 0) && (number % 6 == 0);
        boolean divisibleBy5Or6 = (number % 5 == 0) || (number % 6 == 0);
        boolean divisibleBy5Or6ButNotBoth = (number % 5 == 0) ^ (number % 6 == 0);

        System.out.println(number + " is divisible by 5 and 6? " + divisibleBy5And6);
        System.out.println(number + " is divisible by 5 or 6? " + divisibleBy5Or6);
        System.out.println(number + " is divisible by 5 or 6, but not both? " + divisibleBy5Or6ButNotBoth);
    }
}

import javafx.application.Application;
import javafx.geometry.Point2D;
import javafx.scene.Group;
import javafx.scene.Scene;
import javafx.scene.paint.Color;
import javafx.scene.shape.Circle;
import javafx.scene.shape.Line;
import javafx.stage.Stage;

import java.util.Random;

public class TwoCircles extends Application {

    private final int RADIUS = 15;
    private final int WINDOW_WIDTH = 500;
    private final int WINDOW_HEIGHT = 500;

    @Override
    public void start(Stage primaryStage) throws Exception {
        // Create a Group to hold the circles and line
        Group root = new Group();

        // Create the two circles with random centers
        Random random = new Random();
        Circle circle1 = new Circle(random.nextInt(WINDOW_WIDTH), random.nextInt(WINDOW_HEIGHT), RADIUS, Color.RED);
        Circle circle2 = new Circle(random.nextInt(WINDOW_WIDTH), random.nextInt(WINDOW_HEIGHT), RADIUS, Color.BLUE);

        // Calculate the line endpoints to avoid crossing inside the circles
        Point2D point1 = new Point2D(circle1.getCenterX(), circle1.getCenterY());
        Point2D point2 = new Point2D(circle2.getCenterX(), circle2.getCenterY());
        Point2D direction = point2.subtract(point1).normalize();
        Point2D offset1 = direction.multiply(RADIUS);
        Point2D offset2 = direction.multiply(-RADIUS);
        Point2D lineStart = point1.add(offset1);
        Point2D lineEnd = point2.add(offset2);

        // Create the line with the calculated endpoints
        Line line = new Line(lineStart.getX(), lineStart.getY(), lineEnd.getX(), lineEnd.getY());
        line.setStrokeWidth(2);
        line.setStroke(Color.GREEN);

        // Add the circles and line to the root Group
        root.getChildren().addAll(circle1, circle2, line);

        // Create the Scene and set it on the Stage
        Scene scene = new Scene(root, WINDOW_WIDTH, WINDOW_HEIGHT);
        primaryStage.setScene(scene);
        primaryStage.setTitle("Two Circles");
        primaryStage.show();
    }

    public static void main(String[] args) {
        launch(args);
    }
}

import java.util.Scanner;

public class EvaluateExpression {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        System.out.print("Enter an expression: ");
        String expression = input.nextLine();
        input.close();
        try {
            System.out.println(expression + " = " + evaluateExpression(expression));
        } catch (Exception e) {
            System.out.println("Invalid expression");
        }
    }

    public static int evaluateExpression(String expression) throws Exception {
        expression = expression.replaceAll("\\s", ""); // Remove whitespace
        expression = expression.replaceAll("\\^", "**"); // Replace ^ with ** for exponentiation
        int result = evaluateTerm(expression);
        while (expression.length() > 0) {
            char operator = expression.charAt(0);
            if (operator != '+' && operator != '-' && operator != '*' && operator != '/' && operator != '%') {
                throw new Exception("Invalid operator: " + operator);
            }
            expression = expression.substring(1);
            int term = evaluateTerm(expression);
            switch (operator) {
                case '+':
                    result += term;
                    break;
                case '-':
                    result -= term;
                    break;
                case '*':
                    result *= term;
                    break;
                case '/':
                    result /= term;
                    break;
                case '%':
                    result %= term;
                    break;
                default:
                    throw new Exception("Invalid operator: " + operator);
            }
        }
        return result;
    }

    public static int evaluateTerm(String expression) throws Exception {
        if (expression.charAt(0) == '(') {
            int count = 1;
            for (int i = 1; i < expression.length(); i++) {
                if (expression.charAt(i) == '(') {
                    count++;
                } else if (expression.charAt(i) == ')') {
                    count--;
                    if (count == 0) {
                        int result = evaluateExpression(expression.substring(1, i));
                        expression = expression.substring(i + 1);
                        if (expression.length() > 0 && expression.charAt(0) == '^') {
                            // Handle exponentiation
                            expression = expression.substring(1);
                            int exponent = evaluateTerm(expression);
                            result = (int) Math.pow(result, exponent);
                        }
                        return result;
                    }
                }
            }
            throw new Exception("Unmatched parentheses");
        } else {
            int endIndex = 1;
            while (endIndex < expression.length() && Character.isDigit(expression.charAt(endIndex))) {
                endIndex++;
            }
            int result = Integer.parseInt(expression.substring(0, endIndex));
            expression = expression.substring(endIndex);
            if (expression.length() > 0 && expression.charAt(0) == '^') {
                // Handle exponentiation
                expression = expression.substring(1);
                int exponent = evaluateTerm(expression);
                result = (int) Math.pow(result, exponent);
            }
            return result;
        }
    }
}

import org.apache.commons.math3.fitting.SimpleCurveFitter;
import org.apache.commons.math3.fitting.WeightedObservedPoints;

public class LinearRegression {
    public static void main(String[] args) {
        // create some sample data
        double[] x = {1, 2, 3, 4, 5};
        double[] y = {2, 4, 6, 8, 10};

        // create a fitter
        SimpleCurveFitter fitter = SimpleCurveFitter.create(new org.apache.commons.math3.fitting.PolynomialCurveFitter.Order(1));

        // add data
        WeightedObservedPoints obs = new WeightedObservedPoints();
        for (int i = 0; i < x.length; i++) {
            obs.add(x[i], y[i]);
        }

        // fit the data
        double[] bestFit = fitter.fit(obs.toList());

        // get the coefficients
        double slope = bestFit[1];
        double intercept = bestFit[0];

        // print the results
        System.out.println("Slope: " + slope);
        System.out.println("Intercept: " + intercept);
    }
}

public class SqrtApproximation {
    public static void main(String[] args) {
        long n = 144;
        double sqrtN = sqrt(n);
        System.out.printf("The square root of %d is approximately %.4f\n", n, sqrtN);
    }

    public static double sqrt(long n) {
        double lastGuess = 1.0;
        double nextGuess = (lastGuess + n / lastGuess) / 2.0;
        while (Math.abs(nextGuess - lastGuess) > 0.0001) {
            lastGuess = nextGuess;
            nextGuess = (lastGuess + n / lastGuess) / 2.0;
        }
        return nextGuess;
    }
}

public static int bin2Dec(String binaryString) throws NumberFormatException {
    int decimal = 0;
    for (int i = 0; i < binaryString.length(); i++) {
        char ch = binaryString.charAt(i);
        if (ch < '0' || ch > '1') {
            throw new NumberFormatException("Invalid binary string: " + binaryString);
        }
        decimal = decimal * 2 + (ch - '0');
    }
    return decimal;
}

import java.util.ArrayList;
import java.util.List;

public class Main {
    // Number of vertices
    private int V;
    // Adjacency List
    private List<Integer>[] adj;

    public Main(int V) {
        this.V = V;
        // Create a new array of lists
        adj = (ArrayList<Integer>[]) new ArrayList[V];
        // Initialize each list
        for (int i = 0; i < V; i++) {
            adj[i] = new ArrayList<Integer>();
        }
    }

    // Function to add an edge to the graph
    public void addEdge(int v, int w) {
        adj[v].add(w);
    }

    // DFS traversal of the vertices reachable from v
    public void DFS(int v, boolean[] visited) {
        // Mark the current node as visited
        visited[v] = true;
        System.out.print(v + " ");
        // Recur for all the vertices adjacent to this vertex
        for (int i = 0; i < adj[v].size(); i++) {
            int n = adj[v].get(i);
            if (!visited[n]) {
                DFS(n, visited);
            }
        }
    }

    public static void main(String[] args) {
        // Create a graph
        Main g = new Main(4);
        g.addEdge(0, 1);
        g.addEdge(0, 2);
        g.addEdge(1, 2);
        g.addEdge(2, 0);
        g.addEdge(2, 3);
        g.addEdge(3, 3);

        System.out.println("Following is Depth First Traversal");

        boolean[] visited = new boolean[4];
        g.DFS(2, visited);
    }
}

import java.util.Scanner;

public class PasswordChecker {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);

        // Prompt the user to enter a password
        System.out.print("Enter a password: ");
        String password = input.nextLine();

        // Check if the password is valid
        if (checkPassword(password)) {
            System.out.println("Valid Password");
        } else {
            System.out.println("Invalid Password");
        }
    }

    public static boolean checkPassword(String password) {
        // Check if the password has at least 8 characters
        if (password.length() < 8) {
            return false;
        }

        // Check if the password consists of only letters and digits
        for (int i = 0; i < password.length(); i++) {
            char ch = password.charAt(i);
            if (!Character.isLetterOrDigit(ch)) {
                return false;
            }
        }

        // Check if the password contains at least two digits
        int count = 0;
        for (int i = 0; i < password.length(); i++) {
            char ch = password.charAt(i);
            if (Character.isDigit(ch)) {
                count++;
            }
        }
        if (count < 2) {
            return false;
        }

        // If all checks pass, the password is valid
        return true;
    }
}

import java.util.*;

public class TwelveHourClock {
    public static void main(String[] args) {
        // Create a scanner to get input from the user
        Scanner input = new Scanner(System.in);

        // Get the time zone offset from the user
        System.out.print("Enter the time zone offset to GMT: ");
        int offset = input.nextInt();

        // Get the current time
        Calendar cal = Calendar.getInstance();
        cal.setTimeZone(TimeZone.getTimeZone("GMT"));
        cal.add(Calendar.HOUR_OF_DAY, offset);
        int hour = cal.get(Calendar.HOUR);
        int minute = cal.get(Calendar.MINUTE);
        int second = cal.get(Calendar.SECOND);
        String ampm = cal.get(Calendar.AM_PM) == Calendar.AM ? "AM" : "PM";

        // Display the current time in 12-hour format
        System.out.printf("The current time is %d:%02d:%02d %s\n", hour, minute, second, ampm);
    }
}

public interface MyList<E> {

    // Add a new element at the end of this list
    public boolean add(E e);

    // Add a new element at the specified index in this list
    public void add(int index, E e);

    // Clear the list
    public void clear();

    // Return true if this list contains the element
    public boolean contains(E e);

    // Return the element from this list at the specified index
    public E get(int index);

    // Return the index of the first matching element in this list.
    // Return -1 if no match.
    public int indexOf(E e);

    // Return true if this list doesn't contain any elements
    public boolean isEmpty();

    // Return the index of the last matching element in this list
    // Return -1 if no match.
    public int lastIndexOf(E e);

    // Remove the first occurrence of the element e from this list.
    // Shift any subsequent elements to the left.
    // Return true if the element is removed.
    public boolean remove(E e);

    // Remove the element at the specified position in this list.
    // Shift any subsequent elements to the left.
    // Return the element that was removed from the list.
    public E remove(int index);

    // Replace the element at the specified position in this list
    // with the specified element and return the old element.
    public E set(int index, E e);

    // Return the number of elements in this list
    public int size();

    // Adds the elements in otherList to this list.
    // Returns true if this list changed as a result of the call
    public boolean addAll(MyList<? extends E> otherList);

    // Removes all the elements in otherList from this list
    // Returns true if this list changed as a result of the call
    public boolean removeAll(MyList<?> otherList);

    // Retains the elements in this list that are also in otherList
    // Returns true if this list changed as a result of the call
    public boolean retainAll(MyList<?> otherList);

}

