import java.util.Map;

public class DecisionTree {
    private Node root;

    public DecisionTree(Node root) {
        this.root = root;
    }

    public int predict(Map<String, Object> input) {
        Node current = root;
        while (current.getClassification() == null) {
            String feature = current.getFeature();
            Object value = input.get(feature);
            current = current.getChild(value);
        }
        return current.getClassification();
    }

    private static class Node {
        private String feature;
        private Map<Object, Node> children;
        private Integer classification;

        public Node(String feature, Map<Object, Node> children, Integer classification) {
            this.feature = feature;
            this.children = children;
            this.classification = classification;
        }

        public String getFeature() {
            return feature;
        }

        public Node getChild(Object value) {
            return children.get(value);
        }

        public Integer getClassification() {
            return classification;
        }
    }
}

import java.io.*;

public class BitOutputStream extends FilterOutputStream {
    private int buffer; // 8-bit buffer for storing bits
    private int numBitsInBuffer; // number of bits in the buffer

    public BitOutputStream(OutputStream out) {
        super(out);
        buffer = 0;
        numBitsInBuffer = 0;
    }

    public void writeBit(char bit) throws IOException {
        if (bit != '0' && bit != '1') {
            throw new IllegalArgumentException("Argument must be '0' or '1'");
        }
        buffer <<= 1;
        buffer |= (bit - '0');
        numBitsInBuffer++;
        if (numBitsInBuffer == 8) {
            flush();
        }
    }

    public void writeBit(String bitString) throws IOException {
        for (int i = 0; i < bitString.length(); i++) {
            writeBit(bitString.charAt(i));
        }
    }

    public void close() throws IOException {
        if (numBitsInBuffer > 0) {
            buffer <<= (8 - numBitsInBuffer);
            out.write(buffer);
        }
        super.close();
    }

    public void flush() throws IOException {
        if (numBitsInBuffer > 0) {
            buffer <<= (8 - numBitsInBuffer);
            out.write(buffer);
            buffer = 0;
            numBitsInBuffer = 0;
        }
    }
}
