            } else if (income <= 372950) {
                tax = 8350 * 0.10 + (33950 - 8350) * 0.15 +
                      (82250 - 33950) * 0.25 + (171550 - 82250) * 0.28 +
                      (income - 171550) * 0.33;
            } else {
                tax = 8350 * 0.10 + (33950 - 8350) * 0.15 +
                      (82250 - 33950) * 0.25 + (171550 - 82250) * 0.28 +
                      (372950 - 171550) * 0.33 + (income - 372950) * 0.35;
            }
        } else if (status == 1) { // Compute tax for married filing jointly or qualifying widow(er)
            // Similar to single filers but with different brackets and rates
            // ...
        } else if (status == 2) { // Compute tax for married filing separately
            // Similar to single filers but with different brackets and rates
            // ...
        } else if (status == 3) { // Compute tax for head of household
            // Similar to single filers but with different brackets and rates
            // ...
        } else {
            System.out.println("Error: invalid filing status");
            System.exit(1);
        }

        // Display the result
        System.out.println("Tax is " + (int)(tax * 100) / 100.0);
    }
}

public class Main {
    public static void main(String[] args) {
        for (int i = 10000; i <= 100000; i += 10000) {
            double pi = 0;
            for (int j = 0; j < i; j++) {
                int sign = j % 2 == 0 ? 1 : -1;
                double term = sign * (1.0 / (2 * j + 1));
                pi += term;
            }
            pi *= 4;
            System.out.println("pi for i = " + i + ": " + pi);
        }
    }
}

import java.io.BufferedReader;
import java.io.FileReader;
import java.util.Stack;

public class MatchGroupingSymbols {
    public static void main(String[] args) {
        if (args.length != 1) {
            System.out.println("Usage: java MatchGroupingSymbols filename.java");
            System.exit(1);
        }

        String filename = args[0];
        Stack<Character> stack = new Stack<>();

        try (BufferedReader reader = new BufferedReader(new FileReader(filename))) {
            String line;
            int lineNumber = 1;

            while ((line = reader.readLine()) != null) {
                for (int i = 0; i < line.length(); i++) {
                    char ch = line.charAt(i);

                    if (ch == '(' || ch == '{' || ch == '[') {
                        stack.push(ch);
                    } else if (ch == ')' || ch == '}' || ch == ']') {
                        if (stack.isEmpty()) {
                            System.out.printf("Error: no opening symbol for %c at line %d\n", ch, lineNumber);
                            return;
                        }

                        char top = stack.pop();

                        if (ch == ')' && top != '(' || ch == '}' && top != '{' || ch == ']' && top != '[') {
                            System.out.printf("Error: mismatched symbols %c and %c at line %d\n", top, ch, lineNumber);
                            return;
                        }
                    }
                }

                lineNumber++;
            }

            if (!stack.isEmpty()) {
                char top = stack.pop();
                System.out.printf("Error: no closing symbol for %c\n", top);
            } else {
                System.out.println("All grouping symbols are matched");
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}

import java.util.List;

public class EPC {
    public static double calculateEPC(List<Double> popularityScores) {
        int size = popularityScores.size();
        double epc = 0;
        double totalPopularity = 0;
        for (double score : popularityScores) {
            totalPopularity += score;
        }
        for (int i = 0; i < size; i++) {
            double popularity = popularityScores.get(i);
            epc += (1 - popularity / totalPopularity) * popularity;
        }
        return epc;
    }
}

public class Heap<E extends Comparable<E>> {
    private ArrayList<E> list = new ArrayList<>();

    public Heap() {
    }

    public Heap(E[] objects) {
        for (E object : objects) {
            add(object);
        }
    }

    public void add(E newObject) {
        list.add(newObject);
        int currentIndex = list.size() - 1;

        while (currentIndex > 0) {
            int parentIndex = (currentIndex - 1) / 2;
            if (list.get(currentIndex).compareTo(list.get(parentIndex)) < 0) {
                E temp = list.get(currentIndex);
                list.set(currentIndex, list.get(parentIndex));
                list.set(parentIndex, temp);
            } else {
                break;
            }
            currentIndex = parentIndex;
        }
    }

    public E remove() {
        if (list.size() == 0) {
            return null;
        }

        E removedObject = list.get(0);
        list.set(0, list.get(list.size() - 1));
        list.remove(list.size() - 1);

        int currentIndex = 0;
        while (currentIndex < list.size()) {
            int leftChildIndex = 2 * currentIndex + 1;
            int rightChildIndex = 2 * currentIndex + 2;

            if (leftChildIndex >= list.size()) {
                break;
            }
            int minIndex = leftChildIndex;
            if (rightChildIndex < list.size()) {
                if (list.get(minIndex).compareTo(list.get(rightChildIndex)) > 0) {
                    minIndex = rightChildIndex;
                }
            }

            if (list.get(currentIndex).compareTo(list.get(minIndex)) > 0) {
                E temp = list.get(minIndex);
                list.set(minIndex, list.get(currentIndex));
                list.set(currentIndex, temp);
                currentIndex = minIndex;
            } else {
                break;
            }
        }

        return removedObject;
    }

    public int getSize() {
        return list.size();
    }
}

