public class PrimeNumbers {
    public static void main(String[] args) {
        StackOfIntegers stack = new StackOfIntegers();
        for (int i = 2; i < 120; i++) {
            if (isPrime(i)) {
                stack.push(i);
            }
        }
        System.out.println("Prime numbers less than 120 in decreasing order:");
        while (!stack.isEmpty()) {
            System.out.print(stack.pop() + " ");
        }
    }

    public static boolean isPrime(int number) {
        for (int i = 2; i <= Math.sqrt(number); i++) {
            if (number % i == 0) {
                return false;
            }
        }
        return true;
    }
}

import java.util.ArrayList;
import java.util.Random;

public class GraphWalk {
    public static void main(String[] args) {
        // Create a sample graph with 5 nodes and 7 edges
        ArrayList<ArrayList<Integer>> graph = new ArrayList<>();
        for (int i = 0; i < 5; i++) {
            graph.add(new ArrayList<>());
        }
        graph.get(0).add(1);
        graph.get(0).add(3);
        graph.get(1).add(0);
        graph.get(1).add(2);
        graph.get(1).add(4);
        graph.get(2).add(1);
        graph.get(3).add(0);
        graph.get(4).add(1);

        // Start the random walk at node 0
        int currentNode = 0;
        System.out.print(currentNode + " ");

        // Perform the random walk
        Random rand = new Random();
        for (int i = 0; i < 10; i++) {
            // Choose a random neighbor
            int nextNode = graph.get(currentNode).get(rand.nextInt(graph.get(currentNode).size()));

            // Move to the chosen node
            currentNode = nextNode;
            System.out.print(currentNode + " ");
        }
    }
}

