import java.util.Scanner;

public class ZellerCongruence {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);

        System.out.print("Enter year (e.g., 2022): ");
        int year = input.nextInt();

        System.out.print("Enter month (1-12): ");
        int month = input.nextInt();

        System.out.print("Enter the day of the month (1-31): ");
        int dayOfMonth = input.nextInt();

        if (month == 1 || month == 2) {
            month += 12;
            year--;
        }

        int q = dayOfMonth;
        int m = month;
        int j = year / 100;
        int k = year % 100;

        int h = (q + 26 * (m + 1) / 10 + k + k / 4 + j / 4 + 5 * j) % 7;

        String dayOfWeek;
        switch (h) {
            case 0:
                dayOfWeek = "Saturday";
                break;
            case 1:
                dayOfWeek = "Sunday";
                break;
            case 2:
                dayOfWeek = "Monday";
                break;
            case 3:
                dayOfWeek = "Tuesday";
                break;
            case 4:
                dayOfWeek = "Wednesday";
                break;
            case 5:
                dayOfWeek = "Thursday";
                break;
            default:
                dayOfWeek = "Friday";
        }

        System.out.println("Day of the week is " + dayOfWeek);
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter a string:");
        String s = scanner.nextLine();
        System.out.println(findMaxConsecutiveSubstring(s));
    }

    public static String findMaxConsecutiveSubstring(String s) {
        String maxSubstring = "";
        String currentSubstring = "";

        for (int i = 0; i < s.length(); i++) {
            if (i == 0 || s.charAt(i) <= s.charAt(i-1)) {
                currentSubstring = "";
            }
            currentSubstring += s.charAt(i);
            if (currentSubstring.length() > maxSubstring.length()) {
                maxSubstring = currentSubstring;
            }
        }

        return maxSubstring;
    }
}

import java.util.Arrays;
import java.util.Random;

public class MatrixChecker {

    public static void main(String[] args) {
        // Generate the matrix
        int[][] matrix = generateMatrix(6);

        // Print the matrix
        printMatrix(matrix);

        // Check if every row and column has an even number of 1s
        if (checkMatrix(matrix)) {
            System.out.println("Every row and column has an even number of 1s.");
        } else {
            System.out.println("Not every row and column has an even number of 1s.");
        }
    }

    public static int[][] generateMatrix(int size) {
        Random random = new Random();
        int[][] matrix = new int[size][size];
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                matrix[i][j] = random.nextInt(2);
            }
        }
        return matrix;
    }

    public static void printMatrix(int[][] matrix) {
        for (int i = 0; i < matrix.length; i++) {
            for (int j = 0; j < matrix[0].length; j++) {
                System.out.print(matrix[i][j] + " ");
            }
            System.out.println();
        }
    }

    public static boolean checkMatrix(int[][] matrix) {
        int numRows = matrix.length;
        int numCols = matrix[0].length;
        int[] rowCount = new int[numRows];
        int[] colCount = new int[numCols];

        // Count the number of 1s in each row and column
        for (int i = 0; i < numRows; i++) {
            for (int j = 0; j < numCols; j++) {
                if (matrix[i][j] == 1) {
                    rowCount[i]++;
                    colCount[j]++;
                }
            }
        }

        // Check if every row and column has an even number of 1s
        for (int i = 0; i < numRows; i++) {
            if (rowCount[i] % 2 != 0) {
                return false;
            }
        }
        for (int j = 0; j < numCols; j++) {
            if (colCount[j] % 2 != 0) {
                return false;
            }
        }

        return true;
    }
}

