import javafx.application.Application;
import javafx.geometry.Insets;
import javafx.geometry.Pos;
import javafx.scene.Scene;
import javafx.scene.image.Image;
import javafx.scene.image.ImageView;
import javafx.scene.layout.GridPane;
import javafx.stage.Stage;

import java.util.Random;

public class TicTacToeBoard extends Application {

    @Override
    public void start(Stage primaryStage) throws Exception {
        // Create the GridPane and set the padding and gap between cells
        GridPane gridPane = new GridPane();
        gridPane.setPadding(new Insets(20, 20, 20, 20));
        gridPane.setHgap(10);
        gridPane.setVgap(10);

        // Create an array to hold the X and O images
        Image[] images = new Image[3];
        images[0] = new Image("https://i.imgur.com/WHdYnoM.png");
        images[1] = new Image("https://i.imgur.com/sNDtBvL.png");
        images[2] = null;

        // Create a Random object to generate random numbers
        Random random = new Random();

        // Fill the grid with X's, O's, and empty cells randomly
        for (int row = 0; row < 3; row++) {
            for (int col = 0; col < 3; col++) {
                int index = random.nextInt(3);
                ImageView imageView = new ImageView(images[index]);
                imageView.setFitWidth(100);
                imageView.setFitHeight(100);
                gridPane.add(imageView, col, row);
            }
        }

        // Create a Scene and add the GridPane to it
        Scene scene = new Scene(gridPane, 350, 350);

        // Set the alignment of the GridPane and show the window
        gridPane.setAlignment(Pos.CENTER);
        primaryStage.setScene(scene);
        primaryStage.setTitle("Tic-Tac-Toe Board");
        primaryStage.show();
    }

    public static void main(String[] args) {
        launch(args);
    }
}

import java.util.Scanner;

public class CharacterCounter {
    public static int count(String str, char a) {
        int count = 0;

        for (int i = 0; i < str.length(); i++) {
            if (str.charAt(i) == a) {
                count++;
            }
        }

        return count;
    }

    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);

        System.out.print("Enter a string: ");
        String str = input.nextLine();

        System.out.print("Enter a character: ");
        char a = input.nextLine().charAt(0);

        int count = count(str, a);

        System.out.println("The number of occurrences of the character '" + a + "' in the string \"" + str + "\" is " + count);
    }
}

_____________________________________
|          RegularPolygon            |
|------------------------------------|
| -n: int                            |
| -side: double                      |
| -x: double                         |
| -y: double                         |
|------------------------------------|
| +RegularPolygon()                  |
| +RegularPolygon(n: int, side: double)|
| +RegularPolygon(n: int, side: double, x: double, y: double)|
| +getN(): int                       |
| +setN(n: int): void                |
| +getSide(): double                 |
| +setSide(side: double): void       |
| +getX(): double                    |
| +setX(x: double): void             |
| +getY(): double                    |
| +setY(y: double): void             |
| +getPerimeter(): double            |
| +getArea(): double                 |
|____________________________________|
 public class RegularPolygon {
    private int n;
    private double side;
    private double x;
    private double y;

    public RegularPolygon() {
        this.n = 3;
        this.side = 1.0;
        this.x = 0.0;
        this.y = 0.0;
    }

    public RegularPolygon(int n, double side) {
        this.n = n;
        this.side = side;
        this.x = 0.0;
        this.y = 0.0;
    }

    public RegularPolygon(int n, double side, double x, double y) {
        this.n = n;
        this.side = side;
        this.x = x;
        this.y = y;
    }

    public int getN() {
        return this.n;
    }

    public void setN(int n) {
        this.n = n;
    }

    public double getSide() {
        return this.side;
    }

    public void setSide(double side) {
        this.side = side;
    }

    public double getX() {
        return this.x;
    }

    public void setX(double x) {
        this.x = x;
    }

    public double getY() {
        return this.y;
    }

    public void setY(double y) {
        this.y = y;
    }

    public double getPerimeter() {
        return n * side;
    }

    public double getArea() {
        return (n * Math.pow(side, 2)) / (4 * Math.tan(Math.PI / n));
    }
}

import java.util.LinkedList;
import java.util.Queue;

class Node {
    int val;
    Node left;
    Node right;

    public Node(int val) {
        this.val = val;
        left = null;
        right = null;
    }
}

class BST {
    Node root;

    public void insert(int val) {
        root = insert(root, val);
    }

    private Node insert(Node node, int val) {
        if (node == null) {
            return new Node(val);
        }
        if (val < node.val) {
            node.left = insert(node.left, val);
        } else if (val > node.val) {
            node.right = insert(node.right, val);
        }
        return node;
    }

    public void inorder() {
        inorder(root);
    }

    private void inorder(Node node) {
        if (node == null) {
            return;
        }
        inorder(node.left);
        System.out.print(node.val + " ");
        inorder(node.right);
    }

    public void breadthFirstTraversal() {
        if (root == null) {
            return;
        }
        Queue<Node> queue = new LinkedList<>();
        queue.offer(root);
        while (!queue.isEmpty()) {
            Node current = queue.poll();
            System.out.print(current.val + " ");
            if (current.left != null) {
                queue.offer(current.left);
            }
            if (current.right != null) {
                queue.offer(current.right);
            }
        }
    }

    public int height() {
        return height(root);
    }

    private int height(Node node) {
        if (node == null) {
            return 0;
        }
        int leftHeight = height(node.left);
        int rightHeight = height(node.right);
        return 1 + Math.max(leftHeight, rightHeight);
    }
}

