public class HexEditor extends JFrame {

    private JTextField fileNameTextField;
    private JTextArea hexTextArea;
    private JButton openButton;
    private JButton saveButton;

    public HexEditor() {
        super("Hex Editor");
        initComponents();
        setSize(new Dimension(800, 600));
        setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        setLocationRelativeTo(null);
        setVisible(true);
    }

    private void initComponents() {
        fileNameTextField = new JTextField();
        fileNameTextField.addActionListener(new ActionListener() {
            @Override
            public void actionPerformed(ActionEvent e) {
                openFile();
            }
        });

        hexTextArea = new JTextArea();
        hexTextArea.setEditable(true);

        JScrollPane scrollPane = new JScrollPane(hexTextArea);

        openButton = new JButton("Open");
        openButton.addActionListener(new ActionListener() {
            @Override
            public void actionPerformed(ActionEvent e) {
                openFile();
            }
        });

        saveButton = new JButton("Save");
        saveButton.addActionListener(new ActionListener() {
            @Override
            public void actionPerformed(ActionEvent e) {
                saveFile();
            }
        });

        JPanel buttonPanel = new JPanel();
        buttonPanel.add(openButton);
        buttonPanel.add(saveButton);

        add(fileNameTextField, BorderLayout.NORTH);
        add(scrollPane, BorderLayout.CENTER);
        add(buttonPanel, BorderLayout.SOUTH);
    }

    private void openFile() {
        JFileChooser fileChooser = new JFileChooser();
        int result = fileChooser.showOpenDialog(this);
        if (result == JFileChooser.APPROVE_OPTION) {
            File file = fileChooser.getSelectedFile();
            fileNameTextField.setText(file.getAbsolutePath());
            try {
                FileInputStream fis = new FileInputStream(file);
                StringBuilder sb = new StringBuilder();
                int i = 0;
                while ((i = fis.read()) != -1) {
                    sb.append(String.format("%02X ", i));
                }
                hexTextArea.setText(sb.toString());
                fis.close();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }

    private void saveFile() {
        JFileChooser fileChooser = new JFileChooser();
        int result = fileChooser.showSaveDialog(this);
        if (result == JFileChooser.APPROVE_OPTION) {
            File file = fileChooser.getSelectedFile();
            try {
                FileOutputStream fos = new FileOutputStream(file);
                String hexText = hexTextArea.getText().replaceAll("\\s", "");
                for (int i = 0; i < hexText.length(); i += 2) {
                    String hexByte = hexText.substring(i, i + 2);
                    fos.write(Integer.parseInt(hexByte, 16));
                }
                fos.close();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }

    public static void main(String[] args) {
        try {
            UIManager.setLookAndFeel(UIManager.getSystemLookAndFeelClassName());
        } catch (ClassNotFoundException | InstantiationException | IllegalAccessException | UnsupportedLookAndFeelException e) {
            e.printStackTrace();
        }
        new HexEditor();
    }
}

import java.util.Arrays;
import java.util.Scanner;

public class SortRowsDemo {

    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);

        // Prompt the user to enter a 3-by-3 matrix of double values
        System.out.println("Enter a 3-by-3 matrix row by row:");
        double[][] m = new double[3][3];
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                m[i][j] = input.nextDouble();
            }
        }

        // Sort the rows of the matrix
        double[][] sorted = sortRows(m);

        // Display the sorted matrix
        System.out.println("The row-sorted array is");
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                System.out.print(sorted[i][j] + " ");
            }
            System.out.println();
        }
    }

    public static double[][] sortRows(double[][] m) {
        // Create a new array to hold the sorted matrix
        double[][] sorted = new double[3][3];
        // Copy the elements of the original matrix to the new array
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                sorted[i][j] = m[i][j];
            }
        }
        // Sort each row of the new array
        for (int i = 0; i < 3; i++) {
            Arrays.sort(sorted[i]);
        }
        // Return the sorted matrix
        return sorted;
    }

}

public class PalindromicPrimes {

    public static void main(String[] args) {
        int count = 0;
        int number = 2;

        while (count < 100) {
            if (isPalindrome(number) && isPrime(number)) {
                System.out.print(number + " ");
                count++;

                if (count % 10 == 0) {
                    System.out.println();
                }
            }

            number++;
        }
    }

    // Returns true if the given number is a palindrome
    public static boolean isPalindrome(int number) {
        int reversed = 0;
        int n = number;

        while (n > 0) {
            reversed = reversed * 10 + n % 10;
            n /= 10;
        }

        return reversed == number;
    }

    // Returns true if the given number is a prime number
    public static boolean isPrime(int number) {
        if (number < 2) {
            return false;
        }

        for (int i = 2; i <= Math.sqrt(number); i++) {
            if (number % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.HashMap;
import java.util.Map;

public class RomanToInteger {
    public static int romanToInt(String s) {
        Map<Character, Integer> map = new HashMap<>();
        map.put('I', 1);
        map.put('V', 5);
        map.put('X', 10);
        map.put('L', 50);
        map.put('C', 100);
        map.put('D', 500);
        map.put('M', 1000);

        int result = 0;
        for (int i = 0; i < s.length(); i++) {
            int current = map.get(s.charAt(i));
            int next = i + 1 < s.length() ? map.get(s.charAt(i + 1)) : 0;
            if (current < next) {
                result -= current;
            } else {
                result += current;
            }
        }
        return result;
    }

    public static void main(String[] args) {
        String roman = "XIV";
        int decimal = romanToInt(roman);
        System.out.println("Roman Numeral " + roman + " is equal to " + decimal);
    }
}

