class Solution {
    public List<Integer> parseNestedParens(String paren_string) {
        List<Integer> levels = new ArrayList<>();
        int maxLevel = 0;
        int currentLevel = 0;

        for (char c : paren_string.toCharArray()) {
            if (c == '(') {
                currentLevel++;
                maxLevel = Math.max(maxLevel, currentLevel);
            } else if (c == ')') {
                currentLevel--;
            } else if (c == ' ') {
                levels.add(maxLevel);
                maxLevel = 0;
                currentLevel = 0;
            }
        }

        levels.add(maxLevel);

        return levels;
    }
}

