import java.util.*;
import java.lang.*;

class Solution {
    /**
    Given an array of integers, sort the integers that are between 1 and 9 inclusive,
    reverse the resulting array, and then replace each digit by its corresponding name from
    "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine".

    For example:
      arr = [2, 1, 1, 4, 5, 8, 2, 3]
            -> sort arr -> [1, 1, 2, 2, 3, 4, 5, 8]
            -> reverse arr -> [8, 5, 4, 3, 2, 2, 1, 1]
      return ["Eight", "Five", "Four", "Three", "Two", "Two", "One", "One"]

      If the array is empty, return an empty array:
      arr = []
      return []

      If the array has any strange number ignore it:
      arr = [1, -1 , 55]
            -> sort arr -> [-1, 1, 55]
            -> reverse arr -> [55, 1, -1]
      return = ["One"]
     */
    public List<String> byLength(List<Integer> arr) {
        List<String> result = new ArrayList<>();

        if (arr.isEmpty()) {
            return result;
        }

        List<Integer> validNumbers = new ArrayList<>();
        for (Integer num : arr) {
            if (num >= 1 && num <= 9) {
                validNumbers.add(num);
            }
        }

        Collections.sort(validNumbers);
        Collections.reverse(validNumbers);

        for (Integer num : validNumbers) {
            switch (num) {
                case 1:
                    result.add("One");
                    break;
                case 2:
                    result.add("Two");
                    break;
                case 3:
                    result.add("Three");
                    break;
                case 4:
                    result.add("Four");
                    break;
                case 5:
                    result.add("Five");
                    break;
                case 6:
                    result.add("Six");
                    break;
                case 7:
                    result.add("Seven");
                    break;
                case 8:
                    result.add("Eight");
                    break;
                case 9:
                    result.add("Nine");
                    break;
            }
        }

        return result;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public Optional<Integer> prodSigns(List<Integer> arr) {
        if (arr.isEmpty()) {
            return Optional.empty();
        }

        int sum = 0;
        int signProduct = 1;

        for (int num : arr) {
            sum += Math.abs(num);
            signProduct *= Math.signum(num);
        }

        return Optional.of(sum * signProduct);
    }
}

import java.util.*;

class Solution {
    /**
     * Write a function which sorts the given list of integers
     * in ascending order according to the sum of their digits.
     * Note: if there are several items with similar sum of their digits,
     * order them based on their index in original list.
     *
     * @param nums the list of integers to be sorted
     * @return the sorted list of integers
     */
    public List<Integer> orderByPoints(List<Integer> nums) {
        Collections.sort(nums, new Comparator<Integer>() {
            @Override
            public int compare(Integer num1, Integer num2) {
                int sum1 = computeDigitSum(num1);
                int sum2 = computeDigitSum(num2);

                if (sum1 == sum2) {
                    return nums.indexOf(num1) - nums.indexOf(num2);
                }

                return sum1 - sum2;
            }
        });

        return nums;
    }

    private int computeDigitSum(int num) {
        int sum = 0;
        num = Math.abs(num);

        while (num > 0) {
            sum += num % 10;
            num /= 10;
        }

        return sum;
    }
}

