class Solution {

    public List<Integer> rollingMax(List<Integer> numbers) {
        List<Integer> rollingMaxList = new ArrayList<>();

        for (int i = 0; i < numbers.size(); i++) {
            int max = Integer.MIN_VALUE;
            for (int j = 0; j <= i; j++) {
