public class Solution {
    public String exchange(List<Integer> lst1, List<Integer> lst2) {
        int oddInLst1 = 0;
        int evenInLst2 = 0;

        for (Integer num : lst1) {
            if (num % 2 != 0) {
                oddInLst1++;
            }
        }

        for (Integer num : lst2) {
            if (num % 2 == 0) {
                evenInLst2++;
            }
        }

        if (oddInLst1 <= evenInLst2) {
            return "YES";
        } else {
            return "NO";
        }
    }
}

