public class Solution {

    public List<Integer> countUpTo(int n) {
        List<Integer> primes = new ArrayList<>();
        for (int number = 2; number < n; number++) {
            if (isPrime(number)) {
                primes.add(number);
            }
        }
        return primes;
    }

    private boolean isPrime(int num) {
        if (num <= 1) {
            return false;
        }
        for (int i = 2; i <= Math.sqrt(num); i++) {
            if (num % i == 0) {
                return false;
            }
        }
        return true;
    }
}

