class Solution {
    public List<Integer> evenOddCount(int num) {
        int evenCount = 0;
        int oddCount = 0;
        num = Math.abs(num); // Make sure the number is positive

        while(num > 0) {
            int digit = num % 10;
            if (digit % 2 == 0) {
                evenCount++;
            } else {
                oddCount++;
            }
            num /= 10;
        }

        return Arrays.asList(evenCount, oddCount);
    }
}

