            a = b;
            b = temp;
        }

        for (int i = a; i <= b; i++) {
            String numStr = Integer.toString(i);
            for (char c : numStr.toCharArray()) {
                int digit = Character.getNumericValue(c);
                if (digit % 2 == 0) {
