class Solution {
    public int fizzBuzz(int n) {
        int count = 0;
        for (int i = 7; i < n; i += 11) {
            count += countDigits(i, 7);
        }
        for (int i = 7; i < n; i += 13) {
            count += countDigits(i, 7);
        }
        return count;
    }

    private int countDigits(int x, int target) {
        int count = 0;
        while (x > 0) {
            if (x % 10 == target) {
                count++;
            }
            x /= 10;
        }
        return count;
    }
}

