import java.util.*;
import java.lang.*;

class Solution {
    /**
    returns encoded string by cycling groups of three characters.
     */
    public String encodeCyclic(String s) {
        // split string to groups. Each of length 3.
        List<String> groups = new ArrayList<>();
        for (int i = 0; i < s.length(); i += 3) {
            groups.add(s.substring(i, Math.min(i + 3, s.length())));
        }
        // cycle elements in each group. Unless group has fewer elements than 3.
        for (int i = 0; i < groups.size(); i++) {
            if (groups.get(i).length() == 3) {
                groups.set(i, groups.get(i).substring(1) + groups.get(i).charAt(0));
            }
        }
        return String.join("", groups);
    }

    public String decodeCyclic(String s) {
        // split string to groups. Each of length 3.
        List<String> groups = new ArrayList<>();
        for (int i = 0; i < s.length(); i += 3) {
            groups.add(s.substring(i, Math.min(i + 3, s.length())));
        }
        // cycle elements in each group. Unless group has fewer elements than 3.
        for (int i = 0; i < groups.size(); i++) {
            if (groups.get(i).length() == 3) {
                groups.set(i, groups.get(i).charAt(2) + groups.get(i).substring(0, 2));
            }
        }
        return String.join("", groups);
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public List<Integer> minPath(List<List<Integer>> grid, int k) {
        int n = grid.size();
        int[][][] dp = new int[n][n][k + 1];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                Arrays.fill(dp[i][j], -1);
            }
        }
        List<Integer> ans = new ArrayList<>();
        int min = Integer.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                List<Integer> path = new ArrayList<>();
                int res = dfs(grid, i, j, k, dp, path);
                if (res != -1) {
                    if (res < min) {
                        min = res;
                        ans = path;
                    }
                }
            }
        }
        return ans;
    }

    private int dfs(List<List<Integer>> grid, int i, int j, int k, int[][][] dp, List<Integer> path) {
        int n = grid.size();
        if (i < 0 || i >= n || j < 0 || j >= n || k < 0) {
            return -1;
        }
        if (dp[i][j][k] != -1) {
            return dp[i][j][k];
        }
        int min = Integer.MAX_VALUE;
        path.add(grid.get(i).get(j));
        if (k == 0) {
            min = 0;
        } else {
            // move right
            int res = dfs(grid, i, j + 1, k - 1, dp, path);
            if (res != -1) {
                min = Math.min(min, res);
            }
            // move down
            res = dfs(grid, i + 1, j, k - 1, dp, path);
            if (res != -1) {
                min = Math.min(min, res);
            }
            // move left
            res = dfs(grid, i, j - 1, k - 1, dp, path);
            if (res != -1) {
                min = Math.min(min, res);
            }
            // move up
            res = dfs(grid, i - 1, j, k - 1, dp, path);
            if (res != -1) {
                min = Math.min(min, res);
            }
        }
        path.remove(path.size() - 1);
        if (min != Integer.MAX_VALUE) {
            min += grid.get(i).get(j);
        }
        dp[i][j][k] = min;
        return min;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public boolean validDate(String date) {
        if (date == null || date.isEmpty()) {
            return false;
        }

        String[] dateParts = date.split("-");
        if (dateParts.length != 3) {
            return false;
        }

        int month = Integer.parseInt(dateParts[0]);
        int day = Integer.parseInt(dateParts[1]);
        int year = Integer.parseInt(dateParts[2]);

        // Check if the month is valid
        if (month < 1 || month > 12) {
            return false;
        }

        // Check if the day is valid
        if (day < 1) {
            return false;
        }

        // Check if the year is valid
        if (year < 1) {
            return false;
        }

        // Check if the day is valid for the given month
        int[] daysInMonth = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
        if (month == 2 && day > 29) {
            return false;
        } else if (day > daysInMonth[month - 1]) {
            return false;
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public int fib4(int n) {
        if (n < 4) {
            return n < 2 ? 0 : 2;
        }
        int[] fib = new int[n + 1];
        fib[0] = 0;
        fib[1] = 0;
        fib[2] = 2;
        fib[3] = 0;
        for (int i = 4; i <= n; i++) {
            fib[i] = fib[i - 1] + fib[i - 2] + fib[i - 3] + fib[i - 4];
        }
        return fib[n];
    }
}

