class Solution {
    public List<Integer> uniqueDigits(List<Integer> x) {
        List<Integer> ans = new ArrayList<>();
        for(int num : x){
            boolean isUnique = true;
            while(num > 0){
                int d = num % 10;
                if(d % 2 == 0){
                    isUnique = false;
                    break;
                }
                num /= 10;
            }
            if(isUnique == true){
                ans.add(num);
            }
        }
        Collections.sort(ans);
        return ans;
    }
}

