class Solution {
    public List<Integer> makeAPile(int n) {
        List<Integer> levels = new ArrayList<>();
        int nextNumber = n;
        levels.add(n);
        while (nextNumber > 0) {
            if (n % 2 == 1) {
                nextNumber = n + 2;
            } else {
                nextNumber = n + 1;
            }
            levels.add(nextNumber);
            n = nextNumber;
        }
        return levels;
    }
}

