class Solution {
    public int modp(int n, int p) {
        if (n == 0) {
            return 1;
        }
        if (n == 1) {
            return 2;
        }
        if (n % 2 == 0) {
            int halfPow = modp(n / 2, p);
            return (halfPow * halfPow) % p;
        } else {
            return (2 * modp(n - 1, p)) % p;
        }
    }
}

