class Solution {
    public int countNums(List<Integer> arr) {
        int count = 0;
        for (int num : arr) {
            int sum = 0;
            int currNum = num;
            if (num < 0) {
                currNum *= -1;
            }
            while (currNum > 0) {
                sum += currNum % 10;
                currNum /= 10;
            }
            if (sum > 0) {
                count++;
            }
        }
        return count;
    }
}

