class Solution {
    public List<Integer> tri(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n cannot be a negative number");
        }
        List<Integer> tribo = new ArrayList<>();
        for (int i = 0; i <= n; i++) {
            if (i < 3) {
                if (i == 0) {
                    tribo.add(1);
                } else {
                    tribo.add(3);
                }
            } else {
                if (i % 2 == 0) {
                    tribo.add(1 + i / 2);
                } else {
                    tribo.add(tribo.get(i - 1) + tribo.get(i - 2) + tribo.get(i + 1));
                }
            }
        }
        return tribo;
    }
}

