class Solution {
    public List<Integer> unique(List<Integer> l) {
        if (l == null || l.isEmpty()) {
            return new ArrayList<>();
        }
        Set<Integer> seen = new HashSet<>();
        List<Integer> res = new ArrayList<>();
        for (Integer num : l) {
            if (!seen.contains(num)) {
                seen.add(num);
                res.add(num);
            }
        }
        Collections.sort(res);
        return res;
    }
}

