class Solution {
    public List<Integer> strangeSortList(List<Integer> lst) {
        if (lst.size() == 0) {
            return new ArrayList<>();
        }

        List<Integer> sortedList = new ArrayList<>();
        boolean minTurn = true;
        while (lst.size() > 0) {
            if (minTurn) {
                int min = Integer.MAX_VALUE;
                int minIndex = -1;
                for (int i = 0; i < lst.size(); i++) {
                    if (lst.get(i) < min) {
                        min = lst.get(i);
                        minIndex = i;
                    }
                }
                sortedList.add(min);
                lst.remove(minIndex);
            } else {
                int max = Integer.MIN_VALUE;
                int maxIndex = -1;
                for (int i = 0; i < lst.size(); i++) {
                    if (lst.get(i) > max) {
                        max = lst.get(i);
                        maxIndex = i;
                    }
                }
                sortedList.add(max);
                lst.remove(maxIndex);
            }
            minTurn = !minTurn;
        }

        return sortedList;
    }
}

