class Solution {
    public int maxFill(List<List<Integer>> grid, int capacity) {
        int rows = grid.size();
        int cols = grid.get(0).size();

        int count = 0;
        for (int i = 0; i < cols; i++) {
            int currentCapacity = capacity;

            for (int j = 0; j < rows && currentCapacity > 0; j++) {
                if (grid.get(j).get(i) == 1) {
                    grid.get(j).set(i, 0);
                    currentCapacity--;
                    count++;
                }
            }
        }

        return count;
    }
}

