class Solution {
    public List<Integer> getOddCollatz(int n) {
        List<Integer> res = new ArrayList<>();
        if (n <= 0) {
            return res;
        }
        int curr = n;
        while (curr != 1) {
            if (curr % 2 == 0) {
                curr /= 2;
            } else {
                res.add(curr);
                curr = curr * 3 + 1;
            }
        }
        res.add(1);
        Collections.sort(res);
        return res;
    }
}

