class Solution {
    public int specialFilter(List<Integer> nums) {
        int count = 0;
        for (int num : nums) {
            if (num <= 10) {
                continue;
            }
            int absNum = Math.abs(num);
            int firstDigit = absNum / (int) Math.pow(10, String.valueOf(absNum).length() - 1);
            int lastDigit = absNum % 10;
            if ((firstDigit % 2 == 1) && (lastDigit % 2 == 1)) {
                count++;
            }
        }
        return count;
    }
}

