class Solution {
    public boolean isMultiplyPrime(int a) {
        if (a % 2 == 0) {
            a /= 2;
            if (a % 2 == 0) return false;
        }
        for (int i = 3; i * i <= a; i += 2) {
            while (a % i == 0) {
                a /= i;
                if (a % i == 0) return false;
            }
        }
        if(a > 2) return true;
        return false;
    }
}

