import java.util.*;
import java.lang.*;

class Solution {
    public List<Integer> evenOddCount(int num) {
        List<Integer> res = new ArrayList<>();

        if (num == 0) {
            res.add(0);
            res.add(1);
            return res;
        }

        int evenCount = 0;
        int oddCount = 0;

        if (num < 0) {
            num *= -1;
        }

        while (num != 0) {
            int lastDigit = num % 10;
            if (lastDigit % 2 == 0) {
                evenCount++;
            } else {
                oddCount++;
            }
            num /= 10;
        }

        res.add(evenCount);
        res.add(oddCount);
        return res;
    }
}

