def valid_date(date):
    parts = date.split('-')
    if len(parts) != 3:
        return False

    month = int(parts[0])
    day = int(parts[1])
    year = int(parts[2])

    if month < 1 or month > 12:
        return False

    if day < 1 or day > 31:
        return False

    if month == 2:
        if day > 29:
            return False
        elif day == 29:
            if (year % 4 != 0) or (year % 100 == 0 and year % 400 != 0):
                return False

    if (month == 4 or month == 6 or month == 9 or month == 11) and day > 30:
        return False

    return True

