    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n ** 0.5) + 1):
            if n % i == 0:
                return False
        return True

    # Function to get the sum of the digits of a number
    def get_digit_sum(n):
        digit_sum = 0
        while n > 0:
            digit_sum += n % 10
            n //= 10
        return digit_sum

    # Initialize variables
    largest_prime = 0

    # Iterate over the list
    for num in lst:
