def encrypt(s):
    enc_str = ""

    for char in s:
        if char.isalpha():
            ascii_val = ord(char)
            shifted_ascii = ascii_val + 2 * 2
            if char.isupper():
                if shifted_ascii > ord("Z"):
                    shifted_ascii -= 26
            else:
                if shifted_ascii > ord("z"):
                    shifted_ascii -= 26
            enc_str += chr(shifted_ascii)
        else:
            enc_str += char

    return enc_str

