        if x == 0:
            return 1
        else:
            return x * factorial(x-1)

    def sum_to(x):
        return sum(range(1, x+1))

    result = []
    for i in range(1, n+1):
        if i % 2 == 0:  # even
            result.append(factorial(i))
        else:  # odd
            result.append(sum_to(i))
    return result

