def encrypt(s):
    result = ""
    for char in s:
        if char.isalpha():
            # Calculate the shift, considering both uppercase and lowercase characters
            shift = 4 if char.islower() else 4
            # Shift the character and append it to the result string
            result += chr((ord(char) - 97 + shift) % 26 + 97) if char.islower() else chr((ord(char) - 65 + shift) % 26 + 65)
        else:
            result += char
    return result

def split_words(txt):
    if ' ' in txt:
        return txt.split()
    elif ',' in txt:
        return txt.split(',')
    else:
        return sum(1 for char in txt if char.islower() and ord(char) % 2 != 0)

from typing import List

def has_close_elements(numbers: List[float], threshold: float) -> bool:
    for i in range(len(numbers)):
        for j in range(i + 1, len(numbers)):
            if abs(numbers[i] - numbers[j]) < threshold:
                return True
    return False

def triangle_area(a, b, c):
    if (a + b > c) and (a + c > b) and (b + c > a):
        s = (a + b + c) / 2
        area = (s*(s-a)*(s-b)*(s-c)) ** 0.5
        return round(area, 2)
    else:
        return -1

def closest_integer(value):
    num = float(value)
    lower = int(num)
    upper = lower + 1 if num > 0 else lower - 1
    if (num - lower) < (upper - num):
        return lower
    elif (num - lower) > (upper - num):
        return upper
    else:
        return upper if num > 0 else lower

def check_if_last_char_is_a_letter(txt):
    if not txt or not txt[-1].isalpha() or txt[-1].isspace():
        return False
    if len(txt) > 1 and txt[-2].isalpha():
        return False
    return True

def get_row(lst, x):
    coordinates = []
    for i, row in enumerate(lst):
        for j, elem in enumerate(row):
            if elem == x:
                coordinates.append((i, -j))
    coordinates.sort()
    return [(i, -j) for i, j in coordinates]

def count_upper(s):
    count = 0
    vowels = 'AEIOU'
    for i in range(0, len(s), 2):
        if s[i] in vowels:
            count += 1
    return count

def fib(n: int) -> int:
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

def pairs_sum_to_zero(l):
    seen = set()
    for num in l:
        if -num in seen:
            return True
        seen.add(num)
    return False

from typing import List

def below_zero(operations: List[int]) -> bool:
    balance = 0
    for op in operations:
        balance += op
        if balance < 0:
            return True
    return False

def fibfib(n: int) -> int:
    if n == 0:
        return 0
    elif n == 1:
        return 0
    elif n == 2:
        return 1
    else:
        a, b, c = 0, 0, 1
        for _ in range(3, n + 1):
            a, b, c = b, c, a + b + c
        return c

def is_equal_to_sum_even(n):
    if n < 8 or n % 2 != 0:  # Since the smallest sum of 4 even numbers is 2+2+2+2=8 and n must be even
        return False
    else:
        return n >= 8 and n % 2 == 0

def by_length(arr):
    digit_names = {
        1: "One", 2: "Two", 3: "Three", 4: "Four",
        5: "Five", 6: "Six", 7: "Seven", 8: "Eight", 9: "Nine"
    }
    # Filter, sort in ascending, then reverse for descending order
    sorted_arr = sorted([item for item in arr if 1 <= item <= 9], reverse=True)
    # Replace digits with names
    return [digit_names[item] for item in sorted_arr]

def correct_bracketing(brackets: str) -> bool:
    balance = 0
    for bracket in brackets:
        if bracket == "<":
            balance += 1
        elif bracket == ">":
            if balance == 0:
                return False
            balance -= 1

    return balance == 0

import hashlib

def string_to_md5(text):
    if text == "":
        return None
    else:
        return hashlib.md5(text.encode()).hexdigest()

from typing import List

def rescale_to_unit(numbers: List[float]) -> List[float]:
    if not numbers or len(numbers) < 2:
        raise ValueError("Input list must contain at least two elements.")
    min_num = min(numbers)
    max_num = max(numbers)
    if min_num == max_num:
        raise ValueError("Input list elements cannot all be the same.")
    scale = max_num - min_num
    return [(num - min_num) / scale for num in numbers]

def select_words(s, n):
    def consonant_count(word):
        consonants = "bcdfghjklmnpqrstvwxyz"
        return sum(letter.lower() in consonants for letter in word)

    words = s.split()
    selected_words = [word for word in words if consonant_count(word) == n]
    return selected_words

def is_prime(n):
    if n <= 1:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def x_or_y(n, x, y):
    return x if is_prime(n) else y

from typing import List

def factorize(n: int) -> List[int]:
    i = 2
    factors = []
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            factors.append(i)
    if n > 1:
        factors.append(n)
    return factors

def get_max_triples(n):
    # Create the array a as per the given conditions
    a = [i*i - i + 1 for i in range(1, n+1)]
    # Initialize count to 0 for counting valid triples
    count = 0
    # Iterate through the array to find the valid triples
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                # Check if the sum of a[i], a[j], and a[k] is a multiple of 3
                if (a[i] + a[j] + a[k]) % 3 == 0:
                    count += 1
    return count

