def parse_music(music_string: str) -> List[int]:
    notes = music_string.split()
    beats = []

    for note in notes:
        if note == 'o':
            beats.append(4)
        elif note == 'o|':
            beats.append(2)
        elif note == '.|':
            beats.append(1)

    return beats

def bf(planet1, planet2):
    planets = ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"]

    if planet1 not in planets or planet2 not in planets:
        return ()

    index1, index2 = planets.index(planet1), planets.index(planet2)

    return tuple(sorted(planets[min(index1, index2)+1:max(index1, index2)], key=planets.index))

def triples_sum_to_zero(l: list):
    n = len(l)
    l.sort()
    for i in range(n - 2):
        left = i + 1
        right = n - 1
        while left < right:
            current_sum = l[i] + l[left] + l[right]
            if current_sum == 0:
                return True
            elif current_sum < 0:
                left += 1
            else:
                right -= 1
    return False

def valid_date(date):
    # Check if the date string is not empty and follows the mm-dd-yyyy format.
    if not date or len(date) != 10 or date[2] != '-' or date[5] != '-':
        return False

    # Split the date string into month, day, and year components.
    parts = date.split('-')
    try:
        month = int(parts[0])
        day = int(parts[1])
        year = int(parts[2])
    except ValueError:
        # If conversion to int fails, the date is invalid.
        return False

    # Assess month and day validity based on rules.
    if month < 1 or month > 12:
        return False

    # Define the maximum number of days for each month.
    days_in_month = {1: 31, 2: 29, 3: 31, 4: 30, 5: 31, 6: 30, 7: 31, 8: 31, 9: 30, 10: 31, 11: 30, 12: 31}

    # Check if the number of days is valid for the given month.
    if day < 1 or day > days_in_month.get(month, 31):
        return False

    return True

