def unique_digits(x):
    def has_no_even_digit(n):
        return all(int(digit) % 2 != 0 for digit in str(n))

    return sorted([item for item in x if has_no_even_digit(item)])

def vowels_count(s):
    vowels = "aeiouAEIOU"
    count = 0
    for char in s:
        if char in vowels:
            count += 1
    if len(s) > 0 and s[-1].lower() == 'y':
        count += 1
    return count

def is_palindrome(string: str) -> bool:
    return string == string[::-1]

def make_palindrome(string: str) -> str:
    if is_palindrome(string):
        return string
    for i in range(len(string), -1, -1):
        if is_palindrome(string[:i]):
            return string + string[:len(string) - i][::-1]
    return string

def numerical_letter_grade(grades):
    letter_grades = []
    for gpa in grades:
        if gpa == 4.0:
            letter_grades.append('A+')
        elif gpa > 3.7:
            letter_grades.append('A')
        elif gpa > 3.3:
            letter_grades.append('A-')
        elif gpa > 3.0:
            letter_grades.append('B+')
        elif gpa > 2.7:
            letter_grades.append('B')
        elif gpa > 2.3:
            letter_grades.append('B-')
        elif gpa > 2.0:
            letter_grades.append('C+')
        elif gpa > 1.7:
            letter_grades.append('C')
        elif gpa > 1.3:
            letter_grades.append('C-')
        elif gpa > 1.0:
            letter_grades.append('D+')
        elif gpa > 0.7:
            letter_grades.append('D')
        elif gpa > 0.0:
            letter_grades.append('D-')
        else:
            letter_grades.append('E')
    return letter_grades

def generate_integers(a, b):
    # Ensure that the numbers are in ascending order.
    if b < a:
        a, b = b, a
    # Generate and filter even integers between a and b (inclusive).
    return [i for i in range(a, b + 1) if i % 2 == 0]

def choose_num(x, y):
    for num in range(y, x-1, -1):
        if num % 2 == 0:
            return num
    return -1

def prod_signs(arr):
    if not arr:
        return None
    product_of_signs = 1
    sum_of_magnitudes = 0
    for num in arr:
        product_of_signs *= (-1 if num < 0 else (1 if num > 0 else 0))
        sum_of_magnitudes += abs(num)
    return sum_of_magnitudes * product_of_signs

def cycpattern_check(a, b):
    if len(b) > len(a):
        return False
    for _ in range(len(b)):
        if b in a:
            return True
        # Rotate 'b'
        b = b[1:] + b[:1]
    return False

def search(lst):
    freq = {}
    for num in lst:
        if num not in freq:
            freq[num] = 0
        freq[num] += 1

    for num in lst:
        if freq[num] >= num:
            return num

    return -1

def will_it_fly(q,w):

    # Check if the list is balanced (a palindrome)
    if q==q[::-1]:
        # Check if the sum of the elements is less than or equal to the maximum possible weight
        if sum(q)<=w:
            return True
    return False

def find_max(words):
    max_chars = 0
    result = ""

    for word in words:
        chars = set()
        for char in word:
            chars.add(char)

        if len(chars) > max_chars:
            max_chars = len(chars)
            result = word

    return result

def is_sorted(lst):

    # check if list is empty or has only 1 element
    if len(lst) <= 1:
        return True

    # check if list has more than 1 duplicate of the same number
    for i in range(len(lst)):
        if lst.count(lst[i]) > 1:
            return False

    # check if list is sorted in ascending order
    for i in range(1, len(lst)):
        if lst[i] < lst[i-1]:
            return False

    return True

