def total_match(lst1, lst2):
    def total_chars(lst):
        total = 0 
        for strs in lst:
            total+= len(strs)
        return total

    if not lst1 or not lst2:
        return []

    len1 = total_chars(lst1)
    len2 = total_chars(lst2)

    if len1 < len2:
        return lst1
    elif len1 > len2:
        return lst2
    else:
        return lst1

def valid_date(date):
    try:
        month, day, year = date.split('-')
        month = int(month)
        day = int(day)
        year = int(year)

        if month < 1 or month > 12:
            return False

        if day < 1 or (month in [1, 3, 5, 7, 8, 10, 12] and day > 31) or (month in [4, 6, 9, 11] and day > 30) or (month == 2 and day > 29):
            return False

        if year < 1:
            return False

        return True

    except ValueError:
        return False


