from typing import List, Tuple


def sum_product(numbers: List[int]) -> Tuple[int, int]:
    product = 1
    sum = 0
    for number in numbers:
        product *= number
        sum += number

    return (sum, product)

def count_nums(arr):
    def sum_of_digits(n):
        sum = 0
        if n < 0:
            sum += abs(n % 10)
            n = n // -10
        while n > 0:
            sum += n % 10
            n = n // 10
        return sum

    count = 0
    for num in arr:
        if sum_of_digits(num) > 0:
            count += 1
    return count

def solve(N):
    sum = 0
    while(N):
        if N % 2 == 1:
            sum += 1
        N = N // 2

    ans = str(bin(sum))[2:]
    return ans

