def intersperse(numbers: List[int], delimeter: int) -> List[int]:
    new_list = []
    for i in range(len(numbers)):
        if i < len(numbers) - 1:
            new_list.extend([numbers[i], delimeter])
        else:
            new_list.append(numbers[i])
    return new_list

