        return True
    return False

def exchange(lst1, lst2):

    # Count the number of even and odd elements in lst1 and lst2
    even_lst1 = 0
    odd_lst1 = 0
    even_lst2 = 0
    odd_lst2 = 0

    for num in lst1:
        if num % 2 == 0:
            even_lst1 += 1
        else:
            odd_lst1 += 1

    for num in lst2:
        if num % 2 == 0:
            even_lst2 += 1
        else:
            odd_lst2 += 1

    # Check if it is possible to exchange elements to make lst1 a list of only even numbers
    if even_lst2 >= odd_lst1:
        return "YES"
    else:
        return "NO"

from typing import List


def sort_numbers(numbers: str) -> str:
    numbers = numbers.split()
    numbers_dict = {'one': 1, 'two': 2, 'three': 3, 'four': 4, 'five': 5, 'six': 6, 'seven': 7, 'eight': 8, 'nine': 9, 'zero': 0}
    numbers.sort(key=lambda x: numbers_dict[x])
    return ' '.join(numbers)

def string_sequence(n: int) -> str:
    """ Return a string containing space-delimited numbers starting from 0 upto n inclusive.
    >>> string_sequence(0)
    '0'
    >>> string_sequence(5)
    '0 1 2 3 4 5'
    """
    if n < 0:
        raise ValueError("n must be a non-negative integer")

    return ' '.join(map(str, range(n + 1)))

def get_max_triples(n):
    mod = 10 ** 9 + 7
    def power(x, y): 
        ret = 1
        while (y): 
            if (y % 2 == 0): 
                x = (x * x) 
                y = y / 2
            else: 
                ret = (ret * x) 
                y = y - 1
        return (ret)

    def get_sum(n):
        return (n * (n + 1)) // 2

    return (((power(2, n) - 1 + mod) % mod) * (get_sum(n - 1) % mod)) % mod

