def fix_spaces(text):

    t = ''
    lst = text.split()
    for word in lst:
        t += word + "_"

    t = t[:-1]  # Remove the last '_'

    ans = ''
    i = 0

    while i < len(t):
        if t[i] == '_':
            cnt = 0
            while i < len(t) and t[i] == '_':
                i += 1
                cnt += 1

            if cnt == 1:
                ans += '_'
            else:
                ans += '-'
            i -= 1

        else:
            ans += t[i]

        i += 1

    return ans

