def tri(n):

    def tri_helper(n, memo):
        if n == 0:
            return 0
        if n == 1:
            return 1
        if n == 2:
            return 1
        if n in memo:
            return memo[n]
        if n % 2 == 0:
            memo[n] = 1 + (n / 2)
        else:
            memo[n] = tri_helper(n - 1, memo) + tri_helper(n - 2, memo) + tri_helper(n + 1, memo)
        return memo[n]

    return [tri_helper(i, {}) for i in range(n + 1)]

