def find_longest_consecutive_subsequence_length(arr):
    max_length = 0
    num_set = set(arr)

    for num in num_set:
        if num - 1 not in num_set:
            current_num = num
            current_length = 1

            while current_num + 1 in num_set:
                current_num += 1
                current_length += 1

            max_length = max(max_length, current_length)

    return max_length

