def minimize_string(string):
    """
    :param string: The input string
    :return: The minimized string
    """
    if len(string) == 0 or len(string) == 1:
        return string

    removed = False
    prev = string[0]
    result = []
    count = 1
    for i in range(1, len(string)):
        if string[i] == prev:
            count += 1
        else:
            if count == 1:
                if not removed:
                    removed = True
                else:
                    result.append(prev)
            else:
                result.append(prev * count)
            prev = string[i]
            count = 1

    if count == 1 and not removed:
        result.append(prev)
    else:
        result.append(prev * count)

    return "".join(result)

