def find_lcs(str1, str2, str3):

    m = len(str1)
    n = len(str2)
    o = len(str3)

    dp = [[[0 for _ in range(o+1)] for _ in range(n+1)] for _ in range(m+1)]

    for i in range(m+1):
        for j in range(n+1):
            for k in range(o+1):
                if i == 0 or j == 0 or k == 0:
                    dp[i][j][k] = 0
                elif str1[i-1] == str2[j-1] == str3[k-1]:
                    dp[i][j][k] = dp[i-1][j-1][k-1] + 1
                else:
                    dp[i][j][k] = max(dp[i-1][j][k], dp[i][j-1][k], dp[i][j][k-1])

    lcs_length = dp[m][n][o]
    lcs = [""] * lcs_length

    i = m
    j = n
    k = o

    while i > 0 and j > 0 and k > 0:
        if str1[i-1] == str2[j-1] == str3[k-1]:
            lcs[lcs_length-1] = str1[i-1]
            i -= 1
            j -= 1
            k -= 1
            lcs_length -= 1
        elif dp[i-1][j][k] > dp[i][j-1][k] and dp[i-1][j][k] > dp[i][j][k-1]:
            i -= 1
        elif dp[i][j-1][k] > dp[i][j][k-1]:
            j -= 1
        else:
            k -= 1

    return "".join(lcs)

