def newman_conway(n):
    if n == 0:
        return "Invalid input"

    # Base cases
    if n == 1:
        return "1"

    if n == 2:
        return "1 1"

    # Calculate the nth number in the sequence
    dp = [0] * (n + 1)
    dp[1] = 1
    dp[2] = 1

    for i in range(3, n + 1):
        dp[i] = dp[dp[i - 1]] + dp[i - dp[i - 1]]

    # Return the nth number
    return str(dp[-1])

