def min_cost_path(cost, m, n):
    if m == 0 and n == 0:
        return cost[m][n]
    elif m == 0:
        return cost[0][n] + min_cost_path(cost, 0, n-1)
    elif n == 0:
        return cost[m][0] + min_cost_path(cost, m-1, 0)
