def firstMissingPositive(nums):
    # Separate negative and zero elements
    n = len(nums)
    i = 0
    while i < n:
        if nums[i] <= 0:
            nums[i], nums[n-1] = nums[n-1], nums[i]
            n -= 1
        else:
            i += 1

    # Mark elements as visited
    for i in range(n):
        val = abs(nums[i])
        if val <= n:
            nums[val-1] *= -1

    # Find first missing positive number
