def max_sum_subsequence(nums, k):
    dp = [0] * len(nums)

    for i in range(len(nums)):
        max_sum = 0
        for j in range(i):
            if nums[j] < nums[i] and dp[j] > max_sum:
                max_sum = dp[j]
        dp[i] = max_sum + nums[i]

    return max(dp) + k

