def pancake_sort(arr):
    def flip(arr, k):
        i = 0
        while i < k / 2:
            temp = arr[i]
            arr[i] = arr[k - i - 1]
            arr[k - i - 1] = temp
            i += 1

    def find_max(arr, n):
        mi = 0
        for i in range(0, n):
            if arr[i] > arr[mi]:
                mi = i
        return mi

    def pancake_sort_recursive(arr, n):
        if n == 1:
            return
        mi = find_max(arr, n)
        if mi != n - 1:
            flip(arr, mi + 1)
            flip(arr, n)
        pancake_sort_recursive(arr, n - 1)

    n = len(arr)
    pancake_sort_recursive(arr, n)
    return arr

