        return arr

    middle = len(arr) // 2
    left_half = arr[:middle]
    right_half = arr[middle:]

    left_half = merge_sort(left_half)
    right_half = merge_sort(right_half)

    return merge(left_half, right_half)


def merge(left, right):
    merged = []
    left_index = right_index = 0

    while left_index < len(left) and right_index < len(right):
        if left[left_index] <= right[right_index]:
            merged.append(left[left_index])
            left_index += 1
        else:
            merged.append(right[right_index])
            right_index += 1

    merged.extend(left[left_index:])
    merged.extend(right[right_index:])

    return merged

def ncr_mod_p(n, r, p):
    def factorial_mod_p(n, p):
        fact = 1
        while n > 1:
            fact = (fact * n) % p
            n -= 1
        return fact

    def power_mod_p(x, y, p):
        res = 1
        x = x % p
        while y > 0:
            if y & 1:
                res = (res * x) % p
            y = y >> 1
            x = (x * x) % p
        return res

    def ncr_mod_p_util(n, r, p):
        if r == 0:
            return 1
        if r > n:
            return 0
        fact_n = factorial_mod_p(n, p)
        fact_r = factorial_mod_p(r, p)
        fact_nr = factorial_mod_p(n - r, p)
        return (fact_n * power_mod_p(fact_r * fact_nr % p, p - 2, p)) % p

    return ncr_mod_p_util(n, r, p)

