def count_ways(n):
    if n == 1:
        return 0
    if n == 2:
        return 1
    if n == 3:
        return 3
    ways = [0] * (n + 1)
    ways[1] = 0
    ways[2] = 1
    ways[3] = 3
    for i in range(4, n + 1):
        ways[i] = ways[i - 1] + 2 * ways[i - 2]
    return ways[n]

