def compute_ncr_mod_p(n, r, p):
    fact_n = 1
    fact_r = 1
    fact_nr = 1

    for i in range(1, n + 1):
        fact_n = (fact_n * i) % p

    for i in range(1, r + 1):
        fact_r = (fact_r * i) % p

    for i in range(1, (n - r) + 1):
        fact_nr = (fact_nr * i) % p

    ncr = (fact_n // (fact_r * fact_nr)) % p

    return ncr

