def find_top_k_frequent(nums, k):
    frequency = {}

    for num in nums:
        if num in frequency:
            frequency[num] += 1
        else:
            frequency[num] = 1

    heap = []
    for num in frequency:
        heapq.heappush(heap, (-frequency[num], num))

    top_k = []
    for i in range(k):
        top_k.append(heapq.heappop(heap)[1])

    return top_k

