def find_operations(nums, k):
    target = max(nums)
    operations = 0

    while target > min(nums):
        max_index = nums.index(target)

        for i in range(len(nums)):
            if i != max_index:
                nums[i] += k
                operations += 1

        target = max(nums)

    return operations

