def amicable_sum(n):
    def sum_divisors(number):
        return sum(i for i in range(1, number) if number % i == 0)

    amicable_numbers = []
    for i in range(1, n + 1):
        num1 = sum_divisors(i)
        num2 = sum_divisors(num1)

        if i == num2 and i != num1:
            amicable_numbers.append(i)

    return sum(amicable_numbers)

