def extract_missing_ranges(lst, start_range, end_range):
    missing_ranges = []

    if len(lst) == 0:
        if start_range < end_range:
            missing_ranges.append((start_range, end_range))
        return missing_ranges

    if lst[0] > start_range:
        missing_ranges.append((start_range, lst[0] - 1))

    for i in range(1, len(lst)):
        if lst[i] > lst[i - 1] + 1:
            missing_ranges.append((lst[i - 1] + 1, lst[i] - 1))

    if lst[-1] < end_range:
        missing_ranges.append((lst[-1] + 1, end_range))

    return missing_ranges

def find_largest_divisible_subset(nums):
    if not nums or len(nums) == 1:
        return nums

    nums.sort()

    dp = [1] * len(nums)
    prev = [-1] * len(nums)

    max_idx = 0
    max_size = float('-inf')

    for i in range(len(nums)):
        for j in range(i):
            if nums[i] % nums[j] == 0 and dp[j] + 1 > dp[i]:
                dp[i] = dp[j] + 1
                prev[i] = j

        if dp[i] > max_size:
            max_size = dp[i]
            max_idx = i

    subset = []
    while max_idx != -1:
        subset.append(nums[max_idx])
        max_idx = prev[max_idx]

    return subset[::-1]

import re

def match_string(string):
