def ncr_mod_p(n, r, p):
    if r == 0:
        return 1

    numer = 1
    denom = 1
    for i in range(r):
        numer = (numer * (n - i)) % p
        denom = (denom * (i + 1)) % p

    return (numer * pow(denom, p-2, p)) % p

def eulerian(n, m):
    if n == 0 and m == 0:
        return 1
    if m >= n or m < 0:
        return 0
    return (n - m) * eulerian(n - 1, m - 1) + (m + 1) * eulerian(n - 1, m)

