def maxSumDivThree(n):
    if n == 0 or n == 1 or n == 2:
        return n
    else:
        return max(n, maxSumDivThree(n // 3) + maxSumDivThree(n // 3 + n % 3) + maxSumDivThree(n // 3 - 1 + n % 3))

def is_subset_sum(set, n, sum):
    if sum == 0:
        return True
    if n == 0:
        return False
    if set[n - 1] > sum:
        return is_subset_sum(set, n - 1, sum)
    return is_subset_sum(set, n - 1, sum) or is_subset_sum(set, n - 1, sum - set[n - 1])

def count_distinct_prime_powers(n):
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    prime_powers = set()
    for i in range(2, n + 1):
        if n % i == 0 and is_prime(i):
            count = 0
            while n % i == 0:
                n //= i
                count += 1
            prime_powers.add(count)
    return len(prime_powers)

