        return {}
    count = 1
    frequency = {}
    for i in range(1, len(lst)):
        if lst[i] == lst[i-1]:
            count += 1
        else:
            if count > 1:
                frequency.setdefault(lst[i-1], 0)
                frequency[lst[i-1]] += count
            count = 1
    if count > 1:
        frequency.setdefault(lst[-1], 0)
        frequency[lst[-1]] += count
    return frequency

