from collections import Counter

def top_k_frequent(nums, k):
    nums_flattened = [num for sublist in nums for num in sublist]
    count = Counter(nums_flattened)
    return heapq.nlargest(k, count.keys(), key=count.get)

def radix_sort(lst):
    RADIX = 10
    placement = 1
    max_digit = max(lst)

    while max_digit // placement > 0:
        buckets = [list() for _ in range(RADIX)]
        for i in lst:
            tmp = i // placement
            buckets[tmp % RADIX].append(i)
        a = 0
        for b in range(RADIX):
            for i in buckets[b]:
                lst[a] = i
                a += 1
        placement *= RADIX
    return lst

def count_unset_bits(n):
    unset_bits = 0
    while n > 0:
        if not n & 1:
            unset_bits += 1
        n = n >> 1
    return unset_bits

def set_leftmost_unset_bit(n):
    if n == 0:
        return 1
    m = n
    x = 0
    while m != 0:
        m = m >> 1
        x = (x << 1) + 1
    return n | (n + 1) & ~x

def comb_sort(arr):
    gap = len(arr)
    swapped = True
    while gap != 1 or swapped:
        gap = max(1, int(gap / 1.3))
        swapped = False
        for i in range(len(arr) - gap):
            if arr[i] > arr[i + gap]:
                arr[i], arr[i + gap] = arr[i + gap], arr[i]
                swapped = True
    return arr

def are_isomorphic(str1, str2):
    if len(str1) != len(str2):
        return False

    mapping_str1_to_str2 = {}
    mapping_str2_to_str1 = {}

    for char1, char2 in zip(str1, str2):
        if (char1 in mapping_str1_to_str2 and mapping_str1_to_str2[char1] != char2) or \
           (char2 in mapping_str2_to_str1 and mapping_str2_to_str1[char2] != char1):
            return False
        mapping_str1_to_str2[char1] = char2
        mapping_str2_to_str1[char2] = char1

    return True

def find_smallest_multiple(n):
    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x

    def lcm(x, y):
        return x * y // gcd(x, y)

    smallest_multiple = 1
    for i in range(1, n + 1):
        smallest_multiple = lcm(smallest_multiple, i)
    return smallest_multiple

