        return 0
    dp = [1] * len(arr)  # Initialize DP array
    for i in range(1, len(arr)):
        for j in range(i):
            if abs(arr[i] - arr[j]) == 1:  # Check difference between elements
                dp[i] = max(dp[i], dp[j] + 1)
