def is_keith_number(n):
    if n < 10:
        return False

    temp = n
    seq = []

    while temp > 0:
        seq.append(temp % 10)
        temp //= 10

    seq.reverse()

    while sum(seq) < n:
        seq.append(sum(seq))
        seq.pop(0)

    return sum(seq) == n

