def find_second_smallest(numbers):
    if len(numbers) < 2:
        return None
    first, second = float('inf'), float('inf')
    for num in numbers:
        if num < first:
            second = first
            first = num
        elif first < num < second:
            second = num
    if second == float('inf'):
