    return bool(re.search(pattern, s))

def are_roots_reciprocal(a, b, c):
    if a == 0:
        return False
    discriminant = b**2 - 4*a*c
    if discriminant < 0:
        return False
    root1 = (-b + discriminant**0.5) / (2*a)
    root2 = (-b - discriminant**0.5) / (2*a)
    if root1 == 0 or root2 == 0:
        return False
    return abs(root1 * root2) == 1

def nCr_mod_p(n, r, p):
    if r > n:
        return 0
    if r == 0 or r == n:
        return 1
    num = den = 1
    for i in range(r):
        num = (num * (n - i)) % p
        den = (den * (i + 1)) % p
    return (num * pow(den, p - 2, p)) % p

def find_nth_digit_in_fraction(numerator, denominator, n):
    fraction = numerator / denominator
    fraction_str = str(fraction).split('.')[1]  # Remove the integer part
    if n <= len(fraction_str):
        return fraction_str[n-1]
    else:
        return "Nth digit does not exist."

