    return max(char_frequency, key=char_frequency.get)

import heapq

def max_product_of_three(nums):
    if len(nums) < 3:
        raise ValueError("Array must contain at least three elements.")

    # Find the three largest numbers and two smallest numbers using heap
    largest = heapq.nlargest(3, nums)
    smallest = heapq.nsmallest(2, nums)

    # The maximum product can be either the product of the three largest numbers,
    # or the product of two smallest numbers (possibly negatives) and the largest number
    return max(largest[0] * largest[1] * largest[2], smallest[0] * smallest[1] * largest[0])

def last_digit_of_factorial_division(a, b):
    if a > b:
        return 0
    result = 1
    for i in range(b, a, -1):
        result = (result * i) % 10
    return result

def product_kth_index(tuples, k):
    product = 1
    for tup in tuples:
        if len(tup) > k:
            product *= tup[k]
    return product

def index_of_smallest_triangular_number_with_n_digits(n):
    def is_n_digits(number, n):
        return 10**(n-1) <= number < 10**n

    def triangular_number(k):
        return k * (k + 1) // 2

    k = 1
    while not is_n_digits(triangular_number(k), n):
        k += 1
    return k

def harmonic_sum(n):
    if n == 1:
        return 1
    else:
        return 1 / n + harmonic_sum(n - 1)

def gcd(a, b):
    if b == 0:
        return a
    else:
        return gcd(b, a % b)

def minimize_string_length(s):
    if not s:
        return s
    char_counts = {}
    for char in s:
        char_counts[char] = char_counts.get(char, 0) + 1
    min_char = min(char_counts, key=char_counts.get)
    return s.replace(min_char, '')

import heapq

def find_largest_numbers(nums, k):
    if k >= len(nums):
        return max(nums) if nums else None
    return heapq.nlargest(k, nums)

def find_largest_k(x, y):
    # Assuming x and y are positive integers with x > y
    if x <= y or y < 0:
        return None
    return (x - 1) + y

def count_even_xor_pairs(arr):
    even_count, odd_count = 0, 0

    for num in arr:
        if num % 2 == 0:
            even_count += 1
        else:
            odd_count += 1

    even_xor_pairs = (even_count * (even_count - 1) // 2) + (odd_count * (odd_count - 1) // 2)
    return even_xor_pairs

def find_most_significant_set_bit(n):
    if n == 0:
        return 0
    msb = 1
    while n > 1:
        n = n >> 1
        msb = msb << 1
    return msb

def difference_between_sum_of_even_and_odd_digits(n):
    even_sum = 0
    odd_sum = 0
    while n > 0:
        digit = n % 10
        if digit % 2 == 0:
            even_sum += digit
        else:
            odd_sum += digit
        n = n // 10
    return even_sum - odd_sum

def maxSumBitonicSubseq(arr):
    n = len(arr)
    inc = [0] * n  
    dec = [0] * n  
    maximum = 0

    # Fill inc[] from left to right
    for i in range(n):
        inc[i] = arr[i]
        for j in range(i):
            if (arr[i] > arr[j] and inc[i] < inc[j] + arr[i]):
                inc[i] = inc[j] + arr[i]

    # Fill dec[] from right to left
    for i in reversed(range(n)):
        dec[i] = arr[i]
        for j in range(i + 1, n):
            if(arr[i] > arr[j] and dec[i] < dec[j] + arr[i]):
                dec[i] = dec[j] + arr[i]

    # Find the maximum value by adding inc[] and dec[] values
    # and subtracting arr[i] (As arr[i] is added twice)
    for i in range(n):
        maximum = max((inc[i] + dec[i] - arr[i]), maximum)

    return maximum

def can_be_sum_of_two_squares(n):
    for i in range(int(n**0.5) + 1):
        for j in range(i, int(n**0.5)+1):
            if i*i + j*j == n:
                return True
    return False

def sum_of_amicable_numbers(n):
    def d(num):
        return sum([i for i in range(1, num) if num % i == 0])

    amicable_numbers = set()

    for number in range(1, n + 1):
        partner = d(number)
        if d(partner) == number and number != partner:
            amicable_numbers.add(number)
            amicable_numbers.add(partner)

    return sum(amicable_numbers)

def generate_hexagon_grid(width, height):
    hexagon_grid = []
    for row in range(height):
        for col in range(width):
            x = col * 1.5
            y = row * (3**0.5)
            if col % 2 == 1:
                y += (3**0.5) / 2
            hexagon = [(x, y), (x+0.5, y+(3**0.5)/2), (x+0.5, y+3**0.5),
                       (x, y+2*(3**0.5)/2), (x-0.5, y+3**0.5), (x-0.5, y+(3**0.5)/2)]
            hexagon_grid.append(hexagon)
    return hexagon_grid

def count_sequences(n, m):
    def count_recursive(start, length):
        if length == 1:
            return m - start + 1
        cnt = 0
        for i in range(start * 2, m + 1):
            cnt += count_recursive(i, length - 1)
        return cnt

    return count_recursive(1, n)

