    return [single_or_tuple((len(list(group)), key)) for key, group in groupby(lst)]

import numpy as np

def max_average_path(matrix):
    n = len(matrix)
    if n == 0:
        return 0

    dp = np.zeros((n, n))
    dp[0, 0] = matrix[0][0]

    for i in range(1, n):
        dp[0, i] = dp[0, i-1] + matrix[0][i]
        dp[i, 0] = dp[i-1, 0] + matrix[i][0]

    for i in range(1, n):
        for j in range(1, n):
            dp[i, j] = max(dp[i-1, j], dp[i, j-1]) + matrix[i][j]

    return dp[n-1, n-1] / (2 * n - 1)

def sum_xor_pairs(arr):
    result = 0
    n = len(arr)
    for i in range(32):
        count_set_bits = 0
        for j in range(n):
            if (arr[j] & (1 << i)):
                count_set_bits += 1
        result += (1 << i) * count_set_bits * (n - count_set_bits)
    return result

def first_missing_positive(nums):
    nums = [num for num in nums if num > 0]
    nums.sort()
    missing = 1
    for num in nums:
        if num == missing:
            missing += 1
    return missing

def min_swaps_for_bracket_balancing(s):
    imbalance, swaps = 0, 0
    open_brackets, close_brackets = 0, 0

    for bracket in s:
        if bracket == '[':
            open_brackets += 1
            if imbalance > 0:
                swaps += imbalance
                imbalance -= 1
        else:
            close_brackets += 1
            imbalance = close_brackets - open_brackets

    return swaps

def getMaxGold(grid):
    def isValid(x, y):
        return x >= 0 and x < m and y >= 0 and y < n

    def getMaxGoldUtil(x, y):
        if not isValid(x, y) or grid[x][y] == 0:
            return 0

        grid[x][y] = -grid[x][y]  # Mark visited

        # Possible moves: right, right-up, right-down
        right = getMaxGoldUtil(x, y + 1)
        right_up = getMaxGoldUtil(x - 1, y + 1)
        right_down = getMaxGoldUtil(x + 1, y + 1)

        # Backtrack to unmark visited
        grid[x][y] = -grid[x][y]

        # Return the max gold that can be collected by moving right
        return grid[x][y] + max(right, right_up, right_down)

    if not grid:
        return 0

    m, n = len(grid), len(grid[0])
    max_gold = 0

    # Try starting from each cell
    for i in range(m):
        for j in range(n):
            if grid[i][j] != 0:
                max_gold = max(max_gold, getMaxGoldUtil(i, j))

    return max_gold

def longest_chain(pairs):
    pairs.sort(key=lambda x: x[0])  # Sort pairs based on the first element
    dp = [1] * len(pairs)  # Initialize dp array, 1 chain for each pair initially

    for i in range(1, len(pairs)):
        for j in range(i):
            if pairs[j][1] < pairs[i][0]:  # Check if current pair can follow the jth pair
                dp[i] = max(dp[i], dp[j] + 1)  # Update the longest chain for ith pair

    return max(dp)

def capitalize_first_last_letters(s):
    words = s.split()
    capitalized_words = []
    for word in words:
        if len(word) > 1:
            capitalized_word = word[0].upper() + word[1:-1] + word[-1].upper()
        else:
            capitalized_word = word.upper()
        capitalized_words.append(capitalized_word)
    return ' '.join(capitalized_words)

def min_jumps(arr):
    n = len(arr)
    if n <= 1:
        return 0
    if arr[0] == 0:
        return -1
    max_reach = arr[0]
    step = arr[0]
    jump = 1
    for i in range(1, n):
        if i == n - 1:
            return jump
        max_reach = max(max_reach, i + arr[i])
        step -= 1
        if step == 0:
            jump += 1
            if i >= max_reach:
                return -1
            step = max_reach - i
    return -1

import numpy as np
from scipy.optimize import minimize_scalar

def find_minimum_periodic(f, period, bounds=(0, 1), tol=1e-5):
    def wrapped_f(x):
        return f(x % period)

    res = minimize_scalar(wrapped_f, bounds=bounds, method='bounded', options={'xatol': tol})
    return res.fun

def babylonian_square_root(n, accuracy=1e-10):
    x = n
    while True:
        next_guess = 0.5 * (x + n / x)
        if abs(x - next_guess) < accuracy:
            break
        x = next_guess
    return x

def counting_sort(arr):
    maximum = max(arr)
    minimum = min(arr)
    range_of_elements = maximum - minimum + 1
    count = [0] * range_of_elements
    output = [0] * len(arr)

    for i in range(0, len(arr)):
        count[arr[i]-minimum] += 1

    for i in range(1, len(count)):
        count[i] += count[i-1]

    for i in range(len(arr)-1, -1, -1):
        output[count[arr[i] - minimum] - 1] = arr[i]
        count[arr[i] - minimum] -= 1

    for i in range(0, len(arr)):
        arr[i] = output[i]

def calculate_odd_days(year):
