from math import gcd

def find_lcm(arr):
    if not arr:
        return None
    lcm = arr[0]
    for i in range(1, len(arr)):
        lcm = lcm * arr[i] // gcd(lcm, arr[i])
    return lcm

def maxSumWithK(arr, n, k):
    dp = [0]*n
    dp[0] = arr[0]

    for i in range(1, n):
        dp[i] = arr[i]
        for j in range(i):
            if arr[j] < arr[i]:
                dp[i] = max(dp[i], dp[j] + arr[i])

    max_sum = dp[0]
    for i in range(k):
        if dp[i] + arr[k] > max_sum:
            max_sum = dp[i] + arr[k]

    return max_sum

def find_triplet_with_sum(arr, sum):
    arr.sort()
    n = len(arr)
    for i in range(n - 2):
        left = i + 1
        right = n - 1
        while left < right:
            current_sum = arr[i] + arr[left] + arr[right]
            if current_sum == sum:
                return [arr[i], arr[left], arr[right]]
            elif current_sum < sum:
                left += 1
            else:
                right -= 1
    return []

def frequency_of_smallest(arr):
    if not arr:
        return 0
    smallest = min(arr)
    return arr.count(smallest)

def max_segments(n, a, b, c):
    max_segments = -1
    for i in range(n // a + 1):
        for j in range((n - i * a) // b + 1):
            k = (n - i * a - j * b) / c
            if k.is_integer():
                k = int(k)
                max_segments = max(max_segments, i + j + k)
    return max_segments

def remove_duplicates_from_list_of_lists(list_of_lists):
