    else:
        return(fibonacci(n-1) + fibonacci(n-2))

def find_first_position(arr, target):
    left, right = 0, len(arr) - 1
    while left <= right:
        mid = left + (right - left) // 2
        if arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    if left < len(arr) and arr[left] == target:
        return left
    return -1

