def count_reverse_pairs(str_list):
    reverse_pairs = 0
    checked_pairs = set()

    for i, s in enumerate(str_list):
        if s not in checked_pairs:
            reverse = s[::-1]
            if reverse in str_list[i+1:]:
                reverse_pairs += 1
                checked_pairs.add(s)
                checked_pairs.add(reverse)

    return reverse_pairs

