    return [count_inversions_in_tuple(t) for t in tuple_list]

def sum_of_primes(n):
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num ** 0.5) + 1):
            if num % i == 0:
                return False
        return True

    total = sum(i for i in range(2, n + 1) if is_prime(i))
    return total

def multiply(a, b):
    if b == 0:
        return 0
    if b > 0:
        return a + multiply(a, b - 1)
    if b < 0:
        return -multiply(a, -b)

def check_equal_opposite_roots(a, b, c):
    discriminant = b**2 - 4*a*c
    if discriminant == 0:
        root = -b / (2*a)
        return root == -root
    else:
        return False

def count_elements_in_tuple(my_list, my_tuple):
