    cnt = 0
    for elem1, elem2, elem3 in zip(list1, list2, list3):
        if elem1 == elem2 == elem3:
            cnt += 1
    return cnt

def max_sum(n, memo={}):
    if n == 0:
        return 0
    if n in memo:
        return memo[n]
    memo[n] = max(max_sum(n//2) + max_sum(n//3) + max_sum(n//4) + max_sum(n//5), n)
    return memo[n]

def are_consecutive(lst):
    if not lst:
        return False
    lst_sorted = sorted(lst)
    return all(lst_sorted[i] + 1 == lst_sorted[i + 1] for i in range(len(lst_sorted) - 1))

def min_product_from_pairs(tuples_list):
    if not tuples_list:
        return None
    min_product = float('inf')
    for pair in tuples_list:
        product = pair[0] * pair[1]
        if product < min_product:
            min_product = product
    return min_product

def findMinCoins(V, coins):
    n = len(coins)
    dp = [float('inf')] * (V + 1)
    dp[0] = 0

    for i in range(1, V + 1):
        for j in range(n):
            if coins[j] <= i:
                sub_res = dp[i - coins[j]]
                if sub_res != float('inf') and sub_res + 1 < dp[i]:
                    dp[i] = sub_res + 1

    return dp[V] if dp[V] != float('inf') else -1

def count_squares(length, width):
    count = 0
    for i in range(1, min(length, width) + 1):
        count += (length - i + 1) * (width - i + 1)
    return count

from collections import defaultdict

def group_pairs(kv_pairs):
    grouped_dict = defaultdict(list)
    for key, value in kv_pairs:
        grouped_dict[key].append(value)
    return dict(grouped_dict)

def add_min_to_make_even(arr):
    sum_arr = sum(arr)
    if sum_arr % 2 == 0:
        return 0
    else:
        return 1

def last_two_digits_of_factorial(n):
    if n == 0 or n == 1:
        return "01"
    elif n == 2:
        return "02"
    elif n == 3:
        return "06"
    elif n == 4:
        return "24"
    elif n == 5:
        return "20"
    else:
        return "00"

import re

def match_string(text):
    pattern = 'a.*b$'
    if re.search(pattern, text):
        return True
    else:
        return False

def calculate_height(node):
    if node is None:
        return 0
    else:
        left_height = calculate_height(node.left)
        right_height = calculate_height(node.right)
        return max(left_height, right_height) + 1

def join_tuples(tuples_list):
    result = []
    while tuples_list:
        first = tuples_list.pop(0)
        first_list = list(first)
        indexes_to_remove = []
        for i, other in enumerate(tuples_list):
            if first[0] == other[0]:
                first_list.extend(other[1:])
                indexes_to_remove.append(i)
        for i in sorted(indexes_to_remove, reverse=True):
            tuples_list.pop(i)
        result.append(tuple(first_list))
    return result

def min_operations_to_equal(nums, k):
    nums.sort()
    n = len(nums)
    prefix_sum = [0] * (n + 1)

    for i in range(1, n + 1):
        prefix_sum[i] = prefix_sum[i - 1] + nums[i - 1]

    min_ops = float('inf')

    for i in range(n):
        total = prefix_sum[n] - prefix_sum[i] - (n - i) * nums[i]
        if total <= k:
            min_ops = min(min_ops, i + max(0, k - total))
        else:
            break

    return min_ops

def longestSubseqWithDiffOne(arr):
    n = len(arr)
    dp = [1 for i in range(n)]

    for i in range(n):
        for j in range(i):
            if abs(arr[i] - arr[j]) == 1:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

def count_odd_set_bits(nums):
    def count_set_bits(n):
        count = 0
        while n:
            count += n & 1
            n >>= 1
        return count

    odd_set_bits_count = sum(1 for num in nums if count_set_bits(num) % 2 != 0)

    return odd_set_bits_count

def nth_catalan_number(n):
    if n == 0 or n == 1:
        return 1
    catalan = [0] * (n + 1)
    catalan[0], catalan[1] = 1, 1

    for i in range(2, n + 1):
        for j in range(i):
            catalan[i] += catalan[j] * catalan[i - j - 1]
    return catalan[n]

def is_subarray(main_array, sub_array):
    if not sub_array:  # An empty array is a subarray of any array
        return True
    if not main_array:  # An empty main array cannot have a subarray
        return False

    for i in range(len(main_array) - len(sub_array) + 1):
        for j in range(len(sub_array)):
            if main_array[i + j] != sub_array[j]:
                break
            elif j == len(sub_array) - 1:
                return True
    return False

def min_swaps_to_convert(s1, s2):
    if len(s1) != len(s2) or s1.count('0') != s2.count('0') or s1.count('1') != s2.count('1'):
        return -1
    swaps = 0
    for i in range(len(s1)):
        if s1[i] != s2[i]:
            swaps += 1
    return swaps // 2

def count_primes(n):
    if n < 3:
        return 0
    primes = [True] * n
    primes[0] = primes[1] = False
    for i in range(2, int(n**0.5) + 1):
        if primes[i]:
            primes[i*i:n:i] = [False] * ((n-1-i*i)//i + 1)
    return sum(primes)

def has_increasing_trend(sequence):
    for i in range(len(sequence)-1):
        if sequence[i] >= sequence[i+1]:
            return False
    return True

def max_sum_no_three_consecutive(arr):
    n = len(arr)
    if n == 0:
        return 0
    if n == 1:
        return arr[0]
    if n == 2:
        return arr[0] + arr[1]

    dp = [0] * n
    dp[0] = arr[0]
    dp[1] = arr[0] + arr[1]
    dp[2] = max(dp[1], max(arr[0] + arr[2], arr[1] + arr[2]))

    for i in range(3, n):
        dp[i] = max(dp[i-1], max(dp[i-2] + arr[i], dp[i-3] + arr[i-1] + arr[i]))

    return dp[-1]

def count_hex_numbers(start, end):
    count = 0
    for i in range(start, end + 1):
        if all(c in '0123456789ABCDEFabcdef' for c in hex(i)[2:]):
            count += 1
    return count

def countSubsequences(arr, k):
    n = len(arr)

    def countSubsequencesUtil(arr, n, k, index, product):
        if index == n:
            if product < k:
                return 1
            else:
                return 0
        count = 0
        count += countSubsequencesUtil(arr, n, k, index + 1, product)  # Not including the current element
        if product * arr[index] < k:
            count += countSubsequencesUtil(arr, n, k, index + 1, product * arr[index])  # Including the current element
        return count

    return countSubsequencesUtil(arr, n, k, 0, 1) - 1  # Subtracting 1 to exclude the empty subsequence

def count_numeric_values(input_string):
    numeric_count = 0
    for character in input_string:
        if character.isdigit():
            numeric_count += 1
    return numeric_count

def combine_dictionaries(dict1, dict2):
    combined_dict = {}
    for key in dict1.keys() | dict2.keys():
        combined_dict[key] = dict1.get(key, 0) + dict2.get(key, 0)
    return combined_dict

def is_digit_frequency_valid(num):
    num_str = str(num)
    for digit in set(num_str):
        if num_str.count(digit) > int(digit):
            return False
    return True

def is_undulating(number):
    num_str = str(number)
    if len(num_str) < 3 or len(set(num_str)) != 2:
        return False
    for i in range(len(num_str) - 2):
        if num_str[i] != num_str[i+2]:
            return False
    return True

def find_pair_with_highest_product(arr):
    if len(arr) < 2:
        return None
    if len(arr) == 2:
        return (arr[0], arr[1])

    max_product = float('-inf')
    pair = (0, 0)

    for i in range(len(arr)):
        for j in range(i + 1, len(arr)):
            current_product = arr[i] * arr[j]
            if current_product > max_product:
                max_product = current_product
                pair = (arr[i], arr[j])

    return pair

def largest_product_adjacent(nums):
    if len(nums) < 2:
        return None
    max_product = nums[0] * nums[1]
    for i in range(1, len(nums) - 1):
        product = nums[i] * nums[i + 1]
        if product > max_product:
            max_product = product
    return max_product

def maxProfit(k, prices):
    if not prices:
        return 0

    n = len(prices)
    if k >= n // 2:
        return sum(max(prices[i+1] - prices[i], 0) for i in range(n-1))

    dp = [[0] * n for _ in range(k+1)]

    for i in range(1, k+1):
        max_diff = -prices[0]
        for j in range(1, n):
            dp[i][j] = max(dp[i][j-1], prices[j] + max_diff)
            max_diff = max(max_diff, dp[i-1][j] - prices[j])

    return dp[k][-1]

def find_divisible_numbers(start, end):
    def is_divisible(num):
        for digit in str(num):
            if digit == '0' or num % int(digit) != 0:
                return False
        return True

    divisible_numbers = []
    for number in range(start, end + 1):
        if is_divisible(number):
            divisible_numbers.append(number)

    return divisible_numbers

def extract_elements(lst, count):
    result = []
    for i in range(len(lst) - count + 1):
        result.append(lst[i:i+count])
    return result

def reverse_vowels(s):
    vowels = 'aeiouAEIOU'
    i, j = 0, len(s) - 1
    s_list = list(s)
    while i < j:
        if s_list[i] in vowels and s_list[j] in vowels:
            s_list[i], s_list[j] = s_list[j], s_list[i]
            i += 1
            j -= 1
        if s_list[i] not in vowels:
            i += 1
        if s_list[j] not in vowels:
            j -= 1
    return ''.join(s_list)

def count_pairs_with_sum(arr, sum):
    count = 0
    for i in range(len(arr)):
        for j in range(i + 1, len(arr)):
            if arr[i] + arr[j] == sum:
                count += 1
    return count

def next_bigger_number(n):
    number_list = list(str(n))
    i = len(number_list) - 1
    while i > 0 and number_list[i - 1] >= number_list[i]:
        i -= 1
    if i <= 0:
        return -1
    j = len(number_list) - 1
    while number_list[j] <= number_list[i - 1]:
        j -= 1
    number_list[i - 1], number_list[j] = number_list[j], number_list[i - 1]
    number_list[i:] = number_list[len(number_list) - 1: i - 1: -1]
    return int(''.join(number_list))

def romanToInt(s: str) -> int:
    roman_map = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    prev_value = 0

    for char in reversed(s):
        value = roman_map[char]
        if value < prev_value:
            total -= value
        else:
            total += value
        prev_value = value

    return total

def sum_of_fourth_power(n):
    sum = 0
    for i in range(2, 2*n+1, 2):
        sum += i**4
    return sum

from collections import Counter

def frequency_of_elements(list_of_lists):
