def run_length_encode(lst):
    if not lst:
        return []

    encoded_list = []
    current_element = lst[0]
    count = 1

    for element in lst[1:]:
        if element == current_element:
            count += 1
        else:
            encoded_list.append((current_element, count))
            current_element = element
            count = 1

    encoded_list.append((current_element, count))
    return encoded_list

def max_sum_of_disjoint_pairs(arr, k):
    arr.sort()
    n = len(arr)
    dp = [0 for _ in range(n + 1)]

    for i in range(n - 1, -1, -1):
        not_take = dp[i + 1]
        take = 0
        if i + 1 < n and arr[i + 1] - arr[i] <= k:
            take = arr[i] + arr[i + 1]
            if i + 2 < n:
                take += dp[i + 2]
        dp[i] = max(take, not_take)

    return dp[0]

def maxProductSubarray(arr):
    if not arr:
        return 0

    max_product = min_product = max_so_far = arr[0]

    for num in arr[1:]:
        temp_max = max(num, max_product * num, min_product * num)
        min_product = min(num, max_product * num, min_product * num)
        max_product = temp_max

        max_so_far = max(max_so_far, max_product)

    return max_so_far

def count_unequal_pairs(arr):
    count = 0
    for i in range(len(arr)):
        for j in range(i+1, len(arr)):
            if arr[i] != arr[j]:
