def get_lucid_number(n):
    lucid_numbers = [2]

    for i in range(3, n+1):
        count = 0
        for num in lucid_numbers:
            if i % num == 0:
                count += 1
        if count == 1:
            lucid_numbers.append(i)

    if n < 2:
        return None
    else:
        return max([num for num in lucid_numbers if num <= n])

def longest_palindromic_subsequence(s):
    def helper(start, end):
        if start > end: return 0
        if start == end: return 1
        if s[start] == s[end]:
            return 2 + helper(start + 1, end - 1)
        else:
            return max(helper(start + 1, end), helper(start, end - 1))

    return helper(0, len(s) - 1)

def find_smallest_missing(arr):
    start, end = 0, len(arr) - 1
    while start <= end:
        mid = start + (end - start) // 2
        if arr[mid] == mid:
            start = mid + 1
        else:
            end = mid - 1
    return start

