def max_sum_increasing_subsequence(arr):
    n = len(arr)
    max_sum = [0] * n
    for i in range(n):
        max_sum[i] = arr[i]

    for i in range(1, n):
        for j in range(0, i):
            if arr[i] > arr[j] and max_sum[i] < max_sum[j] + arr[i]:
                max_sum[i] = max_sum[j] + arr[i]

    return max(max_sum)

def find_element_before_count(record, element):
    count = 0
    for item in record:
        if item == element:
            break
        count += 1
    else:
