    return count

def is_majority_element(arr, n):
    mid_index = n // 2
    target = arr[mid_index]
    count = 0
    for num in arr:
        if num == target:
            count += 1
    return count > n // 2

def entringer_number(n, k):
    if k == 0:
        return 1
    elif k > n:
        return 0
    elif k == n:
        return 0 if n % 2 == 0 else 1
    else:
        return entringer_number(n, k - 1) + entringer_number(n - 1, n - k)

def print_season(month, day):
    if (month == 12 and day >= 21) or (1 <= month <= 2) or (month == 3 and day < 21):
        print("Winter")
    elif (month == 3 and day >= 21) or (4 <= month <= 5) or (month == 6 and day < 21):
        print("Spring")
    elif (month == 6 and day >= 21) or (7 <= month <= 8) or (month == 9 and day < 23):
        print("Summer")
    elif (month == 9 and day >= 23) or (10 <= month <= 11) or (month == 12 and day < 21):
        print("Fall")

def is_prime(n):
    if n <= 1:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def find_last_position(arr, target):
    left, right = 0, len(arr) - 1
    position = -1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == target:
            position = mid
            left = mid + 1
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return position

def triangle_type(a, b, c):
    if a == b == c:
        return "Equilateral"
    elif a == b or b == c or a == c:
        return "Isosceles"
    else:
