def largest_palindrome(arr):
    def is_palindrome(n):
        return str(n) == str(n)[::-1]

    largest = -1
    for num in arr:
        if is_palindrome(num) and num > largest:
            largest = num
    return largest

def harmonic_sum(n):
    if n == 1:
        return 1
    else:
        return 1 / n + harmonic_sum(n - 1)

def find_nested_elements_in_list(outer_list, comparison_list):
    found_elements = []
    for element in outer_list:
        if isinstance(element, list):
            for nested_element in element:
                if nested_element in comparison_list:
                    found_elements.append(nested_element)
        elif element in comparison_list:
            found_elements.append(element)
    return found_elements

def count_binary_sequences(n):
    def binomial_coefficient(n, k):
        if k == 0 or k == n:
            return 1
        return binomial_coefficient(n-1, k-1) + binomial_coefficient(n-1, k)

    count = 0
    for i in range(n + 1):
        count += binomial_coefficient(n, i) ** 2
    return count

def remove_parentheses(s):
    result = ''
    depth = 0
    for char in s:
        if char == '(':
            depth += 1
        elif char == ')' and depth:
            depth -= 1
        elif depth == 0:
            result += char
    return result

def filter_student_size(student_sizes, min_height=None, max_height=None, min_width=None, max_width=None):
    filtered_students = {}
    for student, sizes in student_sizes.items():
        height, width = sizes
        if ((min_height is None or height >= min_height) and
                (max_height is None or height <= max_height) and
                (min_width is None or width >= min_width) and
                (max_width is None or width <= max_width)):
            filtered_students[student] = sizes
    return filtered_students

def rearrange_elements(arr):
    left, right = 0, len(arr) - 1
    while left < right:
        while arr[left] < 0 and left < right:
            left += 1
        while arr[right] >= 0 and left < right:
            right -= 1
        if left < right:
            arr[left], arr[right] = arr[right], arr[left]
    return arr

import re

def find_adverbs(sentence):
    adverb_pattern = r'\w+ly\b'
    adverbs = re.findall(adverb_pattern, sentence)
    positions = [match.start() for match in re.finditer(adverb_pattern, sentence)]
    return list(zip(adverbs, positions))

def is_concatenated(s):
    if not s:
        return False
    for i in range(1, len(s)//2 + 1):
        if s[:i] * (len(s) // len(s[:i])) == s:
            return True
    return False

def max_diff_zeros_ones(binary_str):
    max_diff = 0
    current_diff = 0

    for char in binary_str:
        if char == '0':
            current_diff += 1
        else:
            current_diff -= 1

        if current_diff < 0:
            current_diff = 0
        max_diff = max(max_diff, current_diff)

    if max_diff == 0:
        return -1  # Indicates all 1s and no 0s

    return max_diff

class TreeNode:
