def max_sum_non_adjacent(arr):
    incl = 0
    excl = 0

    for i in arr:
        new_excl = excl if excl>incl else incl
        incl = excl + i
        excl = new_excl
    return (excl if excl>incl else incl)

def sum_of_repeated_elements(arr):
    element_count = {}
    for element in arr:
        if element in element_count:
            element_count[element] += 1
        else:
            element_count[element] = 1

    return sum(element * count for element, count in element_count.items() if count > 1)

def min_removals(arr, k):
    arr.sort()
    left, right = 0, 0
    min_removals = float('inf')

    while right < len(arr):
        while arr[right] - arr[left] > k:
            left += 1
        min_removals = min(min_removals, (len(arr) - (right - left + 1)))
        right += 1

    return min_removals

