def check_root_relation(a, b, c):
    discriminant = b**2 - 4*a*c
    if discriminant < 0:
        return False
    else:
        root1 = (-b + discriminant**0.5) / (2*a)
        root2 = (-b - discriminant**0.5) / (2*a)
        return root1 == 2*root2 or root2 == 2*root1

