        return n
    pell_prev, pell = 1, 2
    for i in range(3, n + 1):
        pell_prev, pell = pell, 2 * pell + pell_prev
    return pell

def sort_array_with_012(arr):
    count_0, count_1, count_2 = 0, 0, 0
    for num in arr:
        if num == 0:
            count_0 += 1
        elif num == 1:
            count_1 += 1
        else:
            count_2 += 1
    arr[:count_0] = [0] * count_0
    arr[count_0:count_0+count_1] = [1] * count_1
    arr[count_0+count_1:] = [2] * count_2
    return arr

