        return packed_list
    sublist = [lst[0]]  # Initialize the first sublist
    for element in lst[1:]:
        if element == sublist[-1]:
            sublist.append(element)
        else:
            packed_list.append(sublist)
            sublist = [element]
    packed_list.append(sublist)  # Add the last sublist
    return packed_list

