def max_product_pair(arr):
    if len(arr) < 2:
        return None

    # Initialize maximum and second maximum
    max1 = max(arr[0], arr[1])
    max2 = min(arr[0], arr[1])

    # Traverse given array
    for i in range(2, len(arr)):
        if arr[i] > max1:
            max2 = max1
            max1 = arr[i]
        elif arr[i] > max2:
            max2 = arr[i]

    return (max1, max2)

