def find_fixed_point(arr):
    for i in range(len(arr)):
        if arr[i] == i:
            return i
    return None

def calculate_dogs_age_in_dog_years(human_years):
    if human_years <= 2:
        dog_years = human_years * 10.5
    else:
        dog_years = 21 + (human_years - 2) * 4
    return dog_years

def is_subset_nested(subset, superset):
    def is_subset(sub, sup):
        if not sub:
            return True
        if not sup:
            return False
        if type(sub[0]) == list:
            for i in range(len(sup)):
                if sup[i] == sub[0] or (type(sup[i]) == list and is_subset(sub[0], sup[i])):
                    return is_subset(sub[1:], sup[i+1:])
        else:
            if sub[0] in sup:
                return is_subset(sub[1:], sup[sup.index(sub[0])+1:])
        return False
    return is_subset(subset, superset)

from math import comb

def sum_of_product_of_binomial_coefficients(n):
    total_sum = 0
    for i in range(n + 1):
        for j in range(n + 1 - i):
            total_sum += comb(n, i) * comb(n - i, j)
    return total_sum

def max_path_sum(triangle):
    if not triangle:
        return 0

    for row in range(len(triangle) - 2, -1, -1):
        for col in range(len(triangle[row])):
            triangle[row][col] += max(triangle[row + 1][col], triangle[row + 1][col + 1])

    return triangle[0][0]

def min_rotations_to_same(s):
    for i in range(len(s)):
        rotated_s = s[i:] + s[:i]
        if rotated_s == s:
            return i
    return len(s)

def count_rotations(arr):
    low, high = 0, len(arr) - 1

    while low <= high:
        mid = (low + high) // 2

        if mid < high and arr[mid] > arr[mid + 1]:
            return mid + 1
        if mid > low and arr[mid] < arr[mid - 1]:
            return mid

        if arr[low] >= arr[mid]:
            high = mid - 1
        else:
            low = mid + 1

    return 0

def choose_non_overlapping_points(range1, range2):
    set1 = set(range(range1[0], range1[1]+1))
    set2 = set(range(range2[0], range2[1]+1))

    non_overlapping_points = set1.symmetric_difference(set2)
    return list(non_overlapping_points)

def is_difference_of_squares(n):
    for i in range(1, n):
        for j in range(i, n):
            if i**2 - j**2 == n or j**2 - i**2 == n:
                return True
    return False

def generate_magic_square(n):
    magic_square = [[0] * n for _ in range(n)]

    num = 1
    i, j = 0, n // 2

    while num <= n ** 2:
        magic_square[i][j] = num
        num += 1
        newi, newj = (i - 1) % n, (j + 1) % n
        if magic_square[newi][newj]:
            i += 1
        else:
            i, j = newi, newj

    return magic_square

def min_sum_factors(number):
    if number < 2:
        return number
    sum_of_factors = 0
    while number % 2 == 0:
        sum_of_factors += 2
        number //= 2
    for i in range(3, int(number**0.5)+1, 2):
        while number % i == 0:
            sum_of_factors += i
            number //= i
    if number > 2:
        sum_of_factors += number
    return sum_of_factors

def ways_to_fill_board(n):
    a, b = 1, 0
    for _ in range(n):
        a, b = b, a + b
    return b

def minCost(cost, m, n):
    dp = [[0 for x in range(n+1)] for x in range(m+1)]
    dp[0][0] = cost[0][0]

    for i in range(1, m+1):
        dp[i][0] = dp[i-1][0] + cost[i][0]

    for j in range(1, n+1):
        dp[0][j] = dp[0][j-1] + cost[0][j]

    for i in range(1, m+1):
        for j in range(1, n+1):
            dp[i][j] = min(dp[i-1][j-1], dp[i-1][j], dp[i][j-1]) + cost[i][j]

    return dp[m][n]

def minSwapsToSortBinaryArray(arr):
    ones = arr.count(1)
    min_swaps, current_ones = float('inf'), 0

    for i in range(len(arr) + ones - 1):
        if i >= ones:
            current_ones -= arr[i-ones]
        current_ones += arr[i % len(arr)]
        min_swaps = min(min_swaps, ones - current_ones)

    return min_swaps

def find_max_indices(nums):
    if not nums:
        return []
    max_value = max(nums)
    return [i for i, num in enumerate(nums) if num == max_value]

def product_of_tuple(numbers):
