            return True
    return False

def find_perfect_squares(start, end):
    perfect_squares = []
    for number in range(start, end + 1):
        root = number ** 0.5
        if root.is_integer():
            perfect_squares.append(number)
    return perfect_squares

import math

def polar_to_rectangular(r, theta):
    x = r * math.cos(theta)
    y = r * math.sin(theta)
    return (x, y)

def largest_divisible_subset(nums):
    nums.sort()
    dp = [[num] for num in nums]
    for i in range(len(nums)):
        for j in range(i):
            if nums[i] % nums[j] == 0 and len(dp[i]) < len(dp[j]) + 1:
                dp[i] = dp[j] + [nums[i]]
    return max(dp, key=len)

def nth_jacobsthal_lucas(n):
    if n == 0:
        return 2
    elif n == 1:
        return 1
    else:
        return nth_jacobsthal_lucas(n - 1) + 2 * nth_jacobsthal_lucas(n - 2)

def count_numbers_with_0th_and_nth_bit_set(n, count):
    result = 0
    for i in range(count):
        if (i & 1) and (i & (1 << n)):
            result += 1
    return result

def count_self_inverses(arr, p):
