def sum_first_even_odd(numbers):
    even_sum = 0
    odd_sum = 0
    for num in numbers:
        if num % 2 == 0:
            if even_sum == 0:
                even_sum = num
        else:
            if odd_sum == 0:
                odd_sum = num
    return even_sum + odd_sum

def nth_lucas(n):
    if n == 0:
        return 2
    if n == 1:
        return 1
    return nth_lucas(n-1) + nth_lucas(n-2)

def remove_first_last_char(s, char):
    first = s.find(char)
    last = s.rfind(char)
    if first != -1:
        s = s[:first] + s[first+1:]
    if last != -1 and last != first:
        s = s[:last-1] + s[last:]
    return s

def countWays(n, k):
    if n == 0:
        return 0
    elif n == 1:
        return k
    same = k
    diff = k * (k-1)
    total = same + diff
    for i in range(3, n+1):
        same = diff
        diff = total * (k-1)
        total = same + diff
    return total

def find_pairs_with_sum(arr, target_sum):
    pairs = []
    seen = set()
    for number in arr:
        if target_sum-number in seen:
            pairs.append((target_sum-number, number))
        seen.add(number)
    return pairs

