    for record in records:
        if max_value is None or record[1] > max_value:
            max_value = record[1]
    return max_value

def sum_of_products_subarrays(arr):
    result = 0
    n = len(arr)
    for i in range(n):
        for j in range(i, n):
            product = 1
            for k in range(i, j + 1):
                product *= arr[k]
            result += product
    return result

def frequency_of_largest(arr):
