    return arr.count(max_value)

def calculate_standard_deviation(numbers):
    if not numbers:
        return 0.0
    mean = sum(numbers) / len(numbers)
    variance = sum((x - mean) ** 2 for x in numbers) / len(numbers)
    return variance ** 0.5

def count_sequences(values, length):
    dp = [[0] * (length + 1) for _ in range(sum(values) + 1)]
    dp[0][0] = 1

    for i in range(1, length + 1):
        for sum_val in range(sum(values) + 1):
            for v in values:
                if sum_val >= v:
                    dp[sum_val][i] += dp[sum_val - v][i - 1]

    return sum(dp[sum_val][length] for sum_val in range(sum(values) + 1))

def max_run_uppercase(s):
    max_run = 0
    current_run = 0
    for char in s:
        if char.isupper():
            current_run += 1
            max_run = max(max_run, current_run)
        else:
            current_run = 0
    return max_run

def extract_unique_values(input_dict):
