def find_previous_palindrome(num):
    num -= 1
    while not str(num) == str(num)[::-1]:
        num -= 1
    return num

def extract_even_elements(nested_tuple):
    def flatten_and_filter(t):
        for item in t:
            if isinstance(item, (list, tuple)):
                for sub_item in flatten_and_filter(item):
                    yield sub_item
            elif isinstance(item, int) and item % 2 == 0:
                yield item

    return tuple(flatten_and_filter(nested_tuple))

def geometric_sum(n):
    if n < 0:
        return 0
    else:
        return 1 / (2**n) + geometric_sum(n-1)

def longest_consecutive_subsequence(arr):
    if not arr:
        return 0
    s = set(arr)
    longest_streak = 0
    for num in s:
        if num - 1 not in s:
            current_num = num
            current_streak = 1
            while current_num + 1 in s:
                current_num += 1
                current_streak += 1
            longest_streak = max(longest_streak, current_streak)
    return longest_streak

def count_squares(length, width):
    count = 0
    for i in range(1, min(length, width)+1):
        count += (length - i + 1) * (width - i + 1)
    return count

def count_set_bits(n):
    count = 0
    while n:
        count += n & 1
        n >>= 1
    return count

def search_literal_in_string(pattern, text):
    occurrences = []
    index = 0
    while index < len(text):
        index = text.find(pattern, index)
        if index == -1:
            break
        occurrences.append(index)
        index += 1
    return occurrences

def find_last_occurrence(arr, target):
    left, right = 0, len(arr) - 1
    result = -1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == target:
            result = mid
            left = mid + 1
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return result

def count_coin_change(coins, amount):
    dp = [0] * (amount + 1)
    dp[0] = 1
    for coin in coins:
        for i in range(coin, amount + 1):
            dp[i] += dp[i - coin]
    return dp[amount]

def move_zeroes_to_end(arr):
    count = 0 
    for i in range(len(arr)):
        if arr[i] != 0:
            arr[count], arr[i] = arr[i], arr[count]
            count += 1
    return arr

def setRightmostUnsetBit(n):
    if n == 0:
        return 1
    if (n & (n + 1)) == 0:
        return n
    m = 1
    while (n & m):
        m = m << 1
    return (n | m)

def find_first_occurrence(arr, target):
    low, high = 0, len(arr) - 1
    result = -1
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == target:
            result = mid
            high = mid - 1
        elif arr[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return result

def index_of_min_value_record(records):
    if not records:
        return -1  # return -1 if records are empty

    min_index = 0
    min_value = records[0][1]

    for i, record in enumerate(records):
        if record[1] < min_value:
            min_index = i
            min_value = record[1]

    return min_index

