import re

def remove_uppercase_substrings(text):
  pattern = r'[A-Z]+'
  return re.sub(pattern, '', text)

def pancake_sort(arr):
    for i in range(len(arr),1,-1):
        mx_idx=0
        for j in range(1,i):
            if arr[j]>arr[mx_idx]:
                mx_idx=j
        arr[:mx_idx+1]=arr[mx_idx::-1]
        arr[:i]=arr[i-1::-1]
    return arr

def nCrModp(n: int, r: int, p: int) -> int:
    if r > n:
        return 0
    fac = [1] * (n + 1)
    for i in range(2, n + 1):
        fac[i] = i * fac[i - 1]
    power = pow(10, 9 + len(str(fac[n])), p)
    return (fac[n] * pow(fac[r] * fac[n - r], power - 2, p)) % p

