def catalan(n):
    if n == 0 or n == 1:
        return 1
    catalan_nums = [0] * (n + 1)
    catalan_nums[0] = 1
    catalan_nums[1] = 1
    for i in range(2, n + 1):
        for j in range(i):
            catalan_nums[i] += catalan_nums[j] * catalan_nums[i - j - 1]
    return catalan_nums[n]

