def find_max_rotated_sorted_array(nums):
    """
    Finds the maximum element in a sorted and rotated array.
    """
    left, right = 0, len(nums) - 1
    while left < right:
        mid = left + (right - left) // 2
        if nums[mid] > nums[right]:
            left = mid + 1
        else:
            right = mid
    return nums[left]

