def subset(arr, sum):
    n = len(arr)
    dp = [[False for i in range(sum+1)]for j in range(n+1)]
    for i in range(n+1):
        dp[i][0] = True
    for i in range(1, n+1):
        for j in range(1, sum+1):
            dp[i][j] = dp[i-1][j]
            if arr[i-1] <= j:
                dp[i][j] |= dp[i-1][j - arr[i-1]]
    return dp[n][sum]

def BinarySequence(n): 
    dp = [[[-1 for k in range(2)] 
             for j in range(n + 1)] 
             for i in range(n + 1)] 
    def solve(i, j, k): 
        if (i == n and j == n and k == 0): 
            return 1
        if (i > n or j > n or i + j > 2 * n): 
            return 0
        if (dp[i][j][k] != -1): 
            return dp[i][j][k] 
        dp[i][j][k] = (solve(i + 1, j, (k + 1) % 2) + 
                   solve(i, j + 1, k)) 
        return dp[i][j][k] 
    return solve(0, 0, 0)

