def sum_amicable_numbers(n):
    def sum_proper_divisors(num):
        divisors = [1]
        for i in range(2, int(num**.5) + 1):
            if num % i == 0:
                divisors.extend([i, num // i])
        return sum(divisors)

    amicable_numbers = []
    for i in range(1, n + 1):
        sum_divisors_i = sum_proper_divisors(i)
        sum_divisors_sum_divisors_i = sum_proper_divisors(sum_divisors_i)
        if i == sum_divisors_sum_divisors_i and i != sum_divisors_i:
            amicable_numbers.append(i)

    return sum(amicable_numbers)

def comb_sort(arr: list) -> list:
    """Sort a list of elements using comb sort."""
    n = len(arr)
    gap = n
    swapped = True
    while gap > 1 or swapped:
        gap = int(gap / 1.3)
        if gap < 1:
            gap = 1
        swapped = False
        for i in range(n - gap):
            if arr[i] > arr[i + gap]:
                arr[i], arr[i + gap] = arr[i + gap], arr[i]
                swapped = True
    return arr

