def primedivsum(n):
    sm = 0
    i = 2
    while i*i<=n:
        if n%i == 0 and n/i != i:
            sm+=i+(n/i)
        elif n%i == 0:
            sm+=i
        i+=1
    if n>1:
        sm+=n
    return sm

def last_two_digits_of_factorial(n):
    if n == 0 or n == 1:
        return 1
    if n == 2:
        return 2
    if n == 3:
        return 6
    if n == 4:
        return 4
    return (n % 10) * last_two_digits_of_factorial(n-1) % 100

