    if D < 0:
        return False
    elif D > 0:
        x1 = (-b + D**0.5) / (2*a)
        x2 = (-b - D**0.5) / (2*a)
        if x1 == 2*x2 or x2 == 2*x1:
            return True
        else:
            return False
    else:
        x1 = -b / (2*a)
        if x1 == 0:
            return True
        else:
            return False

