        n //= 10
        i += 1
    return even_product == odd_product

def calculate_eulerian_number(n: int, m: int) -> int:
    """
    Write a function to find eulerian number a(n, m).
    """
    if m == 0:
        return 1
    if n == 0:
        return 0
    return (m - 1) * (calculate_eulerian_number(n - 1, m - 1) + calculate_eulerian_number(n - 1, m))

