def l_bin_search(arr, x):
    low, high = 0, len(arr) - 1
    last = -1
    while low <= high:
        mid = low + (high - low) // 2
        if arr[mid] == x:
            last = mid
            low = mid + 1
        elif arr[mid] > x:
            high = mid - 1
        else:
            low = mid + 1
    return last

def height_of_binary_tree(root):
    if root is None:
        return 0
    left_height = height_of_binary_tree(root.left)
    right_height = height_of_binary_tree(root.right)
    return 1 + max(left_height, right_height)

