def ncrModp(n:int, r:int, p:int) -> int:  
  fac=[1]  
  for i in range(1,n+1):  
    fac.append((fac[-1]*i)%p)  
  return (fac[n]*(pow(fac[r],p-2,p)*pow(fac[n-r],p-2,p))%p)%p

