def find_prime(n):
    """Find the nth newman–shanks–williams prime number."""
    p = 1
    while n > 0:
        p = p + 1
        if is_prime(2**p - 1):
            n -= 1
    return p - 1


def is_prime(n):
    """Check if n is prime."""
    if n == 2:
        return True
    if n % 2 == 0 or n <= 1:
        return False

    sqr = int(n ** 0.5) + 1

    for divisor in range(3, sqr, 2):
        if n % divisor == 0:
            return False
    return True

