def generate_magic_square(n):
    if n % 2 != 1:
        raise ValueError("n must be an odd number")
    magic_square = [[0 for _ in range(n)] for _ in range(n)]
    i, j, num = n//2, n-1, 1
    while num <= n*n:
        if i == -1 and j == n:
            j -= 2
            i += 1
        elif i < 0:
            i += n
        elif j == n:
            j -= n
        elif magic_square[i][j]:  
            j -= 2
            i += 1
        magic_square[i][j] = num
        num += 1
        i -= 1
        j += 1
    return magic_square

