        prev = choose_colors(colors[i+1:], k-1)
        cur = [[colors[i]] + item for item in prev]
        result.extend(cur)

    return result

def find_frequency_list(test_list):
  res = {}
  for ele in test_list:
    if ele not in res:
      res[ele] = 0
    res[ele] += 1  
  return res

def next_permutation(n): 
    n = str(n) 
    l = len(n) 
    i = l - 2
    while i >= 0 and n[i] >= n[i+1]: 
        i -= 1
    if i >= 0: 
        j = l - 1
        while n[j] <= n[i]: 
            j -= 1
        n = n[:i] + n[j] + n[i+1:j] + n[i] + n[j+1:] 
    n = list(n) 
    n[i+1:] = reversed(n[i+1:]) 
    return int(''.join(n))

def repeat_by_count(l: list[int]) -> list[int]:
    """Write a function to iterate over elements repeating each as many times as its count.
    """
    ret = []
    for item in l:
        for _ in range(item):
            ret.append(item)
    return ret

def findMissingNumber(nums):
    nums.sort()
    for i in range(1, len(nums)):
        if nums[i] - nums[i - 1] > 1:
            return nums[i] - 1
    return nums[0] - 1 if nums[0] > 0 else nums[-1] + 1

def rearrange(arr):
    i = -1
    for j in range(len(arr)):
        if arr[j] < 0:
            i += 1
            arr[i],arr[j] = arr[j],arr[i]
    return arr

def convert(list):
    temp = 0
    for num in list:
        temp = temp * 10 + num
    return temp

def find_substrings(string, sub_string):
  positions = []
  start = 0
  while True:
    index = string.find(sub_string, start)
    if index == -1:
      break
    positions.append(index)
    start = index + 1
  return positions

def lcs(sequence1, sequence2):
    len1, len2 = len(sequence1), len(sequence2)
    dp = [[0] * (len2 + 1) for _ in range(len1 + 1)]
    for i in range(1, len1 + 1):
        for j in range(1, len2 + 1):
            if sequence1[i - 1] == sequence2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])
    return dp[len1][len2]

import heapq
def merge_sorted_inputs(*iterables):
  h = []
  for it in iterables:
    try:
      next_val = next(it)
      heapq.heappush(h, (next_val, it))
    except StopIteration:
      pass
  while h:
    val, it = heapq.heappop(h)
    yield val
    try:
      next_val = next(it)
      heapq.heappush(h, (next_val, it))
    except StopIteration:
      pass

def is_coprime(n, m):
  """
  Check whether the given number is co-prime or not.

  """
  if n <= 1 or m <= 1:
    return False

  while m:
    if n < m:
      n, m = m, n
    n, m = m, n % m

  if n == 1:
    return True
  else:
    return False

def operation_equ_ele(arr: list, n: int, k: int) -> int:
    """Write a python function to find k number of operations required to make all elements equal."""
    lm = float('inf')
    mx = float('-inf')

    for i in range(n):
        lm = min(lm, arr[i])
        mx = max(mx, arr[i])

    diff = mx - lm
    if diff <= k:
        return diff
    else:
        return 2*(k - diff)

def count_most_common_character(string):
    characters = {}
    for char in string:
        if char in characters:
            characters[char] += 1
        else:
            characters[char] = 1
    most_common_char = max(characters, key=characters.get)
    return [most_common_char, characters[most_common_char]]
